pub(crate) async fn hydrate_summary_snapshots(state: &AppState) -> Result<()> {
    hydrate_summary_snapshots_with_deadline(state, SUMMARY_PROJECTION_STARTUP_BUILD_DEADLINE).await
}

pub(crate) async fn hydrate_summary_snapshots_with_deadline(
    state: &AppState,
    deadline: Duration,
) -> Result<()> {
    refresh_summary_snapshots_with_deadline(
        state,
        SummaryProjectionBuildMode::Bootstrap,
        Some(deadline),
        false,
    )
    .await
}

pub(crate) async fn refresh_summary_snapshots(state: &AppState) -> Result<()> {
    if state.subscription_hub.summary_projection().await.is_none() {
        // A cold retry has no exact historical coverage proof to reuse. Keep the first
        // publication on the Bootstrap deadline instead of downgrading it to the shorter
        // Rolling deadline used only after an immutable projection exists.
        hydrate_summary_snapshots(state).await?;
    } else if !renew_summary_projection_freshness_if_generation_matches(state).await? {
        refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::RollingDelta)
            .await?;
    }
    let historical_live_recovery_required = state
        .subscription_hub
        .summary_projection()
        .await
        .is_some_and(|projection| {
            projection
                .historical_live_coverage
                .as_ref()
                .is_some_and(|coverage| coverage.reconciliation_required)
        });
    if historical_live_recovery_required {
        // Rolling publication is the availability-critical path. A complete historical live
        // proof can be slower, so recover it afterwards while keeping the newly published exact
        // current/recent selections fresh in the hub. Keep this outside the generation renewal
        // branch: a deferred recovery must retry even while the localized projection remains
        // fresh against an unchanged fence.
        if let Err(error) = refresh_summary_snapshots_with_mode(
            state,
            SummaryProjectionBuildMode::HistoricalLiveCoverage,
        )
        .await
        {
            warn!(error = ?error, "summary historical live coverage recovery deferred; keeping fresh rolling projection");
        }
    }
    if !state.subscription_hub.has_summary_all_time_owner().await {
        return Ok(());
    }
    if summary_projection_all_time_staged_recovery_required(&state.pool).await? {
        let checkpoint = tokio::time::timeout(
            SUMMARY_PROJECTION_BUILD_DEADLINE,
            advance_summary_all_time_projection_checkpoint(state),
        )
        .await
        .map_err(|_| {
            anyhow!(
                "summary all-time staged checkpoint exceeded {SUMMARY_PROJECTION_BUILD_DEADLINE:?}"
            )
        });
        let checkpoint = match checkpoint {
            Ok(Ok(checkpoint)) => checkpoint,
            Ok(Err(error))
                if error
                    .downcast_ref::<SummaryProjectionAllTimeGenerationChanged>()
                    .is_some() =>
            {
                debug!(
                    "summary all-time staged checkpoint observed a generation change; rebuilding rolling projection"
                );
                refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::Rolling)
                    .await?;
                return Ok(());
            }
            Ok(Err(error)) => {
                warn!(error = ?error, "summary all-time staged checkpoint deferred; keeping fresh rolling projection");
                return Ok(());
            }
            Err(error) => return Err(error),
        };
        if checkpoint.global_ready() || checkpoint.account_ready() {
            let publication = tokio::time::timeout(
                SUMMARY_PROJECTION_BUILD_DEADLINE,
                publish_summary_all_time_projection_checkpoint(state, checkpoint),
            )
            .await
            .map_err(|_| {
                anyhow!(
                    "summary all-time staged finalization exceeded {SUMMARY_PROJECTION_BUILD_DEADLINE:?}"
                )
            });
            match publication {
                Ok(Ok(())) => {}
                Ok(Err(error))
                    if error
                        .downcast_ref::<SummaryProjectionAllTimeGenerationChanged>()
                        .is_some() =>
                {
                    debug!(
                        "summary all-time staged finalization observed a generation change; rebuilding rolling projection"
                    );
                    refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::Rolling)
                        .await?;
                }
                Ok(Err(error)) => {
                    warn!(error = ?error, "summary all-time staged finalization deferred; keeping fresh rolling projection");
                }
                Err(error) => return Err(error),
            }
        } else {
            // A proof page can establish that one or more immutable archives need raw
            // replacement, but the checkpoint itself only advances compact proof cursors. Run
            // that replacement on the AllTime reconciliation path: it is the sole background
            // owner of paged raw archive hydration, and a deferred attempt leaves the already
            // published rolling projection intact.
            if let Err(error) =
                refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::AllTime)
                    .await
            {
                if error
                    .downcast_ref::<SummaryProjectionAllTimeGenerationChanged>()
                    .is_some()
                {
                    debug!(
                        "summary all-time paged raw recovery observed a generation change; rebuilding rolling projection"
                    );
                    refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::Rolling)
                        .await?;
                } else {
                    warn!(error = ?error, "summary all-time paged raw recovery deferred; keeping fresh rolling projection");
                }
            }
        }
        return Ok(());
    }
    let coverage = tokio::time::timeout(
        SUMMARY_PROJECTION_BUILD_DEADLINE,
        advance_summary_all_time_coverage_checkpoint(&state.pool),
    )
    .await
    .map_err(|_| {
        anyhow!(
            "summary all-time coverage checkpoint exceeded {SUMMARY_PROJECTION_BUILD_DEADLINE:?}"
        )
    })?;
    let coverage = match coverage {
        Ok(coverage) => coverage,
        Err(error) => {
            warn!(error = ?error, "summary all-time coverage checkpoint deferred; keeping fresh rolling projection");
            return Ok(());
        }
    };
    if !coverage.is_complete() {
        debug!(
            "summary all-time coverage checkpoint remains incomplete; keeping fresh rolling projection"
        );
        return Ok(());
    }
    if let Err(error) =
        refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::AllTime).await
    {
        if error
            .downcast_ref::<SummaryProjectionAllTimeGenerationChanged>()
            .is_some()
        {
            debug!(
                "summary all-time reconciliation cancelled after a generation change; rebuilding rolling projection"
            );
            refresh_summary_snapshots_with_mode(state, SummaryProjectionBuildMode::Rolling).await?;
        } else {
            warn!(error = ?error, "summary all-time reconciliation deferred; keeping fresh rolling projection");
        }
    }
    Ok(())
}

async fn renew_summary_projection_freshness_if_generation_matches(
    state: &AppState,
) -> Result<bool> {
    let generation_fence = load_summary_projection_generation_fence(state).await?;
    let renewed = state
        .subscription_hub
        .renew_summary_projection_freshness_if_generation_matches(generation_fence)
        .await;
    if renewed {
        debug!("summary projection freshness renewed for unchanged durable generation");
    }
    Ok(renewed)
}

/// Reconstruct the bounded durable source tail after a restart or when the in-process delta
/// queue has been dropped.  Only descriptor identities are read from the journal; the canonical
/// source row is hydrated in 400-id chunks and exposed through the existing in-memory replay
/// overlay.  This function deliberately never invokes the full live admission builder.
async fn restore_summary_source_change_tail(state: &AppState) -> Result<bool> {
    let mut after_cursor = state.subscription_hub.summary_source_change_cursor().await;
    if after_cursor == 0 {
        after_cursor = load_summary_source_change_checkpoint(
            &state.pool,
            SUMMARY_SOURCE_CHANGE_CHECKPOINT_SCOPE,
        )
        .await?;
        if after_cursor > 0 {
            state
                .subscription_hub
                .advance_summary_source_change_cursor(after_cursor)
                .await;
        }
    }
    let tail = load_summary_source_change_tail(
        &state.pool,
        after_cursor,
        SUMMARY_SOURCE_CHANGE_JOURNAL_MAX_ENTRIES,
    )
    .await?;
    let Some(last_cursor) = tail.last().map(|record| record.cursor) else {
        return Ok(false);
    };
    state
        .subscription_hub
        .advance_summary_source_change_cursor(last_cursor)
        .await;

    let ids = tail
        .iter()
        .flat_map(|record| record.descriptor.entries.iter().map(|entry| entry.row_id))
        .collect::<Vec<_>>();
    let mut rows_by_id = HashMap::<i64, ApiInvocation>::new();
    for chunk in ids.chunks(DASHBOARD_ACTIVITY_PREVIEW_ID_HYDRATION_CHUNK_SIZE) {
        if chunk.is_empty() {
            continue;
        }
        let mut query = build_invocation_select_query();
        query.push(" WHERE id IN (");
        {
            let mut separated = query.separated(", ");
            for id in chunk {
                separated.push_bind(*id);
            }
        }
        query.push(") ORDER BY id ASC");
        for row in query
            .build_query_as::<ApiInvocation>()
            .fetch_all(&state.pool)
            .await
            .context("summary source descriptor row reconstruction failed")?
        {
            rows_by_id.insert(row.id, row);
        }
    }

    let mut restored = false;
    let mut complete = true;
    for record in tail {
        if record.descriptor.source_kind != "terminal_batch" {
            // Archive and rollup descriptors are durable fence evidence for the independent
            // historical reconciler. They must not be interpreted as live invocation rows.
            state
                .subscription_hub
                .mark_summary_projection_historical_recovery_required()
                .await;
            continue;
        }
        for entry in record.descriptor.entries {
            let Some(row) = rows_by_id.get(&entry.row_id) else {
                complete = false;
                state
                    .subscription_hub
                    .record_summary_source_change_gap(record.cursor)
                    .await;
                continue;
            };
            let mut delta = persisted_dashboard_activity_terminal_delta(row);
            delta.persisted_row_id = Some(row.id);
            state
                .subscription_hub
                .acknowledge_replayed_summary_delta(delta)
                .await;
            restored = true;
        }
    }
    if complete {
        store_summary_source_change_checkpoint(
            &state.pool,
            SUMMARY_SOURCE_CHANGE_CHECKPOINT_SCOPE,
            last_cursor,
        )
        .await?;
    }
    Ok(restored)
}

/// Compatibility recovery for source writers predating the durable descriptor hook.  Bound the
/// read to the legal current prefix and leave a historical reconciliation marker so a missing
/// descriptor can never silently make an old range look exact.
async fn restore_legacy_summary_source_tail(state: &AppState) -> Result<bool> {
    let mut query = build_invocation_select_query();
    query.push(" ORDER BY occurred_at DESC, id DESC LIMIT ");
    query.push_bind(state.config.list_limit_max.min(400) as i64);
    let rows = query
        .build_query_as::<ApiInvocation>()
        .fetch_all(&state.pool)
        .await
        .context("legacy summary source tail reconstruction failed")?;
    let projection = state.subscription_hub.summary_projection().await;
    let Some(projection) = projection else {
        return Ok(false);
    };
    let mut restored = false;
    for row in rows {
        if projection.contains_persisted_live_terminal(&row.invoke_id, &row.occurred_at) {
            continue;
        }
        let mut delta = persisted_dashboard_activity_terminal_delta(&row);
        delta.persisted_row_id = Some(row.id);
        state
            .subscription_hub
            .acknowledge_replayed_summary_delta(delta)
            .await;
        // A legacy writer can advance a historical row without a durable descriptor. Keep its
        // proof scoped to the row's time/account so an independent current selection remains
        // exact while the background historical reconciliation is in flight.
        state
            .subscription_hub
            .record_summary_source_change_scoped_gap(
                row.id as u64,
                row.upstream_account_id,
                row.occurred_at.clone(),
                Some(row.id),
            )
            .await;
        restored = true;
    }
    if restored {
        state
            .subscription_hub
            .mark_summary_projection_historical_recovery_required()
            .await;
    }
    Ok(restored)
}

pub(crate) async fn refresh_summary_snapshots_with_mode(
    state: &AppState,
    mode: SummaryProjectionBuildMode,
) -> Result<()> {
    if matches!(mode, SummaryProjectionBuildMode::RollingDelta) {
        let started = Instant::now();
        if state
            .subscription_hub
            .renew_summary_projection_freshness_from_delta_journal()
            .await
        {
            let (entry_count, gap_count) =
                state.subscription_hub.summary_delta_journal_counts().await;
            debug!(
                ?mode,
                stage = "delta_journal_reduce",
                elapsed_ms = started.elapsed().as_millis() as u64,
                entry_count,
                gap_count,
                "summary projection rolling delta renewed without live source admission"
            );
            return Ok(());
        }
        let mut restored = restore_summary_source_change_tail(state).await?;
        if !restored {
            restored = restore_legacy_summary_source_tail(state).await?;
        }
        if restored
            && state
                .subscription_hub
                .renew_summary_projection_freshness_from_delta_journal()
                .await
        {
            let (entry_count, gap_count) =
                state.subscription_hub.summary_delta_journal_counts().await;
            debug!(
                ?mode,
                stage = "durable_source_tail_reconstruct",
                entry_count,
                gap_count,
                "summary projection rolling delta reconstructed from durable source descriptors"
            );
            return Ok(());
        }
        // A fence change may belong only to archive or rollup coverage. Rebuild the bounded
        // RollingDelta projection so its metadata-only admission can publish a localized gap
        // for the affected range; it still never performs paged raw archive hydration. A
        // no-op here would leave the old projection falsely fresh after an archive replay proof
        // changed underneath it.
        return refresh_summary_snapshots_with_deadline(
            state,
            SummaryProjectionBuildMode::RollingDelta,
            Some(SUMMARY_PROJECTION_BUILD_DEADLINE),
            true,
        )
        .await;
    }
    let deadline = match mode {
        SummaryProjectionBuildMode::HistoricalLiveCoverage
        | SummaryProjectionBuildMode::AllTime => SUMMARY_PROJECTION_ALL_TIME_FINALIZATION_DEADLINE,
        SummaryProjectionBuildMode::Bootstrap
        | SummaryProjectionBuildMode::RollingDelta
        | SummaryProjectionBuildMode::Rolling => SUMMARY_PROJECTION_BUILD_DEADLINE,
    };
    refresh_summary_snapshots_with_deadline(state, mode, Some(deadline), true).await
}

async fn refresh_summary_snapshots_with_deadline(
    state: &AppState,
    mode: SummaryProjectionBuildMode,
    deadline: Option<Duration>,
    coalesce_if_in_flight: bool,
) -> Result<()> {
    let Ok(_refresh_guard) = state.subscription_hub.try_lock_summary_projection_refresh() else {
        if coalesce_if_in_flight {
            debug!("summary projection refresh already in flight; coalescing trigger");
            return Ok(());
        }
        return Err(anyhow!(
            "summary projection startup hydration deferred because a refresh is already in flight"
        ));
    };
    let previous_all_time = state
        .subscription_hub
        .summary_projection()
        .await
        .map(|projection| PreviousSummaryProjectionAllTime {
            all_time_by_account: projection.all_time_by_account.clone(),
            all_time_refreshed_at: projection.all_time_refreshed_at,
            all_time_manifest_admission_blocked_at: projection
                .all_time_manifest_admission_blocked_at,
            all_time_account_manifest_admission_blocked_at: projection
                .all_time_account_manifest_admission_blocked_at,
            all_time_account_refreshed_at: projection.all_time_account_refreshed_at.clone(),
            archive_account_ids_by_file: projection.archive_account_ids_by_file.clone(),
            archive_coverage_ranges_by_file: projection.archive_coverage_ranges_by_file.clone(),
            global_all_time_eligible: projection.freshness.global_all_time_eligible,
            account_all_time_eligible: projection.freshness.account_all_time_eligible.clone(),
            all_time_terminal_coverage_complete: projection.all_time_terminal_coverage_complete(),
            all_time_terminal_sequence_watermark: projection.all_time_terminal_sequence_watermark(),
            all_time_persisted_live_terminal_invoke_ids: projection
                .all_time_persisted_live_terminal_invoke_ids
                .clone(),
            all_time_account_terminal_sequence_watermarks: projection
                .all_time_account_terminal_sequence_watermarks
                .clone(),
            all_time_account_persisted_live_terminal_invoke_ids: projection
                .all_time_account_persisted_live_terminal_invoke_ids
                .clone(),
            historical_live_coverage: projection.historical_live_coverage.clone(),
            unavailable_exact_live_ranges: projection.unavailable_exact_live_ranges.clone(),
            unavailable_exact_live_account_ranges: projection
                .unavailable_exact_live_account_ranges
                .clone(),
            persisted_live_terminal_invoke_ids: projection
                .persisted_live_terminal_invoke_ids
                .clone(),
        });
    // The runtime read model advances this watermark only after SQLite ACKs every preceding
    // terminal in order. Capture it before the durable projection queries so a later successful
    // revision can prove that an overflowed Summary SSE overlay is no longer missing data.
    let durable_terminal_sequence_watermark = state
        .dashboard_activity_snapshot_cache
        .lock()
        .await
        .read_model
        .settled_terminal_sequence;
    let build_started_at = Instant::now();
    let build = build_summary_projection(
        state,
        mode,
        previous_all_time,
        durable_terminal_sequence_watermark,
    );
    let projection = match (mode, deadline) {
        (
            SummaryProjectionBuildMode::HistoricalLiveCoverage
            | SummaryProjectionBuildMode::AllTime,
            Some(deadline),
        ) => await_summary_projection_all_time_build(state, build, deadline).await?,
        (_, Some(deadline)) => tokio::time::timeout(deadline, build)
            .await
            .map_err(|_| anyhow!("summary projection build exceeded {deadline:?}"))??,
        (_, None) => build.await?,
    };
    info!(
        ?mode,
        stage = "generation_fence_snapshot",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build snapshot generation fence accepted"
    );
    state
        .subscription_hub
        .store_summary_projection(projection)
        .await;
    debug!(
        ?mode,
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build published"
    );
    Ok(())
}

async fn await_summary_projection_all_time_build(
    state: &AppState,
    build: impl std::future::Future<Output = Result<SummaryProjection>>,
    deadline: Duration,
) -> Result<SummaryProjection> {
    let mut keepalive = tokio::time::interval_at(
        tokio::time::Instant::now() + SUMMARY_SNAPSHOT_MIN_REFRESH_INTERVAL,
        SUMMARY_SNAPSHOT_MIN_REFRESH_INTERVAL,
    );
    let timeout = tokio::time::sleep(deadline);
    tokio::pin!(build);
    tokio::pin!(timeout);
    loop {
        tokio::select! {
            result = &mut build => return result,
            _ = &mut timeout => return Err(anyhow!("summary projection build exceeded {deadline:?}")),
            _ = keepalive.tick() => match renew_summary_projection_freshness_if_generation_matches(state).await {
                Ok(true) => debug!("summary rolling projection kept fresh during all-time reconciliation"),
                Ok(false) => return Err(SummaryProjectionAllTimeGenerationChanged.into()),
                Err(error) => warn!(error = ?error, "summary all-time reconciliation could not renew rolling freshness"),
            },
        }
    }
}

async fn load_summary_projection_rollup_live_cursor(pool: &Pool<Sqlite>) -> Result<i64> {
    let mut connection = pool.acquire().await?;
    load_invocation_summary_rollup_live_cursor_tx(&mut connection)
        .await
        .map_err(|error| {
            anyhow!("summary projection live rollup cursor hydration failed: {error:?}")
        })
}

async fn load_summary_projection_account_rollup_live_cursor(
    pool: &Pool<Sqlite>,
) -> Result<Option<i64>> {
    // Account activity v2 advances independently from the global invocation rollup.  A global
    // cursor therefore cannot be used to suppress an account-scoped exact row when this marker
    // is behind it.
    sqlx::query_scalar::<_, i64>(
        "SELECT cursor_id FROM hourly_rollup_live_progress \
         WHERE dataset = 'invocation_account_activity_v2_repair_live_cursor'",
    )
    .fetch_optional(pool)
    .await
    .context("summary projection account rollup cursor hydration failed")
}

async fn load_summary_projection_archive_account_ids(
    pool: &Pool<Sqlite>,
    range: ExactUtcRange,
) -> Result<HashSet<i64>> {
    if !crate::stats::sqlite_table_has_column(pool, "codex_invocations", "payload").await? {
        return Ok(HashSet::new());
    }
    let lower = db_occurred_at_lower_bound(range.start);
    let upper = db_occurred_at_upper_bound(range.end);
    // Keep the result itself bounded. DISTINCT prevents a high-row-count archive with only a
    // handful of accounts from consuming the exact-record budget during account discovery.
    let rows = sqlx::query_scalar::<_, Option<i64>>(
        "SELECT DISTINCT CASE WHEN json_valid(payload) \
                    THEN CAST(json_extract(payload, '$.upstreamAccountId') AS INTEGER) \
                    END \
         FROM codex_invocations \
         WHERE occurred_at >= ?1 AND occurred_at < ?2 \
         LIMIT ?3",
    )
    .bind(lower)
    .bind(upper)
    .bind((summary_projection_exact_record_limit() + 1) as i64)
    .fetch_all(pool)
    .await
    .context("summary projection archive account discovery failed")?;
    if rows.len() > summary_projection_exact_record_limit() {
        return Err(anyhow!(
            "summary projection archive account discovery exceeded bounded account budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    Ok(rows
        .into_iter()
        .flatten()
        .filter(|account_id| *account_id > 0)
        .collect())
}

async fn load_summary_projection_archive_row_counts(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<HashMap<String, i64>> {
    if archive_paths.is_empty() {
        return Ok(HashMap::new());
    }

    let mut counts = HashMap::new();
    for archive_paths in archive_paths.chunks(SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE)
    {
        let mut query = QueryBuilder::<Sqlite>::new(
            "SELECT file_path, row_count FROM archive_batches \
             WHERE dataset = 'codex_invocations' AND status = 'completed' AND file_path IN (",
        );
        {
            let mut separated = query.separated(", ");
            for path in archive_paths {
                separated.push_bind(path);
            }
        }
        query.push(")");
        counts.extend(
            query
                .build_query_as::<(String, i64)>()
                .fetch_all(pool)
                .await
                .context("summary projection archive row-count hydration failed")?,
        );
        if counts.len() > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES {
            return Err(anyhow!(
                "summary projection archive batch cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES})"
            ));
        }
    }
    Ok(counts)
}

async fn load_summary_projection_archive_manifest_sha256(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<HashMap<String, String>> {
    if archive_paths.is_empty() {
        return Ok(HashMap::new());
    }

    let expected_count = archive_paths.iter().collect::<HashSet<_>>().len();
    let mut sha256_by_file_path = HashMap::with_capacity(expected_count);
    for archive_paths in archive_paths.chunks(SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE)
    {
        let mut query = QueryBuilder::<Sqlite>::new(
            "SELECT file_path, sha256 FROM archive_batches WHERE dataset = 'codex_invocations' \
             AND status = 'completed' AND file_path IN (",
        );
        {
            let mut separated = query.separated(", ");
            for path in archive_paths {
                separated.push_bind(path);
            }
        }
        query.push(")");
        for (file_path, sha256) in query
            .build_query_as::<(String, String)>()
            .fetch_all(pool)
            .await
            .context("summary projection archive manifest SHA hydration failed")?
        {
            if sha256.trim().is_empty()
                || sha256_by_file_path
                    .insert(file_path.clone(), sha256)
                    .is_some()
            {
                return Err(anyhow!(
                    "summary projection archive manifest SHA is missing or ambiguous for {file_path}"
                ));
            }
        }
    }
    if sha256_by_file_path.len() != expected_count {
        return Err(anyhow!(
            "summary projection archive manifest SHA hydration omitted snapshot rows"
        ));
    }
    Ok(sha256_by_file_path)
}

fn summary_projection_archive_file_is_readable(file_path: &str) -> bool {
    let Ok(file) = fs::File::open(file_path) else {
        return false;
    };
    let mut decoder = GzDecoder::new(file);
    io::copy(&mut decoder, &mut io::sink()).is_ok()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SummaryProjectionArchiveFileIdentity {
    Verified,
    Unavailable,
}

fn verify_summary_projection_archive_file_path_sha256(
    file_path: &str,
    expected_sha256: &str,
) -> Result<SummaryProjectionArchiveFileIdentity> {
    let actual_sha256 = match crate::maintenance::sha256_hex_file(Path::new(file_path)) {
        Ok(actual_sha256) => actual_sha256,
        // An unreadable archive contributes no raw data. Preserve the existing exact fallback:
        // materialized rollups remain usable, while an unmaterialized source is marked
        // unavailable by the strict archive readers below.
        Err(_) => return Ok(SummaryProjectionArchiveFileIdentity::Unavailable),
    };
    if actual_sha256 != expected_sha256 {
        if !summary_projection_archive_file_is_readable(file_path) {
            return Ok(SummaryProjectionArchiveFileIdentity::Unavailable);
        }
        return Err(anyhow!(
            "summary projection archive changed during hydration for {}",
            file_path
        ));
    }
    Ok(SummaryProjectionArchiveFileIdentity::Verified)
}

fn verify_summary_projection_archive_file_sha256(
    archive: &crate::stats::ArchiveBatchPathRow,
    expected_sha256: &str,
) -> Result<SummaryProjectionArchiveFileIdentity> {
    verify_summary_projection_archive_file_path_sha256(archive.file_path(), expected_sha256)
}

fn require_summary_projection_archive_file_sha256(
    archive: &crate::stats::ArchiveBatchPathRow,
    expected_sha256: &str,
) -> Result<()> {
    match verify_summary_projection_archive_file_sha256(archive, expected_sha256)? {
        SummaryProjectionArchiveFileIdentity::Verified => Ok(()),
        SummaryProjectionArchiveFileIdentity::Unavailable => Err(anyhow!(
            "summary projection archive became unavailable during hydration for {}",
            archive.file_path()
        )),
    }
}

fn verify_summary_projection_archive_file_paths_sha256(
    archive_paths: &[String],
    expected_sha256_by_file_path: &HashMap<String, String>,
) -> Result<Vec<String>> {
    let mut verified_paths = Vec::with_capacity(archive_paths.len());
    for file_path in archive_paths {
        let expected_sha256 = expected_sha256_by_file_path.get(file_path).ok_or_else(|| {
            anyhow!(
                "summary projection archive manifest SHA is missing for {}",
                file_path
            )
        })?;
        if verify_summary_projection_archive_file_path_sha256(file_path, expected_sha256)?
            == SummaryProjectionArchiveFileIdentity::Verified
        {
            verified_paths.push(file_path.clone());
        }
    }
    Ok(verified_paths)
}

fn require_summary_projection_archive_file_paths_sha256(
    archive_paths: &[String],
    expected_sha256_by_file_path: &HashMap<String, String>,
) -> Result<()> {
    for file_path in archive_paths {
        let expected_sha256 = expected_sha256_by_file_path.get(file_path).ok_or_else(|| {
            anyhow!(
                "summary projection archive manifest SHA is missing for {}",
                file_path
            )
        })?;
        match verify_summary_projection_archive_file_path_sha256(file_path, expected_sha256)? {
            SummaryProjectionArchiveFileIdentity::Verified => {}
            SummaryProjectionArchiveFileIdentity::Unavailable => {
                return Err(anyhow!(
                    "summary projection archive became unavailable during hydration for {}",
                    file_path
                ));
            }
        }
    }
    Ok(())
}

struct SummaryProjectionAllTimeArchiveScanPaths {
    global: Vec<String>,
    account: Vec<String>,
    global_unmaterialized_count: usize,
}

async fn load_summary_projection_all_time_archive_scan_paths(
    pool: &Pool<Sqlite>,
) -> Result<SummaryProjectionAllTimeArchiveScanPaths> {
    // These are precisely the completed archive paths that the two generic all-time
    // aggregators may inflate: the global pass handles missing invocation replay, and the
    // account pass additionally handles unmaterialized archives missing account replay.
    let rows = sqlx::query_as::<_, (String, i64, i64, i64)>(
        "SELECT batches.file_path, \
                NOT EXISTS ( \
                    SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                    WHERE replay.target = ?1 \
                      AND replay.dataset = 'codex_invocations' \
                      AND replay.file_path = batches.file_path \
                      AND batches.sha256 IS NOT NULL \
                      AND TRIM(batches.sha256) <> '' \
                      AND replay.archive_sha256 = batches.sha256 \
                ) AS needs_global_archive_scan, \
                (batches.historical_rollups_materialized_at IS NULL AND NOT EXISTS ( \
                    SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                    WHERE replay.target = ?2 \
                      AND replay.dataset = 'codex_invocations' \
                      AND replay.file_path = batches.file_path \
                      AND batches.sha256 IS NOT NULL \
                      AND TRIM(batches.sha256) <> '' \
                      AND replay.archive_sha256 = batches.sha256 \
                )) AS needs_account_archive_scan, \
                batches.historical_rollups_materialized_at IS NULL AS is_unmaterialized \
         FROM archive_batches AS batches \
         WHERE batches.dataset = 'codex_invocations' \
         AND batches.status = 'completed' \
         AND COALESCE(batches.summary_source_kind, 'unknown') <> 'live_mirror' \
         AND ( \
               NOT EXISTS ( \
                   SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                   WHERE replay.target = ?1 \
                     AND replay.dataset = 'codex_invocations' \
                     AND replay.file_path = batches.file_path \
                     AND batches.sha256 IS NOT NULL \
                     AND TRIM(batches.sha256) <> '' \
                     AND replay.archive_sha256 = batches.sha256 \
               ) \
               OR ( \
                   batches.historical_rollups_materialized_at IS NULL \
                   AND NOT EXISTS ( \
                   SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                   WHERE replay.target = ?2 \
                     AND replay.dataset = 'codex_invocations' \
                     AND replay.file_path = batches.file_path \
                     AND batches.sha256 IS NOT NULL \
                     AND TRIM(batches.sha256) <> '' \
                     AND replay.archive_sha256 = batches.sha256 \
               ) \
               ) \
           ) \
         ORDER BY batches.month_key ASC, batches.created_at ASC, batches.id ASC \
         LIMIT ?3",
    )
    .bind(HOURLY_ROLLUP_TARGET_INVOCATIONS)
    .bind(HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_STATS_HOURLY)
    .bind((SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES + 1) as i64)
    .fetch_all(pool)
    .await
    .context("summary projection all-time archive scan admission failed")?;
    if rows.len() > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES {
        return Err(anyhow!(
            "summary projection all-time archive scan cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES})"
        ));
    }
    let mut global = Vec::new();
    let mut account = Vec::new();
    let mut global_unmaterialized_count = 0usize;
    for (file_path, needs_global_archive_scan, needs_account_archive_scan, is_unmaterialized) in
        rows
    {
        if needs_global_archive_scan != 0 {
            if is_unmaterialized != 0 {
                global_unmaterialized_count += 1;
            }
            global.push(file_path.clone());
        }
        if needs_account_archive_scan != 0 {
            account.push(file_path);
        }
    }
    Ok(SummaryProjectionAllTimeArchiveScanPaths {
        global,
        account,
        global_unmaterialized_count,
    })
}

async fn load_summary_projection_archive_manifest_accounts(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<Vec<(String, i64)>> {
    if archive_paths.is_empty() {
        return Ok(Vec::new());
    }

    let mut accounts = Vec::new();
    for archive_paths in archive_paths.chunks(SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE)
    {
        let mut query = QueryBuilder::<Sqlite>::new(
            "SELECT batches.file_path, activity.account_id \
             FROM archive_batches AS batches \
             JOIN archive_batch_upstream_activity AS activity \
               ON activity.archive_batch_id = batches.id \
             WHERE batches.dataset = 'codex_invocations' \
               AND batches.status = 'completed' \
               AND activity.account_id > 0 \
               AND batches.file_path IN (",
        );
        {
            let mut separated = query.separated(", ");
            for path in archive_paths {
                separated.push_bind(path);
            }
        }
        query.push(")");
        let remaining = summary_projection_exact_record_limit().saturating_sub(accounts.len());
        query
            .push(" LIMIT ")
            .push_bind((remaining.saturating_add(1)) as i64);
        let rows = query
            .build_query_as::<(String, i64)>()
            .fetch_all(pool)
            .await
            .context("summary projection archive account manifest hydration failed")?;
        if rows.len() > remaining {
            return Err(anyhow!(
                "summary projection archive account manifest exceeded bounded row budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
            ));
        }
        accounts.extend(rows);
    }
    Ok(accounts)
}

async fn load_summary_projection_archive_manifest_refreshed_paths(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<HashSet<String>> {
    if archive_paths.is_empty() {
        return Ok(HashSet::new());
    }

    let mut refreshed_paths = HashSet::new();
    for archive_paths in archive_paths.chunks(SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE)
    {
        let mut query = QueryBuilder::<Sqlite>::new(
            r#"
            SELECT file_path
            FROM archive_batches
            WHERE dataset = 'codex_invocations'
              AND status = 'completed'
              AND upstream_activity_manifest_refreshed_at IS NOT NULL
              AND file_path IN (
            "#,
        );
        {
            let mut separated = query.separated(", ");
            for path in archive_paths {
                separated.push_bind(path);
            }
        }
        let rows = query
            .push(")")
            .build_query_scalar::<String>()
            .fetch_all(pool)
            .await
            .context("summary projection archive account manifest completion hydration failed")?;
        refreshed_paths.extend(rows);
    }
    Ok(refreshed_paths)
}

async fn load_summary_projection_archive_replay_coverage(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<HashMap<String, SummaryProjectionArchiveReplayCoverage>> {
    if archive_paths.is_empty() {
        return Ok(HashMap::new());
    }
    let mut coverage = HashMap::<String, SummaryProjectionArchiveReplayCoverage>::new();
    for archive_paths in archive_paths.chunks(SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE)
    {
        let mut query = QueryBuilder::<Sqlite>::new(
            "SELECT replay.file_path, replay.target FROM hourly_rollup_archive_replay AS replay \
             INNER JOIN archive_batches AS batches \
               ON batches.dataset = replay.dataset \
              AND batches.file_path = replay.file_path \
              AND batches.status = 'completed' \
              AND batches.sha256 IS NOT NULL \
              AND TRIM(batches.sha256) <> '' \
              AND batches.sha256 = replay.archive_sha256 \
             WHERE replay.dataset = 'codex_invocations' AND replay.target IN (",
        );
        query
            .push_bind(HOURLY_ROLLUP_TARGET_INVOCATIONS)
            .push(", ")
            .push_bind(HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_STATS_HOURLY)
            .push(", ")
            .push_bind(HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_USAGE_BREAKDOWN)
            .push(") AND replay.file_path IN (");
        {
            let mut separated = query.separated(", ");
            for path in archive_paths {
                separated.push_bind(path);
            }
        }
        query.push(")");
        let rows = query
            .build_query_as::<(String, String)>()
            .fetch_all(pool)
            .await
            .context("summary projection archive replay coverage hydration failed")?;
        for (file_path, target) in rows {
            let entry = coverage.entry(file_path).or_default();
            if target == HOURLY_ROLLUP_TARGET_INVOCATIONS {
                entry.overall = true;
            }
            if target == HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_STATS_HOURLY {
                entry.account_stats = true;
            }
            if target == HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_USAGE_BREAKDOWN {
                entry.usage_breakdown = true;
            }
        }
    }
    Ok(coverage)
}

async fn summary_projection_completed_manifest_high_watermark(
    pool: &Pool<Sqlite>,
) -> Result<Option<i64>> {
    sqlx::query_scalar::<_, Option<i64>>(
        "SELECT MAX(id) FROM archive_batches \
         WHERE dataset = 'codex_invocations' AND status = 'completed' \
           AND COALESCE(summary_source_kind, 'unknown') <> 'live_mirror'",
    )
    .fetch_one(pool)
    .await
    .context("summary projection completed manifest high-watermark hydration failed")
}

pub(crate) const SUMMARY_ALL_TIME_COVERAGE_SCOPE_GLOBAL: &str = "global";
pub(crate) const SUMMARY_ALL_TIME_COVERAGE_SCOPE_ACCOUNT: &str = "account";

#[derive(Debug, Clone, Copy, sqlx::FromRow)]
pub(crate) struct SummaryAllTimeCoverageCheckpointRow {
    pub(crate) manifest_high_watermark_id: i64,
    pub(crate) next_manifest_id: i64,
    pub(crate) completed: i64,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SummaryAllTimeCoverageProgress {
    global_complete: bool,
    account_complete: bool,
}

impl SummaryAllTimeCoverageProgress {
    pub(crate) const fn is_complete(self) -> bool {
        self.global_complete && self.account_complete
    }
}

pub(crate) async fn load_summary_all_time_coverage_checkpoint(
    pool: &Pool<Sqlite>,
    scope: &str,
) -> Result<Option<SummaryAllTimeCoverageCheckpointRow>> {
    sqlx::query_as::<_, SummaryAllTimeCoverageCheckpointRow>(
        "SELECT manifest_high_watermark_id, next_manifest_id, completed \
         FROM summary_all_time_coverage_checkpoint WHERE scope = ?1",
    )
    .bind(scope)
    .fetch_optional(pool)
    .await
    .context("summary all-time coverage checkpoint hydration failed")
}

async fn store_summary_all_time_coverage_checkpoint(
    pool: &Pool<Sqlite>,
    scope: &str,
    manifest_high_watermark_id: i64,
    next_manifest_id: i64,
    completed: bool,
) -> Result<()> {
    sqlx::query(
        "INSERT INTO summary_all_time_coverage_checkpoint \
         (scope, manifest_high_watermark_id, next_manifest_id, completed, updated_at) \
         VALUES (?1, ?2, ?3, ?4, datetime('now')) \
         ON CONFLICT(scope) DO UPDATE SET \
           manifest_high_watermark_id = excluded.manifest_high_watermark_id, \
           next_manifest_id = excluded.next_manifest_id, \
           completed = excluded.completed, updated_at = excluded.updated_at",
    )
    .bind(scope)
    .bind(manifest_high_watermark_id)
    .bind(next_manifest_id)
    .bind(i64::from(completed))
    .execute(pool)
    .await
    .context("summary all-time coverage checkpoint persistence failed")?;
    Ok(())
}

async fn summary_all_time_coverage_page_is_exact(
    pool: &Pool<Sqlite>,
    page: &SummaryProjectionBoundaryManifestPage,
) -> Result<(bool, bool)> {
    if page.archives.is_empty() {
        return Ok((true, true));
    }
    let paths = page
        .archives
        .iter()
        .map(|archive| archive.file_path().to_string())
        .collect::<Vec<_>>();
    let replay_coverage = load_summary_projection_archive_replay_coverage(pool, &paths).await?;
    let account_ids_by_file = load_summary_projection_archive_manifest_account_sets(pool, &paths)
        .await
        .context("summary all-time coverage account manifest proof hydration failed")?;
    let mut global_complete = true;
    let mut account_complete = true;
    for archive in &page.archives {
        let replay = replay_coverage
            .get(archive.file_path())
            .copied()
            .unwrap_or_default();
        let account_ids = account_ids_by_file
            .get(archive.file_path())
            .expect("coverage proof account manifest includes every archive path");
        let (archive_global_complete, archive_account_complete) =
            if let Some(range) = summary_projection_archive_coverage_range(archive) {
                let rollup_range = (
                    align_bucket_epoch(range.start.timestamp(), 3_600, 0),
                    align_bucket_epoch(range.end.timestamp().saturating_sub(1), 3_600, 0)
                        .saturating_add(3_600),
                );
                let (hourly_rollup_totals, _) =
                    load_summary_projection_rollup_totals_in_range(pool, Some(rollup_range))
                        .await
                        .context("summary all-time coverage rollup key proof hydration failed")?;
                summary_projection_all_time_manifest_scope_coverage(
                    archive,
                    replay,
                    page.account_manifest_refreshed_paths
                        .contains(archive.file_path()),
                    account_ids,
                    &hourly_rollup_totals,
                )?
            } else {
                // Legacy manifests have no finite range. A replay marker is still required, but
                // there are no concrete bucket keys to validate in this bounded proof page.
                (
                    archive.has_materialized_historical_rollups() && replay.overall,
                    archive.has_materialized_historical_rollups()
                        && page
                            .account_manifest_refreshed_paths
                            .contains(archive.file_path())
                        && replay.account_stats
                        && replay.usage_breakdown,
                )
            };
        global_complete &= archive_global_complete;
        account_complete &= archive_account_complete;
        if !global_complete && !account_complete {
            break;
        }
    }
    Ok((global_complete, account_complete))
}

async fn advance_summary_all_time_coverage_checkpoint_scope(
    pool: &Pool<Sqlite>,
    scope: &str,
    high_watermark_id: i64,
) -> Result<bool> {
    let checkpoint = load_summary_all_time_coverage_checkpoint(pool, scope).await?;
    let (next_manifest_id, completed) = match checkpoint {
        Some(checkpoint)
            if checkpoint.manifest_high_watermark_id == high_watermark_id
                && checkpoint.completed != 0 =>
        {
            return Ok(true);
        }
        Some(checkpoint) if checkpoint.manifest_high_watermark_id == high_watermark_id => {
            (checkpoint.next_manifest_id, false)
        }
        _ => (0, false),
    };
    if completed {
        return Ok(true);
    }
    let page = load_summary_projection_boundary_manifest_page(
        pool,
        None,
        (next_manifest_id > 0).then_some(next_manifest_id),
        high_watermark_id,
    )
    .await?;
    if page.archives.is_empty() {
        store_summary_all_time_coverage_checkpoint(
            pool,
            scope,
            high_watermark_id,
            next_manifest_id,
            true,
        )
        .await?;
        debug!(scope, "summary all-time coverage checkpoint completed");
        return Ok(true);
    }
    let (global_complete, account_complete) =
        summary_all_time_coverage_page_is_exact(pool, &page).await?;
    let page_complete = match scope {
        SUMMARY_ALL_TIME_COVERAGE_SCOPE_GLOBAL => global_complete,
        SUMMARY_ALL_TIME_COVERAGE_SCOPE_ACCOUNT => account_complete,
        _ => {
            return Err(anyhow!(
                "unknown summary all-time coverage checkpoint scope"
            ));
        }
    };
    if !page_complete {
        debug!(
            scope,
            manifest_count = page.archives.len(),
            "summary all-time coverage checkpoint waiting for exact page proof"
        );
        return Ok(false);
    }
    let next_after_id = page
        .next_after_id
        .expect("non-empty summary all-time coverage page has a seek cursor");
    store_summary_all_time_coverage_checkpoint(
        pool,
        scope,
        high_watermark_id,
        next_after_id,
        false,
    )
    .await?;
    debug!(
        scope,
        manifest_count = page.archives.len(),
        "summary all-time coverage checkpoint advanced"
    );
    Ok(false)
}

pub(crate) async fn advance_summary_all_time_coverage_checkpoint(
    pool: &Pool<Sqlite>,
) -> Result<SummaryAllTimeCoverageProgress> {
    let manifest_count = sqlx::query_scalar::<_, i64>(
        "SELECT COUNT(*) FROM archive_batches \
         WHERE dataset = 'codex_invocations' AND status = 'completed' \
           AND COALESCE(summary_source_kind, 'unknown') <> 'live_mirror'",
    )
    .fetch_one(pool)
    .await
    .context("summary all-time coverage checkpoint count failed")?;
    if manifest_count <= SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES as i64 {
        return Ok(SummaryAllTimeCoverageProgress {
            global_complete: true,
            account_complete: true,
        });
    }
    let Some(high_watermark_id) =
        summary_projection_completed_manifest_high_watermark(pool).await?
    else {
        return Ok(SummaryAllTimeCoverageProgress {
            global_complete: true,
            account_complete: true,
        });
    };
    let global_complete = advance_summary_all_time_coverage_checkpoint_scope(
        pool,
        SUMMARY_ALL_TIME_COVERAGE_SCOPE_GLOBAL,
        high_watermark_id,
    )
    .await?;
    let account_complete = advance_summary_all_time_coverage_checkpoint_scope(
        pool,
        SUMMARY_ALL_TIME_COVERAGE_SCOPE_ACCOUNT,
        high_watermark_id,
    )
    .await?;
    Ok(SummaryAllTimeCoverageProgress {
        global_complete,
        account_complete,
    })
}

const SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE: &str = "all";
const SUMMARY_PROJECTION_ALL_TIME_ROLLUP_PAGE_SIZE: i64 = 512;
// Coverage proof pages are deliberately smaller than the normal manifest hydration chunk. Each
// archive range is checked against its concrete compact rollup keys, keeping proof memory and
// query work bounded even when thousands of manifests share one retention horizon.
const SUMMARY_PROJECTION_ALL_TIME_MANIFEST_PROOF_PAGE_SIZE: usize = 32;

#[derive(Debug, Clone, sqlx::FromRow)]
struct SummaryAllTimeProjectionCheckpointRow {
    live_high_watermark_id: i64,
    rollup_live_cursor: i64,
    account_rollup_live_cursor: Option<i64>,
    manifest_high_watermark_id: Option<i64>,
    durable_terminal_sequence_watermark: i64,
    global_manifest_next_id: i64,
    account_manifest_next_id: i64,
    global_manifest_complete: i64,
    account_manifest_complete: i64,
    global_rollup_next_rowid: i64,
    account_rollup_next_rowid: i64,
    usage_rollup_next_rowid: i64,
    global_rollup_complete: i64,
    account_rollup_complete: i64,
    usage_rollup_complete: i64,
    account_unavailable: i64,
    global_usage_unavailable: i64,
    account_usage_unavailable: i64,
    global_total_count: i64,
    global_success_count: i64,
    global_failure_count: i64,
    global_total_tokens: i64,
    global_total_cost: f64,
    global_non_success_cost: f64,
}

impl SummaryAllTimeProjectionCheckpointRow {
    fn generation_fence(&self) -> SummaryProjectionGenerationFence {
        SummaryProjectionGenerationFence {
            live_high_watermark_id: self.live_high_watermark_id,
            rollup_live_cursor: self.rollup_live_cursor,
            account_rollup_live_cursor: self.account_rollup_live_cursor,
            completed_manifest_high_watermark_id: self.manifest_high_watermark_id,
            durable_terminal_sequence_watermark: self.durable_terminal_sequence_watermark.max(0)
                as u64,
        }
    }

    fn global_ready(&self) -> bool {
        self.global_manifest_complete != 0
            && self.global_rollup_complete != 0
            && self.usage_rollup_complete != 0
            && self.global_usage_unavailable == 0
    }

    fn account_ready(&self) -> bool {
        self.account_unavailable == 0
            && self.account_manifest_complete != 0
            && self.account_rollup_complete != 0
            && self.usage_rollup_complete != 0
            && self.account_usage_unavailable == 0
    }

    fn global_totals(&self) -> StatsTotals {
        StatsTotals {
            total_count: self.global_total_count,
            success_count: self.global_success_count,
            failure_count: self.global_failure_count,
            total_tokens: self.global_total_tokens,
            total_cost: self.global_total_cost,
            non_success_cost: self.global_non_success_cost,
        }
    }
}

