async fn summary_projection_all_time_staged_recovery_required(pool: &Pool<Sqlite>) -> Result<bool> {
    let count = sqlx::query_scalar::<_, i64>(
        "SELECT COUNT(*) FROM archive_batches \
         WHERE dataset = 'codex_invocations' AND status = 'completed' \
           AND COALESCE(summary_source_kind, 'unknown') <> 'live_mirror'",
    )
    .fetch_one(pool)
    .await
    .context("summary all-time staged recovery admission count failed")?;
    Ok(count > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES as i64)
}

async fn load_summary_all_time_projection_checkpoint(
    pool: &Pool<Sqlite>,
) -> Result<Option<SummaryAllTimeProjectionCheckpointRow>> {
    sqlx::query_as::<_, SummaryAllTimeProjectionCheckpointRow>(
        "SELECT live_high_watermark_id, rollup_live_cursor, account_rollup_live_cursor, \
                manifest_high_watermark_id, durable_terminal_sequence_watermark, \
                global_manifest_next_id, account_manifest_next_id, global_manifest_complete, \
                account_manifest_complete, global_rollup_next_rowid, account_rollup_next_rowid, \
                usage_rollup_next_rowid, global_rollup_complete, account_rollup_complete, \
                usage_rollup_complete, global_usage_unavailable, account_usage_unavailable, account_unavailable, \
                global_total_count, global_success_count, global_failure_count, global_total_tokens, \
                global_total_cost, global_non_success_cost \
         FROM summary_all_time_projection_checkpoint WHERE scope = ?1",
    )
    .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
    .fetch_optional(pool)
    .await
    .context("summary all-time projection checkpoint hydration failed")
}

async fn reset_summary_all_time_projection_checkpoint(
    pool: &Pool<Sqlite>,
    generation_fence: SummaryProjectionGenerationFence,
) -> Result<SummaryAllTimeProjectionCheckpointRow> {
    let mut transaction = pool
        .begin()
        .await
        .context("summary all-time projection checkpoint reset transaction failed")?;
    sqlx::query("DELETE FROM summary_all_time_projection_account_checkpoint WHERE scope = ?1")
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(&mut *transaction)
        .await
        .context("summary all-time projection account checkpoint reset failed")?;
    sqlx::query(
        "INSERT INTO summary_all_time_projection_checkpoint \
         (scope, live_high_watermark_id, rollup_live_cursor, account_rollup_live_cursor, \
          manifest_high_watermark_id, durable_terminal_sequence_watermark) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6) \
         ON CONFLICT(scope) DO UPDATE SET \
           live_high_watermark_id = excluded.live_high_watermark_id, \
           rollup_live_cursor = excluded.rollup_live_cursor, \
           account_rollup_live_cursor = excluded.account_rollup_live_cursor, \
           manifest_high_watermark_id = excluded.manifest_high_watermark_id, \
           durable_terminal_sequence_watermark = excluded.durable_terminal_sequence_watermark, \
           global_manifest_next_id = 0, account_manifest_next_id = 0, \
           global_manifest_complete = 0, account_manifest_complete = 0, \
           global_rollup_next_rowid = 0, account_rollup_next_rowid = 0, \
           global_rollup_complete = 0, account_rollup_complete = 0, account_unavailable = 0, \
           global_total_count = 0, global_success_count = 0, global_failure_count = 0, \
           global_total_tokens = 0, global_total_cost = 0, global_non_success_cost = 0, \
           updated_at = datetime('now')",
    )
    .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
    .bind(generation_fence.live_high_watermark_id)
    .bind(generation_fence.rollup_live_cursor)
    .bind(generation_fence.account_rollup_live_cursor)
    .bind(generation_fence.completed_manifest_high_watermark_id)
    .bind(
        generation_fence
            .durable_terminal_sequence_watermark
            .min(i64::MAX as u64) as i64,
    )
    .execute(&mut *transaction)
    .await
    .context("summary all-time projection checkpoint reset failed")?;
    transaction
        .commit()
        .await
        .context("summary all-time projection checkpoint reset commit failed")?;
    load_summary_all_time_projection_checkpoint(pool)
        .await?
        .ok_or_else(|| anyhow!("summary all-time projection checkpoint disappeared after reset"))
}

async fn advance_summary_all_time_projection_manifest_scope(
    pool: &Pool<Sqlite>,
    checkpoint: &SummaryAllTimeProjectionCheckpointRow,
    account_scope: bool,
) -> Result<()> {
    let complete = if account_scope {
        checkpoint.account_manifest_complete != 0
    } else {
        checkpoint.global_manifest_complete != 0
    };
    if complete {
        return Ok(());
    }
    let Some(high_watermark_id) = checkpoint.manifest_high_watermark_id else {
        let column = if account_scope {
            "account_manifest_complete"
        } else {
            "global_manifest_complete"
        };
        sqlx::query(&format!(
            "UPDATE summary_all_time_projection_checkpoint SET {column} = 1, updated_at = datetime('now') WHERE scope = ?1"
        ))
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(pool)
        .await
        .context("summary all-time projection empty manifest checkpoint advance failed")?;
        return Ok(());
    };
    let after_id = if account_scope {
        checkpoint.account_manifest_next_id
    } else {
        checkpoint.global_manifest_next_id
    };
    let page = load_summary_projection_boundary_manifest_page_with_limit(
        pool,
        None,
        (after_id > 0).then_some(after_id),
        high_watermark_id,
        SUMMARY_PROJECTION_ALL_TIME_MANIFEST_PROOF_PAGE_SIZE,
    )
    .await?;
    let column = if account_scope {
        "account_manifest_complete"
    } else {
        "global_manifest_complete"
    };
    let next_column = if account_scope {
        "account_manifest_next_id"
    } else {
        "global_manifest_next_id"
    };
    if page.archives.is_empty() {
        sqlx::query(&format!(
            "UPDATE summary_all_time_projection_checkpoint SET {column} = 1, updated_at = datetime('now') WHERE scope = ?1"
        ))
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(pool)
        .await
        .context("summary all-time projection manifest completion checkpoint failed")?;
        return Ok(());
    }
    let (global_exact, account_exact) =
        summary_all_time_coverage_page_is_exact(pool, &page).await?;
    let scope_exact = if account_scope {
        account_exact
    } else {
        global_exact
    };
    if !scope_exact {
        debug!(
            account_scope,
            manifest_count = page.archives.len(),
            "summary all-time projection manifest page is not exact yet"
        );
        return Ok(());
    }
    let next_after_id = page
        .next_after_id
        .expect("non-empty summary all-time projection manifest page has a seek cursor");
    sqlx::query(&format!(
        "UPDATE summary_all_time_projection_checkpoint \
         SET {next_column} = ?1, updated_at = datetime('now') WHERE scope = ?2"
    ))
    .bind(next_after_id)
    .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
    .execute(pool)
    .await
    .context("summary all-time projection manifest checkpoint advance failed")?;
    debug!(
        account_scope,
        manifest_count = page.archives.len(),
        "summary all-time projection manifest checkpoint advanced"
    );
    Ok(())
}

async fn advance_summary_all_time_projection_global_rollup(
    pool: &Pool<Sqlite>,
    checkpoint: &SummaryAllTimeProjectionCheckpointRow,
) -> Result<()> {
    if checkpoint.global_rollup_complete != 0 {
        return Ok(());
    }
    let rows = sqlx::query_as::<_, SummaryAllTimeCheckpointGlobalRollupRow>(
        "SELECT rowid, total_count, success_count, failure_count, total_tokens, total_cost, \
                COALESCE(non_success_cost, 0.0) AS non_success_cost \
         FROM invocation_rollup_hourly WHERE rowid > ?1 ORDER BY rowid ASC LIMIT ?2",
    )
    .bind(checkpoint.global_rollup_next_rowid)
    .bind(SUMMARY_PROJECTION_ALL_TIME_ROLLUP_PAGE_SIZE)
    .fetch_all(pool)
    .await
    .context("summary all-time projection global rollup page hydration failed")?;
    if rows.is_empty() {
        sqlx::query(
            "UPDATE summary_all_time_projection_checkpoint \
             SET global_rollup_complete = 1, updated_at = datetime('now') WHERE scope = ?1",
        )
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(pool)
        .await
        .context("summary all-time projection global rollup completion failed")?;
        return Ok(());
    }
    let totals = rows.iter().fold(StatsTotals::default(), |totals, row| {
        totals.add(row.totals())
    });
    let next_rowid = rows
        .last()
        .expect("non-empty global rollup page has a rowid")
        .rowid;
    sqlx::query(
        "UPDATE summary_all_time_projection_checkpoint SET \
           global_rollup_next_rowid = ?1, \
           global_total_count = global_total_count + ?2, \
           global_success_count = global_success_count + ?3, \
           global_failure_count = global_failure_count + ?4, \
           global_total_tokens = global_total_tokens + ?5, \
           global_total_cost = global_total_cost + ?6, \
           global_non_success_cost = global_non_success_cost + ?7, \
           updated_at = datetime('now') WHERE scope = ?8",
    )
    .bind(next_rowid)
    .bind(totals.total_count)
    .bind(totals.success_count)
    .bind(totals.failure_count)
    .bind(totals.total_tokens)
    .bind(totals.total_cost)
    .bind(totals.non_success_cost)
    .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
    .execute(pool)
    .await
    .context("summary all-time projection global rollup checkpoint advance failed")?;
    Ok(())
}

async fn advance_summary_all_time_projection_account_rollup(
    pool: &Pool<Sqlite>,
    checkpoint: &SummaryAllTimeProjectionCheckpointRow,
) -> Result<()> {
    if checkpoint.account_rollup_complete != 0 || checkpoint.account_unavailable != 0 {
        return Ok(());
    }
    let rows = sqlx::query_as::<_, SummaryAllTimeCheckpointAccountRollupRow>(
        "SELECT rowid, upstream_account_id, total_count, success_count, failure_count, \
                total_tokens, total_cost, COALESCE(non_success_cost, 0.0) AS non_success_cost \
         FROM upstream_account_stats_hourly \
         WHERE rowid > ?1 AND upstream_account_id > 0 ORDER BY rowid ASC LIMIT ?2",
    )
    .bind(checkpoint.account_rollup_next_rowid)
    .bind(SUMMARY_PROJECTION_ALL_TIME_ROLLUP_PAGE_SIZE)
    .fetch_all(pool)
    .await
    .context("summary all-time projection account rollup page hydration failed")?;
    let mut transaction = pool
        .begin()
        .await
        .context("summary all-time projection account rollup transaction failed")?;
    if rows.is_empty() {
        sqlx::query(
            "UPDATE summary_all_time_projection_checkpoint \
             SET account_rollup_complete = 1, updated_at = datetime('now') WHERE scope = ?1",
        )
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(&mut *transaction)
        .await
        .context("summary all-time projection account rollup completion failed")?;
        transaction
            .commit()
            .await
            .context("summary all-time projection account rollup completion commit failed")?;
        return Ok(());
    }
    for row in &rows {
        let totals = row.totals();
        sqlx::query(
            "INSERT INTO summary_all_time_projection_account_checkpoint \
             (scope, upstream_account_id, total_count, success_count, failure_count, total_tokens, total_cost, non_success_cost) \
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8) \
             ON CONFLICT(scope, upstream_account_id) DO UPDATE SET \
               total_count = total_count + excluded.total_count, \
               success_count = success_count + excluded.success_count, \
               failure_count = failure_count + excluded.failure_count, \
               total_tokens = total_tokens + excluded.total_tokens, \
               total_cost = total_cost + excluded.total_cost, \
               non_success_cost = non_success_cost + excluded.non_success_cost",
        )
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .bind(row.upstream_account_id)
        .bind(totals.total_count)
        .bind(totals.success_count)
        .bind(totals.failure_count)
        .bind(totals.total_tokens)
        .bind(totals.total_cost)
        .bind(totals.non_success_cost)
        .execute(&mut *transaction)
        .await
        .context("summary all-time projection account rollup accumulation failed")?;
    }
    let account_count = sqlx::query_scalar::<_, i64>(
        "SELECT COUNT(*) FROM summary_all_time_projection_account_checkpoint WHERE scope = ?1",
    )
    .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
    .fetch_one(&mut *transaction)
    .await
    .context("summary all-time projection account checkpoint count failed")?;
    let next_rowid = rows
        .last()
        .expect("non-empty account rollup page has a rowid")
        .rowid;
    if account_count > SUMMARY_PROJECTION_MAX_ACCOUNTS as i64 {
        sqlx::query(
            "UPDATE summary_all_time_projection_checkpoint SET \
             account_unavailable = 1, account_rollup_complete = 1, \
             updated_at = datetime('now') WHERE scope = ?1",
        )
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(&mut *transaction)
        .await
        .context("summary all-time projection account cardinality checkpoint failed")?;
    } else {
        sqlx::query(
            "UPDATE summary_all_time_projection_checkpoint SET \
             account_rollup_next_rowid = ?1, updated_at = datetime('now') WHERE scope = ?2",
        )
        .bind(next_rowid)
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .execute(&mut *transaction)
        .await
        .context("summary all-time projection account rollup checkpoint advance failed")?;
    }
    transaction
        .commit()
        .await
        .context("summary all-time projection account rollup checkpoint commit failed")?;
    Ok(())
}

async fn load_summary_projection_generation_fence(
    state: &AppState,
) -> Result<SummaryProjectionGenerationFence> {
    let durable_terminal_sequence_watermark = state
        .dashboard_activity_snapshot_cache
        .lock()
        .await
        .read_model
        .settled_terminal_sequence;
    Ok(SummaryProjectionGenerationFence {
        live_high_watermark_id: load_summary_projection_live_high_watermark(&state.pool).await?,
        rollup_live_cursor: load_summary_projection_rollup_live_cursor(&state.pool).await?,
        account_rollup_live_cursor: load_summary_projection_account_rollup_live_cursor(&state.pool)
            .await?,
        completed_manifest_high_watermark_id: summary_projection_completed_manifest_high_watermark(
            &state.pool,
        )
        .await?,
        durable_terminal_sequence_watermark,
    })
}

async fn advance_summary_all_time_projection_checkpoint(
    state: &AppState,
) -> Result<SummaryAllTimeProjectionCheckpointRow> {
    let generation_fence = load_summary_projection_generation_fence(state).await?;
    let checkpoint = match load_summary_all_time_projection_checkpoint(&state.pool).await? {
        Some(checkpoint)
            if checkpoint
                .generation_fence()
                .durable_sources_match(generation_fence) =>
        {
            checkpoint
        }
        Some(_) => {
            debug!(
                "summary all-time projection checkpoint generation changed; restarting staged recovery"
            );
            reset_summary_all_time_projection_checkpoint(&state.pool, generation_fence).await?
        }
        None => reset_summary_all_time_projection_checkpoint(&state.pool, generation_fence).await?,
    };
    advance_summary_all_time_projection_manifest_scope(&state.pool, &checkpoint, false).await?;
    let checkpoint = load_summary_all_time_projection_checkpoint(&state.pool)
        .await?
        .expect("summary all-time projection checkpoint exists after global manifest advance");
    advance_summary_all_time_projection_manifest_scope(&state.pool, &checkpoint, true).await?;
    let checkpoint = load_summary_all_time_projection_checkpoint(&state.pool)
        .await?
        .expect("summary all-time projection checkpoint exists after account manifest advance");
    advance_summary_all_time_projection_global_rollup(&state.pool, &checkpoint).await?;
    let checkpoint = load_summary_all_time_projection_checkpoint(&state.pool)
        .await?
        .expect("summary all-time projection checkpoint exists after global rollup advance");
    advance_summary_all_time_projection_account_rollup(&state.pool, &checkpoint).await?;
    // Usage is independently bounded by the existing rollup reader. Mark it ready only after
    // the complete exact usage snapshot has been proven; an over-budget snapshot remains
    // unavailable instead of publishing totals without model/cache detail.
    let usage_ready = match load_summary_projection_rollup_usage(&state.pool).await {
        Ok(_) => (1_i64, 0_i64, 0_i64),
        Err(error) if error.to_string().contains("budget") => (1_i64, 1_i64, 1_i64),
        Err(error) => return Err(error),
    };
    sqlx::query("UPDATE summary_all_time_projection_checkpoint SET usage_rollup_complete = ?1, global_usage_unavailable = ?2, account_usage_unavailable = ?3, updated_at = datetime('now') WHERE scope = ?4")
        .bind(usage_ready.0).bind(usage_ready.1).bind(usage_ready.2)
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE).execute(&state.pool).await?;
    let checkpoint = load_summary_all_time_projection_checkpoint(&state.pool)
        .await?
        .expect("summary all-time projection checkpoint exists after account rollup advance");
    if load_summary_projection_generation_fence(state).await? != generation_fence {
        return Err(SummaryProjectionAllTimeGenerationChanged.into());
    }
    Ok(checkpoint)
}

async fn summary_all_time_projection_checkpoint_live_tail_count(
    pool: &Pool<Sqlite>,
    lower_bound_id: i64,
    upper_bound_id: i64,
    scope: &'static str,
) -> Result<()> {
    if upper_bound_id <= lower_bound_id {
        return Ok(());
    }
    let count = sqlx::query_scalar::<_, i64>(
        "SELECT COUNT(*) FROM codex_invocations WHERE id > ?1 AND id <= ?2",
    )
    .bind(lower_bound_id)
    .bind(upper_bound_id)
    .fetch_one(pool)
    .await
    .with_context(|| format!("summary all-time {scope} live-tail admission count failed"))?;
    if count > summary_projection_exact_record_limit() as i64 {
        return Err(anyhow!(
            "summary all-time {scope} live-tail admission exceeded bounded record budget ({count} > {})",
            summary_projection_exact_record_limit()
        ));
    }
    Ok(())
}

async fn publish_summary_all_time_projection_checkpoint(
    state: &AppState,
    checkpoint: SummaryAllTimeProjectionCheckpointRow,
) -> Result<()> {
    if !checkpoint.global_ready() && !checkpoint.account_ready() {
        return Ok(());
    }
    let generation_fence = checkpoint.generation_fence();
    if load_summary_projection_generation_fence(state).await? != generation_fence {
        return Err(SummaryProjectionAllTimeGenerationChanged.into());
    }
    let projection = state
        .subscription_hub
        .summary_projection()
        .await
        .ok_or_else(|| {
            anyhow!("summary all-time checkpoint requires a published rolling projection")
        })?;
    if projection.generation_fence != generation_fence {
        return Err(SummaryProjectionAllTimeGenerationChanged.into());
    }
    let mut next = Arc::unwrap_or_clone(projection);
    let published_at = Instant::now();
    let mut account_ids = HashSet::new();

    let hourly_rollup_usage = if checkpoint.global_ready() || checkpoint.account_ready() {
        load_summary_projection_rollup_usage(&state.pool).await?
    } else {
        HashMap::new()
    };
    if checkpoint.global_ready() {
        summary_all_time_projection_checkpoint_live_tail_count(
            &state.pool,
            generation_fence.rollup_live_cursor,
            generation_fence.live_high_watermark_id,
            "global",
        )
        .await?;
        let live_tail =
            if generation_fence.live_high_watermark_id > generation_fence.rollup_live_cursor {
                crate::stats::query_live_invocation_totals_after_id(
                    &state.pool,
                    InvocationSourceScope::All,
                    generation_fence.rollup_live_cursor,
                    generation_fence.live_high_watermark_id,
                )
                .await
                .map_err(|error| {
                    anyhow!("summary all-time staged global live-tail hydration failed: {error:?}")
                })?
            } else {
                StatsTotals::default()
            };
        let mut totals = checkpoint.global_totals().add(live_tail);
        let mut exact_record_ids = HashSet::new();
        for record in next.records.iter().chain(next.current_records.iter()) {
            if !exact_record_ids.insert(record.row.invoke_id.as_str())
                || !summary_projection_all_time_uses_global_exact_record(
                    record,
                    generation_fence.rollup_live_cursor,
                )
            {
                continue;
            }
            totals = totals.add(summary_projection_all_time_record_totals(record));
        }
        let mut usage = UsageBreakdownAccumulator::default();
        for (key, value) in &hourly_rollup_usage {
            if key.1.is_none() {
                usage.merge_response(value);
            }
        }
        let mut response = totals.into_response();
        response.usage_breakdown = Some(usage.into_response());
        response.non_success_cost = Some(totals.non_success_cost);
        response.maintenance = next.maintenance.clone();
        let in_progress = next
            .in_progress_by_account
            .get(&None)
            .copied()
            .unwrap_or_default();
        response.in_progress_conversation_count = Some(in_progress.in_progress_count);
        response.in_progress_retry_conversation_count = Some(in_progress.retry_count);
        response.in_progress_avg_wait_ms = in_progress.avg_wait_ms;
        response.in_progress_phase_counts = Some(in_progress.phase_counts);
        next.all_time_by_account.insert(None, response);
        next.all_time_refreshed_at = Some(published_at);
        next.freshness.global_all_time_eligible = true;
        next.all_time_terminal_coverage_complete = true;
        next.all_time_terminal_sequence_watermark =
            generation_fence.durable_terminal_sequence_watermark;
        next.all_time_persisted_live_terminal_invoke_ids = next
            .records
            .iter()
            .chain(next.current_records.iter())
            .filter(|record| record.is_persisted_live_record)
            .map(|record| format!("{}\0{}", record.row.invoke_id, record.row.occurred_at))
            .collect();
    }

    if checkpoint.account_ready()
        && let Some(account_rollup_live_cursor) = generation_fence.account_rollup_live_cursor
    {
        summary_all_time_projection_checkpoint_live_tail_count(
            &state.pool,
            account_rollup_live_cursor,
            generation_fence.live_high_watermark_id,
            "account",
        )
        .await?;
        let mut account_totals = sqlx::query_as::<_, SummaryAllTimeCheckpointAccountTotalsRow>(
            "SELECT upstream_account_id, total_count, success_count, failure_count, total_tokens, \
                    total_cost, non_success_cost \
             FROM summary_all_time_projection_account_checkpoint WHERE scope = ?1",
        )
        .bind(SUMMARY_ALL_TIME_PROJECTION_CHECKPOINT_SCOPE)
        .fetch_all(&state.pool)
        .await
        .context("summary all-time projection account checkpoint finalization failed")?
        .into_iter()
        .map(|row| (row.upstream_account_id, row.totals()))
        .collect::<HashMap<_, _>>();
        if generation_fence.live_high_watermark_id > account_rollup_live_cursor {
            for (account_id, totals) in load_summary_projection_live_tail_account_totals(
                &state.pool,
                Some(account_rollup_live_cursor),
                Some(generation_fence.live_high_watermark_id),
            )
            .await?
            {
                let entry = account_totals.entry(account_id).or_default();
                *entry = entry.add(totals);
            }
        }
        let mut exact_record_ids = HashSet::new();
        for record in next.records.iter().chain(next.current_records.iter()) {
            if !exact_record_ids.insert(record.row.invoke_id.as_str())
                || !summary_projection_all_time_uses_account_exact_record(
                    record,
                    generation_fence.account_rollup_live_cursor,
                )
            {
                continue;
            }
            let Some((account_id, totals)) = summary_projection_account_record_totals(record)
            else {
                continue;
            };
            let entry = account_totals.entry(account_id).or_default();
            *entry = entry.add(totals);
        }
        if account_totals.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
            return Err(anyhow!(
                "summary all-time staged account finalization exceeded bounded account budget ({})",
                account_totals.len()
            ));
        }
        for (account_id, totals) in account_totals {
            let mut usage = UsageBreakdownAccumulator::default();
            for (key, value) in &hourly_rollup_usage {
                if key.1 == Some(account_id) {
                    usage.merge_response(value);
                }
            }
            let mut response = totals.into_response();
            response.usage_breakdown = Some(usage.into_response());
            response.non_success_cost = Some(totals.non_success_cost);
            response.maintenance = next.maintenance.clone();
            let in_progress = next
                .in_progress_by_account
                .get(&Some(account_id))
                .copied()
                .unwrap_or_default();
            response.in_progress_conversation_count = Some(in_progress.in_progress_count);
            response.in_progress_retry_conversation_count = Some(in_progress.retry_count);
            response.in_progress_avg_wait_ms = in_progress.avg_wait_ms;
            response.in_progress_phase_counts = Some(in_progress.phase_counts);
            next.all_time_by_account.insert(Some(account_id), response);
            next.all_time_account_refreshed_at
                .insert(account_id, published_at);
            next.freshness.account_all_time_eligible.insert(account_id);
            next.all_time_account_terminal_sequence_watermarks.insert(
                account_id,
                generation_fence.durable_terminal_sequence_watermark,
            );
            account_ids.insert(account_id);
        }
        next.all_time_account_ids_with_projection_data
            .extend(account_ids.iter().copied());
        next.known_account_ids.extend(account_ids.iter().copied());
        next.all_time_account_manifest_admission_blocked_at = None;
    } else if checkpoint.account_unavailable != 0 {
        next.all_time_account_manifest_admission_blocked_at = Some(published_at);
    }

    next.all_time_oldest_account_refreshed_at =
        next.all_time_account_refreshed_at.values().copied().min();
    next.revision = state
        .subscription_hub
        .next_summary_projection_revision()
        .await;
    if load_summary_projection_generation_fence(state).await? != generation_fence {
        return Err(SummaryProjectionAllTimeGenerationChanged.into());
    }
    state.subscription_hub.store_summary_projection(next).await;
    debug!(
        global_ready = checkpoint.global_ready(),
        account_ready = checkpoint.account_ready(),
        "summary all-time staged projection published"
    );
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SummaryProjectionOverflowedBoundaryCoverage {
    high_watermark_id: i64,
    unknown_coverage_ranges: Vec<ExactUtcRange>,
}

async fn summary_projection_overflowed_boundary_manifest_coverage(
    pool: &Pool<Sqlite>,
    exact_horizon: ExactUtcRange,
) -> Result<Option<SummaryProjectionOverflowedBoundaryCoverage>> {
    // The overflow path pages manifest metadata even when some partitions lack durable replay.
    // Bounded gaps are localized by the exact-range admission below. A legacy manifest without
    // bounds is localized from its immutable `month_key`; malformed keys retain the requested
    // horizon as the conservative fail-closed fallback.
    let Some(high_watermark_id) =
        summary_projection_completed_manifest_high_watermark(pool).await?
    else {
        return Ok(None);
    };
    let month_keys = sqlx::query_scalar::<_, String>(
        "SELECT DISTINCT batches.month_key FROM archive_batches AS batches \
         WHERE batches.dataset = 'codex_invocations' \
           AND batches.status = 'completed' \
           AND COALESCE(batches.summary_source_kind, 'unknown') <> 'live_mirror' \
           AND batches.id <= ?1 \
           AND (batches.coverage_start_at IS NULL OR batches.coverage_end_at IS NULL) \
         ORDER BY batches.month_key",
    )
    .bind(high_watermark_id)
    .fetch_all(pool)
    .await
    .context("summary projection overflowed boundary manifest coverage hydration failed")?;
    let mut unknown_coverage_ranges = Vec::new();
    for month_key in month_keys {
        let buckets = match crate::stats::archive_bucket_start_epochs_from_bounds(
            Some(&month_key),
            None,
            None,
        ) {
            Ok(buckets) if !buckets.is_empty() => buckets,
            // Without a parseable partition key, no finite source boundary exists. Preserve the
            // established fail-closed behavior, limited to the supported request horizon.
            Ok(_) | Err(_) => {
                unknown_coverage_ranges.push(exact_horizon);
                continue;
            }
        };
        let start_epoch = buckets
            .iter()
            .min()
            .copied()
            .expect("non-empty archive buckets");
        let end_epoch = buckets
            .iter()
            .max()
            .copied()
            .expect("non-empty archive buckets")
            + 3_600;
        let Some(start) = Utc.timestamp_opt(start_epoch, 0).single() else {
            unknown_coverage_ranges.push(exact_horizon);
            continue;
        };
        let Some(end) = Utc.timestamp_opt(end_epoch, 0).single() else {
            unknown_coverage_ranges.push(exact_horizon);
            continue;
        };
        let localized = ExactUtcRange {
            start: start.max(exact_horizon.start),
            end: end.min(exact_horizon.end),
        };
        if localized.start < localized.end {
            unknown_coverage_ranges.push(localized);
        }
    }
    let unknown_coverage_ranges = summary_projection_merge_exact_ranges(unknown_coverage_ranges);
    Ok(Some(SummaryProjectionOverflowedBoundaryCoverage {
        high_watermark_id,
        unknown_coverage_ranges,
    }))
}

async fn summary_projection_overflowed_all_time_manifests_have_complete_rollups(
    pool: &Pool<Sqlite>,
) -> Result<Option<i64>> {
    let Some(high_watermark_id) =
        summary_projection_completed_manifest_high_watermark(pool).await?
    else {
        return Ok(None);
    };
    let incomplete = sqlx::query_scalar::<_, i64>(
        "SELECT EXISTS( \
             SELECT 1 FROM archive_batches AS batches \
             WHERE batches.dataset = 'codex_invocations' \
               AND batches.status = 'completed' \
               AND COALESCE(batches.summary_source_kind, 'unknown') <> 'live_mirror' \
               AND batches.id <= ?1 \
               AND ( \
                    batches.coverage_start_at IS NULL \
                    OR batches.coverage_end_at IS NULL \
                    OR batches.historical_rollups_materialized_at IS NULL \
                    OR NOT EXISTS( \
                        SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                        WHERE replay.dataset = batches.dataset \
                          AND replay.file_path = batches.file_path \
                          AND replay.archive_sha256 = batches.sha256 \
                          AND replay.target = ?2 \
                    ) \
                    OR NOT EXISTS( \
                        SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                        WHERE replay.dataset = batches.dataset \
                          AND replay.file_path = batches.file_path \
                          AND replay.archive_sha256 = batches.sha256 \
                          AND replay.target = ?3 \
                    ) \
                    OR NOT EXISTS( \
                        SELECT 1 FROM hourly_rollup_archive_replay AS replay \
                        WHERE replay.dataset = batches.dataset \
                          AND replay.file_path = batches.file_path \
                          AND replay.archive_sha256 = batches.sha256 \
                          AND replay.target = ?4 \
                    ) \
               ) \
         )",
    )
    .bind(high_watermark_id)
    .bind(HOURLY_ROLLUP_TARGET_INVOCATIONS)
    .bind(HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_STATS_HOURLY)
    .bind(HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_USAGE_BREAKDOWN)
    .fetch_one(pool)
    .await
    .context("summary projection overflowed all-time manifest coverage hydration failed")?;
    Ok((incomplete == 0).then_some(high_watermark_id))
}

#[derive(Debug, Clone, sqlx::FromRow)]
struct SummaryProjectionBoundaryManifestPageRow {
    id: i64,
    file_path: String,
    coverage_start_at: Option<String>,
    coverage_end_at: Option<String>,
    historical_rollups_materialized_at: Option<String>,
    upstream_activity_manifest_refreshed_at: Option<String>,
}

struct SummaryProjectionBoundaryManifestPage {
    archives: Vec<crate::stats::ArchiveBatchPathRow>,
    account_manifest_refreshed_paths: HashSet<String>,
    next_after_id: Option<i64>,
}

async fn load_summary_projection_boundary_manifest_page(
    pool: &Pool<Sqlite>,
    range: Option<ExactUtcRange>,
    after_id: Option<i64>,
    high_watermark_id: i64,
) -> Result<SummaryProjectionBoundaryManifestPage> {
    load_summary_projection_boundary_manifest_page_with_limit(
        pool,
        range,
        after_id,
        high_watermark_id,
        SUMMARY_PROJECTION_ARCHIVE_MANIFEST_QUERY_CHUNK_SIZE,
    )
    .await
}

async fn load_summary_projection_boundary_manifest_page_with_limit(
    pool: &Pool<Sqlite>,
    range: Option<ExactUtcRange>,
    after_id: Option<i64>,
    high_watermark_id: i64,
    page_size: usize,
) -> Result<SummaryProjectionBoundaryManifestPage> {
    let mut query = QueryBuilder::<Sqlite>::new(
        "SELECT id, file_path, coverage_start_at, coverage_end_at, \
                historical_rollups_materialized_at, upstream_activity_manifest_refreshed_at \
         FROM archive_batches \
         WHERE dataset = 'codex_invocations' \
           AND status = 'completed' \
           AND COALESCE(summary_source_kind, 'unknown') <> 'live_mirror'",
    );
    if let Some(after_id) = after_id {
        query.push(" AND id > ").push_bind(after_id);
    }
    query.push(" AND id <= ").push_bind(high_watermark_id);
    if let Some(range) = range {
        query
            .push(" AND coverage_end_at >= ")
            .push_bind(db_occurred_at_upper_bound(range.start))
            .push(" AND coverage_start_at < ")
            .push_bind(crate::stats::db_occurred_at_lower_bound(range.end));
    }
    let rows = query
        .push(" ORDER BY id ASC LIMIT ")
        .push_bind(page_size as i64)
        .build_query_as::<SummaryProjectionBoundaryManifestPageRow>()
        .fetch_all(pool)
        .await
        .context("summary projection boundary manifest page hydration failed")?;
    let next_after_id = rows.last().map(|row| row.id);
    let account_manifest_refreshed_paths = rows
        .iter()
        .filter(|row| row.upstream_activity_manifest_refreshed_at.is_some())
        .map(|row| row.file_path.clone())
        .collect();
    let archives = rows
        .into_iter()
        .map(|row| {
            crate::stats::ArchiveBatchPathRow::with_coverage_and_historical_rollups(
                row.file_path,
                row.coverage_start_at,
                row.coverage_end_at,
                row.historical_rollups_materialized_at,
            )
        })
        .collect();
    Ok(SummaryProjectionBoundaryManifestPage {
        archives,
        account_manifest_refreshed_paths,
        next_after_id,
    })
}

async fn load_summary_projection_archive_manifest_account_sets(
    pool: &Pool<Sqlite>,
    archive_paths: &[String],
) -> Result<HashMap<String, HashSet<i64>>> {
    let mut account_ids_by_file = archive_paths
        .iter()
        .cloned()
        .map(|path| (path, HashSet::new()))
        .collect::<HashMap<_, _>>();
    for (file_path, account_id) in
        load_summary_projection_archive_manifest_accounts(pool, archive_paths).await?
    {
        if let Some(account_ids) = account_ids_by_file.get_mut(&file_path) {
            account_ids.insert(account_id);
        }
    }
    Ok(account_ids_by_file)
}

fn summary_projection_all_time_manifest_scope_coverage(
    archive: &crate::stats::ArchiveBatchPathRow,
    replay_coverage: SummaryProjectionArchiveReplayCoverage,
    account_manifest_complete: bool,
    account_ids: &HashSet<i64>,
    hourly_rollup_totals: &HashMap<(i64, Option<i64>), StatsTotals>,
) -> Result<(bool, bool)> {
    let Some(range) = summary_projection_archive_coverage_range(archive) else {
        return Ok((false, false));
    };
    if summary_projection_exact_range_fits_bucket_budget(range).is_err() {
        return Ok((false, false));
    }
    let mut global_covered = replay_coverage.overall;
    let mut accounts_covered = replay_coverage.account_stats && account_manifest_complete;
    let mut bucket = align_bucket_epoch(range.start.timestamp(), 3_600, 0);
    let last_bucket = align_bucket_epoch(range.end.timestamp().saturating_sub(1), 3_600, 0);
    while bucket <= last_bucket {
        global_covered &= hourly_rollup_totals.contains_key(&(bucket, None));
        accounts_covered &= account_ids
            .iter()
            .all(|account_id| hourly_rollup_totals.contains_key(&(bucket, Some(*account_id))));
        if !global_covered && !accounts_covered {
            break;
        }
        bucket = bucket.saturating_add(3_600);
    }
    Ok((global_covered, accounts_covered))
}

async fn summary_projection_paged_all_time_materialized_scope_coverage(
    pool: &Pool<Sqlite>,
    high_watermark_id: i64,
    hourly_rollup_totals: &HashMap<(i64, Option<i64>), StatsTotals>,
) -> Result<(bool, bool, HashSet<i64>)> {
    let mut global_covered = true;
    let mut accounts_covered = true;
    let mut discovered_account_ids = HashSet::new();
    let mut after_id = None;
    loop {
        let page =
            load_summary_projection_boundary_manifest_page(pool, None, after_id, high_watermark_id)
                .await?;
        if page.archives.is_empty() {
            break;
        }
        let paths = page
            .archives
            .iter()
            .map(|archive| archive.file_path().to_string())
            .collect::<Vec<_>>();
        let replay_coverage = load_summary_projection_archive_replay_coverage(pool, &paths).await?;
        let account_ids_by_file =
            match load_summary_projection_archive_manifest_account_sets(pool, &paths).await {
                Ok(account_ids_by_file) => account_ids_by_file,
                Err(error)
                    if error.to_string().starts_with(
                        "summary projection archive account manifest exceeded bounded row budget",
                    ) =>
                {
                    accounts_covered = false;
                    paths
                        .iter()
                        .cloned()
                        .map(|path| (path, HashSet::new()))
                        .collect()
                }
                Err(error) => return Err(error),
            };
        for archive in &page.archives {
            let account_ids = account_ids_by_file
                .get(archive.file_path())
                .expect("page account manifest includes every requested archive path");
            if accounts_covered {
                discovered_account_ids.extend(account_ids.iter().copied());
                if discovered_account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
                    accounts_covered = false;
                    discovered_account_ids.clear();
                }
            }
            let replay = replay_coverage
                .get(archive.file_path())
                .copied()
                .unwrap_or_default();
            let (archive_global_covered, archive_accounts_covered) =
                summary_projection_all_time_manifest_scope_coverage(
                    archive,
                    replay,
                    page.account_manifest_refreshed_paths
                        .contains(archive.file_path()),
                    account_ids,
                    hourly_rollup_totals,
                )?;
            global_covered &= archive_global_covered;
            accounts_covered &= archive_accounts_covered;
        }
        let Some(next_after_id) = page.next_after_id else {
            break;
        };
        after_id = Some(next_after_id);
    }
    Ok((global_covered, accounts_covered, discovered_account_ids))
}

async fn load_summary_projection_durable_account_ids(pool: &Pool<Sqlite>) -> Result<HashSet<i64>> {
    let pool_rows =
        sqlx::query_scalar::<_, i64>("SELECT id FROM pool_upstream_accounts WHERE id > 0 LIMIT ?1")
            .bind((SUMMARY_PROJECTION_MAX_ACCOUNTS + 1) as i64)
            .fetch_all(pool)
            .await
            .context("summary projection account hydration failed")?;
    let rollup_rows = sqlx::query_scalar::<_, i64>(
        "SELECT DISTINCT upstream_account_id \
         FROM upstream_account_stats_hourly \
         WHERE upstream_account_id > 0 \
         LIMIT ?1",
    )
    .bind((SUMMARY_PROJECTION_MAX_ACCOUNTS + 1) as i64)
    .fetch_all(pool)
    .await
    .context("summary projection historical account hydration failed")?;
    if pool_rows.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS
        || rollup_rows.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS
    {
        return Err(anyhow!(
            "summary projection durable account cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
        ));
    }
    Ok(pool_rows.into_iter().chain(rollup_rows).collect())
}

async fn restore_summary_projection_persisted_statuses(
    connection: &mut SqliteConnection,
    rows: &mut [UpstreamAccountInvocationPreviewRow],
) -> Result<()> {
    const STATUS_HYDRATION_CHUNK_SIZE: usize = 500;
    let ids = rows.iter().map(|row| row.id).collect::<Vec<_>>();
    let mut statuses = HashMap::<i64, Option<String>>::new();
    for chunk in ids.chunks(STATUS_HYDRATION_CHUNK_SIZE) {
        let mut query =
            QueryBuilder::<Sqlite>::new("SELECT id, status FROM codex_invocations WHERE id IN (");
        {
            let mut separated = query.separated(", ");
            for id in chunk {
                separated.push_bind(*id);
            }
        }
        query.push(")");
        statuses.extend(
            query
                .build_query_as::<(i64, Option<String>)>()
                .fetch_all(&mut *connection)
                .await?,
        );
    }
    for row in rows {
        if let Some(status) = statuses.get(&row.id).and_then(|status| status.clone()) {
            row.status = status;
        }
    }
    Ok(())
}

fn summary_projection_live_record_from_preview(
    row: UpstreamAccountInvocationPreviewRow,
    rollup_live_cursor: i64,
    account_rollup_live_cursor: Option<i64>,
    hourly_rollup_totals: &HashMap<(i64, Option<i64>), StatsTotals>,
    hourly_rollup_usage: &HashMap<(i64, Option<i64>), UsageBreakdownResponse>,
) -> Option<(String, SummaryProjectionRecord)> {
    let occurred_at = parse_to_utc_datetime(&row.occurred_at)?;
    let bucket = align_bucket_epoch(occurred_at.timestamp(), 3_600, 0);
    let global_rollup_covered =
        row.id <= rollup_live_cursor && hourly_rollup_totals.contains_key(&(bucket, None));
    let account_rollup_covered = account_rollup_live_cursor.is_some_and(|cursor| row.id <= cursor)
        && hourly_rollup_totals.contains_key(&(bucket, row.upstream_account_id));
    let usage_global_rollup_covered =
        row.id <= rollup_live_cursor && hourly_rollup_usage.contains_key(&(bucket, None));
    let usage_account_rollup_covered = account_rollup_live_cursor
        .is_some_and(|cursor| row.id <= cursor)
        && hourly_rollup_usage.contains_key(&(bucket, row.upstream_account_id));
    Some((
        row.invoke_id.clone(),
        SummaryProjectionRecord {
            global_rollup_covered,
            account_rollup_covered,
            usage_global_rollup_covered,
            usage_account_rollup_covered,
            is_persisted_live_record: true,
            is_archive_record: false,
            archive_has_materialized_rollups: false,
            account_archive_totals_fallback_included: false,
            row,
            occurred_at,
        },
    ))
}

#[derive(Clone, Default)]
struct PreviousSummaryProjectionAllTime {
    all_time_by_account: HashMap<Option<i64>, StatsResponse>,
    all_time_refreshed_at: Option<Instant>,
    all_time_manifest_admission_blocked_at: Option<Instant>,
    all_time_account_manifest_admission_blocked_at: Option<Instant>,
    all_time_account_refreshed_at: HashMap<i64, Instant>,
    archive_account_ids_by_file: HashMap<String, HashSet<i64>>,
    archive_coverage_ranges_by_file: HashMap<String, ExactUtcRange>,
    global_all_time_eligible: bool,
    account_all_time_eligible: HashSet<i64>,
    all_time_terminal_coverage_complete: bool,
    all_time_terminal_sequence_watermark: u64,
    all_time_persisted_live_terminal_invoke_ids: HashSet<String>,
    all_time_account_terminal_sequence_watermarks: HashMap<i64, u64>,
    all_time_account_persisted_live_terminal_invoke_ids: HashMap<i64, HashSet<String>>,
    historical_live_coverage: Option<SummaryProjectionHistoricalLiveCoverage>,
    unavailable_exact_live_ranges: Vec<ExactUtcRange>,
    unavailable_exact_live_account_ranges: HashMap<i64, Vec<ExactUtcRange>>,
    persisted_live_terminal_invoke_ids: HashSet<String>,
}

/// Reads every input needed by the hot path while running off-request.  The resulting projection
/// is swapped atomically in the subscription hub only after the complete baseline is available.
async fn build_summary_projection(
    state: &AppState,
    mode: SummaryProjectionBuildMode,
    previous_all_time: Option<PreviousSummaryProjectionAllTime>,
    durable_terminal_sequence_watermark: u64,
) -> Result<SummaryProjection> {
    #[cfg(test)]
    if state.config.database_path == std::path::Path::new(":memory:") {
        // Stateful unit fixtures use a private shared-memory URI while their AppConfig retains
        // `:memory:`. A second URI would point at a blank database, so exercise the regular
        // bounded builder directly in those fixtures.
        return build_summary_projection_once(
            state,
            &state.pool,
            mode,
            previous_all_time,
            durable_terminal_sequence_watermark,
        )
        .await;
    }

    // Hydration issues hundreds of bounded queries. Keep them on one read transaction so a
    // retention commit cannot mix an old rollup with a replacement manifest. WAL readers do not
    // block terminal writers, unlike a global `data_version` retry which treats any new request
    // as a source invalidation and can leave the first snapshot unavailable under normal load.
    let snapshot_options = SqliteConnectOptions::from_str(&state.config.database_url())
        .context("summary projection snapshot connection options failed")?
        .create_if_missing(false)
        .journal_mode(SqliteJournalMode::Wal)
        .busy_timeout(Duration::from_secs(DEFAULT_SQLITE_BUSY_TIMEOUT_SECS));
    let snapshot_pool = SqlitePoolOptions::new()
        .max_connections(1)
        .connect_with(snapshot_options)
        .await
        .context("summary projection snapshot connection failed")?;
    let mut connection = snapshot_pool
        .acquire()
        .await
        .context("summary projection snapshot acquisition failed")?;
    sqlx::query("BEGIN")
        .execute(&mut *connection)
        .await
        .context("summary projection snapshot begin failed")?;
    drop(connection);

    let build = build_summary_projection_once(
        state,
        &snapshot_pool,
        mode,
        previous_all_time,
        durable_terminal_sequence_watermark,
    )
    .await;
    let rollback = sqlx::query("ROLLBACK")
        .execute(&snapshot_pool)
        .await
        .context("summary projection snapshot rollback failed");
    snapshot_pool.close().await;

    match (build, rollback) {
        (Ok(projection), Ok(_)) => Ok(projection),
        (Ok(_), Err(error)) | (Err(error), Ok(_)) | (Err(error), Err(_)) => Err(error),
    }
}

async fn build_summary_projection_once(
    state: &AppState,
    pool: &Pool<Sqlite>,
    mode: SummaryProjectionBuildMode,
    previous_all_time: Option<PreviousSummaryProjectionAllTime>,
    durable_terminal_sequence_watermark: u64,
) -> Result<SummaryProjection> {
    let build_started_at = Instant::now();
    info!(
        ?mode,
        stage = "rollup_load",
        "summary projection build stage started"
    );
    let end = Utc::now() + ChronoDuration::seconds(1);
    let PreviousSummaryProjectionAllTime {
        mut all_time_by_account,
        all_time_refreshed_at: previous_all_time_refreshed_at,
        all_time_manifest_admission_blocked_at: previous_all_time_manifest_admission_blocked_at,
        all_time_account_manifest_admission_blocked_at:
            previous_all_time_account_manifest_admission_blocked_at,
        mut all_time_account_refreshed_at,
        mut archive_account_ids_by_file,
        mut archive_coverage_ranges_by_file,
        global_all_time_eligible: previous_global_all_time_eligible,
        account_all_time_eligible: previous_account_all_time_eligible,
        all_time_terminal_coverage_complete: previous_all_time_terminal_coverage_complete,
        all_time_terminal_sequence_watermark: previous_all_time_terminal_sequence_watermark,
        all_time_persisted_live_terminal_invoke_ids:
            previous_all_time_persisted_live_terminal_invoke_ids,
        all_time_account_terminal_sequence_watermarks:
            previous_all_time_account_terminal_sequence_watermarks,
        all_time_account_persisted_live_terminal_invoke_ids:
            previous_all_time_account_persisted_live_terminal_invoke_ids,
        historical_live_coverage: previous_historical_live_coverage,
        unavailable_exact_live_ranges: previous_unavailable_exact_live_ranges,
        unavailable_exact_live_account_ranges: previous_unavailable_exact_live_account_ranges,
        persisted_live_terminal_invoke_ids: previous_persisted_live_terminal_invoke_ids,
    } = previous_all_time.unwrap_or_default();
    let all_time_was_fully_rebuilt = mode.includes_all_time()
        && summary_projection_manifest_admission_retry_is_due(
            previous_all_time_manifest_admission_blocked_at,
            Instant::now(),
        );
    // Materialized hourly rollups are the canonical historical baseline. Raw live preview rows
    // are limited to the moving exact tail; older live rows are represented by their durable
    // hourly rollups. Archive boundary rows use the wider finite range below so supported 7d/
    // calendar views retain exact partial-hour detail without turning a high-retention database
    // into an epoch-zero allocation.
    let archive_start = end - summary_projection_exact_horizon(state.config.invocation_max_days);
    let live_start = end - SUMMARY_PROJECTION_MIN_EXACT_HORIZON;
    let protected_boundary_buckets = summary_projection_boundary_buckets(end);
    let rollup_range = (
        align_bucket_epoch(archive_start.timestamp(), 3_600, 0),
        align_bucket_epoch(end.timestamp(), 3_600, 0) + 3_600,
    );
    let (hourly_rollup_totals, hourly_rollup_non_success_tokens) =
        load_summary_projection_rollup_totals_in_range(pool, Some(rollup_range)).await?;
    let hourly_rollup_usage =
        load_summary_projection_rollup_usage_in_range(pool, Some(rollup_range)).await?;
    info!(
        ?mode,
        stage = "rollup_load",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    #[cfg(test)]
    pause_summary_projection_test_interleave(
        pool,
        mode,
        SummaryProjectionTestInterleaveStage::AfterRollupLoad,
    )
    .await?;
    // Rolling aggregation must still distinguish an archive-backed retention database from a
    // live-only one. This bounded existence probe is independent of the expensive all-history
    // manifest admission below.
    let has_any_completed_archive =
        !crate::stats::load_completed_invocation_archive_paths_in_range_bounded(pool, None, 1)
            .await?
            .is_empty();
    let current_archive_admission = if has_any_completed_archive {
        load_summary_projection_current_archive_admission(pool, live_start).await?
    } else {
        Vec::new()
    };
    let current_archive_admission_exceeded =
        current_archive_admission.len() > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES;
    let mut current_source_unavailable = false;
    let mut current_source_unavailable_from_rank = None::<usize>;
    let mut current_account_source_unavailable_from_rank = HashMap::<i64, usize>::new();
    let mut paged_boundary_manifest_unknown_coverage_ranges = Vec::<ExactUtcRange>::new();
    // All-time aggregation needs manifest-level key proof, while rolling windows only need the
    // bounded exact horizon below. An oversized history is validated in fixed manifest pages
    // against one immutable high-watermark; it never needs an unbounded path vector or a
    // request-time source fallback.
    let (
        all_time_archives,
        mut all_time_archive_admission_exceeded,
        all_time_manifest_high_watermark_id,
    ) = if all_time_was_fully_rebuilt && has_any_completed_archive {
        let archives = crate::stats::load_completed_invocation_archive_paths_in_range_bounded(
            pool,
            None,
            SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES,
        )
        .await?;
        if archives.len() > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES {
            match summary_projection_overflowed_all_time_manifests_have_complete_rollups(pool)
                .await?
            {
                Some(high_watermark_id) => (Vec::new(), false, Some(high_watermark_id)),
                None => (Vec::new(), true, None),
            }
        } else {
            (archives, false, None)
        }
    } else {
        (Vec::new(), false, None)
    };
    let all_time_archive_paths = all_time_archives
        .iter()
        .map(|archive| archive.file_path().to_string())
        .collect::<Vec<_>>();
    let all_time_archive_manifest_sha256 =
        load_summary_projection_archive_manifest_sha256(pool, &all_time_archive_paths).await?;
    let all_time_archive_replay_coverage =
        load_summary_projection_archive_replay_coverage(pool, &all_time_archive_paths).await?;
    let mut all_time_archive_account_ids_by_file = HashMap::<String, HashSet<i64>>::new();
    let mut all_time_archive_account_manifest_refreshed_paths = HashSet::new();
    let all_time_account_manifest_admission_attempted = all_time_was_fully_rebuilt
        && summary_projection_manifest_admission_retry_is_due(
            previous_all_time_account_manifest_admission_blocked_at,
            Instant::now(),
        );
    let mut all_time_account_manifest_admission_exceeded =
        previous_all_time_account_manifest_admission_blocked_at.is_some()
            && !all_time_account_manifest_admission_attempted;
    if all_time_account_manifest_admission_attempted
        && all_time_manifest_high_watermark_id.is_none()
    {
        match load_summary_projection_archive_manifest_account_sets(pool, &all_time_archive_paths)
            .await
        {
            Ok(accounts) => {
                all_time_archive_account_ids_by_file = accounts;
                all_time_archive_account_manifest_refreshed_paths =
                    load_summary_projection_archive_manifest_refreshed_paths(
                        pool,
                        &all_time_archive_paths,
                    )
                    .await?;
            }
            Err(error)
                if error.to_string().starts_with(
                    "summary projection archive account manifest exceeded bounded row budget",
                ) =>
            {
                all_time_account_manifest_admission_exceeded = true;
            }
            Err(error) => return Err(error),
        }
    }
    let rollup_live_cursor = load_summary_projection_rollup_live_cursor(pool).await?;
    let account_rollup_live_cursor =
        load_summary_projection_account_rollup_live_cursor(pool).await?;
    let completed_manifest_high_watermark_id =
        summary_projection_completed_manifest_high_watermark(pool).await?;
    // An all-time live-only rebuild has a separate aggregate admission bound. Resolve that
    // bounded ID snapshot before hydrating the recent index so an all-time overflow can keep
    // current exact at the configured request limit without materializing an unnecessary 50k
    // candidate prefix.
    let live_history_admission = if all_time_was_fully_rebuilt && !has_any_completed_archive {
        summary_projection_live_history_within_aggregate_budget(pool).await?
    } else {
        None
    };
    let live_high_watermark_id = load_summary_projection_live_high_watermark(pool).await?;
    let mut live_preview_cache = HashMap::<i64, UpstreamAccountInvocationPreviewRow>::new();
    info!(
        ?mode,
        stage = "live_exact_admission",
        "summary projection build stage started"
    );
    let live_admission = query_summary_projection_live_rows_with_budget(
        pool,
        InvocationSourceScope::All,
        ExactUtcRange {
            start: live_start,
            end,
        },
        live_high_watermark_id,
        None,
        summary_projection_exact_record_limit() + 1,
        false,
        SUMMARY_PROJECTION_MAX_PREVIEW_BYTES,
        &mut live_preview_cache,
        UpstreamAccountActivityPreviewReadTelemetry {
            route: "summary_projection",
            builder: "bounded_exact_horizon",
            purpose: "summary_projection_exact_horizon",
        },
    )
    .await?;
    info!(
        ?mode,
        stage = "live_exact_admission",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    let initial_live_admission_gaps = live_admission.gaps;
    let initial_live_admission_overflow = live_admission.overflow;
    // `invoke_id` is the durable identity used by the archive preview contract.  In particular,
    // an archive replay can carry a different timestamp from the richer persisted live row; a
    // `(invoke_id, occurred_at)` key would double count it or overwrite live detail.
    let mut records_by_invoke_id = live_admission
        .rows
        .into_iter()
        .filter_map(|row| {
            summary_projection_live_record_from_preview(
                row,
                rollup_live_cursor,
                account_rollup_live_cursor,
                &hourly_rollup_totals,
                &hourly_rollup_usage,
            )
        })
        .collect::<HashMap<_, _>>();
    let mut exact_record_bytes = records_by_invoke_id
        .values()
        .map(|record| summary_projection_preview_row_bytes(&record.row))
        .sum::<usize>();
    ensure_summary_projection_resident_record_bytes(exact_record_bytes, 0)?;
    // `current` is a latest-N view. Read only the globally newest bounded prefix so SQLite can
    // stop on its occurred-at index before evaluating account metadata. A partitioned window
    // query appears bounded at its output but ranks every retained row first, which turns each
    // projection refresh into a retention-sized scan. Per-account responses remain exact when
    // the requested N entries are present; an overflowing prefix otherwise returns unavailable
    // rather than silently shortening an account's history.
    if state.config.list_limit_max > SUMMARY_PROJECTION_MAX_EXACT_RECORDS {
        return Err(anyhow!(
            "summary projection current limit exceeds bounded record budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    let recent_candidate_limit = state.config.list_limit_max.saturating_add(1);
    info!(
        ?mode,
        stage = "current_index_admission",
        "summary projection build stage started"
    );
    let recent_admission = match query_summary_projection_live_rows_with_budget(
        pool,
        InvocationSourceScope::All,
        ExactUtcRange {
            start: Utc
                .timestamp_opt(0, 0)
                .single()
                .expect("Unix epoch is valid"),
            end,
        },
        live_high_watermark_id,
        None,
        recent_candidate_limit,
        false,
        SUMMARY_PROJECTION_MAX_PREVIEW_BYTES.saturating_sub(exact_record_bytes),
        &mut live_preview_cache,
        UpstreamAccountActivityPreviewReadTelemetry {
            route: "summary_projection",
            builder: "bounded_recent_index",
            purpose: "summary_projection_recent_index",
        },
    )
    .await
    {
        Ok(admission) => admission,
        Err(error) => return Err(error),
    };
    info!(
        ?mode,
        stage = "current_index_admission",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    let recent_live_admission_gaps = recent_admission.gaps;
    let recent_live_admission_overflow = recent_admission.overflow;
    let mut recent_rows = recent_admission.rows;
    for candidate in recent_live_admission_gaps
        .iter()
        .chain(recent_live_admission_overflow.iter())
    {
        current_source_unavailable_from_rank = Some(
            current_source_unavailable_from_rank
                .map(|rank| rank.min(candidate.global_rank))
                .unwrap_or(candidate.global_rank),
        );
        if let Some(account_id) = candidate
            .upstream_account_id
            .filter(|account_id| *account_id > 0)
        {
            current_account_source_unavailable_from_rank
                .entry(account_id)
                .and_modify(|rank| *rank = (*rank).min(candidate.account_rank))
                .or_insert(candidate.account_rank);
        }
    }
    let mut recent_index_complete = recent_live_admission_overflow.is_none();
    let mut recent_index_overflow_at = recent_live_admission_overflow
        .as_ref()
        .map(|candidate| {
            parse_to_utc_datetime(&candidate.occurred_at).ok_or_else(|| {
                anyhow!("summary projection recent index overflow had an invalid occurred_at")
            })
        })
        .transpose()?;
    recent_rows.truncate(summary_projection_exact_record_limit());
    let mut current_records_by_invoke_id = HashMap::<String, SummaryProjectionRecord>::new();
    let mut current_record_bytes = 0_usize;
    let mut current_account_ranks = HashMap::<Option<i64>, usize>::new();
    for (global_index, row) in recent_rows.into_iter().enumerate() {
        let account_rank = current_account_ranks
            .entry(row.upstream_account_id)
            .or_default();
        *account_rank += 1;
        if let Some((invoke_id, record)) = summary_projection_live_record_from_preview(
            row,
            rollup_live_cursor,
            account_rollup_live_cursor,
            &hourly_rollup_totals,
            &hourly_rollup_usage,
        ) {
            let replacement_bytes = summary_projection_preview_row_bytes(&record.row);
            let replaced_bytes = current_records_by_invoke_id
                .get(&invoke_id)
                .map(|previous| summary_projection_preview_row_bytes(&previous.row))
                .unwrap_or_default();
            let next_current_record_bytes = current_record_bytes
                .saturating_sub(replaced_bytes)
                .saturating_add(replacement_bytes);
            if let Err(error) = ensure_summary_projection_resident_record_bytes(
                exact_record_bytes,
                next_current_record_bytes,
            ) {
                if !summary_projection_resident_record_budget_exceeded(&error) {
                    return Err(error);
                }
                let global_rank = global_index + 1;
                current_source_unavailable_from_rank = Some(
                    current_source_unavailable_from_rank
                        .map(|rank| rank.min(global_rank))
                        .unwrap_or(global_rank),
                );
                if let Some(account_id) = record.row.upstream_account_id.filter(|id| *id > 0) {
                    current_account_source_unavailable_from_rank
                        .entry(account_id)
                        .and_modify(|rank| *rank = (*rank).min(*account_rank))
                        .or_insert(*account_rank);
                }
                continue;
            }
            current_record_bytes = next_current_record_bytes;
            current_records_by_invoke_id.insert(invoke_id, record);
        }
    }
    if current_records_by_invoke_id.len() > summary_projection_exact_record_limit() {
        return Err(anyhow!(
            "summary projection current index exceeded bounded record budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    let mut known_account_ids = records_by_invoke_id
        .values()
        .filter_map(|record| record.row.upstream_account_id)
        .filter(|account_id| *account_id > 0)
        .collect::<HashSet<_>>();
    known_account_ids.extend(
        current_records_by_invoke_id
            .values()
            .filter_map(|record| record.row.upstream_account_id)
            .filter(|account_id| *account_id > 0),
    );
    known_account_ids.extend(
        all_time_archive_account_ids_by_file
            .values()
            .flat_map(|account_ids| account_ids.iter().copied()),
    );
    known_account_ids.extend(load_summary_projection_durable_account_ids(pool).await?);
    known_account_ids.extend(
        hourly_rollup_totals
            .keys()
            .filter_map(|(_, account_id)| *account_id)
            .filter(|account_id| *account_id > 0),
    );
    known_account_ids.extend(
        hourly_rollup_usage
            .keys()
            .filter_map(|(_, account_id)| *account_id)
            .filter(|account_id| *account_id > 0),
    );
    if known_account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
        return Err(anyhow!(
            "summary projection account coverage exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
        ));
    }
    // Boundary-hour selection is record-exact, including when the range starts or ends inside
    // an archived hour. Archive rows are streamed into the bounded exact set while building;
    // HTTP never opens or probes archive files.
    let exact_horizon = ExactUtcRange {
        start: archive_start,
        end,
    };
    info!(
        ?mode,
        stage = "boundary_manifest_admission",
        "summary projection build stage started"
    );
    let boundary_archive_admission =
        crate::stats::load_completed_invocation_archive_paths_in_range_bounded(
            pool,
            Some((archive_start, end)),
            SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES,
        )
        .await?;
    info!(
        ?mode,
        stage = "boundary_manifest_admission",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    let (archives, paged_boundary_manifest_high_watermark_id) = if boundary_archive_admission.len()
        > SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES
    {
        let Some(coverage) =
            summary_projection_overflowed_boundary_manifest_coverage(pool, exact_horizon).await?
        else {
            return Err(anyhow!(
                "summary projection overflowed boundary manifests lack a durable high watermark"
            ));
        };
        paged_boundary_manifest_unknown_coverage_ranges = coverage.unknown_coverage_ranges;
        (Vec::new(), Some(coverage.high_watermark_id))
    } else {
        (boundary_archive_admission, None)
    };
    let archive_paths = archives
        .iter()
        .map(|archive| archive.file_path().to_string())
        .collect::<Vec<_>>();
    let archive_path_set = archive_paths.iter().cloned().collect::<HashSet<_>>();
    archive_account_ids_by_file.retain(|path, _| archive_path_set.contains(path));
    archive_coverage_ranges_by_file.retain(|path, _| archive_path_set.contains(path));
    let mut cached_archive_account_id_count = archive_account_ids_by_file
        .values()
        .map(HashSet::len)
        .sum::<usize>();
    if cached_archive_account_id_count > summary_projection_exact_record_limit() {
        return Err(anyhow!(
            "summary projection archive account cache exceeded bounded budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    let archive_row_counts =
        load_summary_projection_archive_row_counts(pool, &archive_paths).await?;
    let archive_manifest_sha256 =
        load_summary_projection_archive_manifest_sha256(pool, &archive_paths).await?;
    let archive_replay_coverage =
        load_summary_projection_archive_replay_coverage(pool, &archive_paths).await?;
    // All-time has no finite request boundary. A materialized archive outside the bounded exact
    // horizon whose replay marker is absent cannot be reconstructed without an unbounded file
    // scan, so preserve an exact last-good all-time response (or its existing unavailable
    // contract) rather than publish a partial compact aggregate. An archive that straddles the
    // bounded horizon is not reconstructable for `all` from only its selected overlap.
    // Archive writers maintain this compact per-batch account manifest.  Hydrate account scope
    // from it before considering archive file I/O; this is the bounded discovery source for
    // large materialized archives and also covers accounts no longer present in live tables.
    let manifest_accounts = if archive_paths.iter().all(|path| {
        archive_replay_coverage
            .get(path)
            .is_some_and(|coverage| coverage.account_stats && coverage.usage_breakdown)
    }) {
        Vec::new()
    } else {
        load_summary_projection_archive_manifest_accounts(pool, &archive_paths).await?
    };
    for (file_path, account_id) in manifest_accounts {
        if !archive_path_set.contains(&file_path) {
            continue;
        }
        archive_account_ids_by_file
            .entry(file_path)
            .or_default()
            .insert(account_id);
    }
    cached_archive_account_id_count = archive_account_ids_by_file
        .values()
        .map(HashSet::len)
        .sum::<usize>();
    if cached_archive_account_id_count > summary_projection_exact_record_limit() {
        return Err(anyhow!(
            "summary projection archive account manifest exceeded bounded budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    for account_ids in archive_account_ids_by_file.values() {
        known_account_ids.extend(account_ids.iter().copied());
    }
    let usage_rollup_progress =
        load_usage_breakdown_archive_progress_by_file_path(pool, &archive_paths)
            .await
            .map_err(|error| {
                anyhow!("summary projection usage progress hydration failed: {error:?}")
            })?;
    let mut unavailable_unmaterialized_archive_buckets = BTreeSet::<i64>::new();
    let mut unavailable_boundary_archive_ranges = Vec::<ExactUtcRange>::new();
    let mut unavailable_unmaterialized_archive_current_ranges = Vec::<ExactUtcRange>::new();
    let mut unavailable_unmaterialized_archive_account_buckets = BTreeSet::<i64>::new();
    let mut unavailable_boundary_archive_account_ranges = Vec::<ExactUtcRange>::new();
    let mut unavailable_unmaterialized_archive_account_current_ranges = Vec::<ExactUtcRange>::new();
    let mut unavailable_unmaterialized_archive_exact_ranges = Vec::<ExactUtcRange>::new();
    if !paged_boundary_manifest_unknown_coverage_ranges.is_empty() {
        // A legacy manifest without exact bounds remains fail-closed, but its `month_key` still
        // proves the finite archive partition it can affect. Never let an old unknown partition
        // poison a disjoint current or rolling selection.
        unavailable_unmaterialized_archive_exact_ranges.extend(
            paged_boundary_manifest_unknown_coverage_ranges
                .iter()
                .copied(),
        );
        unavailable_unmaterialized_archive_current_ranges
            .extend(paged_boundary_manifest_unknown_coverage_ranges);
    }
    let mut unavailable_exact_live_buckets = BTreeSet::<i64>::new();
    let mut unavailable_exact_live_account_buckets = HashMap::<i64, BTreeSet<i64>>::new();
    for candidate in initial_live_admission_gaps
        .into_iter()
        .chain(initial_live_admission_overflow)
    {
        let Some(bucket) = summary_projection_live_candidate_bucket(&candidate) else {
            continue;
        };
        unavailable_exact_live_buckets.insert(bucket);
        if let Some(account_id) = candidate
            .upstream_account_id
            .filter(|account_id| *account_id > 0)
        {
            unavailable_exact_live_account_buckets
                .entry(account_id)
                .or_default()
                .insert(bucket);
        }
    }
    let mut historical_global_covered_terminal_invoke_ids = HashSet::<String>::new();
    let mut current_complete_archive_paths = HashSet::<String>::new();
    // Only rows which can appear in a legal global or account `current` response need the
    // rolling promotion below. The resident index keeps a larger bounded prefix so account
    // selection can remain in-memory; treating every row in that prefix as current-visible
    // would turn unrelated old records into a rolling exact repair and defeat normal coverage
    // deduplication.
    let mut current_visible_persisted_live_ids = HashSet::<String>::new();
    let mut current_visible_candidates =
        HashMap::<Option<i64>, Vec<&SummaryProjectionRecord>>::new();
    for record in current_records_by_invoke_id.values() {
        current_visible_candidates
            .entry(None)
            .or_default()
            .push(record);
        if let Some(account_id) = record.row.upstream_account_id {
            current_visible_candidates
                .entry(Some(account_id))
                .or_default()
                .push(record);
        }
    }
    for candidates in current_visible_candidates.values_mut() {
        candidates.sort_by(|left, right| {
            right
                .occurred_at
                .cmp(&left.occurred_at)
                .then_with(|| right.row.id.cmp(&left.row.id))
        });
        current_visible_persisted_live_ids.extend(
            candidates
                .iter()
                .take(state.config.list_limit_max)
                .filter(|record| record.is_persisted_live_record)
                .map(|record| record.row.invoke_id.clone()),
        );
    }
    // A sparse old durable row can survive in the newest-N current view while falling outside
    // the moving rolling tail. Promote that actual current selection into the rolling canonical
    // view before coverage is evaluated: otherwise an `all` exact repair and the SSE terminal
    // proof can both lose a terminal that is resident but not represented by a compact bucket.
    for record in current_records_by_invoke_id.values() {
        if !record.is_persisted_live_record
            || record.occurred_at >= live_start
            || !current_visible_persisted_live_ids.contains(&record.row.invoke_id)
            || records_by_invoke_id.contains_key(&record.row.invoke_id)
        {
            continue;
        }
        let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
        if records_by_invoke_id.len() >= summary_projection_exact_record_limit() {
            unavailable_exact_live_buckets.insert(bucket);
            continue;
        }
        let next_rolling_record_bytes =
            exact_record_bytes.saturating_add(summary_projection_preview_row_bytes(&record.row));
        if let Err(error) = ensure_summary_projection_resident_record_bytes(
            next_rolling_record_bytes,
            current_record_bytes,
        ) {
            if !summary_projection_resident_record_budget_exceeded(&error) {
                return Err(error);
            }
            unavailable_exact_live_buckets.insert(bucket);
            continue;
        }
        exact_record_bytes = next_rolling_record_bytes;
        records_by_invoke_id.insert(record.row.invoke_id.clone(), record.clone());
    }
    // Rolling boundary ranges may need raw records even when an all-time compact rollup is
    // complete. Keep that narrower unavailability separate from all-time source proof.
    let mut all_time_source_unavailable_from_archive_ranges = false;
    // Discover accounts from archive rows before planning full-hour coverage. Pools are opened
    // and closed one at a time so a large retention horizon never keeps every inflated archive
    // resident concurrently. Immutable completed archives reuse the cached account set on later
    // refreshes; only a new path pays the discovery pass.
    let mut archive_actual_coverage_ranges = archive_coverage_ranges_by_file.clone();
    info!(
        ?mode,
        stage = "archive_account_discovery",
        "summary projection build stage started"
    );
    for archive in &archives {
        let Some(archive_range) = summary_projection_archive_overlap_range(
            archive,
            ExactUtcRange {
                start: archive_start,
                end,
            },
        ) else {
            continue;
        };
        let cached_coverage_is_sufficient = summary_projection_archive_has_coverage_bounds(archive)
            || archive_actual_coverage_ranges.contains_key(archive.file_path());
        if archive_account_ids_by_file.contains_key(archive.file_path())
            && cached_coverage_is_sufficient
        {
            if let Some(account_ids) = archive_account_ids_by_file.get(archive.file_path()) {
                known_account_ids.extend(account_ids.iter().copied());
            }
            if known_account_ids.len() > summary_projection_exact_record_limit() {
                return Err(anyhow!(
                    "summary projection archive account coverage exceeded bounded budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
                ));
            }
            continue;
        }
        let row_count = archive_row_counts.get(archive.file_path()).copied();
        if !archive.has_materialized_historical_rollups()
            && row_count.is_some_and(|count| count > summary_projection_exact_record_limit() as i64)
        {
            return Err(anyhow!(
                "summary projection unmaterialized archive account discovery exceeded bounded row budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
            ));
        }
        // A large materialized archive cannot be opened merely to discover account ids within
        // the refresh deadline.  Without a bounded discovery cache we fail closed above instead
        // of publishing a projection that silently undercounts an archive-only account.
        let replay_coverage = summary_projection_effective_replay_coverage(
            archive,
            archive_replay_coverage
                .get(archive.file_path())
                .copied()
                .unwrap_or_default(),
        );
        if archive.has_materialized_historical_rollups()
            && row_count.is_some_and(|count| count > summary_projection_exact_record_limit() as i64)
            && replay_coverage.account_stats
            && replay_coverage.usage_breakdown
        {
            // All account-scoped targets have replayed this immutable archive. Durable rollup
            // account keys are sufficient for admission; do not inflate a large file merely to
            // rediscover the same account ids.
            continue;
        }
        if archive.has_materialized_historical_rollups()
            && row_count.is_some_and(|count| count > summary_projection_exact_record_limit() as i64)
        {
            return Err(anyhow!(
                "summary projection cannot prove account coverage for a large materialized archive without complete replay coverage"
            ));
        }
        let manifest_sha256 = archive_manifest_sha256
            .get(archive.file_path())
            .ok_or_else(|| {
                anyhow!(
                    "summary projection archive manifest SHA is missing for {}",
                    archive.file_path()
                )
            })?;
        if Path::new(archive.file_path()).exists() {
            verify_summary_projection_archive_file_sha256(archive, manifest_sha256)?;
        }
        let Some((archive_pool, temp_cleanup)) =
            crate::stats::open_invocation_archive_batch_pool(archive, "summary-projection").await?
        else {
            if replay_coverage.supports_unavailable_archive() {
                // A materialized archive remains answerable from its durable rollup baseline.
                // Replay fallback additionally needs every response dimension, otherwise a
                // global total could conceal missing account or usage/model detail.
                continue;
            }
            if !archive.has_materialized_historical_rollups() {
                all_time_source_unavailable_from_archive_ranges = true;
            }
            continue;
        };
        require_summary_projection_archive_file_sha256(archive, manifest_sha256)?;
        if !summary_projection_archive_has_coverage_bounds(archive)
            && let Some(actual_range) = load_summary_projection_archive_coverage_range(
                &archive_pool,
            )
            .await
            .map_err(|error| {
                anyhow!(
                    "summary projection archive coverage hydration failed for {}: {error:?}",
                    archive.file_path()
                )
            })?
        {
            archive_actual_coverage_ranges.insert(archive.file_path().to_string(), actual_range);
        }
        let account_ids = load_summary_projection_archive_account_ids(&archive_pool, archive_range)
            .await
            .map_err(|error| {
                anyhow!(
                    "summary projection archive account discovery failed for {}: {error:?}",
                    archive.file_path()
                )
            })?;
        known_account_ids.extend(account_ids.iter().copied());
        cached_archive_account_id_count =
            cached_archive_account_id_count.saturating_add(account_ids.len());
        if cached_archive_account_id_count > summary_projection_exact_record_limit() {
            return Err(anyhow!(
                "summary projection archive account cache exceeded bounded budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
            ));
        }
        if known_account_ids.len() > summary_projection_exact_record_limit() {
            return Err(anyhow!(
                "summary projection archive account coverage exceeded bounded budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
            ));
        }
        archive_account_ids_by_file.insert(archive.file_path().to_string(), account_ids);
        require_summary_projection_archive_file_sha256(archive, manifest_sha256)?;
        archive_pool.close().await;
        drop(temp_cleanup);
    }
    info!(
        ?mode,
        stage = "archive_account_discovery",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    // All-time materialized coverage is checked after loading its complete compact rollup map.
    // Replay markers alone do not prove the per-hour global/account key exists, while a bounded
    // manifest plus materialization and the actual key do. Do not pre-classify either scope from
    // marker absence here.
    let all_time_global_exact_source_unavailable = false;
    let all_time_account_exact_source_unavailable = false;

    // A missing replay marker means the compact rollup might contain only a prefix of this
    // archive. Reconstruct the complete affected full hour off-request, including retained live
    // rows, before allowing the reducer to replace that bucket. This prevents an archive repair
    // from suppressing a co-located live failure or terminal tail.
    let mut exact_global_total_rollup_buckets = HashSet::new();
    let mut exact_account_total_rollup_buckets = HashSet::new();
    let mut exact_global_usage_rollup_buckets = HashSet::new();
    let mut exact_account_usage_rollup_buckets = HashSet::new();
    for archive in &archives {
        let Some(archive_range) = summary_projection_archive_overlap_range(
            archive,
            ExactUtcRange {
                start: archive_start,
                end,
            },
        ) else {
            continue;
        };
        let replay_coverage = summary_projection_effective_replay_coverage(
            archive,
            archive_replay_coverage
                .get(archive.file_path())
                .copied()
                .unwrap_or_default(),
        );
        // A point-like legacy manifest has no finite coverage interval. All-time scope coverage
        // deliberately treats its materialization flag as the established global compact proof;
        // do not reinterpret the inclusive endpoint used by rolling archive reads as a one-second
        // replacement range and suppress that same durable aggregate.
        if summary_projection_archive_coverage_range(archive).is_some() {
            summary_projection_mark_exact_replacement_buckets(
                archive.has_materialized_historical_rollups(),
                replay_coverage,
                archive_range,
                &protected_boundary_buckets,
                &mut exact_global_total_rollup_buckets,
                &mut exact_account_total_rollup_buckets,
                &mut exact_global_usage_rollup_buckets,
                &mut exact_account_usage_rollup_buckets,
            )?;
        }
    }
    // When one archive has incomplete replay, every archive and persisted live row in its
    // compact bucket must be available as an exact replacement source. A fully replayed sibling
    // cannot stay hidden behind the bucket-wide aggregate once that aggregate is suppressed.
    let mut exact_archive_buckets = protected_boundary_buckets.clone();
    exact_archive_buckets.extend(exact_global_total_rollup_buckets.iter().copied());
    exact_archive_buckets.extend(exact_account_total_rollup_buckets.iter().copied());
    exact_archive_buckets.extend(exact_global_usage_rollup_buckets.iter().copied());
    exact_archive_buckets.extend(exact_account_usage_rollup_buckets.iter().copied());
    summary_projection_ensure_exact_bucket_budget(&exact_archive_buckets)?;
    // A materialized archive can be fully replayed yet still lack one scope's compact bucket.
    // Its raw fallback must also pull co-located persisted/live rows before archive/live ID
    // exclusion picks the richer live copy; otherwise both sources disappear for that scope.
    // Plan all such buckets before exact-live hydration so archive and live use one source set.
    for archive in &archives {
        let Some(archive_range) = summary_projection_archive_overlap_range(
            archive,
            ExactUtcRange {
                start: archive_start,
                end,
            },
        ) else {
            continue;
        };
        let replay_coverage = summary_projection_effective_replay_coverage(
            archive,
            archive_replay_coverage
                .get(archive.file_path())
                .copied()
                .unwrap_or_default(),
        );
        summary_projection_exact_range_fits_bucket_budget(archive_range)?;
        let raw_fallback_ranges = summary_projection_archive_exact_ranges_with_coverage(
            archive.has_materialized_historical_rollups(),
            Some(replay_coverage.overall),
            Some(replay_coverage.account_stats),
            Some(replay_coverage.usage_breakdown),
            archive_range,
            &exact_archive_buckets,
            &hourly_rollup_totals,
            &hourly_rollup_usage,
            &known_account_ids,
        );
        summary_projection_extend_exact_buckets_for_ranges(
            &mut exact_archive_buckets,
            raw_fallback_ranges,
        )?;
    }
    let mut paged_boundary_raw_archive_admissions = 0usize;
    if let Some(high_watermark_id) = paged_boundary_manifest_high_watermark_id {
        // Page only bounded manifest metadata while planning the finite exact buckets. The raw
        // archives themselves are opened later one at a time after live boundary records have
        // been admitted; each page retains its actual replay/materialization proof.
        info!(
            ?mode,
            stage = "boundary_manifest_page_planning",
            "summary projection build stage started"
        );
        let mut after_id = None;
        loop {
            let page = load_summary_projection_boundary_manifest_page(
                pool,
                Some(exact_horizon),
                after_id,
                high_watermark_id,
            )
            .await?;
            if page.archives.is_empty() {
                break;
            }
            let page_paths = page
                .archives
                .iter()
                .map(|archive| archive.file_path().to_string())
                .collect::<Vec<_>>();
            let page_replay_coverage =
                load_summary_projection_archive_replay_coverage(pool, &page_paths).await?;
            let page_account_ids_by_file =
                load_summary_projection_archive_manifest_account_sets(pool, &page_paths).await?;
            for account_ids in page_account_ids_by_file.values() {
                known_account_ids.extend(account_ids.iter().copied());
            }
            if known_account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
                return Err(anyhow!(
                    "summary projection paged boundary account cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
                ));
            }
            for archive in &page.archives {
                let Some(archive_range) =
                    summary_projection_archive_overlap_range(archive, exact_horizon)
                else {
                    continue;
                };
                let replay_coverage = summary_projection_effective_replay_coverage(
                    archive,
                    page_replay_coverage
                        .get(archive.file_path())
                        .copied()
                        .unwrap_or_default(),
                );
                let mut paged_exact_global_total_buckets = HashSet::new();
                let mut paged_exact_account_total_buckets = HashSet::new();
                let mut paged_exact_global_usage_buckets = HashSet::new();
                let mut paged_exact_account_usage_buckets = HashSet::new();
                if mode.includes_all_time()
                    && summary_projection_archive_coverage_range(archive).is_some()
                {
                    summary_projection_mark_exact_replacement_buckets(
                        archive.has_materialized_historical_rollups(),
                        replay_coverage,
                        archive_range,
                        &protected_boundary_buckets,
                        &mut exact_global_total_rollup_buckets,
                        &mut exact_account_total_rollup_buckets,
                        &mut exact_global_usage_rollup_buckets,
                        &mut exact_account_usage_rollup_buckets,
                    )?;
                } else if summary_projection_archive_coverage_range(archive).is_some() {
                    summary_projection_mark_exact_replacement_buckets(
                        archive.has_materialized_historical_rollups(),
                        replay_coverage,
                        archive_range,
                        &protected_boundary_buckets,
                        &mut paged_exact_global_total_buckets,
                        &mut paged_exact_account_total_buckets,
                        &mut paged_exact_global_usage_buckets,
                        &mut paged_exact_account_usage_buckets,
                    )?;
                }
                let account_ids = page_account_ids_by_file
                    .get(archive.file_path())
                    .expect("page account manifest includes every requested archive path");
                let account_manifest_complete = page
                    .account_manifest_refreshed_paths
                    .contains(archive.file_path());
                if mode.includes_all_time() && !account_manifest_complete {
                    summary_projection_mark_account_exact_replacement_buckets(
                        archive.has_materialized_historical_rollups(),
                        archive_range,
                        &mut exact_account_total_rollup_buckets,
                    )?;
                } else if !account_manifest_complete {
                    summary_projection_mark_account_exact_replacement_buckets(
                        archive.has_materialized_historical_rollups(),
                        archive_range,
                        &mut paged_exact_account_total_buckets,
                    )?;
                }
                let (account_replayed, usage_replayed) = if !account_manifest_complete {
                    // A stale account manifest invalidates account-scoped totals. Preserve the
                    // durable usage replay proof when one exists; unmaterialized archives may
                    // lack both markers and must therefore use their raw source.
                    (Some(false), Some(replay_coverage.usage_breakdown))
                } else if account_ids.is_empty() {
                    (Some(true), Some(replay_coverage.usage_breakdown))
                } else {
                    (None, None)
                };
                let raw_fallback_ranges = summary_projection_archive_exact_ranges_with_coverage(
                    archive.has_materialized_historical_rollups(),
                    Some(replay_coverage.overall),
                    account_replayed,
                    usage_replayed,
                    archive_range,
                    &exact_archive_buckets,
                    &hourly_rollup_totals,
                    &hourly_rollup_usage,
                    account_ids,
                );
                if mode.includes_all_time() {
                    summary_projection_extend_exact_buckets_for_ranges(
                        &mut exact_archive_buckets,
                        raw_fallback_ranges,
                    )?;
                } else {
                    // Paged metadata can prove that a raw source would be needed, but Bootstrap
                    // and Rolling cannot open that source before publication. Preserve compact
                    // coverage and publish an exact local gap for every unproven replacement.
                    let mut global_bucket_requirements = paged_exact_global_total_buckets;
                    global_bucket_requirements.extend(paged_exact_global_usage_buckets);
                    let mut account_bucket_requirements = paged_exact_account_total_buckets;
                    account_bucket_requirements.extend(paged_exact_account_usage_buckets);

                    // A complete internal compact bucket with a missing rollup key is not a
                    // boundary-only repair. It would make a rolling response undercount even
                    // when neither request endpoint intersects the archive range, so retain a
                    // strict range-local unavailable proof for that bucket.
                    let global_compact_coverage_gaps =
                        summary_projection_archive_exact_ranges_with_coverage(
                            archive.has_materialized_historical_rollups(),
                            Some(replay_coverage.overall),
                            Some(true),
                            Some(true),
                            archive_range,
                            &HashSet::new(),
                            &hourly_rollup_totals,
                            &hourly_rollup_usage,
                            account_ids,
                        );
                    let account_compact_coverage_gaps =
                        summary_projection_archive_exact_ranges_with_coverage(
                            archive.has_materialized_historical_rollups(),
                            Some(replay_coverage.overall),
                            account_replayed,
                            usage_replayed,
                            archive_range,
                            &HashSet::new(),
                            &hourly_rollup_totals,
                            &hourly_rollup_usage,
                            account_ids,
                        );
                    summary_projection_extend_exact_buckets_for_ranges(
                        &mut global_bucket_requirements,
                        global_compact_coverage_gaps,
                    )?;
                    summary_projection_extend_exact_buckets_for_ranges(
                        &mut account_bucket_requirements,
                        account_compact_coverage_gaps,
                    )?;

                    // The global aggregate can be exact even when the account manifest is
                    // stale. Check its dimensions independently so a missing account proof
                    // does not poison a compact global rollup.
                    let mut global_unavailable_ranges =
                        summary_projection_archive_exact_ranges_with_coverage(
                            archive.has_materialized_historical_rollups(),
                            Some(replay_coverage.overall),
                            Some(true),
                            Some(true),
                            archive_range,
                            &exact_archive_buckets,
                            &hourly_rollup_totals,
                            &hourly_rollup_usage,
                            account_ids,
                        );
                    let mut account_unavailable_ranges = raw_fallback_ranges;
                    for (ranges, requirements) in [
                        (&mut global_unavailable_ranges, &global_bucket_requirements),
                        (
                            &mut account_unavailable_ranges,
                            &account_bucket_requirements,
                        ),
                    ] {
                        for range in summary_projection_exact_bucket_ranges(requirements) {
                            let range = ExactUtcRange {
                                start: range.start.max(archive_range.start),
                                end: range.end.min(archive_range.end),
                            };
                            if range.start < range.end {
                                ranges.push(range);
                            }
                        }
                    }
                    let global_unavailable_ranges =
                        summary_projection_merge_exact_ranges(global_unavailable_ranges);
                    let account_unavailable_ranges =
                        summary_projection_merge_exact_ranges(account_unavailable_ranges);
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_buckets,
                        &mut unavailable_boundary_archive_ranges,
                        archive.has_materialized_historical_rollups(),
                        &global_unavailable_ranges,
                        &global_bucket_requirements,
                    )?;
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_account_buckets,
                        &mut unavailable_boundary_archive_account_ranges,
                        archive.has_materialized_historical_rollups(),
                        &account_unavailable_ranges,
                        &account_bucket_requirements,
                    )?;
                    if !global_unavailable_ranges.is_empty() {
                        unavailable_unmaterialized_archive_current_ranges.push(archive_range);
                    }
                    if !account_unavailable_ranges.is_empty() {
                        unavailable_unmaterialized_archive_account_current_ranges
                            .push(archive_range);
                    }
                }
            }
            let Some(next_after_id) = page.next_after_id else {
                break;
            };
            after_id = Some(next_after_id);
        }
        info!(
            ?mode,
            stage = "boundary_manifest_page_planning",
            elapsed_ms = build_started_at.elapsed().as_millis() as u64,
            "summary projection build stage completed"
        );
    }
    let mut exact_bucket_requirements = exact_archive_buckets
        .difference(&protected_boundary_buckets)
        .copied()
        .collect::<HashSet<_>>();
    // A protected boundary normally makes only a partial-hour selection unavailable when its
    // raw archive is unreadable. Missing compact replay or rollup coverage is different: every
    // selection touching that bucket lacks an exact durable source, so it must remain strict
    // even if the same bucket is also a supported calendar/timezone boundary.
    exact_bucket_requirements.extend(exact_global_total_rollup_buckets.iter().copied());
    exact_bucket_requirements.extend(exact_account_total_rollup_buckets.iter().copied());
    exact_bucket_requirements.extend(exact_global_usage_rollup_buckets.iter().copied());
    exact_bucket_requirements.extend(exact_account_usage_rollup_buckets.iter().copied());
    let exact_live_ranges = summary_projection_exact_bucket_ranges(&exact_archive_buckets)
        .into_iter()
        .filter_map(|range| {
            (range.start < live_start).then_some(ExactUtcRange {
                start: range.start,
                end: range.end.min(live_start),
            })
        })
        .collect::<Vec<_>>();
    for record in records_by_invoke_id.values_mut() {
        let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
        if exact_global_total_rollup_buckets.contains(&bucket) {
            record.global_rollup_covered = false;
        }
        if exact_account_total_rollup_buckets.contains(&bucket) {
            record.account_rollup_covered = false;
        }
        if exact_global_usage_rollup_buckets.contains(&bucket) {
            record.usage_global_rollup_covered = false;
        }
        if exact_account_usage_rollup_buckets.contains(&bucket) {
            record.usage_account_rollup_covered = false;
        }
    }
    // A complete raw replacement has stronger proof than a lagging compact cursor. Preserve
    // those bucket identities so the later historical coverage pass does not revoke an exact
    // archive/live selection it has already admitted under this build's high-watermark.
    let mut fully_admitted_historical_live_buckets = BTreeSet::<i64>::new();
    for range in exact_live_ranges {
        if recent_index_overflow_at.is_some_and(|overflow_at| range.start <= overflow_at) {
            // The recent index already proves that this range reaches omitted live history. Do
            // not spend the remaining resident budget rereading rows that cannot make the range
            // exact; the cutoff below will fail closed for any request which touches it.
            continue;
        }
        let remaining = summary_projection_exact_record_limit()
            .saturating_sub(records_by_invoke_id.len())
            .saturating_add(1);
        let exact_live_admission = match query_summary_projection_live_rows_with_budget(
            pool,
            InvocationSourceScope::All,
            range,
            live_high_watermark_id,
            None,
            remaining,
            false,
            SUMMARY_PROJECTION_MAX_PREVIEW_BYTES.saturating_sub(current_record_bytes),
            &mut live_preview_cache,
            UpstreamAccountActivityPreviewReadTelemetry {
                route: "summary_projection",
                builder: "exact_replacement_bucket",
                purpose: "summary_projection_archive_live_replacement",
            },
        )
        .await
        {
            Ok(admission) => admission,
            Err(error) => return Err(error),
        };
        if exact_live_admission.overflow.is_some() || !exact_live_admission.gaps.is_empty() {
            // A rolling window whose partial boundary includes this dense hour cannot be exact
            // within the finite record budget. Keep the independently admitted `current` prefix
            // and unaffected ranges available, while making only this range explicitly
            // unavailable instead of aborting the complete read-model build.
            summary_projection_mark_unavailable_archive_ranges(
                &mut unavailable_exact_live_buckets,
                [range],
            )?;
            continue;
        }
        let mut range_fully_admitted = true;
        for row in exact_live_admission.rows {
            let Some(occurred_at) = parse_to_utc_datetime(&row.occurred_at) else {
                range_fully_admitted = false;
                break;
            };
            let bucket = align_bucket_epoch(occurred_at.timestamp(), 3_600, 0);
            let replacement_bytes = summary_projection_preview_row_bytes(&row);
            let replaced_bytes = records_by_invoke_id
                .get(&row.invoke_id)
                .map(|previous| summary_projection_preview_row_bytes(&previous.row))
                .unwrap_or_default();
            let next_rolling_record_bytes = exact_record_bytes
                .saturating_sub(replaced_bytes)
                .saturating_add(replacement_bytes);
            if let Err(error) = ensure_summary_projection_resident_record_bytes(
                next_rolling_record_bytes,
                current_record_bytes,
            ) {
                if !summary_projection_resident_record_budget_exceeded(&error) {
                    return Err(error);
                }
                // This range needs the omitted record to replace a compact bucket. Do not
                // poison the independently admitted `current` view when the two resident
                // views cannot coexist within the shared byte limit.
                summary_projection_mark_unavailable_archive_ranges(
                    &mut unavailable_exact_live_buckets,
                    [range],
                )?;
                range_fully_admitted = false;
                break;
            }
            exact_record_bytes = next_rolling_record_bytes;
            records_by_invoke_id.insert(
                row.invoke_id.clone(),
                SummaryProjectionRecord {
                    global_rollup_covered: row.id <= rollup_live_cursor
                        && hourly_rollup_totals.contains_key(&(bucket, None))
                        && !exact_global_total_rollup_buckets.contains(&bucket),
                    account_rollup_covered: account_rollup_live_cursor
                        .is_some_and(|cursor| row.id <= cursor)
                        && hourly_rollup_totals.contains_key(&(bucket, row.upstream_account_id))
                        && !exact_account_total_rollup_buckets.contains(&bucket),
                    usage_global_rollup_covered: row.id <= rollup_live_cursor
                        && hourly_rollup_usage.contains_key(&(bucket, None))
                        && !exact_global_usage_rollup_buckets.contains(&bucket),
                    usage_account_rollup_covered: account_rollup_live_cursor
                        .is_some_and(|cursor| row.id <= cursor)
                        && hourly_rollup_usage.contains_key(&(bucket, row.upstream_account_id))
                        && !exact_account_usage_rollup_buckets.contains(&bucket),
                    is_persisted_live_record: true,
                    is_archive_record: false,
                    archive_has_materialized_rollups: false,
                    account_archive_totals_fallback_included: false,
                    row,
                    occurred_at,
                },
            );
        }
        if range_fully_admitted {
            let mut bucket = align_bucket_epoch(range.start.timestamp(), 3_600, 0);
            let last_bucket = align_bucket_epoch(range.end.timestamp().saturating_sub(1), 3_600, 0);
            while bucket <= last_bucket {
                fully_admitted_historical_live_buckets.insert(bucket);
                bucket = bucket.saturating_add(3_600);
            }
        }
    }
    let historical_live_range = ExactUtcRange {
        start: archive_start,
        end: live_start,
    };
    let mut historical_live_coverage = None;
    if historical_live_range.start < historical_live_range.end {
        if mode.requires_full_historical_live_coverage() {
            info!(
                ?mode,
                stage = "historical_live_coverage",
                "summary projection build stage started"
            );
            #[cfg(test)]
            pause_summary_projection_test_interleave(
                pool,
                mode,
                SummaryProjectionTestInterleaveStage::BeforeHistoricalLiveCoverage,
            )
            .await?;
            mark_summary_projection_uncovered_historical_live_ranges(
                pool,
                historical_live_range,
                live_high_watermark_id,
                rollup_live_cursor,
                account_rollup_live_cursor,
                &hourly_rollup_totals,
                &hourly_rollup_usage,
                &fully_admitted_historical_live_buckets,
                &state
                    .subscription_hub
                    .summary_terminal_overlay_identities()
                    .await,
                &mut unavailable_exact_live_buckets,
                &mut unavailable_exact_live_account_buckets,
                &mut historical_global_covered_terminal_invoke_ids,
            )
            .await?;
            historical_live_coverage = Some(SummaryProjectionHistoricalLiveCoverage {
                range: historical_live_range,
                high_watermark_id: live_high_watermark_id,
                reconciliation_required: false,
            });
            info!(
                ?mode,
                stage = "historical_live_coverage",
                elapsed_ms = build_started_at.elapsed().as_millis() as u64,
                "summary projection build stage completed"
            );
        } else {
            let coverage = reuse_summary_projection_historical_live_coverage(
                pool,
                previous_historical_live_coverage.as_ref(),
                historical_live_range,
                live_high_watermark_id,
                rollup_live_cursor,
                account_rollup_live_cursor,
                &hourly_rollup_totals,
                &hourly_rollup_usage,
                &fully_admitted_historical_live_buckets,
                &previous_unavailable_exact_live_ranges,
                &previous_unavailable_exact_live_account_ranges,
                &previous_persisted_live_terminal_invoke_ids,
                &state
                    .subscription_hub
                    .summary_terminal_overlay_identities()
                    .await,
                &mut unavailable_exact_live_buckets,
                &mut unavailable_exact_live_account_buckets,
                &mut historical_global_covered_terminal_invoke_ids,
            )
            .await?;
            info!(
                ?mode,
                stage = "historical_live_coverage_reuse",
                reconciliation_required = coverage.reconciliation_required,
                elapsed_ms = build_started_at.elapsed().as_millis() as u64,
                "summary projection historical live coverage reused"
            );
            historical_live_coverage = Some(coverage);
        }
    }
    known_account_ids.extend(
        records_by_invoke_id
            .values()
            .filter_map(|record| record.row.upstream_account_id)
            .filter(|account_id| *account_id > 0),
    );
    if records_by_invoke_id.len() > summary_projection_exact_record_limit() {
        return Err(anyhow!(
            "summary projection exact archive/live replacement exceeded bounded record budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
        ));
    }
    let persisted_live_ids = records_by_invoke_id.keys().cloned().collect::<HashSet<_>>();
    let mut exact_record_budget = records_by_invoke_id.len();
    info!(
        ?mode,
        stage = "boundary_archive_hydration",
        "summary projection build stage started"
    );
    for archive in archives {
        let Some(archive_range) = summary_projection_archive_overlap_range(
            &archive,
            ExactUtcRange {
                start: archive_start,
                end,
            },
        ) else {
            continue;
        };
        let replay_coverage = summary_projection_effective_replay_coverage(
            &archive,
            archive_replay_coverage
                .get(archive.file_path())
                .copied()
                .unwrap_or_default(),
        );
        let exact_ranges = summary_projection_archive_exact_ranges_with_coverage(
            archive.has_materialized_historical_rollups(),
            Some(replay_coverage.overall),
            Some(replay_coverage.account_stats),
            Some(replay_coverage.usage_breakdown),
            archive_range,
            &exact_archive_buckets,
            &hourly_rollup_totals,
            &hourly_rollup_usage,
            &known_account_ids,
        );
        if exact_ranges.is_empty() {
            continue;
        }
        if !archive.has_materialized_historical_rollups()
            && archive_row_counts
                .get(archive.file_path())
                .is_some_and(|count| *count > summary_projection_exact_record_limit() as i64)
        {
            return Err(anyhow!(
                "summary projection exact archive boundary exceeds bounded row budget ({SUMMARY_PROJECTION_MAX_EXACT_RECORDS})"
            ));
        }
        let manifest_sha256 = archive_manifest_sha256
            .get(archive.file_path())
            .ok_or_else(|| {
                anyhow!(
                    "summary projection archive manifest SHA is missing for {}",
                    archive.file_path()
                )
            })?;
        if Path::new(archive.file_path()).exists()
            && verify_summary_projection_archive_file_sha256(&archive, manifest_sha256)?
                == SummaryProjectionArchiveFileIdentity::Unavailable
        {
            if !archive.has_materialized_historical_rollups()
                && !replay_coverage.supports_unavailable_archive()
            {
                all_time_source_unavailable_from_archive_ranges = true;
            }
            summary_projection_mark_unavailable_archive_ranges_by_requirement(
                &mut unavailable_unmaterialized_archive_buckets,
                &mut unavailable_boundary_archive_ranges,
                archive.has_materialized_historical_rollups(),
                &exact_ranges,
                &exact_bucket_requirements,
            )?;
            unavailable_unmaterialized_archive_current_ranges.push(archive_range);
            continue;
        }
        let Some((archive_pool, temp_cleanup)) =
            crate::stats::open_invocation_archive_batch_pool(&archive, "summary-projection")
                .await?
        else {
            if !archive.has_materialized_historical_rollups()
                && !replay_coverage.supports_unavailable_archive()
            {
                all_time_source_unavailable_from_archive_ranges = true;
            }
            // Complete replay can replace a full compact hour, but it cannot reconstruct this
            // request-visible partial hour or its usage/model detail. The raw archive is an
            // exact source for every range in `exact_ranges`; without it, retain unavailable
            // rather than allowing the memory-only reducer to omit that contribution.
            summary_projection_mark_unavailable_archive_ranges_by_requirement(
                &mut unavailable_unmaterialized_archive_buckets,
                &mut unavailable_boundary_archive_ranges,
                archive.has_materialized_historical_rollups(),
                &exact_ranges,
                &exact_bucket_requirements,
            )?;
            unavailable_unmaterialized_archive_current_ranges.push(archive_range);
            continue;
        };
        require_summary_projection_archive_file_sha256(&archive, manifest_sha256)?;
        let records_before_archive = records_by_invoke_id.clone();
        let exact_record_budget_before_archive = exact_record_budget;
        let exact_record_bytes_before_archive = exact_record_bytes;
        let merge_result = merge_summary_projection_archive_records_with_coverage(
            &archive_pool,
            pool,
            &persisted_live_ids,
            &hourly_rollup_totals,
            &hourly_rollup_usage,
            archive.has_materialized_historical_rollups(),
            Some(replay_coverage.overall),
            Some(replay_coverage.account_stats),
            Some(replay_coverage.usage_breakdown),
            archive_range,
            &exact_archive_buckets,
            usage_rollup_progress.get(archive.file_path()).copied(),
            &known_account_ids,
            &mut records_by_invoke_id,
            &mut exact_record_budget,
            &mut exact_record_bytes,
            current_record_bytes,
        )
        .await;
        require_summary_projection_archive_file_sha256(&archive, manifest_sha256)?;
        archive_pool.close().await;
        drop(temp_cleanup);
        if let Err(error) = merge_result {
            if !summary_projection_archive_raw_admission_exceeded(&error) {
                return Err(anyhow!(
                    "summary projection archive hydration failed for {}: {error:?}",
                    archive.file_path()
                ));
            }
            records_by_invoke_id = records_before_archive;
            exact_record_budget = exact_record_budget_before_archive;
            exact_record_bytes = exact_record_bytes_before_archive;
            summary_projection_mark_unavailable_archive_ranges_by_requirement(
                &mut unavailable_unmaterialized_archive_buckets,
                &mut unavailable_boundary_archive_ranges,
                archive.has_materialized_historical_rollups(),
                &exact_ranges,
                &exact_bucket_requirements,
            )?;
            unavailable_unmaterialized_archive_current_ranges.push(archive_range);
        }
    }
    info!(
        ?mode,
        stage = "boundary_archive_hydration",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    if mode.includes_all_time()
        && let Some(high_watermark_id) = paged_boundary_manifest_high_watermark_id
    {
        info!(
            ?mode,
            stage = "paged_boundary_archive_hydration",
            "summary projection build stage started"
        );
        #[cfg(test)]
        pause_summary_projection_test_interleave(
            pool,
            mode,
            SummaryProjectionTestInterleaveStage::BeforePagedBoundaryArchiveHydration,
        )
        .await?;
        let mut after_id = None;
        loop {
            let page = load_summary_projection_boundary_manifest_page(
                pool,
                Some(exact_horizon),
                after_id,
                high_watermark_id,
            )
            .await?;
            if page.archives.is_empty() {
                break;
            }
            let page_paths = page
                .archives
                .iter()
                .map(|archive| archive.file_path().to_string())
                .collect::<Vec<_>>();
            let page_manifest_sha256 =
                load_summary_projection_archive_manifest_sha256(pool, &page_paths).await?;
            let page_replay_coverage =
                load_summary_projection_archive_replay_coverage(pool, &page_paths).await?;
            let usage_rollup_progress = load_usage_breakdown_archive_progress_by_file_path(
                pool,
                &page_paths,
            )
            .await
            .map_err(|error| {
                anyhow!(
                    "summary projection paged boundary usage progress hydration failed: {error:?}"
                )
            })?;
            let page_account_ids_by_file =
                load_summary_projection_archive_manifest_account_sets(pool, &page_paths).await?;
            for archive in page.archives {
                let Some(archive_range) =
                    summary_projection_archive_overlap_range(&archive, exact_horizon)
                else {
                    continue;
                };
                let account_ids = page_account_ids_by_file
                    .get(archive.file_path())
                    .expect("page account manifest includes every requested archive path");
                let account_manifest_complete = page
                    .account_manifest_refreshed_paths
                    .contains(archive.file_path());
                let replay_coverage = summary_projection_effective_replay_coverage(
                    &archive,
                    page_replay_coverage
                        .get(archive.file_path())
                        .copied()
                        .unwrap_or_default(),
                );
                let (account_replayed, usage_replayed) = if !account_manifest_complete {
                    // A stale account manifest invalidates account-scoped totals. Preserve the
                    // durable usage replay proof when one exists; unmaterialized archives may
                    // lack both markers and must therefore use their raw source.
                    (Some(false), Some(replay_coverage.usage_breakdown))
                } else if account_ids.is_empty() {
                    (Some(true), Some(replay_coverage.usage_breakdown))
                } else {
                    (None, None)
                };
                let mut exact_ranges = summary_projection_archive_exact_ranges_with_coverage(
                    archive.has_materialized_historical_rollups(),
                    Some(replay_coverage.overall),
                    account_replayed,
                    usage_replayed,
                    archive_range,
                    &exact_archive_buckets,
                    &hourly_rollup_totals,
                    &hourly_rollup_usage,
                    account_ids,
                );
                if !mode.includes_all_time() {
                    exact_ranges = summary_projection_split_ranges_by_buckets(
                        exact_ranges,
                        &protected_boundary_buckets,
                    )
                    .0;
                }
                if exact_ranges.is_empty() {
                    continue;
                }
                if let Err(error) = summary_projection_admit_paged_boundary_raw_archive(
                    &mut paged_boundary_raw_archive_admissions,
                ) {
                    if !summary_projection_archive_raw_admission_exceeded(&error) {
                        return Err(error);
                    }
                    // A dense boundary can contain more raw manifests than the resident archive
                    // admission permits. Keep only this manifest's exact range unavailable and
                    // continue paging so disjoint ranges remain publishable.
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_buckets,
                        &mut unavailable_boundary_archive_ranges,
                        archive.has_materialized_historical_rollups(),
                        &exact_ranges,
                        &exact_bucket_requirements,
                    )?;
                    unavailable_unmaterialized_archive_current_ranges.push(archive_range);
                    continue;
                }
                let manifest_sha256 =
                    page_manifest_sha256
                        .get(archive.file_path())
                        .ok_or_else(|| {
                            anyhow!(
                                "summary projection paged archive manifest SHA is missing for {}",
                                archive.file_path()
                            )
                        })?;
                if Path::new(archive.file_path()).exists()
                    && verify_summary_projection_archive_file_sha256(&archive, manifest_sha256)?
                        == SummaryProjectionArchiveFileIdentity::Unavailable
                {
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_buckets,
                        &mut unavailable_boundary_archive_ranges,
                        archive.has_materialized_historical_rollups(),
                        &exact_ranges,
                        &exact_bucket_requirements,
                    )?;
                    unavailable_unmaterialized_archive_current_ranges.push(archive_range);
                    continue;
                }
                let Some((archive_pool, temp_cleanup)) =
                    crate::stats::open_invocation_archive_batch_pool(
                        &archive,
                        "summary-projection-paged-boundary",
                    )
                    .await?
                else {
                    // Planned exact ranges still need raw records. Mark the range unavailable so
                    // HTTP cannot publish an undercount from either a compact or raw source.
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_buckets,
                        &mut unavailable_boundary_archive_ranges,
                        archive.has_materialized_historical_rollups(),
                        &exact_ranges,
                        &exact_bucket_requirements,
                    )?;
                    unavailable_unmaterialized_archive_current_ranges.push(archive_range);
                    continue;
                };
                require_summary_projection_archive_file_sha256(&archive, manifest_sha256)?;
                let records_before_archive = records_by_invoke_id.clone();
                let exact_record_budget_before_archive = exact_record_budget;
                let exact_record_bytes_before_archive = exact_record_bytes;
                let merge_result = merge_summary_projection_archive_records_with_coverage(
                    &archive_pool,
                    pool,
                    &persisted_live_ids,
                    &hourly_rollup_totals,
                    &hourly_rollup_usage,
                    archive.has_materialized_historical_rollups(),
                    Some(replay_coverage.overall),
                    account_replayed,
                    usage_replayed,
                    archive_range,
                    &exact_archive_buckets,
                    usage_rollup_progress.get(archive.file_path()).copied(),
                    account_ids,
                    &mut records_by_invoke_id,
                    &mut exact_record_budget,
                    &mut exact_record_bytes,
                    current_record_bytes,
                )
                .await;
                require_summary_projection_archive_file_sha256(&archive, manifest_sha256)?;
                archive_pool.close().await;
                drop(temp_cleanup);
                if let Err(error) = merge_result {
                    if !summary_projection_archive_raw_admission_exceeded(&error) {
                        return Err(anyhow!(
                            "summary projection paged boundary archive hydration failed for {}: {error:?}",
                            archive.file_path()
                        ));
                    }
                    records_by_invoke_id = records_before_archive;
                    exact_record_budget = exact_record_budget_before_archive;
                    exact_record_bytes = exact_record_bytes_before_archive;
                    summary_projection_mark_unavailable_archive_ranges_by_requirement(
                        &mut unavailable_unmaterialized_archive_buckets,
                        &mut unavailable_boundary_archive_ranges,
                        archive.has_materialized_historical_rollups(),
                        &exact_ranges,
                        &exact_bucket_requirements,
                    )?;
                    unavailable_unmaterialized_archive_current_ranges.push(archive_range);
                }
            }
            let Some(next_after_id) = page.next_after_id else {
                break;
            };
            after_id = Some(next_after_id);
        }
        info!(
            ?mode,
            stage = "paged_boundary_archive_hydration",
            elapsed_ms = build_started_at.elapsed().as_millis() as u64,
            "summary projection build stage completed"
        );
    }
    // Archive rows are merged after the first live-record pass. Apply the same bucket-wide
    // coverage decision once every exact archive/live contribution is present.
    for record in records_by_invoke_id.values_mut() {
        let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
        if exact_global_total_rollup_buckets.contains(&bucket) {
            record.global_rollup_covered = false;
        }
        if exact_account_total_rollup_buckets.contains(&bucket) {
            record.account_rollup_covered = false;
        }
        if exact_global_usage_rollup_buckets.contains(&bucket) {
            record.usage_global_rollup_covered = false;
        }
        if exact_account_usage_rollup_buckets.contains(&bucket) {
            record.usage_account_rollup_covered = false;
        }
    }
    // A fully materialized archive in the moving exact tail can be an actual global newest-N
    // candidate. Read that bounded file source during hydration, not from HTTP, and keep only
    // its raw candidates in the separate current view. Unmaterialized archives remain an
    // explicit current-source gap because their latest-N order is not proven by rollups.
    let current_materialized_archives = current_archive_admission
        .iter()
        .filter(|archive| archive.has_materialized_historical_rollups())
        .cloned()
        .collect::<Vec<_>>();
    info!(
        ?mode,
        stage = "current_archive_admission",
        "summary projection build stage started"
    );
    let current_materialized_paths = current_materialized_archives
        .iter()
        .map(|archive| archive.file_path().to_string())
        .collect::<Vec<_>>();
    let current_materialized_sha256 =
        load_summary_projection_archive_manifest_sha256(pool, &current_materialized_paths).await?;
    let mut current_archive_candidate_records = HashMap::<String, SummaryProjectionRecord>::new();
    // A current-only archive candidate can fall just outside the bounded resident prefix. That
    // pruning cannot make a rolling/calendar range inexact when its compact totals and usage
    // dimensions have already replayed independently. Keep that proof distinct from current-N
    // admission, whose cutoff remains governed by the retained prefix.
    let mut current_archive_compact_rollup_proven_ids = HashSet::<String>::new();
    let mut current_archive_candidate_budget = 0usize;
    let mut current_archive_candidate_bytes = 0usize;
    let current_persisted_live_ids = records_by_invoke_id
        .values()
        .filter(|record| record.is_persisted_live_record)
        .map(|record| record.row.invoke_id.clone())
        .collect::<HashSet<_>>();
    for archive in &current_materialized_archives {
        let Some(archive_range) = summary_projection_archive_overlap_range(
            archive,
            ExactUtcRange {
                start: live_start,
                end,
            },
        ) else {
            continue;
        };
        let Some(manifest_sha256) = current_materialized_sha256.get(archive.file_path()) else {
            current_source_unavailable = true;
            continue;
        };
        let Some((archive_pool, temp_cleanup)) =
            crate::stats::open_invocation_archive_batch_pool(archive, "summary-projection-current")
                .await?
        else {
            continue;
        };
        let candidate_ids_before_archive = current_archive_candidate_records
            .keys()
            .cloned()
            .collect::<HashSet<_>>();
        require_summary_projection_archive_file_sha256(archive, manifest_sha256)?;
        let merge_result = merge_summary_projection_archive_records_with_coverage(
            &archive_pool,
            pool,
            &current_persisted_live_ids,
            &hourly_rollup_totals,
            &hourly_rollup_usage,
            false,
            None,
            None,
            None,
            archive_range,
            &HashSet::new(),
            None,
            &known_account_ids,
            &mut current_archive_candidate_records,
            &mut current_archive_candidate_budget,
            &mut current_archive_candidate_bytes,
            exact_record_bytes.saturating_add(current_record_bytes),
        )
        .await;
        require_summary_projection_archive_file_sha256(archive, manifest_sha256)?;
        archive_pool.close().await;
        drop(temp_cleanup);
        match merge_result {
            Ok(()) => {
                let replay_coverage = summary_projection_effective_replay_coverage(
                    archive,
                    archive_replay_coverage
                        .get(archive.file_path())
                        .copied()
                        .unwrap_or_default(),
                );
                if replay_coverage.supports_unavailable_archive() {
                    for (invoke_id, record) in &current_archive_candidate_records {
                        if candidate_ids_before_archive.contains(invoke_id) {
                            continue;
                        }
                        let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
                        let global_proven = hourly_rollup_totals.contains_key(&(bucket, None))
                            && hourly_rollup_usage.contains_key(&(bucket, None));
                        let account_proven =
                            record.row.upstream_account_id.is_none_or(|account_id| {
                                hourly_rollup_totals.contains_key(&(bucket, Some(account_id)))
                                    && hourly_rollup_usage.contains_key(&(bucket, Some(account_id)))
                            });
                        if global_proven && account_proven {
                            current_archive_compact_rollup_proven_ids.insert(invoke_id.clone());
                        }
                    }
                }
                // The current candidate read only covers the moving exact tail. Do not treat a
                // manifest which reaches outside that tail as fully represented: a larger
                // newest-N selection could still need one of its older rows.
                if summary_projection_archive_is_fully_represented_for_current(
                    archive,
                    ExactUtcRange {
                        start: live_start,
                        end,
                    },
                ) {
                    current_complete_archive_paths.insert(archive.file_path().to_string());
                }
            }
            Err(error) if summary_projection_archive_raw_admission_exceeded(&error) => {
                current_source_unavailable = true;
            }
            Err(error) => {
                return Err(anyhow!(
                    "summary projection current archive hydration failed for {}: {error:?}",
                    archive.file_path()
                ));
            }
        }
    }
    for record in current_archive_candidate_records.into_values() {
        let invoke_id = record.row.invoke_id.clone();
        if current_records_by_invoke_id.contains_key(&invoke_id) {
            continue;
        }
        let next_current_record_bytes =
            current_record_bytes.saturating_add(summary_projection_preview_row_bytes(&record.row));
        if let Err(error) = ensure_summary_projection_resident_record_bytes(
            exact_record_bytes,
            next_current_record_bytes,
        ) {
            if !summary_projection_resident_record_budget_exceeded(&error) {
                return Err(error);
            }
            current_source_unavailable = true;
            break;
        }
        current_record_bytes = next_current_record_bytes;
        current_records_by_invoke_id.insert(invoke_id, record);
    }
    info!(
        ?mode,
        stage = "current_archive_admission",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    let mut global_all_time_source_unavailable = all_time_global_exact_source_unavailable
        || all_time_archive_admission_exceeded
        || all_time_source_unavailable_from_archive_ranges;
    info!(
        ?mode,
        stage = "runtime_overlay",
        "summary projection build stage started"
    );
    // Runtime is an authoritative typed overlay until the terminal writer persists it.  Replace
    // only matching live keys; a new in-flight record is inserted exactly once.
    for runtime_record in state.proxy_runtime_invocations.snapshot() {
        let Some(row) = runtime_upstream_account_activity_preview_row_with_terminal(
            runtime_record,
            InvocationSourceScope::All,
            true,
        ) else {
            continue;
        };
        let Some(occurred_at) = parse_to_utc_datetime(&row.occurred_at) else {
            continue;
        };
        let is_new_rolling_record = !records_by_invoke_id.contains_key(&row.invoke_id);
        if is_new_rolling_record
            && records_by_invoke_id.len() >= summary_projection_exact_record_limit()
        {
            let bucket = align_bucket_epoch(occurred_at.timestamp(), 3_600, 0);
            unavailable_exact_live_buckets.insert(bucket);
            continue;
        }
        let record = SummaryProjectionRecord {
            row,
            occurred_at,
            global_rollup_covered: false,
            account_rollup_covered: false,
            usage_global_rollup_covered: false,
            usage_account_rollup_covered: false,
            is_persisted_live_record: false,
            is_archive_record: false,
            archive_has_materialized_rollups: false,
            account_archive_totals_fallback_included: false,
        };
        let replacement_bytes = summary_projection_preview_row_bytes(&record.row);
        let replaced_rolling_bytes = records_by_invoke_id
            .get(&record.row.invoke_id)
            .map(|previous| summary_projection_preview_row_bytes(&previous.row))
            .unwrap_or_default();
        let next_rolling_record_bytes = exact_record_bytes
            .saturating_sub(replaced_rolling_bytes)
            .saturating_add(replacement_bytes);
        let replaced_bytes = current_records_by_invoke_id
            .get(&record.row.invoke_id)
            .map(|previous| summary_projection_preview_row_bytes(&previous.row))
            .unwrap_or_default();
        let next_current_record_bytes = current_record_bytes
            .saturating_sub(replaced_bytes)
            .saturating_add(replacement_bytes);
        if let Err(error) = ensure_summary_projection_resident_record_bytes(
            next_rolling_record_bytes,
            next_current_record_bytes,
        ) {
            if !summary_projection_resident_record_budget_exceeded(&error) {
                return Err(error);
            }
            let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
            summary_projection_mark_unavailable_archive_ranges(
                &mut unavailable_exact_live_buckets,
                [ExactUtcRange {
                    start: Utc
                        .timestamp_opt(bucket, 0)
                        .single()
                        .expect("valid runtime overflow bucket start"),
                    end: Utc
                        .timestamp_opt(bucket.saturating_add(3_600), 0)
                        .single()
                        .expect("valid runtime overflow bucket end"),
                }],
            )?;
            current_source_unavailable = true;
            continue;
        }
        exact_record_bytes = next_rolling_record_bytes;
        current_record_bytes = next_current_record_bytes;
        records_by_invoke_id.insert(record.row.invoke_id.clone(), record.clone());
        current_records_by_invoke_id.insert(record.row.invoke_id.clone(), record);
    }

    info!(
        ?mode,
        stage = "runtime_overlay",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    info!(
        ?mode,
        stage = "projection_materialization",
        "summary projection build stage started"
    );
    let maintenance = load_stats_maintenance_response(state)
        .await
        .map_err(|error| anyhow!("summary projection maintenance hydration failed: {error:?}"))?;
    let mut records = records_by_invoke_id.into_values().collect::<Vec<_>>();
    records.sort_by(|left, right| {
        left.occurred_at
            .cmp(&right.occurred_at)
            .then_with(|| left.row.id.cmp(&right.row.id))
    });
    let mut current_records = current_records_by_invoke_id
        .into_values()
        .collect::<Vec<_>>();
    current_records.sort_by(|left, right| {
        left.occurred_at
            .cmp(&right.occurred_at)
            .then_with(|| left.row.id.cmp(&right.row.id))
    });
    if current_records.len() > summary_projection_exact_record_limit() {
        let first_retained = current_records.len() - summary_projection_exact_record_limit();
        recent_index_complete = false;
        let newly_pruned_at = current_records[..first_retained]
            .iter()
            .filter(|record| {
                !current_archive_compact_rollup_proven_ids.contains(&record.row.invoke_id)
            })
            .map(|record| record.occurred_at)
            .max();
        // A runtime overlay can be older than an already omitted durable row. Keep the newest
        // omitted timestamp so every range that could include either unretained source remains
        // unavailable instead of letting the older overlay relax the durable proof boundary.
        if let Some(newly_pruned_at) = newly_pruned_at {
            recent_index_overflow_at = Some(
                recent_index_overflow_at
                    .map(|existing| existing.max(newly_pruned_at))
                    .unwrap_or(newly_pruned_at),
            );
        }
        current_records.drain(..first_retained);
    }
    let mut hourly_buckets = BTreeMap::<i64, Vec<usize>>::new();
    for (index, record) in records.iter().enumerate() {
        hourly_buckets
            .entry(align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0))
            .or_default()
            .push(index);
    }
    let recent_limit = state.config.list_limit_max;
    let mut recent_indexes = HashMap::<Option<i64>, Vec<usize>>::new();
    for index in (0..current_records.len()).rev() {
        let account_id = current_records[index].row.upstream_account_id;
        for key in std::iter::once(None).chain(account_id.map(Some)) {
            let index_entries = recent_indexes.entry(key).or_default();
            if index_entries.len() < recent_limit {
                index_entries.push(index);
            }
        }
    }

    // Account ids are finite durable state at the hydration boundary. Include ids which only
    // survive in archived/rollup data as well as ids visible in the live record view, so `all`
    // never falls back to a differently scoped aggregate.
    let mut account_ids = known_account_ids;
    account_ids.extend(
        records
            .iter()
            .filter_map(|record| record.row.upstream_account_id)
            .filter(|account_id| *account_id > 0)
            .collect::<HashSet<_>>(),
    );
    account_ids.extend(
        current_records
            .iter()
            .filter_map(|record| record.row.upstream_account_id)
            .filter(|account_id| *account_id > 0),
    );
    account_ids.extend(load_summary_projection_durable_account_ids(pool).await?);
    if account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
        return Err(anyhow!(
            "summary projection account cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
        ));
    }
    let mut in_progress_by_account = HashMap::new();
    let mut active_in_progress_accounts = HashSet::new();
    for record in &records {
        if matches!(
            normalized_runtime_text(Some(record.row.status.as_str())).as_str(),
            "running" | "pending"
        ) && let Some(account_id) = record.row.upstream_account_id
        {
            active_in_progress_accounts.insert(account_id);
        }
    }
    for runtime_record in state.proxy_runtime_invocations.snapshot() {
        if runtime_in_flight_record_matches_filters(
            &runtime_record,
            &InvocationRecordsFilters::default(),
            InvocationSourceScope::All,
        ) && let Some(account_id) = runtime_record.upstream_account_id
        {
            active_in_progress_accounts.insert(account_id);
        }
    }
    account_ids.extend(active_in_progress_accounts.iter().copied());
    if account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
        return Err(anyhow!(
            "summary projection account cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
        ));
    }
    let global_in_progress =
        load_in_progress_summary_snapshot(state, InvocationSourceScope::All, None)
            .await
            .map_err(|error| {
                anyhow!("summary projection in-progress hydration failed: {error:?}")
            })?;
    let mut account_ids_with_projection_data = records
        .iter()
        .filter_map(|record| record.row.upstream_account_id)
        .filter(|account_id| *account_id > 0)
        .collect::<HashSet<_>>();
    account_ids_with_projection_data.extend(
        current_records
            .iter()
            .filter_map(|record| record.row.upstream_account_id)
            .filter(|account_id| *account_id > 0),
    );
    account_ids_with_projection_data.extend(
        hourly_rollup_totals
            .keys()
            .filter_map(|(_, account_id)| *account_id)
            .filter(|account_id| *account_id > 0),
    );
    account_ids_with_projection_data.extend(
        hourly_rollup_usage
            .keys()
            .filter_map(|(_, account_id)| *account_id)
            .filter(|account_id| *account_id > 0),
    );
    account_ids_with_projection_data.extend(
        archive_account_ids_by_file
            .values()
            .flat_map(|account_ids| account_ids.iter().copied())
            .filter(|account_id| *account_id > 0),
    );
    let mut batched_all_time_by_account = HashMap::<i64, StatsTotals>::new();
    let mut account_all_time_unavailable = all_time_account_exact_source_unavailable
        || all_time_archive_admission_exceeded
        || all_time_account_manifest_admission_exceeded
        || all_time_source_unavailable_from_archive_ranges;
    // Rolling-only rebuilds preserve the already-owned all-time map unchanged. Avoid a second
    // high-cardinality clone on that path; a previous copy is needed only when an all-time
    // rebuild may have to restore an exact last-good aggregate after a source failure.
    let previous_all_time_by_account =
        all_time_was_fully_rebuilt.then(|| all_time_by_account.clone());
    let all_time_built_at = Instant::now();
    let mut rebuilt_all_time_account_ids = HashSet::new();
    // All-time must use the same bounded projection inputs as rolling windows. The generic
    // stats query can open every unmaterialized archive and therefore cannot run in the
    // refresh path without defeating the rebuild deadline.
    let all_time_rollup_totals =
        if all_time_was_fully_rebuilt && !all_time_archive_admission_exceeded {
            match load_summary_projection_rollup_totals(pool).await {
                Ok((rollups, _)) => Some(rollups),
                Err(error) if summary_projection_rollup_admission_exceeded(&error) => {
                    // An `all` baseline outside the finite public horizon cannot prevent an exact
                    // rolling snapshot from publishing. Keep the existing all-time last-good (or
                    // unavailable state) and retry through the controlled admission path.
                    all_time_archive_admission_exceeded = true;
                    global_all_time_source_unavailable = true;
                    account_all_time_unavailable = true;
                    None
                }
                Err(error) => return Err(error),
            }
        } else {
            None
        };
    if let Some(all_time_rollup_totals) = all_time_rollup_totals {
        let all_time_archive_scan_paths =
            load_summary_projection_all_time_archive_scan_paths(pool).await?;
        // The finite exact tail deliberately does not retain every historical live row. When a
        // retained boundary replacement row is older than that tail, the complete all-time map
        // is the durable proof that it is already included. Refresh its per-scope flags before
        // adding exact fallbacks so old persisted rows cannot be counted twice.
        for record in records.iter_mut().chain(current_records.iter_mut()) {
            if !record.is_persisted_live_record {
                continue;
            }
            let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
            if record.row.id <= rollup_live_cursor
                && all_time_rollup_totals.contains_key(&(bucket, None))
                && !exact_global_total_rollup_buckets.contains(&bucket)
            {
                record.global_rollup_covered = true;
            }
            if account_rollup_live_cursor.is_some_and(|cursor| record.row.id <= cursor)
                && all_time_rollup_totals.contains_key(&(bucket, record.row.upstream_account_id))
                && !exact_account_total_rollup_buckets.contains(&bucket)
            {
                record.account_rollup_covered = true;
            }
        }
        let (
            global_rollup_coverage_proven,
            account_rollup_coverage_proven,
            paged_all_time_account_ids,
        ) = if let Some(high_watermark_id) = all_time_manifest_high_watermark_id {
            summary_projection_paged_all_time_materialized_scope_coverage(
                pool,
                high_watermark_id,
                &all_time_rollup_totals,
            )
            .await?
        } else {
            let (global_covered, account_covered) =
                summary_projection_all_time_materialized_scope_coverage(
                    &all_time_archives,
                    &all_time_archive_replay_coverage,
                    &all_time_archive_account_manifest_refreshed_paths,
                    &all_time_archive_account_ids_by_file,
                    &all_time_rollup_totals,
                )?;
            (global_covered, account_covered, HashSet::new())
        };
        account_ids.extend(paged_all_time_account_ids.iter().copied());
        account_ids_with_projection_data.extend(paged_all_time_account_ids);
        if account_ids.len() > SUMMARY_PROJECTION_MAX_ACCOUNTS {
            return Err(anyhow!(
                "summary projection all-time account cardinality exceeded bounded budget ({SUMMARY_PROJECTION_MAX_ACCOUNTS})"
            ));
        }
        // A replay marker is not sufficient by itself: a deleted or never-written aggregate key
        // would make the compact all-time baseline silently lose that archive bucket. Preserve
        // an exact last-good aggregate (or its existing unavailable contract) until durable
        // coverage can again be proven off-request.
        global_all_time_source_unavailable |= !global_rollup_coverage_proven;
        account_all_time_unavailable |= !account_rollup_coverage_proven;
        // A failed paged proof is retried on the same controlled admission cadence as a failed
        // bounded admission. A normally admitted manifest set keeps its existing immediate
        // repair behavior, but an overflowed history must not rescan every 10 seconds after an
        // incomplete durable repair.
        if all_time_manifest_high_watermark_id.is_some() {
            all_time_archive_admission_exceeded |= !global_rollup_coverage_proven;
            all_time_account_manifest_admission_exceeded |= !account_rollup_coverage_proven;
        }
        // With no completed archives, the canonical live rows are authoritative even when a
        // stale hourly rollup exists. Once archives are present, the rollup is the historical
        // prefix and only rows beyond the shared live cursor are an exact live tail.
        if !has_any_completed_archive && live_history_admission.is_none() {
            // A durable live table beyond the aggregate admission bound cannot be scanned during
            // hydration. Keep rolling/current projections available and fail closed for all-time
            // until archive/rollup maintenance supplies a compact baseline.
            global_all_time_source_unavailable = true;
            account_all_time_unavailable = true;
        }
        let mut global_totals = if !has_any_completed_archive {
            // Without archives the live table is the complete durable history. Keep that
            // history compact by hydrating one aggregate row instead of retaining/sorting every
            // old live record in the projection.
            if let Some(admission) = live_history_admission.as_ref() {
                StatsTotals::from(
                    crate::stats::query_stats_row_through_id(
                        pool,
                        InvocationSourceScope::All,
                        admission.upper_bound_id,
                    )
                    .await
                    .map_err(|error| {
                        anyhow!("summary projection live all-time hydration failed: {error:?}")
                    })?,
                )
            } else {
                StatsTotals::default()
            }
        } else {
            all_time_rollup_totals
                .iter()
                .filter(|((bucket, account_id), _)| {
                    account_id.is_none() && !exact_global_total_rollup_buckets.contains(bucket)
                })
                .fold(StatsTotals::default(), |totals, (_, bucket_totals)| {
                    totals.add(*bucket_totals)
                })
        };
        let live_tail = if !has_any_completed_archive {
            crate::stats::BoundedLiveInvocationIds {
                ids: HashSet::new(),
                upper_bound_id: rollup_live_cursor,
            }
        } else {
            crate::stats::load_live_invocation_ids_after_id_bounded_snapshot(
                pool,
                InvocationSourceScope::All,
                rollup_live_cursor,
                summary_projection_exact_record_limit(),
            )
            .await
            .map_err(|error| {
                anyhow!("summary projection live-tail id hydration failed: {error:?}")
            })?
        };
        let live_tail_ids = &live_tail.ids;
        if has_any_completed_archive && !live_tail_ids.is_empty() {
            // A zero global cursor proves no live row is represented by the compact baseline.
            // It may be missing after an interrupted repair, so publishing that baseline would
            // silently omit or double count the live history. Preserve exact last-good instead.
            if rollup_live_cursor == 0 {
                global_all_time_source_unavailable = true;
            }
            // Account rollups advance independently. Without their cursor, no account-scoped
            // all-time response can prove whether its compact prefix already contains live rows.
            if account_rollup_live_cursor.is_none() {
                account_all_time_unavailable = true;
            }
        }
        if has_any_completed_archive && rollup_live_cursor > 0 {
            global_totals = global_totals.add(
                crate::stats::query_live_invocation_totals_after_id(
                    pool,
                    InvocationSourceScope::All,
                    rollup_live_cursor,
                    live_tail.upper_bound_id,
                )
                .await
                .map_err(|error| {
                    anyhow!("summary projection live-tail totals hydration failed: {error:?}")
                })?,
            );
        }
        #[cfg(test)]
        pause_summary_projection_test_interleave(
            pool,
            mode,
            SummaryProjectionTestInterleaveStage::AfterAllTimeArchiveDiscovery,
        )
        .await?;
        let global_archive_scan_verified_paths =
            verify_summary_projection_archive_file_paths_sha256(
                &all_time_archive_scan_paths.global,
                &all_time_archive_manifest_sha256,
            )?;
        #[cfg(test)]
        pause_summary_projection_test_interleave(
            pool,
            mode,
            SummaryProjectionTestInterleaveStage::BeforeAllTimeArchiveScan,
        )
        .await?;
        if global_archive_scan_verified_paths.len() != all_time_archive_scan_paths.global.len() {
            // The generic global aggregate chooses its own archive paths inside `stats`. Do not
            // let a source which was unavailable at preflight become readable and enter that
            // scan under a different manifest revision. When every candidate is already
            // materialized, the compact global rollup is its exact all-time source and no raw
            // reconciliation is necessary; otherwise retain the last-good global aggregate.
            if all_time_archive_scan_paths.global_unmaterialized_count != 0 {
                global_all_time_source_unavailable = true;
            }
        } else {
            let unmaterialized_archive_totals =
                crate::stats::query_unmaterialized_invocation_archive_totals_bounded_strict(
                    pool,
                    InvocationSourceScope::All,
                    None,
                    Some(live_tail_ids),
                    summary_projection_exact_record_limit(),
                )
                .await;
            match unmaterialized_archive_totals {
                Ok(totals) => {
                    require_summary_projection_archive_file_paths_sha256(
                        &all_time_archive_scan_paths.global,
                        &all_time_archive_manifest_sha256,
                    )?;
                    global_totals = global_totals.add(totals);
                }
                Err(error)
                    if error
                        .to_string()
                        .starts_with("summary archive is unavailable:") =>
                {
                    global_all_time_source_unavailable = true;
                }
                Err(error) => {
                    return Err(anyhow!(
                        "summary projection global archive hydration failed: {error:?}"
                    ));
                }
            }
        }
        // Any materialized compact gap, including a missing rollup key with complete replay
        // markers, is replaced by its exact canonical source. Unmaterialized sibling archives
        // remain owned by the bounded delta helper above; adding their retained range records
        // here would double count the sibling after its durable overlap subtraction.
        let mut global_exact_record_ids = HashSet::<&str>::new();
        for record in records.iter().chain(current_records.iter()) {
            if !global_exact_record_ids.insert(record.row.invoke_id.as_str()) {
                continue;
            }
            if summary_projection_all_time_uses_global_exact_record(record, rollup_live_cursor) {
                global_totals =
                    global_totals.add(summary_projection_all_time_record_totals(record));
            }
        }
        if global_all_time_source_unavailable {
            // Retain only an exact prior aggregate, whose independent age still gates serving,
            // rather than publishing a zero or partial `all` response.
            if let Some(previous_global) = previous_all_time_by_account
                .as_ref()
                .and_then(|responses| responses.get(&None))
            {
                all_time_by_account.insert(None, previous_global.clone());
            } else {
                all_time_by_account.remove(&None);
            }
        } else {
            let mut global_response = global_totals.into_response();
            global_response.non_success_cost = Some(global_totals.non_success_cost);
            global_response.maintenance = Some(maintenance.clone());
            all_time_by_account.insert(None, global_response);
        }

        let account_totals = if !has_any_completed_archive {
            if let Some(admission) = live_history_admission.as_ref() {
                load_summary_projection_live_account_totals(pool, admission.upper_bound_id).await?
            } else {
                HashMap::new()
            }
        } else {
            load_summary_projection_account_rollup_totals(pool, &exact_account_total_rollup_buckets)
                .await?
        };
        for (account_id, totals) in account_totals {
            batched_all_time_by_account.insert(account_id, totals);
        }
        // Account rollups advance independently from the global compact baseline. Admit this
        // tail before aggregation and fence it at the observed ID, just as the global tail is
        // fenced above. A lagging account cursor must not turn one background refresh into an
        // unbounded table scan or absorb writes that arrived after this projection revision.
        if has_any_completed_archive {
            let account_live_tail =
                admit_summary_projection_live_tail_account_ids(pool, account_rollup_live_cursor)
                    .await?;
            for (account_id, totals) in load_summary_projection_live_tail_account_totals(
                pool,
                account_rollup_live_cursor,
                account_live_tail.map(|tail| tail.upper_bound_id),
            )
            .await?
            {
                let entry = batched_all_time_by_account.entry(account_id).or_default();
                *entry = entry.add(totals);
            }
        }
        let account_archive_scan_verified_paths =
            verify_summary_projection_archive_file_paths_sha256(
                &all_time_archive_scan_paths.account,
                &all_time_archive_manifest_sha256,
            )?;
        let account_archive_totals = if account_archive_scan_verified_paths.len()
            != all_time_archive_scan_paths.account.len()
        {
            account_all_time_unavailable = true;
            HashMap::new()
        } else {
            let account_archive_totals =
                crate::stats::query_unmaterialized_upstream_account_archive_totals_by_account(
                    pool,
                    HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_STATS_HOURLY,
                    InvocationSourceScope::All,
                    None,
                    Some(live_tail_ids),
                )
                .await;
            match account_archive_totals {
                Ok(totals) => {
                    require_summary_projection_archive_file_paths_sha256(
                        &all_time_archive_scan_paths.account,
                        &all_time_archive_manifest_sha256,
                    )?;
                    totals
                }
                Err(error)
                    if error
                        .to_string()
                        .starts_with("summary account archive is unavailable:") =>
                {
                    // Global rollups remain a valid read-only fallback for this refresh, but an
                    // account response would be an undercount without the missing archive.
                    account_all_time_unavailable = true;
                    HashMap::new()
                }
                Err(error) => {
                    return Err(anyhow!(
                        "summary projection account archive hydration failed: {error:?}"
                    ));
                }
            }
        };
        for (account_id, totals) in account_archive_totals {
            let entry = batched_all_time_by_account.entry(account_id).or_default();
            *entry = entry.add(totals);
        }
        // A global materialization marker does not prove account coverage. Only canonical rows
        // not represented by the account compact aggregate contribute here, so a global-only
        // fallback does not double count an otherwise covered account bucket.
        let mut account_exact_record_ids = HashSet::<&str>::new();
        for record in records.iter().chain(current_records.iter()) {
            if !account_exact_record_ids.insert(record.row.invoke_id.as_str()) {
                continue;
            }
            // With no completed archives the live-table aggregate above is the complete
            // persisted history, regardless of rollup cursor lag. Only runtime overlay rows
            // are absent from that aggregate and need an exact-record contribution here.
            if !has_any_completed_archive && record.is_persisted_live_record {
                continue;
            }
            let Some((account_id, totals)) = summary_projection_account_record_totals(record)
            else {
                continue;
            };
            if !summary_projection_all_time_uses_account_exact_record(
                record,
                account_rollup_live_cursor,
            ) {
                continue;
            }
            let entry = batched_all_time_by_account.entry(account_id).or_default();
            *entry = entry.add(totals);
        }
    }
    for upstream_account_id in std::iter::once(None).chain(account_ids.iter().copied().map(Some)) {
        // Runtime state belongs to every admitted account independently of whether its compact
        // all-time aggregate is currently available. Populate it before an all-time fail-closed
        // branch can skip that account, so ranged hot reads never lose an in-flight overlay.
        let in_progress = match upstream_account_id {
            None => global_in_progress,
            Some(account_id) if active_in_progress_accounts.contains(&account_id) => {
                load_in_progress_summary_snapshot(
                    state,
                    InvocationSourceScope::All,
                    Some(account_id),
                )
                .await
                .map_err(|error| {
                    anyhow!("summary projection in-progress hydration failed: {error:?}")
                })?
            }
            Some(_) => InProgressSummarySnapshot::default(),
        };
        in_progress_by_account.insert(upstream_account_id, in_progress);
        if all_time_was_fully_rebuilt && let Some(account_id) = upstream_account_id {
            if account_all_time_unavailable {
                continue;
            }
            let totals = match batched_all_time_by_account.get(&account_id).copied() {
                Some(totals) => totals,
                None if account_ids_with_projection_data.contains(&account_id) => {
                    // A legal account with known history but no exact all-time aggregate must
                    // not fall through to the retained records view, which would silently
                    // undercount archive-only history.
                    continue;
                }
                None => StatsTotals::default(),
            };
            let mut response = totals.into_response();
            response.non_success_cost = Some(totals.non_success_cost);
            response.maintenance = Some(maintenance.clone());
            all_time_by_account.insert(Some(account_id), response);
            all_time_account_refreshed_at.insert(account_id, all_time_built_at);
            rebuilt_all_time_account_ids.insert(account_id);
        }
        if all_time_was_fully_rebuilt
            && let Some(response) = all_time_by_account.get_mut(&upstream_account_id)
        {
            response.in_progress_conversation_count = Some(in_progress.in_progress_count);
            response.in_progress_retry_conversation_count = Some(in_progress.retry_count);
            response.in_progress_avg_wait_ms = in_progress.avg_wait_ms;
            response.in_progress_phase_counts = Some(in_progress.phase_counts);
        }
    }
    let revision = state
        .subscription_hub
        .next_summary_projection_revision()
        .await;
    let all_time_completed_at = all_time_was_fully_rebuilt.then(Instant::now);
    if let Some(completed_at) = all_time_completed_at {
        for account_id in &rebuilt_all_time_account_ids {
            all_time_account_refreshed_at.insert(*account_id, completed_at);
        }
    }
    let refreshed_at = Some(Instant::now());
    let freshness = SummaryProjectionFreshness {
        global_all_time_eligible: if all_time_was_fully_rebuilt {
            if global_all_time_source_unavailable {
                previous_global_all_time_eligible && all_time_by_account.contains_key(&None)
            } else {
                all_time_by_account.contains_key(&None)
            }
        } else {
            previous_global_all_time_eligible
        },
        account_all_time_eligible: if all_time_was_fully_rebuilt {
            if account_all_time_unavailable {
                previous_account_all_time_eligible
            } else {
                all_time_by_account
                    .keys()
                    .filter_map(|account_id| *account_id)
                    .collect()
            }
        } else {
            previous_account_all_time_eligible
        },
    };
    let all_time_oldest_account_refreshed_at =
        all_time_account_refreshed_at.values().copied().min();
    let persisted_live_record_has_unavailable_global_rolling_coverage =
        |record: &SummaryProjectionRecord| {
            unavailable_exact_live_buckets.contains(&align_bucket_epoch(
                record.occurred_at.timestamp(),
                3_600,
                0,
            ))
        };
    let persisted_live_record_has_unavailable_account_rolling_coverage =
        |record: &SummaryProjectionRecord| {
            let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
            record
                .row
                .upstream_account_id
                .filter(|account_id| *account_id > 0)
                .is_some_and(|account_id| {
                    unavailable_exact_live_account_buckets
                        .get(&account_id)
                        .is_some_and(|buckets| buckets.contains(&bucket))
                })
        };
    let rolling_exact_persisted_live_invoke_ids = records
        .iter()
        .filter(|record| record.is_persisted_live_record)
        .map(|record| record.row.invoke_id.as_str())
        .collect::<HashSet<_>>();
    let mut persisted_live_terminal_invoke_ids = records
        .iter()
        .chain(current_records.iter())
        .filter(|record| {
            record.is_persisted_live_record
                // The current index deliberately keeps a larger bounded prefix than a legal
                // newest-N response. An old persisted row in that prefix cannot suppress an
                // SSE terminal delta unless it is also retained in the rolling exact view; its
                // compact coverage is added separately below after both totals and usage proof.
                && rolling_exact_persisted_live_invoke_ids.contains(record.row.invoke_id.as_str())
                && !persisted_live_record_has_unavailable_global_rolling_coverage(record)
        })
        .map(|record| format!("{}\0{}", record.row.invoke_id, record.row.occurred_at))
        .collect::<HashSet<_>>();
    persisted_live_terminal_invoke_ids.extend(historical_global_covered_terminal_invoke_ids);
    let all_time_terminal_coverage_complete = if all_time_was_fully_rebuilt {
        // Global all-time responses have an independent durable source contract. An account
        // manifest gap must not make an otherwise exact global aggregate replay every terminal
        // delta or exhaust the shared all-time overlay budget.
        !global_all_time_source_unavailable
    } else {
        previous_all_time_terminal_coverage_complete
    };
    let all_time_terminal_sequence_watermark = summary_projection_all_time_sequence_watermark(
        all_time_was_fully_rebuilt,
        all_time_terminal_coverage_complete,
        durable_terminal_sequence_watermark,
        previous_all_time_terminal_sequence_watermark,
    );
    let all_time_persisted_live_terminal_invoke_ids =
        if all_time_was_fully_rebuilt && all_time_terminal_coverage_complete {
            records
                .iter()
                .chain(current_records.iter())
                .filter(|record| {
                    record.is_persisted_live_record
                        && !persisted_live_record_has_unavailable_global_rolling_coverage(record)
                })
                .map(|record| format!("{}\0{}", record.row.invoke_id, record.row.occurred_at))
                .collect()
        } else {
            previous_all_time_persisted_live_terminal_invoke_ids
        };
    let (
        all_time_account_terminal_sequence_watermarks,
        all_time_account_persisted_live_terminal_invoke_ids,
    ) = if all_time_was_fully_rebuilt && !account_all_time_unavailable {
        let account_watermarks = rebuilt_all_time_account_ids
            .iter()
            .map(|account_id| (*account_id, durable_terminal_sequence_watermark))
            .collect::<HashMap<_, _>>();
        let mut account_identities = HashMap::<i64, HashSet<String>>::new();
        for record in records
            .iter()
            .chain(current_records.iter())
            .filter(|record| {
                record.is_persisted_live_record
                    && !persisted_live_record_has_unavailable_global_rolling_coverage(record)
                    && !persisted_live_record_has_unavailable_account_rolling_coverage(record)
                    && record.row.upstream_account_id.is_some_and(|account_id| {
                        rebuilt_all_time_account_ids.contains(&account_id)
                    })
            })
        {
            let Some(account_id) = record.row.upstream_account_id else {
                continue;
            };
            account_identities
                .entry(account_id)
                .or_default()
                .insert(format!(
                    "{}\0{}",
                    record.row.invoke_id, record.row.occurred_at
                ));
        }
        (account_watermarks, account_identities)
    } else {
        (
            previous_all_time_account_terminal_sequence_watermarks,
            previous_all_time_account_persisted_live_terminal_invoke_ids,
        )
    };
    let mut unavailable_unmaterialized_archive_ranges =
        summary_projection_unavailable_bucket_ranges(unavailable_unmaterialized_archive_buckets);
    unavailable_unmaterialized_archive_ranges
        .extend(unavailable_unmaterialized_archive_exact_ranges);
    let unavailable_unmaterialized_archive_ranges =
        summary_projection_merge_exact_ranges(unavailable_unmaterialized_archive_ranges);
    let unavailable_boundary_archive_ranges =
        summary_projection_merge_exact_ranges(unavailable_boundary_archive_ranges);
    let unavailable_unmaterialized_archive_current_ranges =
        summary_projection_merge_exact_ranges(unavailable_unmaterialized_archive_current_ranges);
    let unavailable_unmaterialized_archive_account_ranges =
        summary_projection_unavailable_bucket_ranges(
            unavailable_unmaterialized_archive_account_buckets,
        );
    let unavailable_boundary_archive_account_ranges =
        summary_projection_merge_exact_ranges(unavailable_boundary_archive_account_ranges);
    let unavailable_unmaterialized_archive_account_current_ranges =
        summary_projection_merge_exact_ranges(
            unavailable_unmaterialized_archive_account_current_ranges,
        );
    let unavailable_exact_live_ranges =
        summary_projection_unavailable_bucket_ranges(unavailable_exact_live_buckets);
    let unavailable_exact_live_account_ranges = unavailable_exact_live_account_buckets
        .into_iter()
        .map(|(account_id, buckets)| {
            (
                account_id,
                summary_projection_unavailable_bucket_ranges(buckets),
            )
        })
        .collect();
    let (current_archive_latest_coverage_end, current_archive_has_unknown_coverage) =
        load_summary_projection_unrepresented_current_archive_coverage(
            pool,
            &current_complete_archive_paths,
        )
        .await?;
    // The global current admission only hydrates the moving exact tail. A completed archive
    // outside that tail may still be the newest record for a quiet account, so account current
    // can be exact only when every completed archive was represented in the resident view.
    let current_account_source_unavailable = current_archive_admission_exceeded
        || current_archive_has_unknown_coverage
        || current_archive_latest_coverage_end.is_some();
    let projection = SummaryProjection {
        records,
        current_records,
        persisted_live_terminal_invoke_ids,
        all_time_terminal_coverage_complete,
        all_time_terminal_sequence_watermark,
        all_time_persisted_live_terminal_invoke_ids,
        all_time_account_terminal_sequence_watermarks,
        all_time_account_persisted_live_terminal_invoke_ids,
        durable_terminal_sequence_watermark,
        hourly_buckets,
        recent_indexes,
        recent_index_complete,
        recent_index_overflow_at,
        hourly_rollup_totals,
        hourly_rollup_non_success_tokens,
        hourly_rollup_usage,
        exact_global_total_rollup_buckets,
        exact_account_total_rollup_buckets,
        exact_global_usage_rollup_buckets,
        exact_account_usage_rollup_buckets,
        rollup_live_cursor,
        historical_live_coverage,
        all_time_by_account,
        all_time_refreshed_at: if all_time_was_fully_rebuilt && !global_all_time_source_unavailable
        {
            all_time_completed_at
        } else {
            previous_all_time_refreshed_at
        },
        all_time_manifest_admission_blocked_at: if all_time_was_fully_rebuilt {
            all_time_archive_admission_exceeded.then(Instant::now)
        } else {
            previous_all_time_manifest_admission_blocked_at
        },
        all_time_account_manifest_admission_blocked_at:
            if all_time_account_manifest_admission_attempted {
                all_time_account_manifest_admission_exceeded.then(Instant::now)
            } else {
                previous_all_time_account_manifest_admission_blocked_at
            },
        all_time_account_refreshed_at,
        all_time_oldest_account_refreshed_at,
        all_time_account_ids_with_projection_data: account_ids_with_projection_data,
        known_account_ids: account_ids,
        archive_account_ids_by_file,
        archive_coverage_ranges_by_file: archive_actual_coverage_ranges,
        unavailable_unmaterialized_archive_ranges,
        unavailable_boundary_archive_ranges,
        unavailable_unmaterialized_archive_current_ranges,
        unavailable_unmaterialized_archive_account_ranges,
        unavailable_boundary_archive_account_ranges,
        unavailable_unmaterialized_archive_account_current_ranges,
        unavailable_exact_live_ranges,
        unavailable_exact_live_account_ranges,
        current_source_unavailable,
        current_source_unavailable_from_rank,
        current_account_source_unavailable_from_rank,
        current_archive_latest_coverage_end,
        current_archive_has_unknown_coverage,
        current_archive_admission_exceeded,
        current_account_source_unavailable,
        in_progress_by_account,
        maintenance: Some(maintenance),
        generation_fence: SummaryProjectionGenerationFence {
            live_high_watermark_id,
            rollup_live_cursor,
            account_rollup_live_cursor,
            completed_manifest_high_watermark_id,
            durable_terminal_sequence_watermark,
        },
        freshness_lease: SummaryProjectionFreshnessLease::default(),
        refreshed_at,
        freshness,
        revision,
    };
    info!(
        ?mode,
        stage = "projection_materialization",
        elapsed_ms = build_started_at.elapsed().as_millis() as u64,
        "summary projection build stage completed"
    );
    #[cfg(test)]
    pause_summary_projection_test_interleave(
        pool,
        mode,
        SummaryProjectionTestInterleaveStage::BeforeProjectionPublication,
    )
    .await?;
    Ok(projection)
}

#[derive(Debug, Clone, Copy)]
enum SummarySnapshotTrigger {
    Cadence,
    Mutation,
}

fn summary_snapshot_trigger_marks_dirty(trigger: SummarySnapshotTrigger, has_owner: bool) -> bool {
    matches!(trigger, SummarySnapshotTrigger::Mutation)
        || (matches!(trigger, SummarySnapshotTrigger::Cadence) && has_owner)
}

pub(crate) fn spawn_summary_snapshot_maintenance(state: Arc<AppState>) {
    tokio::spawn(async move {
        let mut receiver = state.broadcaster.subscribe();
        let mut mutation_receiver = state.subscription_hub.runtime_mutation_bus().subscribe();
        let mut cadence = tokio::time::interval(SUMMARY_SNAPSHOT_REFRESH_INTERVAL);
        cadence.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let mut last_refresh_attempt = None;
        let mut retry_not_before = None;
        let mut dirty = false;
        loop {
            let trigger_refresh = tokio::select! {
                _ = state.shutdown.cancelled() => return,
                _ = cadence.tick() => {
                    if !state.subscription_hub.has_summary_owner().await {
                        None
                    } else {
                    let has_all_time_owner = state.subscription_hub.has_summary_all_time_owner().await;
                    let needs_attention = state
                        .subscription_hub
                        .summary_projection()
                        .await
                        .is_none_or(|projection| projection.needs_cadence_refresh(has_all_time_owner));
                        needs_attention.then_some(SummarySnapshotTrigger::Cadence)
                    }
                },
                payload = receiver.recv() => matches!(
                    payload,
                    Ok(BroadcastPayload::DashboardCurrentSlice { .. })
                        | Ok(BroadcastPayload::DashboardTerminalSlice { .. })
                        | Ok(BroadcastPayload::DashboardActivityLive { .. })
                        | Err(broadcast::error::RecvError::Lagged(_))
                ).then_some(SummarySnapshotTrigger::Mutation),
                mutation = mutation_receiver.recv() => summary_snapshot_runtime_mutation_is_dirty(mutation)
                    .then_some(SummarySnapshotTrigger::Mutation),
            };
            let Some(trigger) = trigger_refresh else {
                continue;
            };
            let has_owner = state.subscription_hub.has_summary_owner().await;
            // Mutations remain coalesced while idle so the next real consumer receives a
            // bounded off-request rebuild. A due cadence is meaningful only for a live owner;
            // otherwise it would renew a full SQLite/archive hydration indefinitely.
            dirty |= summary_snapshot_trigger_marks_dirty(trigger, has_owner);
            if !has_owner {
                continue;
            }
            if !dirty {
                continue;
            }
            let now = Instant::now();
            if !summary_snapshot_refresh_is_due(last_refresh_attempt, retry_not_before, now) {
                continue;
            }
            // Merge mutation bursts before starting the expensive off-request baseline. A due
            // cadence already spent its full minimum interval and must start immediately to
            // retain the strict hot-read freshness budget.
            if matches!(trigger, SummarySnapshotTrigger::Mutation) {
                tokio::time::sleep(SUMMARY_SNAPSHOT_EVENT_DEBOUNCE).await;
            }
            while receiver.try_recv().is_ok() {}
            while mutation_receiver.try_recv().is_ok() {}
            last_refresh_attempt = Some(Instant::now());
            match refresh_summary_snapshots(state.as_ref()).await {
                Ok(()) => {
                    dirty = false;
                    retry_not_before = None;
                }
                Err(error) => {
                    retry_not_before = Some(summary_snapshot_retry_not_before(Instant::now()));
                    warn!(
                        ?error,
                        retry_after_secs = SUMMARY_SNAPSHOT_FAILURE_RETRY_BACKOFF.as_secs(),
                        "summary snapshot maintenance failed; retaining last-good responses before a bounded retry"
                    );
                }
            }
        }
    });
}

fn summary_snapshot_runtime_mutation_is_dirty(
    mutation: Result<SequencedRuntimeMutation, broadcast::error::RecvError>,
) -> bool {
    match mutation {
        Ok(event) => matches!(
            event.mutation,
            RuntimeMutation::Invocation(_) | RuntimeMutation::AttemptChanged { .. }
        ),
        Err(broadcast::error::RecvError::Lagged(_)) => true,
        Err(broadcast::error::RecvError::Closed) => false,
    }
}

fn summary_snapshot_retry_not_before(failed_at: Instant) -> Instant {
    failed_at + SUMMARY_SNAPSHOT_FAILURE_RETRY_BACKOFF
}

fn summary_snapshot_refresh_is_due(
    last_refresh_attempt: Option<Instant>,
    retry_not_before: Option<Instant>,
    now: Instant,
) -> bool {
    last_refresh_attempt
        .is_none_or(|attempt| now.duration_since(attempt) >= SUMMARY_SNAPSHOT_MIN_REFRESH_INTERVAL)
        && retry_not_before.is_none_or(|retry_at| now >= retry_at)
}

#[derive(Debug, Clone, Copy)]
pub(crate) enum SummaryBuildRoute {
    Http,
    Topic,
    Background,
}

impl SummaryBuildRoute {
    fn telemetry_route(self) -> &'static str {
        match self {
            Self::Http => "summary_http",
            Self::Topic => "summary_topic",
            Self::Background => "summary_background",
        }
    }

    fn closed_window_delivery_mode(self) -> &'static str {
        match self {
            Self::Http => "http_closed",
            Self::Topic => "sse_topic",
            Self::Background => "background_snapshot",
        }
    }
}

fn summary_window_is_closed(window: &SummaryWindow) -> bool {
    matches!(window, SummaryWindow::Calendar(spec) if spec == "yesterday")
        || matches!(window, SummaryWindow::PreviousFullDays(_))
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SummaryRangeBuildTelemetry {
    route: SummaryBuildRoute,
    window_kind: &'static str,
    window_name: &'static str,
    closed_window: bool,
}

impl SummaryRangeBuildTelemetry {
    pub(crate) fn new(
        route: SummaryBuildRoute,
        window: &SummaryWindow,
        requested_window: Option<&str>,
    ) -> Self {
        let window_kind = match window {
            SummaryWindow::Duration(_) => "duration",
            SummaryWindow::Calendar(_) => "calendar",
            SummaryWindow::PreviousFullDays(_) => "previous_full_days",
            SummaryWindow::All => "all",
            SummaryWindow::Current(_) => "current",
        };
        let window_name = match window {
            SummaryWindow::Duration(_) => match requested_window {
                Some("7d") => "7d",
                Some("1d") | None => "1d",
                _ => "range",
            },
            SummaryWindow::Calendar(spec) => match spec.as_str() {
                "today" => "today",
                "yesterday" => "yesterday",
                _ => "range",
            },
            SummaryWindow::PreviousFullDays(7) => "previous7d",
            _ => "range",
        };
        Self {
            route,
            window_kind,
            window_name,
            closed_window: summary_window_is_closed(window),
        }
    }

    fn route_label(self) -> &'static str {
        self.route.telemetry_route()
    }
}

#[derive(Debug, Clone, Copy)]
struct UsageBreakdownBuildTelemetry {
    route: &'static str,
    window_kind: &'static str,
    window_name: &'static str,
    closed_window: bool,
}

impl UsageBreakdownBuildTelemetry {
    fn from_summary(telemetry: SummaryRangeBuildTelemetry) -> Self {
        Self {
            route: telemetry.route_label(),
            window_kind: telemetry.window_kind,
            window_name: telemetry.window_name,
            closed_window: telemetry.closed_window,
        }
    }

    fn from_range_route(route: &'static str, range_name: &str) -> Self {
        let (window_kind, window_name, closed_window) = match range_name {
            "today" => ("calendar", "today", false),
            "yesterday" => ("calendar", "yesterday", true),
            "1d" => ("duration", "1d", false),
            "7d" => ("duration", "7d", false),
            "previous7d" => ("previous_full_days", "previous7d", true),
            _ => ("range", "range", false),
        };
        Self {
            route,
            window_kind,
            window_name,
            closed_window,
        }
    }
}

fn emit_summary_range_builder_telemetry(
    telemetry: SummaryRangeBuildTelemetry,
    builder: &'static str,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    aggregation_mode: &'static str,
    archive_overlap_strategy: &'static str,
    live_group_row_count: usize,
    archive_group_row_count: usize,
    live_row_scan_mode: &'static str,
    live_id_overlap_scan_mode: &'static str,
    elapsed_ms: u64,
) {
    let route = telemetry.route_label();
    let group_row_count = live_group_row_count + archive_group_row_count;
    if elapsed_ms >= 250 {
        tracing::warn!(
            route,
            builder,
            ?source_scope,
            upstream_account_id,
            window_kind = telemetry.window_kind,
            window_name = telemetry.window_name,
            closed_window = telemetry.closed_window,
            aggregation_mode,
            archive_overlap_strategy,
            live_group_row_count,
            archive_group_row_count,
            group_row_count,
            live_row_scan_mode,
            live_id_overlap_scan_mode,
            elapsed_ms,
            "summary range builder exceeded slow-path threshold"
        );
    } else {
        tracing::debug!(
            route,
            builder,
            ?source_scope,
            upstream_account_id,
            window_kind = telemetry.window_kind,
            window_name = telemetry.window_name,
            closed_window = telemetry.closed_window,
            aggregation_mode,
            archive_overlap_strategy,
            live_group_row_count,
            archive_group_row_count,
            group_row_count,
            live_row_scan_mode,
            live_id_overlap_scan_mode,
            elapsed_ms,
            "summary range builder completed"
        );
    }
}

fn emit_usage_breakdown_builder_telemetry(
    telemetry: UsageBreakdownBuildTelemetry,
    source_scope: InvocationSourceScope,
    full_hour_bucket_count: usize,
    rollup_row_count: usize,
    partial_hour_row_count: usize,
    archive_batch_count: usize,
    fallback_reason: &'static str,
    legacy_pruned_payload_mode: &'static str,
    elapsed_ms: u64,
) {
    let builder = if archive_batch_count > 0 {
        "usage_breakdown_archive_fallback"
    } else if full_hour_bucket_count == 0 {
        "usage_breakdown_exact_tail"
    } else {
        "usage_breakdown_rollup"
    };
    let archive_replay_target = HOURLY_ROLLUP_TARGET_UPSTREAM_ACCOUNT_USAGE_BREAKDOWN;
    let fallback_batch_count_after_rollup = archive_batch_count;
    if elapsed_ms >= 250 {
        tracing::warn!(
            route = telemetry.route,
            builder,
            ?source_scope,
            window_kind = telemetry.window_kind,
            window_name = telemetry.window_name,
            closed_window = telemetry.closed_window,
            full_hour_bucket_count,
            rollup_row_count,
            partial_hour_row_count,
            archive_batch_count,
            fallback_reason,
            legacy_pruned_payload_mode,
            archive_replay_target,
            fallback_batch_count_after_rollup,
            elapsed_ms,
            "usage breakdown builder exceeded slow-path threshold"
        );
    } else {
        tracing::debug!(
            route = telemetry.route,
            builder,
            ?source_scope,
            window_kind = telemetry.window_kind,
            window_name = telemetry.window_name,
            closed_window = telemetry.closed_window,
            full_hour_bucket_count,
            rollup_row_count,
            partial_hour_row_count,
            archive_batch_count,
            fallback_reason,
            legacy_pruned_payload_mode,
            archive_replay_target,
            fallback_batch_count_after_rollup,
            elapsed_ms,
            "usage breakdown builder completed"
        );
    }
}

#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct SummaryLiveAugmentation {
    in_progress_conversation_count: Option<i64>,
    in_progress_retry_conversation_count: Option<i64>,
    in_progress_avg_wait_ms: Option<f64>,
    in_progress_phase_counts: Option<InvocationPhaseCountsResponse>,
    non_success_tokens: Option<i64>,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SummaryLiveAugmentationPolicy {
    include_in_progress: bool,
    include_non_success_tokens: bool,
}

pub(crate) fn summary_window_range(
    window: &SummaryWindow,
    reporting_tz: Tz,
    now: DateTime<Utc>,
) -> Result<Option<(DateTime<Utc>, DateTime<Utc>)>, ApiError> {
    match window {
        SummaryWindow::All | SummaryWindow::Current(_) => Ok(None),
        SummaryWindow::Duration(duration) => Ok(Some((now - *duration, now))),
        SummaryWindow::Calendar(spec) => {
            let range =
                resolve_range_window(spec.as_str(), reporting_tz).map_err(ApiError::from)?;
            Ok(Some((range.start, range.end)))
        }
        SummaryWindow::PreviousFullDays(day_count) => {
            let (start, end) = previous_full_days_range_bounds(*day_count, now, reporting_tz)
                .ok_or_else(|| {
                    ApiError::bad_request(anyhow!("invalid previous full days window"))
                })?;
            Ok(Some((start, end)))
        }
    }
}

pub(crate) async fn load_summary_live_augmentation(
    state: &AppState,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    range: Option<(DateTime<Utc>, DateTime<Utc>)>,
    policy: SummaryLiveAugmentationPolicy,
    range_telemetry: Option<SummaryRangeBuildTelemetry>,
) -> Result<SummaryLiveAugmentation, ApiError> {
    let in_progress = if policy.include_in_progress {
        let snapshot =
            load_in_progress_summary_snapshot(state, source_scope, upstream_account_id).await?;
        (
            Some(snapshot.in_progress_count),
            Some(snapshot.retry_count),
            snapshot.avg_wait_ms,
            Some(snapshot.phase_counts),
        )
    } else {
        (None, None, None, None)
    };
    let non_success_tokens = if policy.include_non_success_tokens {
        if let Some((start, end)) = range {
            let telemetry = range_telemetry.ok_or_else(|| {
                ApiError::from(anyhow!(
                    "summary range telemetry is required for non-success token augmentation"
                ))
            })?;
            load_non_success_tokens_snapshot(
                state,
                source_scope,
                upstream_account_id,
                ExactUtcRange { start, end },
                telemetry,
            )
            .await?
        } else {
            None
        }
    } else {
        None
    };

    Ok(SummaryLiveAugmentation {
        in_progress_conversation_count: in_progress.0,
        in_progress_retry_conversation_count: in_progress.1,
        in_progress_avg_wait_ms: in_progress.2,
        in_progress_phase_counts: in_progress.3,
        non_success_tokens,
    })
}

pub(crate) fn apply_summary_live_augmentation(
    response: &mut StatsResponse,
    augmentation: SummaryLiveAugmentation,
) {
    response.in_progress_conversation_count = augmentation.in_progress_conversation_count;
    response.in_progress_retry_conversation_count =
        augmentation.in_progress_retry_conversation_count;
    response.in_progress_avg_wait_ms = augmentation.in_progress_avg_wait_ms;
    response.in_progress_phase_counts = augmentation.in_progress_phase_counts;
    response.non_success_tokens = augmentation.non_success_tokens;
}

#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct InProgressSummarySnapshot {
    in_progress_count: i64,
    retry_count: i64,
    avg_wait_ms: Option<f64>,
    phase_counts: InvocationPhaseCountsResponse,
}

pub(crate) async fn load_in_progress_summary_snapshot(
    state: &AppState,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
) -> Result<InProgressSummarySnapshot, ApiError> {
    #[derive(Debug, FromRow)]
    struct RuntimeKeyRow {
        invoke_id: String,
        occurred_at: String,
        upstream_account_id: Option<i64>,
        retry_count: i64,
        upstream_ttfb_ms: Option<f64>,
        live_phase: Option<String>,
    }

    let resolved_upstream_account_id_sql =
        invocation_upstream_account_id_with_attempt_fallback_sql("inv");
    let retry_sql = if upstream_account_id.is_some() {
        invocation_account_retry_after_failure_with_attempt_fallback_sql(
            resolved_upstream_account_id_sql.as_str(),
            source_scope,
        )
    } else {
        match source_scope {
            InvocationSourceScope::All => "live.is_retry_after_failure_all".to_string(),
            InvocationSourceScope::ProxyOnly => {
                "live.is_retry_after_failure_proxy_only".to_string()
            }
        }
    };
    let final_first_token_timing_sql = final_pool_invocation_timing_sql("inv", "first_token_ms");
    let final_live_phase_sql =
        invocation_live_phase_sql_with_timing_sql("inv", final_first_token_timing_sql.as_str());
    let live_ttfb_nonnegative_sql = sqlite_nonnegative_timing_sql("live.upstream_ttfb_ms");
    let mut query = QueryBuilder::<Sqlite>::new(
        "SELECT \
            COALESCE(COUNT(*), 0) AS in_progress_count, \
            COALESCE(SUM(",
    );
    query.push(retry_sql.as_str()).push(
        format!(
            "), 0) AS retry_count, \
         AVG(CASE WHEN {live_ttfb_nonnegative_sql} THEN live.upstream_ttfb_ms END) AS avg_wait_ms, \
         COUNT(CASE WHEN {live_ttfb_nonnegative_sql} THEN 1 END) AS avg_wait_sample_count \
         FROM invocation_in_progress_live live \
         JOIN codex_invocations inv ON inv.id = live.invocation_id \
         WHERE 1 = 1",
        )
        .as_str(),
    );

    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND live.source = ").push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        query
            .push(" AND ")
            .push(resolved_upstream_account_id_sql.as_str())
            .push(" = ")
            .push_bind(upstream_account_id);
    }

    let (mut db_in_progress_count, mut retry_count, avg_wait_ms, mut avg_wait_sample_count) = query
        .build_query_as::<(i64, i64, Option<f64>, i64)>()
        .fetch_one(&state.pool)
        .await?;
    let mut db_key_query = QueryBuilder::<Sqlite>::new(
        "SELECT inv.invoke_id AS invoke_id, inv.occurred_at AS occurred_at, ",
    );
    db_key_query
        .push(resolved_upstream_account_id_sql.as_str())
        .push(" AS upstream_account_id, ")
        .push(retry_sql.as_str())
        .push(" AS retry_count, live.upstream_ttfb_ms AS upstream_ttfb_ms, ");
    db_key_query.push(final_live_phase_sql.as_str()).push(
        " AS live_phase \
         FROM invocation_in_progress_live live \
         JOIN codex_invocations inv ON inv.id = live.invocation_id \
         WHERE 1 = 1",
    );
    if source_scope == InvocationSourceScope::ProxyOnly {
        db_key_query
            .push(" AND live.source = ")
            .push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        db_key_query
            .push(" AND ")
            .push(resolved_upstream_account_id_sql.as_str())
            .push(" = ")
            .push_bind(upstream_account_id);
    }
    let db_runtime_rows = db_key_query
        .build_query_as::<RuntimeKeyRow>()
        .fetch_all(&state.pool)
        .await?;
    let mut phase_counts = InvocationPhaseCountsResponse::default();
    for row in &db_runtime_rows {
        phase_counts.increment_phase_name(row.live_phase.as_deref());
    }
    let runtime_snapshot = state.proxy_runtime_invocations.snapshot();
    let db_terminal_keys =
        query_terminal_db_keys_for_runtime_records(&state.pool, &runtime_snapshot, None).await?;
    let runtime_by_key = runtime_snapshot
        .iter()
        .map(|record| {
            (
                (record.invoke_id.clone(), record.occurred_at.clone()),
                record,
            )
        })
        .collect::<HashMap<_, _>>();
    let filter = InvocationRecordsFilters {
        upstream_account_id,
        ..InvocationRecordsFilters::default()
    };
    let filter_without_upstream_account = InvocationRecordsFilters {
        upstream_account_id: None,
        ..filter.clone()
    };
    let mut db_ttfb_sum = avg_wait_ms.unwrap_or_default() * avg_wait_sample_count as f64;
    for row in &db_runtime_rows {
        let key = (row.invoke_id.clone(), row.occurred_at.clone());
        let Some(runtime_record) = runtime_by_key.get(&key) else {
            continue;
        };
        let account_matches = upstream_account_id
            .map(|account_id| row.upstream_account_id == Some(account_id))
            .unwrap_or(true);
        if account_matches
            && runtime_in_flight_record_matches_filters(
                runtime_record,
                &filter_without_upstream_account,
                source_scope,
            )
        {
            let runtime_phase = runtime_record_live_phase(runtime_record);
            if runtime_phase != row.live_phase.as_deref() {
                phase_counts.decrement_phase_name(row.live_phase.as_deref());
                phase_counts.increment_phase_name(runtime_phase);
            }
            if runtime_record_ttfb_differs(runtime_record.t_upstream_ttfb_ms, row.upstream_ttfb_ms)
            {
                db_ttfb_sum = (db_ttfb_sum
                    - normalized_wait_ms(row.upstream_ttfb_ms).unwrap_or_default())
                .max(0.0)
                    + normalized_wait_ms(runtime_record.t_upstream_ttfb_ms).unwrap_or_default();
                avg_wait_sample_count =
                    avg_wait_sample_count.saturating_sub(i64::from(
                        normalized_wait_ms(row.upstream_ttfb_ms).is_some(),
                    )) + i64::from(normalized_wait_ms(runtime_record.t_upstream_ttfb_ms).is_some());
            }
            continue;
        }
        db_in_progress_count = db_in_progress_count.saturating_sub(1);
        phase_counts.decrement_phase_name(row.live_phase.as_deref());
        if row.retry_count > 0 {
            retry_count = retry_count.saturating_sub(1);
        }
        if let Some(ttfb_ms) = row
            .upstream_ttfb_ms
            .filter(|value| value.is_finite() && *value >= 0.0)
        {
            db_ttfb_sum -= ttfb_ms;
            avg_wait_sample_count = avg_wait_sample_count.saturating_sub(1);
        }
    }
    let db_runtime_keys = db_runtime_rows
        .into_iter()
        .map(|row| ((row.invoke_id, row.occurred_at), row.retry_count > 0))
        .collect::<HashMap<_, _>>();
    let runtime_records = runtime_snapshot
        .into_iter()
        .filter(|record| {
            !db_terminal_keys.contains(&(record.invoke_id.clone(), record.occurred_at.clone()))
        })
        .filter(|record| runtime_in_flight_record_matches_filters(record, &filter, source_scope))
        .collect::<Vec<_>>();
    let runtime_in_progress_count = runtime_records
        .iter()
        .filter(|record| {
            !db_runtime_keys.contains_key(&(record.invoke_id.clone(), record.occurred_at.clone()))
        })
        .count() as i64;
    let runtime_retry_count = runtime_records
        .iter()
        .filter(|record| {
            let key = (record.invoke_id.clone(), record.occurred_at.clone());
            runtime_record_is_retry(record) && !db_runtime_keys.get(&key).copied().unwrap_or(false)
        })
        .count() as i64;
    let runtime_phase_counts = runtime_records
        .iter()
        .filter(|record| {
            !db_runtime_keys.contains_key(&(record.invoke_id.clone(), record.occurred_at.clone()))
        })
        .fold(
            InvocationPhaseCountsResponse::default(),
            |mut counts, record| {
                counts.increment_phase_name(runtime_record_live_phase(record));
                counts
            },
        );
    let (ttfb_sum, ttfb_count) = runtime_records
        .iter()
        .filter(|record| {
            !db_runtime_keys.contains_key(&(record.invoke_id.clone(), record.occurred_at.clone()))
        })
        .filter_map(|record| {
            record
                .t_upstream_ttfb_ms
                .filter(|value| value.is_finite() && *value >= 0.0)
        })
        .fold((0.0, 0_i64), |(sum, count), value| (sum + value, count + 1));
    let combined_avg_wait_ms = match (avg_wait_sample_count, ttfb_count) {
        (db_sample_count, runtime_count) if db_sample_count > 0 || runtime_count > 0 => {
            Some((db_ttfb_sum + ttfb_sum) / (db_sample_count + runtime_count) as f64)
        }
        _ => None,
    };
    if runtime_in_progress_count > 0 {
        debug!(
            endpoint = "/api/stats/summary",
            runtime_overlay_row_count = runtime_in_progress_count,
            upstream_account_id,
            "overlayed memory runtime in-progress records into summary live augmentation"
        );
    }
    phase_counts.queued += runtime_phase_counts.queued;
    phase_counts.requesting += runtime_phase_counts.requesting;
    phase_counts.responding += runtime_phase_counts.responding;
    Ok(InProgressSummarySnapshot {
        in_progress_count: db_in_progress_count + runtime_in_progress_count,
        retry_count: retry_count + runtime_retry_count,
        avg_wait_ms: combined_avg_wait_ms,
        phase_counts,
    })
}

pub(crate) async fn load_live_invocation_ids_in_range(
    pool: &Pool<Sqlite>,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    start: DateTime<Utc>,
    end: DateTime<Utc>,
) -> Result<std::collections::HashSet<i64>, ApiError> {
    #[derive(Debug, FromRow)]
    struct IdRow {
        id: i64,
    }

    let mut query =
        QueryBuilder::<Sqlite>::new("SELECT id FROM codex_invocations WHERE occurred_at >= ");
    query
        .push_bind(db_occurred_at_lower_bound(start))
        .push(" AND occurred_at < ")
        .push_bind(db_occurred_at_upper_bound(end));

    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        query
            .push(" AND ")
            .push(crate::api::INVOCATION_UPSTREAM_ACCOUNT_ID_SQL)
            .push(" = ")
            .push_bind(upstream_account_id);
    }

    Ok(query
        .build_query_as::<IdRow>()
        .fetch_all(pool)
        .await?
        .into_iter()
        .map(|row| row.id)
        .collect())
}

pub(crate) fn summary_live_augmentation_policy(
    window: &SummaryWindow,
    range: Option<(DateTime<Utc>, DateTime<Utc>)>,
    now: DateTime<Utc>,
) -> SummaryLiveAugmentationPolicy {
    let closed_named_window = matches!(
        window,
        SummaryWindow::Calendar(_) | SummaryWindow::PreviousFullDays(_)
    ) && range.is_some_and(|(_, end)| end < now);

    SummaryLiveAugmentationPolicy {
        include_in_progress: !closed_named_window,
        include_non_success_tokens: !closed_named_window && range.is_some(),
    }
}

async fn query_account_activity_v2_non_success_tokens(
    tx: &mut SqliteConnection,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    bucket_epochs: &[i64],
) -> Result<i64, ApiError> {
    if bucket_epochs.is_empty() {
        return Ok(0);
    }
    let mut query = QueryBuilder::<Sqlite>::new(
        "SELECT COALESCE(SUM(COALESCE(activity_v2_non_success_tokens, 0)), 0) \
         FROM upstream_account_stats_hourly WHERE bucket_start_epoch IN (",
    );
    {
        let mut separated = query.separated(", ");
        for bucket_epoch in bucket_epochs {
            separated.push_bind(*bucket_epoch);
        }
    }
    query.push(")");
    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        query
            .push(" AND upstream_account_id = ")
            .push_bind(upstream_account_id);
    }
    Ok(query.build_query_scalar::<i64>().fetch_one(tx).await?)
}

async fn query_non_success_tokens_exact_tail(
    executor: impl sqlx::Executor<'_, Database = Sqlite>,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    range: ExactUtcRange,
) -> Result<i64, ApiError> {
    let normalized_status_sql = INVOCATION_STATUS_NORMALIZED_SQL;
    let resolved_failure_class_sql = INVOCATION_RESOLVED_FAILURE_CLASS_SQL;
    let non_success_sql = format!(
        "({normalized_status_sql} = 'interrupted' OR \
         ({normalized_status_sql} NOT IN ('running', 'pending') \
          AND ({resolved_failure_class_sql}) <> 'none'))"
    );
    let mut query = QueryBuilder::<Sqlite>::new(format!(
        "SELECT COALESCE(SUM(CASE WHEN {non_success_sql} THEN COALESCE(total_tokens, 0) ELSE 0 END), 0) \
         FROM codex_invocations WHERE occurred_at >= "
    ));
    query
        .push_bind(db_occurred_at_lower_bound(range.start))
        .push(" AND occurred_at < ")
        .push_bind(db_occurred_at_upper_bound(range.end));
    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        query
            .push(" AND ")
            .push(INVOCATION_UPSTREAM_ACCOUNT_ID_SQL)
            .push(" = ")
            .push_bind(upstream_account_id);
    }
    Ok(query
        .build_query_scalar::<i64>()
        .fetch_one(executor)
        .await?)
}

async fn query_non_success_tokens_unreplayed_live_tail(
    tx: &mut SqliteConnection,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    covered_hours: &[i64],
    repair_cursor: i64,
    bucket_watermarks: &BTreeMap<i64, i64>,
) -> Result<i64, ApiError> {
    if covered_hours.is_empty() {
        return Ok(0);
    }
    let normalized_status_sql = INVOCATION_STATUS_NORMALIZED_SQL;
    let resolved_failure_class_sql = INVOCATION_RESOLVED_FAILURE_CLASS_SQL;
    let non_success_sql = format!(
        "({normalized_status_sql} = 'interrupted' OR \
         ({normalized_status_sql} NOT IN ('running', 'pending') \
          AND ({resolved_failure_class_sql}) <> 'none'))"
    );
    let mut query = QueryBuilder::<Sqlite>::new(format!(
        "SELECT COALESCE(SUM(CASE WHEN {non_success_sql} THEN COALESCE(total_tokens, 0) ELSE 0 END), 0) \
         FROM codex_invocations WHERE ("
    ));
    for (index, bucket_epoch) in covered_hours.iter().enumerate() {
        let start = Utc
            .timestamp_opt(*bucket_epoch, 0)
            .single()
            .ok_or_else(|| ApiError::from(anyhow!("invalid covered-hour start epoch")))?;
        let end = start + ChronoDuration::hours(1);
        if index > 0 {
            query.push(" OR ");
        }
        query
            .push("(id > ")
            .push_bind(
                repair_cursor.max(
                    bucket_watermarks
                        .get(bucket_epoch)
                        .copied()
                        .unwrap_or_default(),
                ),
            )
            .push(" AND occurred_at >= ")
            .push_bind(db_occurred_at_lower_bound(start))
            .push(" AND occurred_at < ")
            .push_bind(db_occurred_at_upper_bound(end))
            .push(")");
    }
    query.push(")");
    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    if let Some(upstream_account_id) = upstream_account_id {
        query
            .push(" AND ")
            .push(INVOCATION_UPSTREAM_ACCOUNT_ID_SQL)
            .push(" = ")
            .push_bind(upstream_account_id);
    }
    Ok(query.build_query_scalar::<i64>().fetch_one(tx).await?)
}

fn summary_non_success_tokens_lock_fallback(
    telemetry: SummaryRangeBuildTelemetry,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    range: ExactUtcRange,
    stage: &'static str,
) -> Result<Option<i64>, ApiError> {
    tracing::warn!(
        route = telemetry.route_label(),
        builder = "summary_non_success_tokens",
        ?source_scope,
        upstream_account_id,
        window_kind = telemetry.window_kind,
        window_name = telemetry.window_name,
        aggregation_mode = "fallback",
        archive_overlap_strategy = "fallback",
        live_row_scan_mode = "fallback",
        live_id_overlap_scan_mode = "none",
        stage,
        start = %range.start,
        end = %range.end,
        "summary non-success token augmentation skipped because sqlite is locked"
    );
    Ok(None)
}

pub(crate) async fn load_non_success_tokens_snapshot(
    state: &AppState,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
    range: ExactUtcRange,
    telemetry: SummaryRangeBuildTelemetry,
) -> Result<Option<i64>, ApiError> {
    let started_at = Instant::now();
    let retention_cutoff = shanghai_retention_cutoff(state.config.invocation_max_days);
    let live_range = ExactUtcRange {
        start: range.start.max(retention_cutoff),
        end: range.end,
    };
    let mut live_tokens = 0_i64;
    let mut live_group_row_count = 0_usize;
    let mut covered_hour_count = 0_usize;
    let mut boundary_tail_count = 0_usize;
    let mut fallback_hour_count = 0_usize;
    let mut live_row_scan_mode = "none";
    let historical_live_end = range.end.min(retention_cutoff);
    if range.start < historical_live_end {
        let historical_tokens = match query_non_success_tokens_exact_tail(
            &state.pool,
            source_scope,
            upstream_account_id,
            ExactUtcRange {
                start: range.start,
                end: historical_live_end,
            },
        )
        .await
        {
            Ok(tokens) => tokens,
            Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "historical_exact_tail",
                );
            }
            Err(err) => return Err(err),
        };
        live_tokens += historical_tokens;
        live_row_scan_mode = "fallback";
    }
    if live_range.start < live_range.end {
        let mut tx = match state.pool.begin().await {
            Ok(tx) => tx,
            Err(err) if crate::is_sqlite_lock_error(&anyhow!(err.to_string())) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "live_snapshot",
                );
            }
            Err(err) => return Err(err.into()),
        };
        let plan = match plan_account_activity_range_tx(state, tx.as_mut(), live_range).await {
            Ok(plan) => plan,
            Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "coverage_planner",
                );
            }
            Err(err) => return Err(err),
        };
        covered_hour_count = plan.covered_hours.len();
        fallback_hour_count = plan.uncovered_hours.len();
        boundary_tail_count = plan.boundary_tail_count;
        let rollup_tokens = match query_account_activity_v2_non_success_tokens(
            tx.as_mut(),
            source_scope,
            upstream_account_id,
            &plan.covered_hours,
        )
        .await
        {
            Ok(tokens) => tokens,
            Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "hourly_rollup",
                );
            }
            Err(err) => return Err(err),
        };
        live_tokens += rollup_tokens;
        live_group_row_count = plan.covered_hours.len();
        let repair_cursor = match load_hourly_rollup_live_progress_tx(
            tx.as_mut(),
            INVOCATION_ACCOUNT_ACTIVITY_V2_REPAIR_CURSOR_DATASET,
        )
        .await
        {
            Ok(cursor) => cursor,
            Err(err) => {
                if crate::is_sqlite_lock_error(&err) {
                    return summary_non_success_tokens_lock_fallback(
                        telemetry,
                        source_scope,
                        upstream_account_id,
                        range,
                        "v2_repair_cursor",
                    );
                }
                return Err(err.into());
            }
        };
        let bucket_watermarks = match load_account_activity_v2_bucket_repair_watermarks(
            tx.as_mut(),
            &plan.covered_hours,
        )
        .await
        {
            Ok(watermarks) => watermarks,
            Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "v2_bucket_watermarks",
                );
            }
            Err(err) => return Err(err),
        };
        let unreplayed_live_tail = match query_non_success_tokens_unreplayed_live_tail(
            tx.as_mut(),
            source_scope,
            upstream_account_id,
            &plan.covered_hours,
            repair_cursor,
            &bucket_watermarks,
        )
        .await
        {
            Ok(tokens) => tokens,
            Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                return summary_non_success_tokens_lock_fallback(
                    telemetry,
                    source_scope,
                    upstream_account_id,
                    range,
                    "unreplayed_live_tail",
                );
            }
            Err(err) => return Err(err),
        };
        live_tokens += unreplayed_live_tail;
        if unreplayed_live_tail != 0 {
            tracing::debug!(
                route = telemetry.route_label(),
                builder = "summary_non_success_tokens",
                purpose = "unreplayed_live_tail",
                repair_cursor,
                covered_hour_count = plan.covered_hours.len(),
                "summary non-success token rollup included unreplayed live tail"
            );
        }
        for (index, exact_range) in plan.exact_ranges.into_iter().enumerate() {
            let exact_tokens = match query_non_success_tokens_exact_tail(
                tx.as_mut(),
                source_scope,
                upstream_account_id,
                exact_range,
            )
            .await
            {
                Ok(tokens) => tokens,
                Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
                    return summary_non_success_tokens_lock_fallback(
                        telemetry,
                        source_scope,
                        upstream_account_id,
                        range,
                        "exact_tail",
                    );
                }
                Err(err) => return Err(err),
            };
            live_tokens += exact_tokens;
            live_row_scan_mode = "fallback";
            if index >= boundary_tail_count {
                tracing::debug!(
                    route = telemetry.route_label(),
                    builder = "summary_non_success_tokens",
                    purpose = "coverage_hole",
                    source_scope = ?source_scope,
                    start = %exact_range.start,
                    end = %exact_range.end,
                    "summary non-success token exact fallback covered an hourly hole"
                );
            }
        }
        tx.commit().await?;
    }

    if range.start >= retention_cutoff {
        let elapsed_ms = started_at.elapsed().as_millis() as u64;
        tracing::debug!(
            route = telemetry.route_label(),
            builder = "summary_non_success_tokens",
            ?source_scope,
            upstream_account_id,
            window_kind = telemetry.window_kind,
            window_name = telemetry.window_name,
            aggregation_mode = "rollup_plus_boundary",
            archive_overlap_strategy = "aggregate_merge",
            covered_hour_count,
            fallback_hour_count,
            boundary_tail_count,
            live_group_row_count,
            archive_group_row_count = 0_usize,
            live_row_scan_mode,
            live_id_overlap_scan_mode = "none",
            elapsed_ms,
            "summary non-success token rollup completed"
        );
        return Ok(Some(live_tokens));
    }

    let archive_rows = match query_completed_invocation_archive_activity_aggregate_rows(
        &state.pool,
        source_scope,
        range,
    )
    .await
    {
        Ok(rows) => rows,
        Err(ApiError::Internal(err)) if crate::is_sqlite_lock_error(&err) => {
            tracing::warn!(
                route = telemetry.route_label(),
                builder = "summary_non_success_tokens",
                ?source_scope,
                upstream_account_id,
                window_kind = telemetry.window_kind,
                window_name = telemetry.window_name,
                aggregation_mode = "fallback",
                archive_overlap_strategy = "fallback",
                live_group_row_count,
                archive_group_row_count = 0_usize,
                live_row_scan_mode,
                live_id_overlap_scan_mode = "none",
                start = %range.start,
                end = %range.end,
                "summary archive aggregate overlap merge skipped because sqlite is locked"
            );
            return Ok(None);
        }
        Err(err) => return Err(err),
    };
    let archive_group_row_count = archive_rows.aggregates.len();
    if !archive_rows.skipped_materialized_ranges.is_empty() {
        let elapsed_ms = started_at.elapsed().as_millis() as u64;
        emit_summary_range_builder_telemetry(
            telemetry,
            "summary_non_success_tokens",
            source_scope,
            upstream_account_id,
            "fallback",
            "fallback",
            live_group_row_count,
            archive_group_row_count,
            live_row_scan_mode,
            "none",
            elapsed_ms,
        );
        return Ok(None);
    }
    let archived_tokens = archive_rows
        .aggregates
        .into_iter()
        .filter(|row| {
            upstream_account_id.is_none_or(|account_id| row.upstream_account_id == Some(account_id))
        })
        .map(|row| row.non_success_tokens)
        .sum::<i64>();
    let elapsed_ms = started_at.elapsed().as_millis() as u64;
    emit_summary_range_builder_telemetry(
        telemetry,
        "summary_non_success_tokens",
        source_scope,
        upstream_account_id,
        "rollup_plus_boundary",
        "aggregate_merge",
        live_group_row_count,
        archive_group_row_count,
        live_row_scan_mode,
        "none",
        elapsed_ms,
    );
    Ok(Some(live_tokens + archived_tokens))
}

pub(crate) async fn build_empty_summary_response(
    state: &AppState,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
) -> Result<StatsResponse, ApiError> {
    let mut response = StatsResponse {
        total_count: 0,
        success_count: 0,
        failure_count: 0,
        total_cost: 0.0,
        total_tokens: 0,
        usage_breakdown: None,
        in_progress_conversation_count: None,
        in_progress_retry_conversation_count: None,
        in_progress_avg_wait_ms: None,
        in_progress_phase_counts: None,
        non_success_cost: Some(0.0),
        non_success_tokens: None,
        maintenance: Some(load_stats_maintenance_response(state).await?),
    };
    let augmentation = load_summary_live_augmentation(
        state,
        source_scope,
        upstream_account_id,
        None,
        SummaryLiveAugmentationPolicy {
            include_in_progress: true,
            include_non_success_tokens: false,
        },
        None,
    )
    .await?;
    apply_summary_live_augmentation(&mut response, augmentation);
    Ok(response)
}

