pub(crate) async fn query_dashboard_activity_live_snapshot_from_runtime(
    pool: &Pool<Sqlite>,
    proxy_runtime_invocations: &ProxyRuntimeInvocationStore,
    dashboard_network_speed_cache: &DashboardNetworkSpeedCache,
    revision: u64,
) -> Result<DashboardActivityLiveSnapshot, ApiError> {
    query_dashboard_activity_live_snapshot_with_baseline_from_runtime(
        pool,
        proxy_runtime_invocations,
        dashboard_network_speed_cache,
        revision,
    )
    .await
    .map(|(snapshot, _)| snapshot)
}

pub(crate) async fn query_dashboard_activity_live_snapshot_with_baseline_from_runtime(
    pool: &Pool<Sqlite>,
    proxy_runtime_invocations: &ProxyRuntimeInvocationStore,
    dashboard_network_speed_cache: &DashboardNetworkSpeedCache,
    revision: u64,
) -> Result<
    (
        DashboardActivityLiveSnapshot,
        DashboardRuntimeProjectionBaseline,
    ),
    ApiError,
> {
    let now = Utc::now();
    let source_scope = resolve_default_source_scope(pool).await?;
    flush_dashboard_network_socket_minute_rollups(pool, dashboard_network_speed_cache, now).await?;
    let mut baseline = query_dashboard_runtime_projection_baseline(pool, source_scope).await?;
    let counts = query_upstream_account_in_progress_counts_with_baseline(
        pool,
        proxy_runtime_invocations,
        source_scope,
        &baseline,
    )
    .await?;
    let account_rates = dashboard_network_speed_cache.snapshot_account_rates(now);
    let global_realtime_rate = build_dashboard_network_realtime_rate_response(
        dashboard_network_speed_cache
            .snapshot_scope_realtime_bytes(DashboardNetworkScopeKey::Global, now),
    );
    let mut live_bucket_account_ids = counts.keys().copied().collect::<Vec<_>>();
    for upstream_account_id in account_rates.keys() {
        if !live_bucket_account_ids.contains(upstream_account_id) {
            live_bucket_account_ids.push(*upstream_account_id);
        }
    }
    let mut live_buckets = HashMap::new();
    for upstream_account_id in live_bucket_account_ids {
        live_buckets.insert(
            upstream_account_id,
            load_dashboard_network_live_bucket_point(
                pool,
                dashboard_network_speed_cache,
                source_scope,
                now,
                match upstream_account_id {
                    Some(id) => DashboardNetworkScopeKey::Account(id),
                    None => DashboardNetworkScopeKey::Unassigned,
                },
            )
            .await?,
        );
    }
    let mut accounts = counts
        .into_iter()
        .map(|(upstream_account_id, summary)| {
            let rate = account_rates
                .get(&upstream_account_id)
                .copied()
                .unwrap_or_default();
            DashboardActivityLiveAccount {
                account_key: upstream_account_id
                    .map(|id| format!("upstream:{id}"))
                    .unwrap_or_else(|| "unassigned".to_string()),
                upstream_account_id,
                upstream_account_name: None,
                in_progress_invocation_count: summary.in_progress_count,
                in_progress_phase_counts: summary.phase_counts,
                retry_invocation_count: summary.retry_count,
                in_progress_wait_sum_ms: summary.wait_sum_ms,
                in_progress_wait_sample_count: summary.wait_sample_count,
                upload_bytes_per_second: rate.upload_bytes_per_second,
                download_bytes_per_second: rate.download_bytes_per_second,
                network_live_bucket: live_buckets.get(&upstream_account_id).cloned(),
            }
        })
        .collect::<Vec<_>>();
    let existing_account_keys = accounts
        .iter()
        .map(|account| account.account_key.clone())
        .collect::<HashSet<_>>();
    for (upstream_account_id, rate) in account_rates {
        let account_key = upstream_account_id
            .map(|id| format!("upstream:{id}"))
            .unwrap_or_else(|| "unassigned".to_string());
        if existing_account_keys.contains(&account_key) {
            continue;
        }
        accounts.push(DashboardActivityLiveAccount {
            account_key,
            upstream_account_id,
            upstream_account_name: None,
            in_progress_invocation_count: 0,
            in_progress_phase_counts: InvocationPhaseCountsResponse::default(),
            retry_invocation_count: 0,
            in_progress_wait_sum_ms: 0.0,
            in_progress_wait_sample_count: 0,
            upload_bytes_per_second: rate.upload_bytes_per_second,
            download_bytes_per_second: rate.download_bytes_per_second,
            network_live_bucket: live_buckets.get(&upstream_account_id).cloned(),
        });
    }
    accounts.sort_by(|left, right| left.account_key.cmp(&right.account_key));

    let global_live_bucket = load_dashboard_network_live_bucket_point(
        pool,
        dashboard_network_speed_cache,
        source_scope,
        now,
        DashboardNetworkScopeKey::Global,
    )
    .await?;
    let mut network_open_buckets = HashMap::new();
    for (upstream_account_id, live_bucket) in &live_buckets {
        let scope = DashboardNetworkScopeKey::account_scope(*upstream_account_id);
        let memory = dashboard_network_speed_cache.snapshot_open_bucket(scope, now);
        network_open_buckets.insert(
            scope,
            DashboardRuntimeNetworkOpenBucketBaseline {
                bucket_start: memory.bucket_start,
                bucket_end: memory.bucket_end,
                baseline_totals: DashboardNetworkByteTotals {
                    upload_bytes: live_bucket.upload_bytes,
                    download_bytes: live_bucket.download_bytes,
                },
                memory_totals_at_install: memory.totals,
            },
        );
    }
    let global_memory =
        dashboard_network_speed_cache.snapshot_open_bucket(DashboardNetworkScopeKey::Global, now);
    network_open_buckets.insert(
        DashboardNetworkScopeKey::Global,
        DashboardRuntimeNetworkOpenBucketBaseline {
            bucket_start: global_memory.bucket_start,
            bucket_end: global_memory.bucket_end,
            baseline_totals: DashboardNetworkByteTotals {
                upload_bytes: global_live_bucket.upload_bytes,
                download_bytes: global_live_bucket.download_bytes,
            },
            memory_totals_at_install: global_memory.totals,
        },
    );
    baseline.network_open_buckets = network_open_buckets;

    let mut in_progress_phase_counts = InvocationPhaseCountsResponse::default();
    let mut in_progress_invocation_count = 0;
    let mut retry_invocation_count = 0;
    let mut in_progress_wait_sum_ms = 0.0;
    let mut in_progress_wait_sample_count = 0;
    for account in &accounts {
        in_progress_invocation_count += account.in_progress_invocation_count;
        retry_invocation_count += account.retry_invocation_count;
        in_progress_wait_sum_ms += account.in_progress_wait_sum_ms;
        in_progress_wait_sample_count += account.in_progress_wait_sample_count;
        in_progress_phase_counts.queued += account.in_progress_phase_counts.queued;
        in_progress_phase_counts.requesting += account.in_progress_phase_counts.requesting;
        in_progress_phase_counts.responding += account.in_progress_phase_counts.responding;
    }

    Ok((
        DashboardActivityLiveSnapshot {
            revision,
            generated_at: format_utc_iso(now),
            in_progress_invocation_count,
            in_progress_phase_counts,
            retry_invocation_count,
            in_progress_wait_sum_ms,
            in_progress_wait_sample_count,
            network_live_bucket: Some(global_live_bucket),
            network_realtime_rate: Some(global_realtime_rate),
            accounts,
        },
        baseline,
    ))
}

fn dashboard_live_snapshot_in_progress_counts(
    snapshot: &DashboardActivityLiveSnapshot,
) -> HashMap<Option<i64>, UpstreamAccountInProgressSummary> {
    snapshot
        .accounts
        .iter()
        .map(|account| {
            (
                account.upstream_account_id,
                UpstreamAccountInProgressSummary {
                    in_progress_count: account.in_progress_invocation_count,
                    retry_count: account.retry_invocation_count,
                    phase_counts: account.in_progress_phase_counts,
                    wait_sum_ms: account.in_progress_wait_sum_ms,
                    wait_sample_count: account.in_progress_wait_sample_count,
                },
            )
        })
        .collect()
}

pub(crate) const DASHBOARD_ACTIVITY_RATE_WINDOW_MINUTES: i64 = 5;
/// DB-backed Dashboard baselines are reconciled at a bounded cadence. Terminal records are
/// layered onto the cached baseline synchronously, so this is not an owner-visible freshness
/// budget.
pub(crate) const DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_TTL_SECS: u64 = 60;
const DASHBOARD_ACTIVITY_READ_MODEL_MAX_TERMINAL_KEYS: usize = 50_000;
const DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_TERMINALS: usize = 10_000;
const DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_BYTES: usize = 64 * 1024 * 1024;
const DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_MAX_ENTRIES: usize = 64;
const DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_MAX_EXPIRY_BYTES: usize = 64 * 1024 * 1024;
const DASHBOARD_ACTIVITY_LAST_GOOD_MAX_AGE: Duration = Duration::from_secs(15 * 60);
const DASHBOARD_ACTIVITY_PRESSURE_RECONCILE_MAX_AGE: Duration = Duration::from_secs(5 * 60);

#[derive(Debug, Clone)]
pub(crate) struct DashboardActivitySnapshot {
    range: String,
    range_start: DateTime<Utc>,
    range_end: DateTime<Utc>,
    terminal_sequence: u64,
    accounts: Vec<DashboardActivityAccountResponse>,
    summary: DashboardActivitySummaryResponse,
    summary_model_performance_accumulator: ModelPerformanceAccumulator,
    account_model_performance_accumulators: HashMap<Option<i64>, ModelPerformanceAccumulator>,
    account_latency_accumulators: HashMap<Option<i64>, DashboardActivityAccountLatencyAccumulator>,
    model_performance_accumulator_ready: bool,
    materialized_archive_fallback_totals: StatsTotals,
    materialized_archive_details_limited: bool,
    build_telemetry: DashboardActivityBuildTelemetry,
}

/// Stateful typed base used only by Auto dashboard topic delivery. It retains the aggregate
/// inputs that are intentionally absent from the public response so terminal slices can preserve
/// the existing model-performance, latency, and recent-invocation response semantics.
#[derive(Debug)]
pub(crate) struct DashboardActivityTopicMaterializedBase {
    response: DashboardActivityResponse,
    summary_model_performance_accumulator: ModelPerformanceAccumulator,
    account_model_performance_accumulators: HashMap<Option<i64>, ModelPerformanceAccumulator>,
    account_latency_accumulators: HashMap<Option<i64>, DashboardActivityAccountLatencyAccumulator>,
    model_performance_accumulator_ready: bool,
    recent_limit: usize,
    include_recent: bool,
}

impl DashboardActivityTopicMaterializedBase {
    pub(crate) fn response(&self) -> &DashboardActivityResponse {
        &self.response
    }

    pub(crate) fn response_mut(&mut self) -> &mut DashboardActivityResponse {
        &mut self.response
    }

    pub(crate) fn apply_terminal_slice(
        &mut self,
        reporting_tz: Tz,
        source_scope: InvocationSourceScope,
        slice: &DashboardTerminalProjectionSlice,
    ) {
        let Ok(range) = resolve_dashboard_activity_cached_range(&self.response.range, reporting_tz)
        else {
            return;
        };
        let deltas = slice
            .deltas
            .iter()
            .filter(|delta| {
                dashboard_activity_terminal_delta_matches_source_scope(delta, source_scope)
                    && delta.terminal_sequence > self.response.terminal_sequence
                    && dashboard_activity_terminal_delta_is_within_range(delta, range)
            })
            .collect::<Vec<_>>();
        if deltas.is_empty() {
            return;
        }

        self.response.range_start = format_utc_iso_precise(range.start);
        self.response.range_end = format_utc_iso_precise(range.end);
        self.response.snapshot_id = range.end.timestamp_millis();
        let model_performance_available = self.response.summary.model_performance.available;
        for delta in &deltas {
            apply_dashboard_activity_terminal_delta_to_stats(
                &mut self.response.summary.stats,
                delta,
            );
            if self.model_performance_accumulator_ready {
                self.summary_model_performance_accumulator
                    .add_terminal_delta(delta);
            }
            self.response.terminal_sequence =
                self.response.terminal_sequence.max(delta.terminal_sequence);
        }
        if self.model_performance_accumulator_ready {
            self.response.summary.model_performance = self
                .summary_model_performance_accumulator
                .clone()
                .into_response(range, model_performance_available);
        }

        let Some(accounts) = self.response.accounts.as_mut() else {
            return;
        };
        let mut account_indexes = accounts
            .iter()
            .enumerate()
            .map(|(index, account)| (account.upstream_account_id, index))
            .collect::<HashMap<_, _>>();
        let mut updated_account_ids = HashSet::new();
        for delta in deltas {
            let account_index = if let Some(index) = account_indexes.get(&delta.upstream_account_id)
            {
                *index
            } else {
                accounts.push(dashboard_activity_terminal_account_for_range(range, delta));
                let index = accounts.len() - 1;
                account_indexes.insert(delta.upstream_account_id, index);
                index
            };

            if self.model_performance_accumulator_ready {
                let accumulator = self
                    .account_model_performance_accumulators
                    .entry(delta.upstream_account_id)
                    .or_default();
                accumulator.add_terminal_delta(delta);
            }
            self.account_latency_accumulators
                .entry(delta.upstream_account_id)
                .or_default()
                .add_terminal_delta(delta);
            let account = &mut accounts[account_index];
            apply_dashboard_activity_terminal_delta_to_account(account, delta);
            if self.include_recent {
                account.recent_invocations = merge_dashboard_activity_recent_invocations(
                    vec![delta.recent_invocation.clone()],
                    std::mem::take(&mut account.recent_invocations),
                    self.recent_limit,
                );
            }
            updated_account_ids.insert(delta.upstream_account_id);
        }
        for upstream_account_id in updated_account_ids {
            let account = &mut accounts[*account_indexes
                .get(&upstream_account_id)
                .expect("terminal account index inserted when absent")];
            self.account_latency_accumulators
                .get(&upstream_account_id)
                .expect("terminal latency accumulator inserted")
                .apply_to_account(account);
            if self.model_performance_accumulator_ready {
                account.model_performance = self
                    .account_model_performance_accumulators
                    .get(&upstream_account_id)
                    .expect("terminal model-performance accumulator inserted")
                    .clone()
                    .into_response(range, model_performance_available);
            }
        }
        sort_dashboard_activity_accounts(accounts);
    }
}

