fn option_string_capacity(value: &Option<String>) -> usize {
    value.as_ref().map_or(0, String::capacity)
}

fn usage_breakdown_memory_bytes(value: &UsageBreakdownResponse) -> usize {
    let model_bytes = value
        .models
        .iter()
        .map(|model| model.model.capacity() + option_string_capacity(&model.reasoning_effort))
        .sum::<usize>();
    value
        .models
        .capacity()
        .saturating_mul(std::mem::size_of::<UsageBreakdownModelResponse>())
        .saturating_add(model_bytes)
}

fn model_performance_memory_bytes(value: &ModelPerformanceResponse) -> usize {
    let model_bytes = value
        .models
        .iter()
        .map(|model| model.model.capacity() + option_string_capacity(&model.reasoning_effort))
        .sum::<usize>();
    value
        .models
        .capacity()
        .saturating_mul(std::mem::size_of::<ModelPerformanceModelResponse>())
        .saturating_add(model_bytes)
}

fn dashboard_activity_account_memory_bytes(value: &DashboardActivityAccountResponse) -> usize {
    value.account_key.capacity()
        + value.display_name.capacity()
        + option_string_capacity(&value.latest_conversation_created_at)
        + option_string_capacity(&value.last_invocation_at)
        + option_string_capacity(&value.group_name)
        + option_string_capacity(&value.plan_type)
        + option_string_capacity(&value.display_status)
        + option_string_capacity(&value.enable_status)
        + option_string_capacity(&value.work_status)
        + option_string_capacity(&value.health_status)
        + option_string_capacity(&value.sync_state)
        + option_string_capacity(&value.last_error)
        + option_string_capacity(&value.last_action_reason_message)
        + value
            .recent_invocations
            .capacity()
            .saturating_mul(std::mem::size_of::<
                PromptCacheConversationInvocationPreviewResponse,
            >())
        + usage_breakdown_memory_bytes(&value.usage_breakdown)
        + model_performance_memory_bytes(&value.model_performance)
}

pub(crate) fn dashboard_activity_snapshot_memory_estimate(
    snapshot: &DashboardActivitySnapshot,
) -> usize {
    let account_bytes = snapshot
        .accounts
        .iter()
        .map(dashboard_activity_account_memory_bytes)
        .sum::<usize>();
    let summary = &snapshot.summary;
    let summary_usage_bytes = summary
        .stats
        .usage_breakdown
        .as_ref()
        .map(usage_breakdown_memory_bytes)
        .unwrap_or_default();
    let summary_bytes = std::mem::size_of_val(summary)
        + summary_usage_bytes
        + model_performance_memory_bytes(&summary.model_performance);
    std::mem::size_of_val(snapshot)
        .saturating_add(
            snapshot
                .accounts
                .capacity()
                .saturating_mul(std::mem::size_of::<DashboardActivityAccountResponse>()),
        )
        .saturating_add(account_bytes)
        .saturating_add(summary_bytes)
        .saturating_add(
            snapshot
                .account_model_performance_accumulators
                .capacity()
                .saturating_mul(std::mem::size_of::<(
                    Option<i64>,
                    ModelPerformanceAccumulator,
                )>()),
        )
        .saturating_add(
            snapshot
                .account_latency_accumulators
                .capacity()
                .saturating_mul(std::mem::size_of::<(
                    Option<i64>,
                    DashboardActivityAccountLatencyAccumulator,
                )>()),
        )
}

#[derive(Debug, Clone, Copy, Default)]
struct DashboardActivityAccountLatencyAccumulator {
    first_response_byte_total_sample_count: i64,
    first_response_byte_total_sum_ms: f64,
    first_token_sample_count: i64,
    first_token_sum_ms: f64,
    total_latency_sample_count: i64,
    total_latency_sum_ms: f64,
}

impl DashboardActivityAccountLatencyAccumulator {
    fn from_aggregate(aggregate: &UpstreamAccountActivityAccumulator) -> Self {
        Self {
            first_response_byte_total_sample_count: aggregate
                .first_response_byte_total_sample_count,
            first_response_byte_total_sum_ms: aggregate.first_response_byte_total_sum_ms,
            first_token_sample_count: aggregate.first_token_sample_count,
            first_token_sum_ms: aggregate.first_token_sum_ms,
            total_latency_sample_count: aggregate.total_latency_sample_count,
            total_latency_sum_ms: aggregate.total_latency_sum_ms,
        }
    }

    fn add_terminal_delta(&mut self, delta: &DashboardActivityTerminalDelta) {
        if let Some(first_token_ms) = delta
            .first_token_ms
            .filter(|value| value.is_finite() && *value >= 0.0)
        {
            self.first_token_sample_count += 1;
            self.first_token_sum_ms += first_token_ms;
        }
        if !delta.success {
            return;
        }
        if delta
            .t_upstream_ttfb_ms
            .filter(|value| value.is_finite() && *value > 0.0)
            .is_some()
            && let Some(first_response_byte_total_ms) =
                crate::stats::resolve_first_response_byte_total_ms(
                    delta.t_req_read_ms,
                    delta.t_req_parse_ms,
                    delta.t_upstream_connect_ms,
                    delta.t_upstream_ttfb_ms,
                )
        {
            self.first_response_byte_total_sample_count += 1;
            self.first_response_byte_total_sum_ms += first_response_byte_total_ms;
        }
        if let Some(total_latency_ms) = delta
            .t_total_ms
            .filter(|value| value.is_finite() && *value >= 0.0)
        {
            self.total_latency_sample_count += 1;
            self.total_latency_sum_ms += total_latency_ms;
        }
    }

    fn subtract_terminal_delta(&mut self, delta: &DashboardActivityTerminalDelta) {
        if let Some(value) = delta
            .first_token_ms
            .filter(|value| value.is_finite() && *value >= 0.0)
        {
            self.first_token_sample_count = self.first_token_sample_count.saturating_sub(1);
            self.first_token_sum_ms = (self.first_token_sum_ms - value).max(0.0);
        }
        if !delta.success {
            return;
        }
        if delta
            .t_upstream_ttfb_ms
            .is_some_and(|value| value.is_finite() && value > 0.0)
            && let Some(value) = crate::stats::resolve_first_response_byte_total_ms(
                delta.t_req_read_ms,
                delta.t_req_parse_ms,
                delta.t_upstream_connect_ms,
                delta.t_upstream_ttfb_ms,
            )
        {
            self.first_response_byte_total_sample_count = self
                .first_response_byte_total_sample_count
                .saturating_sub(1);
            self.first_response_byte_total_sum_ms =
                (self.first_response_byte_total_sum_ms - value).max(0.0);
        }
        if let Some(value) = delta
            .t_total_ms
            .filter(|value| value.is_finite() && *value >= 0.0)
        {
            self.total_latency_sample_count = self.total_latency_sample_count.saturating_sub(1);
            self.total_latency_sum_ms = (self.total_latency_sum_ms - value).max(0.0);
        }
    }

    fn apply_to_account(self, account: &mut DashboardActivityAccountResponse) {
        let first_response_byte_total_avg_ms = (self.first_response_byte_total_sample_count > 0)
            .then_some(
                self.first_response_byte_total_sum_ms
                    / self.first_response_byte_total_sample_count as f64,
            );
        account.first_byte_avg_ms = first_response_byte_total_avg_ms;
        account.first_response_byte_total_avg_ms = first_response_byte_total_avg_ms;
        account.first_token_avg_ms = (self.first_token_sample_count > 0)
            .then_some(self.first_token_sum_ms / self.first_token_sample_count as f64);
        account.avg_total_ms = (self.total_latency_sample_count > 0)
            .then_some(self.total_latency_sum_ms / self.total_latency_sample_count as f64);
    }
}

#[derive(Debug, Clone, Copy)]
struct DashboardActivitySnapshotCacheOutcome {
    cache_hit_or_miss: &'static str,
    cache_bypass_reason: &'static str,
    coalesced_waiter_count: usize,
    db_build_elapsed_ms: u64,
    cache_ttl_ms: u64,
    cache_entry_age_ms: u64,
    cache_entry_count: usize,
    in_flight_count: usize,
    refresh_reason: &'static str,
    selection_fingerprint: u64,
    terminal_delta_count: u64,
    duplicate_delta_count: u64,
    pending_delta_count: usize,
    pending_delta_estimated_bytes: usize,
    persisted_ack_pending_count: usize,
    delta_pruned_count: u64,
    expiry_delta_count: usize,
    hard_limit_reason: &'static str,
    baseline_cursor: i64,
    sequence_gap_count: u64,
    build_attempted: bool,
    snapshot_origin: &'static str,
}

fn dashboard_activity_read_model_state(
    outcome: DashboardActivitySnapshotCacheOutcome,
) -> &'static str {
    if outcome.hard_limit_reason != "none" || outcome.sequence_gap_count > 0 {
        return "dirty_last_good";
    }
    match outcome.cache_hit_or_miss {
        "last_good_fallback" => "stale_last_good",
        "cache_miss_build" => "reconciled",
        "uncached" => "exact_closed_range",
        _ => "healthy",
    }
}

#[derive(Debug, Clone, Copy)]
struct DashboardActivityBuildTelemetry {
    preview_read_mode: &'static str,
    candidate_preview_id_count: usize,
    hydrated_preview_row_count: usize,
    account_aggregation: AccountActivityRangeBuildTelemetry,
}

#[derive(Debug, Default, Clone)]
pub(crate) struct DashboardActivityTerminalDeltaOutcome {
    pub(crate) applied_selection_count: usize,
    pub(crate) duplicate: bool,
    pub(crate) skipped_out_of_range_count: usize,
    pub(crate) hard_limit_reason: Option<&'static str>,
    pub(crate) terminal_sequence: Option<u64>,
    pub(crate) terminal_delta: Option<DashboardActivityTerminalDelta>,
}

fn dashboard_activity_selection_includes_compact_terminal(
    selection: &DashboardActivitySnapshotSelection,
    delta: &DashboardActivityTerminalDelta,
    occurred_at: DateTime<Utc>,
) -> bool {
    if !matches!(selection.range.as_str(), "today" | "1d" | "7d")
        || (selection.source_scope == "proxy_only" && delta.source != SOURCE_PROXY)
    {
        return false;
    }
    let Ok(reporting_tz) = selection.time_zone.parse::<Tz>() else {
        return false;
    };
    let Ok(range) = resolve_dashboard_activity_exact_range(&selection.range, reporting_tz) else {
        return false;
    };
    occurred_at >= range.start && occurred_at < range.end
}

fn dashboard_activity_selection_includes_terminal(
    selection: &DashboardActivitySnapshotSelection,
    record: &ApiInvocation,
    occurred_at: DateTime<Utc>,
) -> bool {
    dashboard_activity_selection_includes_compact_terminal(
        selection,
        &dashboard_activity_terminal_delta(record),
        occurred_at,
    )
}

fn dashboard_activity_selection_source_scope(
    selection: &DashboardActivitySnapshotSelection,
) -> InvocationSourceScope {
    if selection.source_scope == "proxy_only" {
        InvocationSourceScope::ProxyOnly
    } else {
        InvocationSourceScope::All
    }
}

fn dashboard_activity_entry_includes_terminal(
    entry: &DashboardActivitySnapshotCacheEntry,
    delta: &DashboardActivityTerminalDelta,
) -> bool {
    delta
        .persisted_row_id
        .is_some_and(|row_id| row_id <= entry.baseline_snapshot_cursor)
}

fn dashboard_activity_baseline_includes_pending_delta(
    delta: &DashboardActivityTerminalDelta,
    baseline_cursor: i64,
    persisted_terminal_ids: &HashMap<(String, String), i64>,
) -> bool {
    delta
        .persisted_row_id
        .is_some_and(|row_id| row_id <= baseline_cursor)
        || persisted_terminal_ids.contains_key(&delta.key())
}

fn replay_dashboard_activity_pending_deltas_without_expiry(
    snapshot: &mut DashboardActivitySnapshot,
    selection: &DashboardActivitySnapshotSelection,
    pending_terminal_deltas: &VecDeque<DashboardActivityTerminalDelta>,
    baseline_cursor: i64,
    persisted_terminal_ids: &HashMap<(String, String), i64>,
) -> usize {
    let mut replayed = 0usize;
    for delta in pending_terminal_deltas {
        let Some(occurred_at) = parse_to_utc_datetime(&delta.occurred_at) else {
            continue;
        };
        if dashboard_activity_selection_includes_compact_terminal(selection, delta, occurred_at) {
            if dashboard_activity_baseline_includes_pending_delta(
                delta,
                baseline_cursor,
                persisted_terminal_ids,
            ) {
                snapshot.terminal_sequence =
                    snapshot.terminal_sequence.max(delta.terminal_sequence);
            } else {
                apply_dashboard_activity_compact_terminal_delta(snapshot, delta);
                replayed += 1;
            }
        }
    }
    replayed
}

fn dashboard_activity_terminal_delta(record: &ApiInvocation) -> DashboardActivityTerminalDelta {
    dashboard_activity_terminal_delta_with_first_token(
        record,
        runtime_record_first_token_ms(record),
    )
}

// Persisted dashboard rows come from build_invocation_select_query(), whose timing expression
// already establishes final-attempt ownership. Runtime records need the stricter retry guard.
pub(crate) fn persisted_dashboard_activity_terminal_delta(
    record: &ApiInvocation,
) -> DashboardActivityTerminalDelta {
    dashboard_activity_terminal_delta_with_first_token(
        record,
        finite_nonnegative_timing(record.first_token_ms),
    )
}

fn dashboard_activity_terminal_delta_with_first_token(
    record: &ApiInvocation,
    first_token_ms: Option<f64>,
) -> DashboardActivityTerminalDelta {
    let classification = resolve_failure_classification(
        record.status.as_deref(),
        record.error_message.as_deref(),
        record.failure_kind.as_deref(),
        record.failure_class.as_deref(),
        record.is_actionable.map(i64::from),
    );
    let success = runtime_record_is_success_for_summary(record)
        && classification.failure_class == FailureClass::None;
    let failure = matches!(
        classification.failure_class,
        FailureClass::ServiceFailure | FailureClass::ClientFailure | FailureClass::ClientAbort
    );
    let cache_read_tokens = record.cache_input_tokens.unwrap_or_default().max(0);
    let cache_write_tokens = record
        .cache_write_tokens
        .unwrap_or_else(|| {
            record
                .input_tokens
                .unwrap_or_default()
                .saturating_sub(cache_read_tokens)
        })
        .max(0);
    let model = record
        .response_model
        .as_deref()
        .or(record.model.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("unknown")
        .to_string();
    let reasoning_effort = record
        .reasoning_effort
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let upstream_account_name = record
        .upstream_account_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let breakdown_complete = record.cost.is_some()
        && record.cost_input.is_some()
        && record.cost_cache_write.is_some()
        && record.cost_cache_read.is_some()
        && record.cost_output.is_some()
        && record.cost_reasoning.is_some();
    let total_cost = record.cost.unwrap_or_default().max(0.0);
    let string_bytes = record.invoke_id.len()
        + record.occurred_at.len()
        + record.source.len()
        + model.len()
        + reasoning_effort.as_ref().map_or(0, String::len)
        + upstream_account_name.as_ref().map_or(0, String::len);
    let recent_projection_string_bytes = record.invoke_id.len()
        + record.prompt_cache_key.as_ref().map_or(0, String::len)
        + record.occurred_at.len()
        + record.status.as_ref().map_or(0, String::len)
        + record.live_phase.as_ref().map_or(0, String::len)
        + record.failure_class.as_ref().map_or(0, String::len)
        + record.route_mode.as_ref().map_or(0, String::len)
        + record.model.as_ref().map_or(0, String::len)
        + record.request_model.as_ref().map_or(0, String::len)
        + record.response_model.as_ref().map_or(0, String::len)
        + record.proxy_display_name.as_ref().map_or(0, String::len)
        + record.upstream_account_name.as_ref().map_or(0, String::len)
        + record.endpoint.as_ref().map_or(0, String::len)
        + record
            .compaction_request_kind
            .as_ref()
            .map_or(0, String::len)
        + record
            .compaction_response_kind
            .as_ref()
            .map_or(0, String::len)
        + record.image_intent.as_ref().map_or(0, String::len)
        + record.reasoning_effort.as_ref().map_or(0, String::len)
        + record.error_message.as_ref().map_or(0, String::len)
        + record
            .downstream_error_message
            .as_ref()
            .map_or(0, String::len)
        + record.failure_kind.as_ref().map_or(0, String::len)
        + record
            .response_content_encoding
            .as_ref()
            .map_or(0, String::len)
        + record
            .request_compression_algorithm
            .as_ref()
            .map_or(0, String::len)
        + record.transport.as_ref().map_or(0, String::len)
        + record
            .requested_service_tier
            .as_ref()
            .map_or(0, String::len)
        + record.service_tier.as_ref().map_or(0, String::len)
        + record.billing_service_tier.as_ref().map_or(0, String::len);
    let mut timeseries = TimeseriesTerminalDelta::from(record);
    timeseries.first_token_ms = first_token_ms;
    DashboardActivityTerminalDelta {
        terminal_sequence: 0,
        timeseries,
        invoke_id: record.invoke_id.clone(),
        occurred_at: record.occurred_at.clone(),
        source: record.source.clone(),
        model,
        reasoning_effort,
        upstream_account_id: record.upstream_account_id,
        upstream_account_name,
        success,
        failure,
        total_tokens: record.total_tokens.unwrap_or_default().max(0),
        cache_write_tokens,
        cache_read_tokens,
        output_tokens: record.output_tokens.unwrap_or_default().max(0),
        has_cost: record.cost.is_some(),
        total_cost,
        cost_input: record
            .cost_input
            .filter(|_| breakdown_complete)
            .unwrap_or_default(),
        cost_cache_write: record
            .cost_cache_write
            .filter(|_| breakdown_complete)
            .unwrap_or_default(),
        cost_cache_read: record
            .cost_cache_read
            .filter(|_| breakdown_complete)
            .unwrap_or_default(),
        cost_output: record
            .cost_output
            .filter(|_| breakdown_complete)
            .unwrap_or_default(),
        cost_reasoning: record
            .cost_reasoning
            .filter(|_| breakdown_complete)
            .unwrap_or_default(),
        cost_unknown: if breakdown_complete { 0.0 } else { total_cost },
        t_total_ms: record.t_total_ms,
        t_req_read_ms: record.t_req_read_ms,
        t_req_parse_ms: record.t_req_parse_ms,
        t_upstream_connect_ms: record.t_upstream_connect_ms,
        t_upstream_ttfb_ms: record.t_upstream_ttfb_ms,
        first_token_ms,
        t_upstream_stream_ms: record.t_upstream_stream_ms,
        recent_invocation: invocation_preview_from_runtime_record(record),
        persisted_row_id: (record.id > 0).then_some(record.id),
        estimated_bytes: std::mem::size_of::<DashboardActivityTerminalDelta>()
            + string_bytes
            + recent_projection_string_bytes,
    }
}

fn dashboard_activity_terminal_delta_matches_source_scope(
    delta: &DashboardActivityTerminalDelta,
    source_scope: InvocationSourceScope,
) -> bool {
    source_scope != InvocationSourceScope::ProxyOnly || delta.source == SOURCE_PROXY
}

fn dashboard_activity_terminal_delta_is_within_range(
    delta: &DashboardActivityTerminalDelta,
    range: ExactUtcRange,
) -> bool {
    parse_to_utc_datetime(&delta.occurred_at)
        .is_some_and(|occurred_at| occurred_at >= range.start && occurred_at < range.end)
}

fn add_dashboard_activity_terminal_usage(
    usage: &mut UsageBreakdownResponse,
    delta: &DashboardActivityTerminalDelta,
) {
    let costs = delta.has_cost.then_some(UsageCostBreakdownResponse {
        input: delta.cost_input,
        cache_write: delta.cost_cache_write,
        cache_read: delta.cost_cache_read,
        output: delta.cost_output,
        reasoning: delta.cost_reasoning,
        unknown: delta.cost_unknown,
    });

    usage.cache_write_tokens += delta.cache_write_tokens;
    usage.cache_read_tokens += delta.cache_read_tokens;
    usage.output_tokens += delta.output_tokens;
    if let Some(costs) = &costs {
        let target = usage
            .costs
            .get_or_insert_with(UsageCostBreakdownResponse::default);
        target.input += costs.input;
        target.cache_write += costs.cache_write;
        target.cache_read += costs.cache_read;
        target.output += costs.output;
        target.reasoning += costs.reasoning;
        target.unknown += costs.unknown;
    }

    let model_usage = usage.models.iter_mut().find(|entry| {
        entry.model == delta.model
            && entry.reasoning_effort.as_deref() == delta.reasoning_effort.as_deref()
    });
    let entry = if let Some(entry) = model_usage {
        entry
    } else {
        usage.models.push(UsageBreakdownModelResponse {
            model: delta.model.clone(),
            reasoning_effort: delta.reasoning_effort.clone(),
            cache_write_tokens: 0,
            cache_read_tokens: 0,
            output_tokens: 0,
            costs: None,
        });
        usage.models.last_mut().expect("just inserted usage model")
    };
    entry.cache_write_tokens += delta.cache_write_tokens;
    entry.cache_read_tokens += delta.cache_read_tokens;
    entry.output_tokens += delta.output_tokens;
    if let Some(costs) = costs {
        let target = entry
            .costs
            .get_or_insert_with(UsageCostBreakdownResponse::default);
        target.input += costs.input;
        target.cache_write += costs.cache_write;
        target.cache_read += costs.cache_read;
        target.output += costs.output;
        target.reasoning += costs.reasoning;
        target.unknown += costs.unknown;
    }
    usage.models.sort_by(|left, right| {
        left.model
            .cmp(&right.model)
            .then_with(|| left.reasoning_effort.cmp(&right.reasoning_effort))
    });
}

fn subtract_dashboard_activity_terminal_usage(
    usage: &mut UsageBreakdownResponse,
    delta: &DashboardActivityTerminalDelta,
) {
    usage.cache_write_tokens = usage
        .cache_write_tokens
        .saturating_sub(delta.cache_write_tokens);
    usage.cache_read_tokens = usage
        .cache_read_tokens
        .saturating_sub(delta.cache_read_tokens);
    usage.output_tokens = usage.output_tokens.saturating_sub(delta.output_tokens);
    if let Some(costs) = usage.costs.as_mut() {
        costs.input = (costs.input - delta.cost_input).max(0.0);
        costs.cache_write = (costs.cache_write - delta.cost_cache_write).max(0.0);
        costs.cache_read = (costs.cache_read - delta.cost_cache_read).max(0.0);
        costs.output = (costs.output - delta.cost_output).max(0.0);
        costs.reasoning = (costs.reasoning - delta.cost_reasoning).max(0.0);
        costs.unknown = (costs.unknown - delta.cost_unknown).max(0.0);
    }
    if let Some(entry) = usage.models.iter_mut().find(|entry| {
        entry.model == delta.model
            && entry.reasoning_effort.as_deref() == delta.reasoning_effort.as_deref()
    }) {
        entry.cache_write_tokens = entry
            .cache_write_tokens
            .saturating_sub(delta.cache_write_tokens);
        entry.cache_read_tokens = entry
            .cache_read_tokens
            .saturating_sub(delta.cache_read_tokens);
        entry.output_tokens = entry.output_tokens.saturating_sub(delta.output_tokens);
        if let Some(costs) = entry.costs.as_mut() {
            costs.input = (costs.input - delta.cost_input).max(0.0);
            costs.cache_write = (costs.cache_write - delta.cost_cache_write).max(0.0);
            costs.cache_read = (costs.cache_read - delta.cost_cache_read).max(0.0);
            costs.output = (costs.output - delta.cost_output).max(0.0);
            costs.reasoning = (costs.reasoning - delta.cost_reasoning).max(0.0);
            costs.unknown = (costs.unknown - delta.cost_unknown).max(0.0);
        }
    }
    usage.models.retain(|entry| {
        entry.cache_write_tokens != 0
            || entry.cache_read_tokens != 0
            || entry.output_tokens != 0
            || entry.costs.as_ref().is_some_and(|costs| {
                costs.input != 0.0
                    || costs.cache_write != 0.0
                    || costs.cache_read != 0.0
                    || costs.output != 0.0
                    || costs.reasoning != 0.0
                    || costs.unknown != 0.0
            })
    });
}

fn dashboard_activity_terminal_account(
    snapshot: &DashboardActivitySnapshot,
    delta: &DashboardActivityTerminalDelta,
) -> DashboardActivityAccountResponse {
    dashboard_activity_terminal_account_for_range(
        ExactUtcRange {
            start: snapshot.range_start,
            end: snapshot.range_end,
        },
        delta,
    )
}

pub(crate) fn dashboard_activity_terminal_account_for_range(
    range: ExactUtcRange,
    delta: &DashboardActivityTerminalDelta,
) -> DashboardActivityAccountResponse {
    let upstream_account_id = delta.upstream_account_id;
    DashboardActivityAccountResponse {
        account_key: upstream_account_id
            .map(|id| format!("upstream:{id}"))
            .unwrap_or_else(|| "unassigned".to_string()),
        upstream_account_id,
        display_name: upstream_account_id
            .and_then(|_| delta.upstream_account_name.clone())
            .filter(|name| !name.trim().is_empty())
            .unwrap_or_else(|| {
                upstream_account_id
                    .map(|id| format!("Upstream {id}"))
                    .unwrap_or_else(|| "Unassigned upstream account".to_string())
            }),
        is_unassigned: upstream_account_id.is_none(),
        latest_conversation_created_at: None,
        last_invocation_at: None,
        group_name: None,
        plan_type: None,
        enabled: None,
        display_status: None,
        enable_status: None,
        work_status: None,
        health_status: None,
        sync_state: None,
        last_error: None,
        last_action_reason_message: None,
        request_count: 0,
        success_count: 0,
        failure_count: 0,
        non_success_count: 0,
        total_tokens: 0,
        success_tokens: 0,
        non_success_tokens: 0,
        failure_tokens: 0,
        failure_cost: 0.0,
        non_success_cost: 0.0,
        total_cost: 0.0,
        usage_breakdown: UsageBreakdownResponse {
            cache_write_tokens: 0,
            cache_read_tokens: 0,
            output_tokens: 0,
            costs: None,
            models: Vec::new(),
        },
        model_performance: ModelPerformanceAccumulator::default().into_response(range, false),
        cache_hit_rate: None,
        tokens_per_minute: None,
        spend_rate: None,
        first_byte_avg_ms: None,
        first_response_byte_total_avg_ms: None,
        first_token_avg_ms: None,
        avg_total_ms: None,
        current_first_response_byte_total_avg_ms: None,
        current_first_token_avg_ms: None,
        current_avg_total_ms: None,
        current_avg_response_ms: None,
        in_progress_invocation_count: Some(0),
        in_progress_phase_counts: Some(InvocationPhaseCountsResponse::default()),
        retry_invocation_count: Some(0),
        upload_bytes_per_second: 0.0,
        download_bytes_per_second: 0.0,
        in_progress_wait_sum_ms: 0.0,
        in_progress_wait_sample_count: 0,
        effective_routing_rule: None,
        recent_invocations: Vec::new(),
    }
}

fn apply_dashboard_activity_compact_terminal_delta(
    snapshot: &mut DashboardActivitySnapshot,
    delta: &DashboardActivityTerminalDelta,
) {
    snapshot.terminal_sequence = snapshot.terminal_sequence.max(delta.terminal_sequence);
    apply_dashboard_activity_terminal_delta_to_stats(&mut snapshot.summary.stats, delta);

    let model_performance_available = snapshot.summary.model_performance.available;
    let snapshot_range = ExactUtcRange {
        start: snapshot.range_start,
        end: snapshot.range_end,
    };
    if snapshot.model_performance_accumulator_ready {
        snapshot
            .summary_model_performance_accumulator
            .add_terminal_delta(delta);
        snapshot.summary.model_performance = snapshot
            .summary_model_performance_accumulator
            .clone()
            .into_response(snapshot_range, model_performance_available);
        snapshot
            .account_model_performance_accumulators
            .entry(delta.upstream_account_id)
            .or_default()
            .add_terminal_delta(delta);
    }
    let account_model_performance = snapshot
        .account_model_performance_accumulators
        .get(&delta.upstream_account_id)
        .cloned()
        .unwrap_or_default()
        .into_response(snapshot_range, model_performance_available);

    if !snapshot
        .accounts
        .iter()
        .any(|account| account.upstream_account_id == delta.upstream_account_id)
    {
        snapshot
            .accounts
            .push(dashboard_activity_terminal_account(snapshot, delta));
    }
    let account_latency = snapshot
        .account_latency_accumulators
        .entry(delta.upstream_account_id)
        .or_default();
    account_latency.add_terminal_delta(delta);
    let account_latency = *account_latency;
    let account = snapshot
        .accounts
        .iter_mut()
        .find(|account| account.upstream_account_id == delta.upstream_account_id)
        .expect("terminal account inserted when absent");
    apply_dashboard_activity_terminal_delta_to_account(account, delta);
    account_latency.apply_to_account(account);
    account.model_performance = account_model_performance;
    sort_dashboard_activity_accounts(&mut snapshot.accounts);
}

pub(crate) fn apply_dashboard_activity_terminal_delta_to_stats(
    stats: &mut StatsResponse,
    delta: &DashboardActivityTerminalDelta,
) {
    let non_success = !delta.success;
    stats.total_count += 1;
    stats.success_count += i64::from(delta.success);
    stats.failure_count += i64::from(delta.failure);
    stats.total_tokens += delta.total_tokens;
    stats.total_cost += delta.total_cost;
    if non_success {
        if let Some(non_success_cost) = stats.non_success_cost.as_mut() {
            *non_success_cost += delta.total_cost;
        }
        if let Some(non_success_tokens) = stats.non_success_tokens.as_mut() {
            *non_success_tokens += delta.total_tokens;
        }
    }
    if let Some(usage) = stats.usage_breakdown.as_mut() {
        add_dashboard_activity_terminal_usage(usage, delta);
    }
}

pub(crate) fn apply_dashboard_activity_terminal_delta_to_account(
    account: &mut DashboardActivityAccountResponse,
    delta: &DashboardActivityTerminalDelta,
) {
    let non_success = !delta.success;
    account.request_count += 1;
    account.success_count += i64::from(delta.success);
    account.failure_count += i64::from(delta.failure);
    account.non_success_count += i64::from(non_success);
    account.total_tokens += delta.total_tokens;
    account.total_cost += delta.total_cost;
    if delta.success {
        account.success_tokens += delta.total_tokens;
    } else {
        account.non_success_tokens += delta.total_tokens;
    }
    if delta.failure {
        account.failure_tokens += delta.total_tokens;
        account.failure_cost += delta.total_cost;
    }
    if non_success {
        account.non_success_cost += delta.total_cost;
    }
    if account
        .last_invocation_at
        .as_deref()
        .is_none_or(|current| delta.occurred_at.as_str() > current)
    {
        account.last_invocation_at = Some(delta.occurred_at.clone());
    }
    add_dashboard_activity_terminal_usage(&mut account.usage_breakdown, delta);
    account.cache_hit_rate = (account.total_tokens > 0)
        .then_some(account.usage_breakdown.cache_read_tokens as f64 / account.total_tokens as f64);
}

fn apply_dashboard_activity_terminal_delta(
    snapshot: &mut DashboardActivitySnapshot,
    record: &ApiInvocation,
) {
    apply_dashboard_activity_compact_terminal_delta(
        snapshot,
        &dashboard_activity_terminal_delta(record),
    );
}

fn subtract_dashboard_activity_compact_terminal_delta(
    snapshot: &mut DashboardActivitySnapshot,
    delta: &DashboardActivityTerminalDelta,
) {
    let non_success = !delta.success;
    let stats = &mut snapshot.summary.stats;
    stats.total_count = stats.total_count.saturating_sub(1);
    stats.success_count = stats.success_count.saturating_sub(i64::from(delta.success));
    stats.failure_count = stats.failure_count.saturating_sub(i64::from(delta.failure));
    stats.total_tokens = stats.total_tokens.saturating_sub(delta.total_tokens);
    stats.total_cost = (stats.total_cost - delta.total_cost).max(0.0);
    if non_success {
        if let Some(value) = stats.non_success_cost.as_mut() {
            *value = (*value - delta.total_cost).max(0.0);
        }
        if let Some(value) = stats.non_success_tokens.as_mut() {
            *value = value.saturating_sub(delta.total_tokens);
        }
    }
    if let Some(usage) = stats.usage_breakdown.as_mut() {
        subtract_dashboard_activity_terminal_usage(usage, delta);
    }
    let snapshot_range = ExactUtcRange {
        start: snapshot.range_start,
        end: snapshot.range_end,
    };
    let available = snapshot.summary.model_performance.available;
    if snapshot.model_performance_accumulator_ready {
        snapshot
            .summary_model_performance_accumulator
            .subtract_terminal_delta(delta);
        snapshot.summary.model_performance = snapshot
            .summary_model_performance_accumulator
            .clone()
            .into_response(snapshot_range, available);
        if let Some(accumulator) = snapshot
            .account_model_performance_accumulators
            .get_mut(&delta.upstream_account_id)
        {
            accumulator.subtract_terminal_delta(delta);
        }
    }
    if let Some(latency) = snapshot
        .account_latency_accumulators
        .get_mut(&delta.upstream_account_id)
    {
        latency.subtract_terminal_delta(delta);
    }
    let account_performance = snapshot
        .account_model_performance_accumulators
        .get(&delta.upstream_account_id)
        .cloned()
        .unwrap_or_default()
        .into_response(snapshot_range, available);
    if let Some(account) = snapshot
        .accounts
        .iter_mut()
        .find(|account| account.upstream_account_id == delta.upstream_account_id)
    {
        account.request_count = account.request_count.saturating_sub(1);
        account.success_count = account
            .success_count
            .saturating_sub(i64::from(delta.success));
        account.failure_count = account
            .failure_count
            .saturating_sub(i64::from(delta.failure));
        account.non_success_count = account
            .non_success_count
            .saturating_sub(i64::from(non_success));
        account.total_tokens = account.total_tokens.saturating_sub(delta.total_tokens);
        account.total_cost = (account.total_cost - delta.total_cost).max(0.0);
        if delta.success {
            account.success_tokens = account.success_tokens.saturating_sub(delta.total_tokens);
        } else {
            account.non_success_tokens = account
                .non_success_tokens
                .saturating_sub(delta.total_tokens);
        }
        if delta.failure {
            account.failure_tokens = account.failure_tokens.saturating_sub(delta.total_tokens);
            account.failure_cost = (account.failure_cost - delta.total_cost).max(0.0);
        }
        if non_success {
            account.non_success_cost = (account.non_success_cost - delta.total_cost).max(0.0);
        }
        if account.last_invocation_at.as_deref() == Some(delta.occurred_at.as_str()) {
            account.last_invocation_at = None;
        }
        subtract_dashboard_activity_terminal_usage(&mut account.usage_breakdown, delta);
        if let Some(latency) = snapshot
            .account_latency_accumulators
            .get(&delta.upstream_account_id)
            .copied()
        {
            latency.apply_to_account(account);
        }
        account.cache_hit_rate = (account.total_tokens > 0).then_some(
            account.usage_breakdown.cache_read_tokens as f64 / account.total_tokens as f64,
        );
        account.model_performance = account_performance;
    }
    snapshot
        .accounts
        .retain(|account| account.request_count > 0);
    sort_dashboard_activity_accounts(&mut snapshot.accounts);
}

fn restore_dashboard_activity_last_invocation_after_expiry(
    snapshot: &mut DashboardActivitySnapshot,
    expired: &DashboardActivityTerminalDelta,
    remaining_expiry_deltas: &VecDeque<DashboardActivityTerminalDelta>,
) {
    let Some(account) = snapshot
        .accounts
        .iter_mut()
        .find(|account| account.upstream_account_id == expired.upstream_account_id)
    else {
        return;
    };
    if account.last_invocation_at.is_some() || account.request_count <= 0 {
        return;
    }
    account.last_invocation_at = remaining_expiry_deltas
        .iter()
        .filter(|delta| delta.upstream_account_id == expired.upstream_account_id)
        .max_by_key(|delta| parse_to_utc_datetime(&delta.occurred_at))
        .map(|delta| delta.occurred_at.clone());
}

/// Applies an accepted terminal record to every warm open-range baseline. This is deliberately
/// independent from the subscription listener so a lagged broadcast cannot drop cumulative UI
/// totals before the next reconciliation build.
pub(crate) async fn apply_dashboard_activity_terminal_record(
    state: &AppState,
    record: &ApiInvocation,
) -> DashboardActivityTerminalDeltaOutcome {
    let mut delta = dashboard_activity_terminal_delta(record);
    let Some(occurred_at) = parse_to_utc_datetime(&delta.occurred_at) else {
        return DashboardActivityTerminalDeltaOutcome::default();
    };
    let key = delta.key();
    let mut outcome = DashboardActivityTerminalDeltaOutcome::default();
    let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
    if cache.read_model.applied_terminal_keys.contains_key(&key) {
        cache.read_model.duplicate_delta_count += 1;
        outcome.duplicate = true;
        return outcome;
    }
    cache.read_model.next_terminal_sequence =
        cache.read_model.next_terminal_sequence.saturating_add(1);
    delta.terminal_sequence = cache.read_model.next_terminal_sequence;
    outcome.terminal_sequence = Some(delta.terminal_sequence);
    insert_dashboard_activity_applied_terminal_key(&mut cache.read_model, key);
    cache.read_model.terminal_delta_count += 1;
    prune_dashboard_activity_applied_terminal_keys(&mut cache.read_model);
    if delta.persisted_row_id.is_some() {
        settle_dashboard_activity_terminal_sequence(&mut cache.read_model, delta.terminal_sequence);
    }
    let hard_limit_reason = dashboard_activity_terminal_delta_needs_persistence_ack(&delta)
        .then(|| dashboard_activity_terminal_delta_hard_limit_reason(&cache.read_model, &delta))
        .flatten();
    if let Some(reason) = hard_limit_reason {
        cache.read_model.hard_limit_reason = Some(reason);
        cache.read_model.hard_limit_sequence = Some(delta.terminal_sequence);
        cache.read_model.pending_terminal_overflow_count += 1;
        outcome.hard_limit_reason = Some(reason);
        tracing::warn!(
            hard_limit_reason = reason,
            pending_delta_count = cache.read_model.pending_terminal_deltas.len(),
            pending_delta_estimated_bytes = cache.read_model.pending_delta_estimated_bytes,
            persisted_ack_pending_count = cache.read_model.persisted_ack_pending_count,
            "dashboard activity read model entered dirty last-good protection"
        );
        return outcome;
    }
    let mut expiry_hard_limit = None;
    for (selection, entry) in &mut cache.entries {
        if !dashboard_activity_selection_includes_compact_terminal(selection, &delta, occurred_at) {
            outcome.skipped_out_of_range_count += 1;
            continue;
        }
        if dashboard_activity_entry_includes_terminal(entry, &delta) {
            continue;
        }
        if let Err(reason) = insert_dashboard_activity_expiry_delta(
            &mut entry.expiry_terminal_deltas,
            &mut entry.expiry_delta_estimated_bytes,
            entry.expiry_covered_until,
            &delta,
            occurred_at,
        ) {
            entry.expiry_covered_until = Some(DateTime::<Utc>::MIN_UTC);
            expiry_hard_limit = Some(reason);
            continue;
        }
        apply_dashboard_activity_compact_terminal_delta(&mut entry.response, &delta);
        outcome.applied_selection_count += 1;
    }
    let evicted_entry_count = prune_dashboard_activity_snapshot_entries(&mut cache, None);
    if evicted_entry_count > 0 {
        prune_dashboard_activity_terminal_deltas(&mut cache);
        tracing::debug!(
            evicted_entry_count,
            cache_entry_count = cache.entries.len(),
            "evicted dashboard activity snapshots to enforce the global cache budget"
        );
    }
    if let Some(reason) = expiry_hard_limit {
        cache.read_model.hard_limit_reason = Some(reason);
        cache.read_model.pending_terminal_overflow_count += 1;
        outcome.hard_limit_reason = Some(reason);
        return outcome;
    }
    outcome.terminal_delta = Some(delta.clone());
    if !dashboard_activity_terminal_delta_needs_persistence_ack(&delta) {
        return outcome;
    }
    cache.read_model.pending_delta_estimated_bytes = cache
        .read_model
        .pending_delta_estimated_bytes
        .saturating_add(delta.estimated_bytes);
    cache.read_model.pending_terminal_deltas.push_back(delta);
    outcome
}

fn prune_dashboard_activity_applied_terminal_keys(read_model: &mut DashboardActivityReadModel) {
    let max_age = Duration::from_secs(7 * 24 * 60 * 60);
    while let Some((key, applied_at)) = read_model.applied_terminal_key_order.front() {
        let is_live_entry = read_model.applied_terminal_keys.get(key) == Some(applied_at);
        if is_live_entry
            && read_model.applied_terminal_keys.len()
                <= DASHBOARD_ACTIVITY_READ_MODEL_MAX_TERMINAL_KEYS
            && applied_at.elapsed() <= max_age
        {
            break;
        }
        let key = key.clone();
        let applied_at = *applied_at;
        read_model.applied_terminal_key_order.pop_front();
        if read_model.applied_terminal_keys.get(&key) == Some(&applied_at) {
            read_model.applied_terminal_keys.remove(&key);
        }
    }
}

fn insert_dashboard_activity_applied_terminal_key(
    read_model: &mut DashboardActivityReadModel,
    key: (String, String),
) {
    let applied_at = Instant::now();
    read_model
        .applied_terminal_keys
        .insert(key.clone(), applied_at);
    read_model
        .applied_terminal_key_order
        .push_back((key, applied_at));
}

fn dashboard_activity_terminal_delta_hard_limit_reason(
    read_model: &DashboardActivityReadModel,
    delta: &DashboardActivityTerminalDelta,
) -> Option<&'static str> {
    if read_model.pending_terminal_deltas.len()
        >= DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_TERMINALS
    {
        Some("count_limit")
    } else if read_model
        .pending_delta_estimated_bytes
        .saturating_add(delta.estimated_bytes)
        > DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_BYTES
    {
        Some("byte_limit")
    } else {
        None
    }
}

fn dashboard_activity_terminal_delta_needs_persistence_ack(
    delta: &DashboardActivityTerminalDelta,
) -> bool {
    delta.persisted_row_id.is_none()
}

fn prune_dashboard_activity_terminal_deltas(cache: &mut DashboardActivitySnapshotCacheState) {
    let minimum_cursor = cache
        .entries
        .values()
        .map(|entry| entry.baseline_snapshot_cursor)
        .chain(
            cache
                .in_flight
                .values()
                .filter_map(|flight| flight.baseline_cursor),
        )
        .min();
    let can_prune_all_persisted = cache.entries.is_empty() && cache.in_flight.is_empty();
    let before = cache.read_model.pending_terminal_deltas.len();
    cache.read_model.pending_terminal_deltas.retain(|delta| {
        let Some(row_id) = delta.persisted_row_id else {
            return true;
        };
        !(can_prune_all_persisted || minimum_cursor.is_some_and(|cursor| cursor >= row_id))
    });
    let pruned = before.saturating_sub(cache.read_model.pending_terminal_deltas.len());
    cache.read_model.delta_pruned_count = cache
        .read_model
        .delta_pruned_count
        .saturating_add(pruned as u64);
    cache.read_model.pending_delta_estimated_bytes = cache
        .read_model
        .pending_terminal_deltas
        .iter()
        .map(|delta| delta.estimated_bytes)
        .sum();
    cache.read_model.persisted_ack_pending_count = cache
        .read_model
        .pending_terminal_deltas
        .iter()
        .filter(|delta| delta.persisted_row_id.is_some())
        .count();
}

fn prune_dashboard_activity_snapshot_entries(
    cache: &mut DashboardActivitySnapshotCacheState,
    protected_selection: Option<&DashboardActivitySnapshotSelection>,
) -> usize {
    let mut evicted = 0usize;
    loop {
        let expiry_bytes = cache
            .entries
            .values()
            .map(|entry| entry.expiry_delta_estimated_bytes)
            .sum::<usize>();
        if cache.entries.len() <= DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_MAX_ENTRIES
            && expiry_bytes <= DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_MAX_EXPIRY_BYTES
        {
            break;
        }

        let candidate = cache
            .entries
            .iter()
            .filter(|(selection, _)| protected_selection != Some(*selection))
            .min_by_key(|(_, entry)| entry.cached_at)
            .map(|(selection, _)| selection.clone())
            .or_else(|| protected_selection.cloned());
        let Some(candidate) = candidate else {
            break;
        };
        cache.entries.remove(&candidate);
        cache.invalidation_reasons.remove(&candidate);
        evicted += 1;
    }
    evicted
}

fn dashboard_activity_hard_limit_is_settled(read_model: &DashboardActivityReadModel) -> bool {
    read_model
        .hard_limit_sequence
        .is_none_or(|sequence| read_model.settled_terminal_sequence >= sequence)
}

fn dashboard_activity_read_model_requires_reconcile(
    read_model: &DashboardActivityReadModel,
) -> bool {
    read_model.hard_limit_reason.is_some() && dashboard_activity_hard_limit_is_settled(read_model)
}

fn settle_dashboard_activity_terminal_sequence(
    read_model: &mut DashboardActivityReadModel,
    terminal_sequence: u64,
) {
    if terminal_sequence <= read_model.settled_terminal_sequence {
        return;
    }
    read_model
        .settled_terminal_sequences
        .insert(terminal_sequence);
    while let Some(next_sequence) = read_model.settled_terminal_sequence.checked_add(1)
        && read_model.settled_terminal_sequences.remove(&next_sequence)
    {
        read_model.settled_terminal_sequence = next_sequence;
    }
}

fn clear_dashboard_activity_hard_limit_after_baseline(read_model: &mut DashboardActivityReadModel) {
    if dashboard_activity_hard_limit_is_settled(read_model)
        && read_model.pending_terminal_deltas.len()
            < DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_TERMINALS
        && read_model.pending_delta_estimated_bytes
            < DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_BYTES
    {
        read_model.hard_limit_reason = None;
        read_model.hard_limit_sequence = None;
    }
}

pub(crate) async fn acknowledge_dashboard_activity_terminal_record(
    cache: &Arc<tokio::sync::Mutex<DashboardActivitySnapshotCacheState>>,
    invoke_id: &str,
    occurred_at: &str,
    row_id: i64,
    terminal_sequence: Option<u64>,
) {
    let mut cache = cache.lock().await;
    if let Some(terminal_sequence) = terminal_sequence {
        settle_dashboard_activity_terminal_sequence(&mut cache.read_model, terminal_sequence);
    }
    let mut ack_sequence_gap = false;
    for delta in &mut cache.read_model.pending_terminal_deltas {
        if delta.invoke_id == invoke_id && delta.occurred_at == occurred_at {
            ack_sequence_gap = delta
                .persisted_row_id
                .is_some_and(|persisted| persisted != row_id);
            delta.persisted_row_id = Some(row_id);
            break;
        }
    }
    if ack_sequence_gap {
        cache.read_model.sequence_gap_count += 1;
        cache.read_model.hard_limit_reason = Some("ack_sequence_gap");
    }
    // A writer retry can acknowledge a delta after every warm cursor already allowed it to be
    // pruned. Matching row IDs are therefore idempotent; only a conflicting ACK is a gap.
    prune_dashboard_activity_terminal_deltas(&mut cache);
}

/// The write-side delta is registered before an asynchronous SQLite enqueue. If the queue
/// rejects that enqueue, discard the speculative delta and force future reads to rebuild from
/// persisted state rather than attempting an unsafe inverse for every aggregate field.
pub(crate) async fn rollback_dashboard_activity_terminal_record(
    state: &AppState,
    record: &ApiInvocation,
    terminal_sequence: Option<u64>,
) {
    let key = (record.invoke_id.clone(), record.occurred_at.clone());
    let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
    cache.read_model.applied_terminal_keys.remove(&key);
    cache
        .read_model
        .pending_terminal_deltas
        .retain(|pending| pending.key() != key);
    cache.read_model.pending_delta_estimated_bytes = cache
        .read_model
        .pending_terminal_deltas
        .iter()
        .map(|delta| delta.estimated_bytes)
        .sum();
    cache.read_model.persisted_ack_pending_count = cache
        .read_model
        .pending_terminal_deltas
        .iter()
        .filter(|delta| delta.persisted_row_id.is_some())
        .count();
    if let Some(terminal_sequence) = terminal_sequence {
        settle_dashboard_activity_terminal_sequence(&mut cache.read_model, terminal_sequence);
    }
    cache.entries.clear();
    cache.invalidation_reasons.clear();
    clear_dashboard_activity_hard_limit_after_baseline(&mut cache.read_model);
}

/// Recovery can replace a previously persisted running row with its terminal form. Its positive
/// row ID is not proof that a warm baseline observed the terminal fields, so force the next read
/// to rebuild from persisted state before registering the recovered record as pending.
pub(crate) async fn invalidate_dashboard_activity_baselines_for_recovery(state: &AppState) {
    let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
    cache.entries.clear();
    cache.invalidation_reasons.clear();
}

impl Default for DashboardActivityBuildTelemetry {
    fn default() -> Self {
        Self {
            preview_read_mode: "none",
            candidate_preview_id_count: 0,
            hydrated_preview_row_count: 0,
            account_aggregation: AccountActivityRangeBuildTelemetry::default(),
        }
    }
}

fn dashboard_activity_build_scope(include_accounts: bool, _include_recent: bool) -> &'static str {
    if !include_accounts {
        "summary_only"
    } else {
        "full"
    }
}

fn dashboard_activity_stats_totals_from_aggregate_rows(
    rows: &[UpstreamAccountActivityAggregateRow],
) -> StatsTotals {
    let mut totals = StatsTotals::default();
    for row in rows {
        totals.total_count += row.request_count;
        totals.success_count += row.success_count;
        totals.failure_count += row.failure_count;
        totals.total_cost += row.total_cost;
        totals.total_tokens += row.total_tokens;
        totals.non_success_cost += row.non_success_cost;
    }
    totals
}

fn dashboard_activity_stats_totals_subtract(left: StatsTotals, right: StatsTotals) -> StatsTotals {
    StatsTotals {
        total_count: left.total_count.saturating_sub(right.total_count).max(0),
        success_count: left
            .success_count
            .saturating_sub(right.success_count)
            .max(0),
        failure_count: left
            .failure_count
            .saturating_sub(right.failure_count)
            .max(0),
        total_cost: (left.total_cost - right.total_cost).max(0.0),
        total_tokens: left.total_tokens.saturating_sub(right.total_tokens).max(0),
        non_success_cost: (left.non_success_cost - right.non_success_cost).max(0.0),
    }
}

fn dashboard_activity_stats_totals_has_values(totals: StatsTotals) -> bool {
    totals.total_count > 0
        || totals.success_count > 0
        || totals.failure_count > 0
        || totals.total_cost > 0.0
        || totals.total_tokens > 0
        || totals.non_success_cost > 0.0
}

async fn dashboard_activity_materialized_archive_fallback_totals(
    state: &AppState,
    source_scope: InvocationSourceScope,
    skipped_materialized_ranges: Vec<ExactUtcRange>,
) -> Result<StatsTotals, ApiError> {
    let mut fallback_totals = StatsTotals::default();
    for skipped_range in skipped_materialized_ranges {
        let rollup_totals = query_hourly_backed_summary_range(
            state,
            skipped_range.start,
            skipped_range.end,
            source_scope,
        )
        .await?;
        let live_rows = query_live_upstream_account_activity_aggregate_rows(
            &state.pool,
            source_scope,
            skipped_range,
            true,
            DashboardActivityExcludedInvocationIdsFilter::None,
        )
        .await?;
        let live_totals = dashboard_activity_stats_totals_from_aggregate_rows(&live_rows);
        fallback_totals = fallback_totals.add(dashboard_activity_stats_totals_subtract(
            rollup_totals,
            live_totals,
        ));
    }
    Ok(fallback_totals)
}

async fn dashboard_activity_materialized_archive_first_token_fallback_totals(
    state: &AppState,
    source_scope: InvocationSourceScope,
    skipped_materialized_ranges: &[ExactUtcRange],
) -> Result<(i64, f64), ApiError> {
    let mut sample_count = 0_i64;
    let mut sum_ms = 0.0_f64;
    let retention_cutoff = shanghai_retention_cutoff(state.config.invocation_max_days);
    for skipped_range in skipped_materialized_ranges {
        let range_plan = build_hourly_rollup_exact_range_plan(
            skipped_range.start,
            skipped_range.end,
            retention_cutoff,
        )?;
        let Some((range_start_epoch, range_end_epoch)) = range_plan.full_hour_range else {
            continue;
        };
        let full_hour_range = dashboard_activity_full_hour_exact_range(range_plan.full_hour_range)?
            .expect("non-empty full-hour epoch range should produce an exact range");
        let rollup_rows = crate::stats::query_invocation_hourly_rollup_range(
            &state.pool,
            range_start_epoch,
            range_end_epoch,
            source_scope,
        )
        .await?;
        let rollup_count = rollup_rows
            .iter()
            .map(|row| row.first_token_sample_count.max(0))
            .sum::<i64>();
        let rollup_sum = rollup_rows
            .iter()
            .map(|row| row.first_token_sum_ms.max(0.0))
            .sum::<f64>();
        let live_rows = query_live_upstream_account_activity_aggregate_rows(
            &state.pool,
            source_scope,
            full_hour_range,
            true,
            DashboardActivityExcludedInvocationIdsFilter::None,
        )
        .await?;
        let live_count = live_rows
            .iter()
            .map(|row| row.first_token_sample_count.max(0))
            .sum::<i64>();
        let live_sum = live_rows
            .iter()
            .map(|row| row.first_token_sum_ms.max(0.0))
            .sum::<f64>();
        sample_count += rollup_count.saturating_sub(live_count).max(0);
        sum_ms += (rollup_sum - live_sum).max(0.0);
    }
    Ok((sample_count, sum_ms))
}

fn dashboard_activity_historical_live_gap_ranges(
    range: ExactUtcRange,
    retention_cutoff: DateTime<Utc>,
) -> Result<Vec<ExactUtcRange>, ApiError> {
    if range.start >= retention_cutoff {
        return Ok(Vec::new());
    }

    let full_hour_start_epoch = ceil_hour_epoch(range.start.timestamp());
    let full_hour_end_epoch = crate::stats::align_bucket_epoch(range.end.timestamp(), 3_600, 0);
    let full_hour_start = Utc
        .timestamp_opt(full_hour_start_epoch, 0)
        .single()
        .ok_or_else(|| ApiError::from(anyhow!("invalid dashboard activity gap start epoch")))?;
    let full_hour_end = Utc
        .timestamp_opt(full_hour_end_epoch, 0)
        .single()
        .ok_or_else(|| ApiError::from(anyhow!("invalid dashboard activity gap end epoch")))?;

    let mut gap_ranges = Vec::new();
    if let Some(gap) = exact_utc_range(
        range.start,
        range.end.min(full_hour_start).min(retention_cutoff),
    )? {
        gap_ranges.push(gap);
    }
    if let Some(gap) = exact_utc_range(
        range.start.max(full_hour_end),
        range.end.min(retention_cutoff),
    )? {
        gap_ranges.push(gap);
    }
    Ok(gap_ranges)
}

async fn dashboard_activity_historical_live_gap_totals(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
    retention_cutoff: DateTime<Utc>,
) -> Result<StatsTotals, ApiError> {
    let mut totals = StatsTotals::default();
    for gap_range in dashboard_activity_historical_live_gap_ranges(range, retention_cutoff)? {
        totals = totals.add(dashboard_activity_stats_totals_from_aggregate_rows(
            &query_live_upstream_account_activity_aggregate_rows(
                &state.pool,
                source_scope,
                gap_range,
                true,
                DashboardActivityExcludedInvocationIdsFilter::None,
            )
            .await?,
        ));
    }
    Ok(totals)
}

fn dashboard_activity_apply_materialized_archive_fallback_to_stats(
    stats: &mut StatsResponse,
    fallback_totals: StatsTotals,
) {
    if !dashboard_activity_stats_totals_has_values(fallback_totals) {
        return;
    }

    stats.total_count += fallback_totals.total_count;
    stats.success_count += fallback_totals.success_count;
    stats.failure_count += fallback_totals.failure_count;
    stats.total_cost += fallback_totals.total_cost;
    stats.total_tokens += fallback_totals.total_tokens;
    stats.non_success_cost =
        Some(stats.non_success_cost.unwrap_or_default() + fallback_totals.non_success_cost);
    // Materialized invocation rollups do not retain model/cost-breakdown or non-success-token
    // detail, so omit those partial fields when they would no longer align with top-level totals.
    stats.usage_breakdown = None;
    stats.non_success_tokens = None;
}

fn dashboard_activity_clear_materialized_archive_detail_fields(stats: &mut StatsResponse) {
    stats.usage_breakdown = None;
    stats.non_success_tokens = None;
}

#[derive(Debug, FromRow)]
struct DashboardActivityAccountStatsRollupAggregateRow {
    upstream_account_id: i64,
    request_count: i64,
    success_count: i64,
    failure_count: i64,
    total_tokens: i64,
    input_tokens: i64,
    output_tokens: i64,
    cache_input_tokens: i64,
    total_cost: f64,
    non_success_cost: f64,
    first_response_byte_total_sample_count: i64,
    first_response_byte_total_sum_ms: f64,
    first_token_sample_count: i64,
    first_token_sum_ms: f64,
    total_latency_sample_count: i64,
    total_latency_sum_ms: f64,
}

#[derive(Debug, Default, Clone, Copy)]
struct DashboardActivityUsageFallbackTotals {
    cache_write_tokens: i64,
    cache_read_tokens: i64,
    output_tokens: i64,
}

#[derive(Debug, Default, Clone, Copy)]
struct DashboardActivityAccountFallbackTotals {
    request_count: i64,
    success_count: i64,
    failure_count: i64,
    non_success_count: i64,
    total_tokens: i64,
    success_tokens: i64,
    non_success_tokens: i64,
    failure_tokens: i64,
    failure_cost: f64,
    non_success_cost: f64,
    cache_input_tokens: i64,
    total_cost: f64,
    cache_write_tokens: i64,
    cache_read_tokens: i64,
    output_tokens: i64,
    first_response_byte_total_sample_count: i64,
    first_response_byte_total_sum_ms: f64,
    first_token_sample_count: i64,
    first_token_sum_ms: f64,
    total_latency_sample_count: i64,
    total_latency_sum_ms: f64,
}

impl DashboardActivityAccountFallbackTotals {
    fn from_stats_totals(totals: StatsTotals) -> Self {
        let non_success_count = totals
            .total_count
            .saturating_sub(totals.success_count)
            .max(0);
        Self {
            request_count: totals.total_count,
            success_count: totals.success_count,
            failure_count: totals.failure_count,
            non_success_count: non_success_count.max(totals.failure_count),
            total_tokens: totals.total_tokens,
            success_tokens: if non_success_count == 0 {
                totals.total_tokens
            } else {
                0
            },
            non_success_tokens: if totals.success_count == 0 {
                totals.total_tokens
            } else {
                0
            },
            failure_tokens: if totals.success_count == 0 && totals.failure_count > 0 {
                totals.total_tokens
            } else {
                0
            },
            failure_cost: if totals.success_count == 0 && totals.failure_count > 0 {
                totals.non_success_cost
            } else {
                0.0
            },
            non_success_cost: totals.non_success_cost,
            total_cost: totals.total_cost,
            ..Self::default()
        }
    }

    fn from_rollup_minus_live(
        row: &DashboardActivityAccountStatsRollupAggregateRow,
        live: Option<&UpstreamAccountActivityAggregateRow>,
        live_usage: DashboardActivityUsageFallbackTotals,
    ) -> Self {
        let live_request_count = live.map_or(0, |row| row.request_count);
        let live_success_count = live.map_or(0, |row| row.success_count);
        let live_failure_count = live.map_or(0, |row| row.failure_count);
        let live_total_tokens = live.map_or(0, |row| row.total_tokens);
        let live_cache_input_tokens = live.map_or(0, |row| row.cache_input_tokens);
        let live_total_cost = live.map_or(0.0, |row| row.total_cost);
        let live_non_success_cost = live.map_or(0.0, |row| row.non_success_cost);
        let live_first_response_count =
            live.map_or(0, |row| row.first_response_byte_total_sample_count);
        let live_first_response_sum = live.map_or(0.0, |row| row.first_response_byte_total_sum_ms);
        let live_first_token_count = live.map_or(0, |row| row.first_token_sample_count);
        let live_first_token_sum = live.map_or(0.0, |row| row.first_token_sum_ms);
        let live_total_latency_count = live.map_or(0, |row| row.total_latency_sample_count);
        let live_total_latency_sum = live.map_or(0.0, |row| row.total_latency_sum_ms);

        let request_count = row.request_count.saturating_sub(live_request_count).max(0);
        let success_count = row.success_count.saturating_sub(live_success_count).max(0);
        let failure_count = row.failure_count.saturating_sub(live_failure_count).max(0);
        let non_success_count = request_count
            .saturating_sub(success_count)
            .max(failure_count);
        let total_tokens = row.total_tokens.saturating_sub(live_total_tokens).max(0);
        let non_success_cost = (row.non_success_cost - live_non_success_cost).max(0.0);
        let total_cost = (row.total_cost - live_total_cost).max(0.0);
        let cache_input_tokens = row
            .cache_input_tokens
            .saturating_sub(live_cache_input_tokens)
            .max(0);
        let rollup_cache_write_tokens = row
            .input_tokens
            .max(0)
            .saturating_sub(row.cache_input_tokens.max(0))
            .max(0);
        let cache_write_tokens = rollup_cache_write_tokens
            .saturating_sub(live_usage.cache_write_tokens)
            .max(0);
        let cache_read_tokens = row
            .cache_input_tokens
            .max(0)
            .saturating_sub(live_usage.cache_read_tokens)
            .max(0);
        let output_tokens = row
            .output_tokens
            .max(0)
            .saturating_sub(live_usage.output_tokens)
            .max(0);

        Self {
            request_count,
            success_count,
            failure_count,
            non_success_count,
            total_tokens,
            success_tokens: if non_success_count == 0 {
                total_tokens
            } else {
                0
            },
            non_success_tokens: if success_count == 0 { total_tokens } else { 0 },
            failure_tokens: if success_count == 0 && failure_count > 0 {
                total_tokens
            } else {
                0
            },
            failure_cost: if success_count == 0 && failure_count > 0 {
                non_success_cost
            } else {
                0.0
            },
            non_success_cost,
            cache_input_tokens,
            total_cost,
            cache_write_tokens,
            cache_read_tokens,
            output_tokens,
            first_response_byte_total_sample_count: row
                .first_response_byte_total_sample_count
                .saturating_sub(live_first_response_count)
                .max(0),
            first_response_byte_total_sum_ms: (row.first_response_byte_total_sum_ms
                - live_first_response_sum)
                .max(0.0),
            first_token_sample_count: row
                .first_token_sample_count
                .saturating_sub(live_first_token_count)
                .max(0),
            first_token_sum_ms: (row.first_token_sum_ms - live_first_token_sum).max(0.0),
            total_latency_sample_count: row
                .total_latency_sample_count
                .saturating_sub(live_total_latency_count)
                .max(0),
            total_latency_sum_ms: (row.total_latency_sum_ms - live_total_latency_sum).max(0.0),
        }
    }

    fn add_assign(&mut self, other: Self) {
        self.request_count += other.request_count;
        self.success_count += other.success_count;
        self.failure_count += other.failure_count;
        self.non_success_count += other.non_success_count;
        self.total_tokens += other.total_tokens;
        self.success_tokens += other.success_tokens;
        self.non_success_tokens += other.non_success_tokens;
        self.failure_tokens += other.failure_tokens;
        self.failure_cost += other.failure_cost;
        self.non_success_cost += other.non_success_cost;
        self.cache_input_tokens += other.cache_input_tokens;
        self.total_cost += other.total_cost;
        self.cache_write_tokens += other.cache_write_tokens;
        self.cache_read_tokens += other.cache_read_tokens;
        self.output_tokens += other.output_tokens;
        self.first_response_byte_total_sample_count += other.first_response_byte_total_sample_count;
        self.first_response_byte_total_sum_ms += other.first_response_byte_total_sum_ms;
        self.first_token_sample_count += other.first_token_sample_count;
        self.first_token_sum_ms += other.first_token_sum_ms;
        self.total_latency_sample_count += other.total_latency_sample_count;
        self.total_latency_sum_ms += other.total_latency_sum_ms;
    }

    fn stats_totals(self) -> StatsTotals {
        StatsTotals {
            total_count: self.request_count,
            success_count: self.success_count,
            failure_count: self.failure_count,
            total_cost: self.total_cost,
            total_tokens: self.total_tokens,
            non_success_cost: self.non_success_cost,
        }
    }
}

fn dashboard_activity_residual_first_token_totals(
    global_sample_count: i64,
    global_sum_ms: f64,
    account_totals: &HashMap<Option<i64>, DashboardActivityAccountFallbackTotals>,
) -> (i64, f64) {
    let account_sample_count = account_totals
        .values()
        .map(|totals| totals.first_token_sample_count)
        .sum::<i64>();
    let account_sum_ms = account_totals
        .values()
        .map(|totals| totals.first_token_sum_ms)
        .sum::<f64>();
    (
        global_sample_count
            .saturating_sub(account_sample_count)
            .max(0),
        (global_sum_ms - account_sum_ms).max(0.0),
    )
}

#[cfg(test)]
mod dashboard_activity_ttft_fallback_tests {
    use super::*;

    #[test]
    fn residual_archive_fallback_keeps_unassigned_ttft_samples() {
        let account_totals = HashMap::from([(
            Some(7),
            DashboardActivityAccountFallbackTotals {
                first_token_sample_count: 2,
                first_token_sum_ms: 500.0,
                ..DashboardActivityAccountFallbackTotals::default()
            },
        )]);

        assert_eq!(
            dashboard_activity_residual_first_token_totals(3, 900.0, &account_totals),
            (1, 400.0)
        );
    }
}

async fn query_dashboard_activity_account_stats_rollup_aggregate_rows(
    pool: &Pool<Sqlite>,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<Vec<DashboardActivityAccountStatsRollupAggregateRow>, ApiError> {
    let range_start_epoch = ceil_hour_epoch(range.start.timestamp());
    let range_end_epoch = crate::stats::align_bucket_epoch(range.end.timestamp(), 3_600, 0);
    if range_start_epoch >= range_end_epoch {
        return Ok(Vec::new());
    }

    let mut query = QueryBuilder::<Sqlite>::new(
        r#"
        SELECT
            upstream_account_id,
            COALESCE(SUM(total_count), 0) AS request_count,
            COALESCE(SUM(success_count), 0) AS success_count,
            COALESCE(SUM(failure_count), 0) AS failure_count,
            COALESCE(SUM(total_tokens), 0) AS total_tokens,
            COALESCE(SUM(input_tokens), 0) AS input_tokens,
            COALESCE(SUM(output_tokens), 0) AS output_tokens,
            COALESCE(SUM(cache_input_tokens), 0) AS cache_input_tokens,
            CAST(COALESCE(SUM(total_cost), 0.0) AS REAL) AS total_cost,
            CAST(COALESCE(SUM(non_success_cost), 0.0) AS REAL) AS non_success_cost,
            COALESCE(SUM(first_response_byte_total_sample_count), 0) AS first_response_byte_total_sample_count,
            CAST(COALESCE(SUM(first_response_byte_total_sum_ms), 0.0) AS REAL) AS first_response_byte_total_sum_ms,
            COALESCE(SUM(first_token_sample_count), 0) AS first_token_sample_count,
            CAST(COALESCE(SUM(first_token_sum_ms), 0.0) AS REAL) AS first_token_sum_ms,
            COALESCE(SUM(total_latency_sample_count), 0) AS total_latency_sample_count,
            CAST(COALESCE(SUM(total_latency_sum_ms), 0.0) AS REAL) AS total_latency_sum_ms
        FROM upstream_account_stats_hourly
        WHERE bucket_start_epoch >=
        "#,
    );
    query
        .push_bind(range_start_epoch)
        .push(" AND bucket_start_epoch < ")
        .push_bind(range_end_epoch);
    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    query.push(" GROUP BY upstream_account_id");
    Ok(query
        .build_query_as::<DashboardActivityAccountStatsRollupAggregateRow>()
        .fetch_all(pool)
        .await?)
}

async fn dashboard_activity_materialized_archive_account_fallback_totals(
    state: &AppState,
    source_scope: InvocationSourceScope,
    skipped_materialized_ranges: &[ExactUtcRange],
) -> Result<HashMap<Option<i64>, DashboardActivityAccountFallbackTotals>, ApiError> {
    let mut fallback_by_account =
        HashMap::<Option<i64>, DashboardActivityAccountFallbackTotals>::new();
    let retention_cutoff = shanghai_retention_cutoff(state.config.invocation_max_days);
    for skipped_range in skipped_materialized_ranges {
        let range_plan = build_hourly_rollup_exact_range_plan(
            skipped_range.start,
            skipped_range.end,
            retention_cutoff,
        )?;
        if let Some(full_hour_range) =
            dashboard_activity_full_hour_exact_range(range_plan.full_hour_range)?
        {
            let rollup_rows = query_dashboard_activity_account_stats_rollup_aggregate_rows(
                &state.pool,
                source_scope,
                full_hour_range,
            )
            .await?;
            let live_full_hour_rows = query_live_upstream_account_activity_aggregate_rows(
                &state.pool,
                source_scope,
                full_hour_range,
                true,
                DashboardActivityExcludedInvocationIdsFilter::None,
            )
            .await?;
            let live_full_hour_by_account = live_full_hour_rows
                .into_iter()
                .map(|row| (row.upstream_account_id, row))
                .collect::<HashMap<_, _>>();
            let mut live_full_hour_usage_by_account =
                HashMap::<Option<i64>, DashboardActivityUsageFallbackTotals>::new();
            for row in query_live_upstream_account_usage_breakdown_rows(
                &state.pool,
                source_scope,
                full_hour_range,
                true,
                true,
                DashboardActivityExcludedInvocationIdsFilter::None,
            )
            .await?
            {
                let entry = live_full_hour_usage_by_account
                    .entry(row.upstream_account_id)
                    .or_default();
                entry.cache_write_tokens += row.cache_write_tokens;
                entry.cache_read_tokens += row.cache_read_tokens;
                entry.output_tokens += row.output_tokens;
            }

            for row in rollup_rows {
                let account_id = Some(row.upstream_account_id);
                let totals = DashboardActivityAccountFallbackTotals::from_rollup_minus_live(
                    &row,
                    live_full_hour_by_account.get(&account_id),
                    live_full_hour_usage_by_account
                        .get(&account_id)
                        .copied()
                        .unwrap_or_default(),
                );
                if !dashboard_activity_stats_totals_has_values(totals.stats_totals()) {
                    continue;
                }
                fallback_by_account
                    .entry(account_id)
                    .or_default()
                    .add_assign(totals);
            }
        }
    }
    Ok(fallback_by_account)
}

fn dashboard_activity_merge_account_fallback_totals(
    entry: &mut UpstreamAccountActivityAccumulator,
    totals: DashboardActivityAccountFallbackTotals,
) {
    entry.request_count += totals.request_count;
    entry.success_count += totals.success_count;
    entry.failure_count += totals.failure_count;
    entry.non_success_count += totals.non_success_count;
    entry.total_tokens += totals.total_tokens;
    entry.success_tokens += totals.success_tokens;
    entry.non_success_tokens += totals.non_success_tokens;
    entry.failure_tokens += totals.failure_tokens;
    entry.failure_cost += totals.failure_cost;
    entry.non_success_cost += totals.non_success_cost;
    entry.cache_input_tokens += totals.cache_input_tokens;
    entry.total_cost += totals.total_cost;
    entry.first_response_byte_total_sample_count += totals.first_response_byte_total_sample_count;
    entry.first_response_byte_total_sum_ms += totals.first_response_byte_total_sum_ms;
    entry.first_token_sample_count += totals.first_token_sample_count;
    entry.first_token_sum_ms += totals.first_token_sum_ms;
    entry.total_latency_sample_count += totals.total_latency_sample_count;
    entry.total_latency_sum_ms += totals.total_latency_sum_ms;
    entry.usage_breakdown.add_coarse_rollup_totals(
        totals.cache_write_tokens,
        totals.cache_read_tokens,
        totals.output_tokens,
        totals.total_cost,
    );
}

fn dashboard_activity_source_scope_cache_key(source_scope: InvocationSourceScope) -> &'static str {
    match source_scope {
        InvocationSourceScope::ProxyOnly => "proxy_only",
        InvocationSourceScope::All => "all",
    }
}

pub(crate) fn build_dashboard_activity_snapshot_selection(
    range: &str,
    exact_range: ExactUtcRange,
    reporting_tz: Tz,
    source_scope: InvocationSourceScope,
    recent_limit: usize,
    include_accounts: bool,
    include_recent: bool,
) -> DashboardActivitySnapshotSelection {
    DashboardActivitySnapshotSelection {
        range: range.to_string(),
        range_anchor: dashboard_activity_snapshot_selection_anchor(
            range,
            exact_range,
            reporting_tz,
        ),
        time_zone: reporting_tz.to_string(),
        source_scope: dashboard_activity_source_scope_cache_key(source_scope).to_string(),
        recent_limit,
        include_accounts,
        include_recent,
    }
}

#[derive(Debug, Clone)]
pub(crate) struct DashboardActivityTerminalPayload {
    pub(crate) summary: DashboardActivitySummaryResponse,
    pub(crate) accounts: Vec<DashboardActivityAccountResponse>,
}

pub(crate) async fn dashboard_activity_terminal_payload_from_memory(
    state: &AppState,
    selection: &DashboardActivitySnapshotSelection,
) -> Option<DashboardActivityTerminalPayload> {
    let cache = state.dashboard_activity_snapshot_cache.lock().await;
    let entry = cache.entries.get(selection)?;
    Some(DashboardActivityTerminalPayload {
        summary: entry.response.summary.clone(),
        accounts: entry.response.accounts.clone(),
    })
}

fn dashboard_activity_snapshot_selection_anchor(
    range: &str,
    exact_range: ExactUtcRange,
    reporting_tz: Tz,
) -> String {
    if parse_duration_spec(range).is_ok() {
        return "rolling".to_string();
    }
    exact_range
        .start
        .with_timezone(&reporting_tz)
        .format("%Y-%m-%d")
        .to_string()
}

fn dashboard_activity_snapshot_cache_ttl(_range_name: &str) -> Duration {
    Duration::from_secs(DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_TTL_SECS)
}

fn dashboard_activity_snapshot_cache_can_track_expiry(
    range_name: &str,
    range: ExactUtcRange,
    retention_cutoff: DateTime<Utc>,
) -> bool {
    parse_duration_spec(range_name).is_err() || range.start >= retention_cutoff
}

fn dashboard_activity_entry_expiry_covers(
    entry: &DashboardActivitySnapshotCacheEntry,
    range: ExactUtcRange,
) -> bool {
    entry
        .expiry_covered_until
        .is_none_or(|covered_until| range.start <= covered_until)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DashboardActivitySnapshotReuseMode {
    Current,
    LastGoodReconcileBackoff,
}

fn dashboard_activity_snapshot_reuse_mode(
    entry: &DashboardActivitySnapshotCacheEntry,
    range: ExactUtcRange,
    cache_ttl: Duration,
) -> Option<DashboardActivitySnapshotReuseMode> {
    let within_reconcile_deadline = entry.last_reconcile_attempted_at.elapsed() <= cache_ttl;
    if dashboard_activity_entry_expiry_covers(entry, range) {
        return within_reconcile_deadline.then_some(DashboardActivitySnapshotReuseMode::Current);
    }
    if !entry.last_reconcile_failed || !within_reconcile_deadline {
        return None;
    }
    Some(DashboardActivitySnapshotReuseMode::LastGoodReconcileBackoff)
}

fn mark_dashboard_activity_reconcile_failed(entry: &mut DashboardActivitySnapshotCacheEntry) {
    entry.last_reconcile_attempted_at = Instant::now();
    entry.last_reconcile_failed = true;
}

fn dashboard_activity_pressure_reconcile_deferred(
    entry: &DashboardActivitySnapshotCacheEntry,
) -> bool {
    entry.cached_at.elapsed() <= DASHBOARD_ACTIVITY_PRESSURE_RECONCILE_MAX_AGE
}

fn insert_dashboard_activity_expiry_delta(
    deltas: &mut VecDeque<DashboardActivityTerminalDelta>,
    estimated_bytes: &mut usize,
    expiry_covered_until: Option<DateTime<Utc>>,
    delta: &DashboardActivityTerminalDelta,
    occurred_at: DateTime<Utc>,
) -> Result<(), &'static str> {
    if expiry_covered_until.is_none_or(|covered_until| occurred_at >= covered_until) {
        return Ok(());
    }
    if deltas.len() >= DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_TERMINALS {
        return Err("expiry_count_limit");
    }
    if estimated_bytes.saturating_add(delta.estimated_bytes)
        > DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_BYTES
    {
        return Err("expiry_byte_limit");
    }
    let insert_at = deltas
        .iter()
        .position(|existing| {
            parse_to_utc_datetime(&existing.occurred_at)
                .is_some_and(|existing_at| existing_at > occurred_at)
        })
        .unwrap_or(deltas.len());
    deltas.insert(insert_at, delta.clone());
    *estimated_bytes = estimated_bytes.saturating_add(delta.estimated_bytes);
    Ok(())
}

async fn load_dashboard_activity_expiry_deltas(
    pool: &Pool<Sqlite>,
    selection: &DashboardActivitySnapshotSelection,
    range: ExactUtcRange,
    baseline_cursor: i64,
) -> Result<
    (
        VecDeque<DashboardActivityTerminalDelta>,
        Option<DateTime<Utc>>,
        usize,
        Option<&'static str>,
    ),
    ApiError,
> {
    if parse_duration_spec(&selection.range).is_err() {
        return Ok((VecDeque::new(), None, 0, None));
    }
    // Resolve the moving range immediately before the query. The resulting upper bound is also
    // stored on the cache entry, so time spent querying can only shorten reuse instead of leaving
    // an uncovered expiry interval after a slow baseline build.
    let expiry_covered_until = resolve_dashboard_activity_cached_range(
        &selection.range,
        selection
            .time_zone
            .parse::<Tz>()
            .map_err(|_| ApiError::from(anyhow!("invalid dashboard activity cache timezone")))?,
    )?
    .start
        + ChronoDuration::seconds(DASHBOARD_ACTIVITY_SNAPSHOT_CACHE_TTL_SECS as i64);
    let mut query = build_invocation_select_query();
    query
        .push(" AND id <= ")
        .push_bind(baseline_cursor)
        .push(" AND occurred_at >= ")
        .push_bind(db_occurred_at_lower_bound(range.start))
        .push(" AND occurred_at < ")
        .push_bind(db_occurred_at_upper_bound(expiry_covered_until))
        .push(" AND LOWER(TRIM(COALESCE(status, ''))) NOT IN ('running', 'pending')");
    if selection.source_scope == "proxy_only" {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }
    query.push(" ORDER BY occurred_at ASC, id ASC");
    let mut rows = query.build_query_as::<ApiInvocation>().fetch(pool);
    let mut deltas = VecDeque::new();
    let mut estimated_bytes = 0usize;
    while let Some(record) = rows.try_next().await? {
        let delta = persisted_dashboard_activity_terminal_delta(&record);
        if deltas.len() >= DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_TERMINALS {
            return Ok((VecDeque::new(), None, 0, Some("expiry_count_limit")));
        }
        if estimated_bytes.saturating_add(delta.estimated_bytes)
            > DASHBOARD_ACTIVITY_READ_MODEL_MAX_PENDING_BYTES
        {
            return Ok((VecDeque::new(), None, 0, Some("expiry_byte_limit")));
        }
        estimated_bytes = estimated_bytes.saturating_add(delta.estimated_bytes);
        deltas.push_back(delta);
    }
    Ok((deltas, Some(expiry_covered_until), estimated_bytes, None))
}

fn resolve_dashboard_activity_exact_range(
    range_name: &str,
    reporting_tz: Tz,
) -> Result<ExactUtcRange, ApiError> {
    let range_window = resolve_range_window(range_name, reporting_tz).map_err(ApiError::from)?;
    Ok(ExactUtcRange {
        start: range_window.start,
        end: range_window.end,
    })
}

pub(crate) fn resolve_dashboard_activity_cached_range(
    range_name: &str,
    reporting_tz: Tz,
) -> Result<ExactUtcRange, ApiError> {
    resolve_dashboard_activity_exact_range(range_name, reporting_tz)
}

fn dashboard_activity_full_hour_exact_range(
    full_hour_range: Option<(i64, i64)>,
) -> Result<Option<ExactUtcRange>, ApiError> {
    let Some((start_epoch, end_epoch)) = full_hour_range else {
        return Ok(None);
    };
    Ok(Some(ExactUtcRange {
        start: Utc.timestamp_opt(start_epoch, 0).single().ok_or_else(|| {
            ApiError::from(anyhow!("invalid dashboard activity full-hour start epoch"))
        })?,
        end: Utc.timestamp_opt(end_epoch, 0).single().ok_or_else(|| {
            ApiError::from(anyhow!("invalid dashboard activity full-hour end epoch"))
        })?,
    }))
}

pub(crate) fn sort_dashboard_activity_accounts(accounts: &mut [DashboardActivityAccountResponse]) {
    accounts.sort_by(|left, right| {
        right
            .total_tokens
            .cmp(&left.total_tokens)
            .then_with(|| {
                right
                    .recent_invocations
                    .first()
                    .map(|row| row.occurred_at.as_str())
                    .cmp(
                        &left
                            .recent_invocations
                            .first()
                            .map(|row| row.occurred_at.as_str()),
                    )
            })
            .then_with(|| {
                right
                    .upstream_account_id
                    .unwrap_or(i64::MIN)
                    .cmp(&left.upstream_account_id.unwrap_or(i64::MIN))
            })
    });
}

pub(crate) fn dashboard_activity_account_from_live(
    live_account: &DashboardActivityLiveAccount,
    meta: Option<&UpstreamAccountActivityMetaRow>,
    range: ExactUtcRange,
    current_snapshot: DashboardActivityCurrentSnapshot,
    model_performance_available: bool,
    effective_routing_rule: Option<crate::upstream_accounts::EffectiveRoutingRule>,
    recent_invocations: Vec<PromptCacheConversationInvocationPreviewResponse>,
) -> DashboardActivityAccountResponse {
    let status_fields =
        meta.map(|row| build_upstream_account_activity_status_fields(row, Utc::now()));
    let display_name_hint = recent_invocations
        .iter()
        .find_map(|invocation| {
            invocation
                .upstream_account_name
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
        .or_else(|| live_account.upstream_account_name.clone());
    let plan_type_hint = recent_invocations.iter().find_map(|invocation| {
        invocation
            .upstream_account_plan_type
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    });
    let display_name = live_account
        .upstream_account_id
        .map(|id| {
            resolve_upstream_account_activity_display_name(id, meta, display_name_hint.as_deref())
        })
        .unwrap_or_else(|| "未分配上游账号".to_string());

    DashboardActivityAccountResponse {
        account_key: live_account.account_key.clone(),
        upstream_account_id: live_account.upstream_account_id,
        display_name,
        is_unassigned: live_account.upstream_account_id.is_none(),
        latest_conversation_created_at: None,
        last_invocation_at: None,
        group_name: normalize_trimmed_optional_string_local(
            meta.and_then(|row| row.group_name.clone()),
        ),
        plan_type: normalize_trimmed_optional_string_local(
            meta.and_then(|row| row.plan_type.clone())
                .or(plan_type_hint),
        ),
        enabled: status_fields.as_ref().map(|fields| fields.enabled),
        display_status: status_fields
            .as_ref()
            .map(|fields| fields.display_status.clone()),
        enable_status: status_fields
            .as_ref()
            .map(|fields| fields.enable_status.clone()),
        work_status: status_fields
            .as_ref()
            .map(|fields| fields.work_status.clone()),
        health_status: status_fields
            .as_ref()
            .map(|fields| fields.health_status.clone()),
        sync_state: status_fields
            .as_ref()
            .map(|fields| fields.sync_state.clone()),
        last_error: status_fields
            .as_ref()
            .and_then(|fields| fields.last_error.clone()),
        last_action_reason_message: status_fields
            .as_ref()
            .and_then(|fields| fields.last_action_reason_message.clone()),
        request_count: live_account.in_progress_invocation_count.max(0),
        success_count: 0,
        failure_count: 0,
        non_success_count: 0,
        total_tokens: 0,
        success_tokens: 0,
        non_success_tokens: 0,
        failure_tokens: 0,
        failure_cost: 0.0,
        non_success_cost: 0.0,
        total_cost: 0.0,
        usage_breakdown: UsageBreakdownAccumulator::default().into_response(),
        model_performance: ModelPerformanceAccumulator::default()
            .into_response(range, model_performance_available),
        cache_hit_rate: None,
        tokens_per_minute: Some(current_snapshot.qualified_tokens.max(0) as f64),
        spend_rate: Some(current_snapshot.total_cost.max(0.0)),
        first_byte_avg_ms: None,
        first_response_byte_total_avg_ms: None,
        first_token_avg_ms: None,
        avg_total_ms: None,
        current_first_token_avg_ms: current_snapshot.first_token_avg_ms(),
        current_first_response_byte_total_avg_ms: current_snapshot
            .first_response_byte_total_avg_ms(),
        current_avg_total_ms: current_snapshot.avg_total_ms(),
        current_avg_response_ms: current_snapshot.avg_response_duration_ms(),
        in_progress_invocation_count: Some(live_account.in_progress_invocation_count),
        in_progress_phase_counts: Some(live_account.in_progress_phase_counts),
        retry_invocation_count: Some(live_account.retry_invocation_count),
        upload_bytes_per_second: live_account.upload_bytes_per_second,
        download_bytes_per_second: live_account.download_bytes_per_second,
        in_progress_wait_sum_ms: 0.0,
        in_progress_wait_sample_count: 0,
        effective_routing_rule,
        recent_invocations,
    }
}

fn merge_dashboard_activity_recent_invocations(
    mut recent_invocations: Vec<PromptCacheConversationInvocationPreviewResponse>,
    existing_recent_invocations: Vec<PromptCacheConversationInvocationPreviewResponse>,
    recent_limit: usize,
) -> Vec<PromptCacheConversationInvocationPreviewResponse> {
    recent_invocations.extend(existing_recent_invocations);
    let mut seen_keys = HashSet::with_capacity(recent_invocations.len());
    recent_invocations.retain(|invocation| {
        seen_keys.insert((invocation.invoke_id.clone(), invocation.occurred_at.clone()))
    });
    recent_invocations.sort_by(|left, right| {
        right
            .occurred_at
            .cmp(&left.occurred_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    recent_invocations.truncate(recent_limit);
    recent_invocations
}

async fn load_dashboard_activity_live_recent_invocations_by_account(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
    recent_limit: usize,
) -> Result<HashMap<Option<i64>, Vec<PromptCacheConversationInvocationPreviewResponse>>, ApiError> {
    let mut rows = query_live_upstream_account_activity_preview_rows_per_account_limit(
        &state.pool,
        source_scope,
        range,
        recent_limit,
        UpstreamAccountActivityPreviewReadTelemetry {
            route: "dashboard",
            builder: "live_recent_overlay",
            purpose: "bounded_per_account_recent",
        },
    )
    .await?;
    overlay_runtime_upstream_account_activity_preview_rows(state, &mut rows, source_scope, range);
    overlay_runtime_terminal_upstream_account_activity_preview_rows(
        state,
        &mut rows,
        source_scope,
        range,
    )
    .await?;

    let mut recent_invocations_by_account =
        HashMap::<Option<i64>, Vec<PromptCacheConversationInvocationPreviewResponse>>::new();
    for row in rows {
        recent_invocations_by_account
            .entry(row.upstream_account_id)
            .or_default()
            .push(upstream_account_invocation_preview_from_row(row));
    }
    for recent_invocations in recent_invocations_by_account.values_mut() {
        *recent_invocations = merge_dashboard_activity_recent_invocations(
            std::mem::take(recent_invocations),
            Vec::new(),
            recent_limit,
        );
    }

    Ok(recent_invocations_by_account)
}

async fn overlay_dashboard_activity_live_accounts(
    state: &AppState,
    snapshot: &mut DashboardActivitySnapshot,
    live: DashboardActivityLiveSnapshot,
    request_range: ExactUtcRange,
    include_accounts: bool,
    include_recent: bool,
    recent_limit: usize,
) -> Result<(), ApiError> {
    snapshot.summary.stats.in_progress_conversation_count = Some(live.in_progress_invocation_count);
    snapshot.summary.stats.in_progress_retry_conversation_count = Some(live.retry_invocation_count);
    snapshot.summary.stats.in_progress_phase_counts = Some(live.in_progress_phase_counts);

    let current_snapshot_by_account = state
        .dashboard_network_speed_cache
        .snapshot_dashboard_activity_accounts(Utc::now());
    let current_snapshot_summary =
        sum_dashboard_activity_current_snapshots(current_snapshot_by_account.values().copied());
    snapshot.summary.tokens_per_minute =
        Some(current_snapshot_summary.qualified_tokens.max(0) as f64);
    snapshot.summary.spend_rate = Some(current_snapshot_summary.total_cost.max(0.0));
    snapshot.summary.current_first_response_byte_total_avg_ms = current_snapshot_summary
        .first_response_byte_total_avg_ms()
        .or(snapshot.summary.current_first_response_byte_total_avg_ms);
    snapshot.summary.current_first_token_avg_ms = current_snapshot_summary.first_token_avg_ms();
    snapshot.summary.current_avg_total_ms = current_snapshot_summary
        .avg_total_ms()
        .or(snapshot.summary.current_avg_total_ms);
    snapshot.summary.current_avg_response_ms = current_snapshot_summary
        .avg_response_duration_ms()
        .or(snapshot.summary.current_avg_response_ms);

    if !include_accounts {
        return Ok(());
    }

    let recent_source_scope = if include_recent {
        Some(resolve_default_source_scope(&state.pool).await?)
    } else {
        None
    };
    let mut refreshed_recent_invocations_by_account =
        if let Some(source_scope) = recent_source_scope {
            Some(
                load_dashboard_activity_live_recent_invocations_by_account(
                    state,
                    source_scope,
                    request_range,
                    recent_limit,
                )
                .await?,
            )
        } else {
            None
        };
    let live_accounts = live
        .accounts
        .into_iter()
        .map(|account| (account.account_key.clone(), account))
        .collect::<HashMap<_, _>>();
    let metadata_refresh_ids = snapshot
        .accounts
        .iter()
        .filter(|account| account.enabled.is_none() && account.upstream_account_id.is_some())
        .filter_map(|account| account.upstream_account_id)
        .collect::<Vec<_>>();
    let metadata_refresh = if metadata_refresh_ids.is_empty() {
        (HashMap::new(), HashMap::new())
    } else {
        (
            query_upstream_account_activity_meta(&state.pool, &metadata_refresh_ids).await?,
            crate::upstream_accounts::load_effective_routing_rules_for_accounts(
                &state.pool,
                &metadata_refresh_ids,
            )
            .await?,
        )
    };
    for account in &mut snapshot.accounts {
        if let Some(account_id) = account.upstream_account_id
            && let Some(meta) = metadata_refresh.0.get(&account_id)
        {
            let status_fields = build_upstream_account_activity_status_fields(meta, Utc::now());
            account.display_name = resolve_upstream_account_activity_display_name(
                account_id,
                Some(meta),
                Some(account.display_name.as_str()),
            );
            account.group_name = normalize_trimmed_optional_string_local(meta.group_name.clone());
            account.plan_type = normalize_trimmed_optional_string_local(meta.plan_type.clone());
            account.enabled = Some(status_fields.enabled);
            account.display_status = Some(status_fields.display_status);
            account.enable_status = Some(status_fields.enable_status);
            account.work_status = Some(status_fields.work_status);
            account.health_status = Some(status_fields.health_status);
            account.sync_state = Some(status_fields.sync_state);
            account.last_error = status_fields.last_error;
            account.last_action_reason_message = status_fields.last_action_reason_message;
            account.effective_routing_rule = Some(
                metadata_refresh
                    .1
                    .get(&account_id)
                    .cloned()
                    .unwrap_or_else(crate::upstream_accounts::default_effective_routing_rule),
            );
        }
        let live_account = live_accounts.get(&account.account_key);
        account.in_progress_invocation_count =
            Some(live_account.map_or(0, |row| row.in_progress_invocation_count));
        account.in_progress_phase_counts = Some(
            live_account
                .map(|row| row.in_progress_phase_counts)
                .unwrap_or_default(),
        );
        account.retry_invocation_count =
            Some(live_account.map_or(0, |row| row.retry_invocation_count));
        if let Some(live_account) = live_account {
            account.request_count = account
                .request_count
                .max(live_account.in_progress_invocation_count.max(0));
        }
        account.upload_bytes_per_second =
            live_account.map_or(0.0, |row| row.upload_bytes_per_second);
        account.download_bytes_per_second =
            live_account.map_or(0.0, |row| row.download_bytes_per_second);
        let current_snapshot = current_snapshot_by_account
            .get(&account.upstream_account_id)
            .copied()
            .unwrap_or_default();
        account.tokens_per_minute = Some(current_snapshot.qualified_tokens.max(0) as f64);
        account.spend_rate = Some(current_snapshot.total_cost.max(0.0));
        account.current_first_response_byte_total_avg_ms = current_snapshot
            .first_response_byte_total_avg_ms()
            .or(account.current_first_response_byte_total_avg_ms);
        account.current_first_token_avg_ms = current_snapshot.first_token_avg_ms();
        account.current_avg_total_ms = current_snapshot
            .avg_total_ms()
            .or(account.current_avg_total_ms);
        account.current_avg_response_ms = current_snapshot
            .avg_response_duration_ms()
            .or(account.current_avg_response_ms);
        if let Some(refreshed_recent_invocations_by_account) =
            refreshed_recent_invocations_by_account.as_mut()
            && let Some(recent_invocations) =
                refreshed_recent_invocations_by_account.remove(&account.upstream_account_id)
        {
            let existing_recent_invocations = std::mem::take(&mut account.recent_invocations);
            account.recent_invocations = merge_dashboard_activity_recent_invocations(
                recent_invocations,
                existing_recent_invocations,
                recent_limit,
            );
        }
    }

    let existing_account_keys = snapshot
        .accounts
        .iter()
        .map(|account| account.account_key.clone())
        .collect::<HashSet<_>>();
    let missing_live_accounts = live_accounts
        .values()
        .filter(|account| !existing_account_keys.contains(&account.account_key))
        .collect::<Vec<_>>();

    if !missing_live_accounts.is_empty() {
        let missing_account_ids = missing_live_accounts
            .iter()
            .filter_map(|account| account.upstream_account_id)
            .collect::<Vec<_>>();
        let account_meta =
            query_upstream_account_activity_meta(&state.pool, &missing_account_ids).await?;
        let effective_routing_rules =
            crate::upstream_accounts::load_effective_routing_rules_for_accounts(
                &state.pool,
                &missing_account_ids,
            )
            .await?;
        for live_account in missing_live_accounts {
            let meta = live_account
                .upstream_account_id
                .and_then(|id| account_meta.get(&id));
            let effective_routing_rule = live_account.upstream_account_id.map(|id| {
                effective_routing_rules
                    .get(&id)
                    .cloned()
                    .unwrap_or_else(crate::upstream_accounts::default_effective_routing_rule)
            });
            let current_snapshot = current_snapshot_by_account
                .get(&live_account.upstream_account_id)
                .copied()
                .unwrap_or_default();
            let recent_invocations = if let Some(refreshed_recent_invocations_by_account) =
                refreshed_recent_invocations_by_account.as_mut()
            {
                refreshed_recent_invocations_by_account
                    .remove(&live_account.upstream_account_id)
                    .unwrap_or_default()
            } else {
                Vec::new()
            };
            snapshot.accounts.push(dashboard_activity_account_from_live(
                live_account,
                meta,
                request_range,
                current_snapshot,
                snapshot.summary.model_performance.available,
                effective_routing_rule,
                recent_invocations,
            ));
        }
        sort_dashboard_activity_accounts(&mut snapshot.accounts);
    }

    if let Some(refreshed_recent_invocations_by_account) = refreshed_recent_invocations_by_account {
        let existing_account_ids = snapshot
            .accounts
            .iter()
            .map(|account| account.upstream_account_id)
            .collect::<HashSet<_>>();
        let missing_terminal_account_ids = refreshed_recent_invocations_by_account
            .keys()
            .copied()
            .filter(|account_id| !existing_account_ids.contains(account_id))
            .collect::<Vec<_>>();

        if !missing_terminal_account_ids.is_empty() {
            let missing_terminal_account_meta_ids = missing_terminal_account_ids
                .iter()
                .filter_map(|account_id| *account_id)
                .collect::<Vec<_>>();
            let account_meta = if missing_terminal_account_meta_ids.is_empty() {
                HashMap::new()
            } else {
                query_upstream_account_activity_meta(
                    &state.pool,
                    &missing_terminal_account_meta_ids,
                )
                .await?
            };
            let effective_routing_rules = if missing_terminal_account_meta_ids.is_empty() {
                HashMap::new()
            } else {
                crate::upstream_accounts::load_effective_routing_rules_for_accounts(
                    &state.pool,
                    &missing_terminal_account_meta_ids,
                )
                .await?
            };
            let mut refreshed_recent_invocations_by_account =
                refreshed_recent_invocations_by_account;
            for upstream_account_id in missing_terminal_account_ids {
                let recent_invocations = refreshed_recent_invocations_by_account
                    .remove(&upstream_account_id)
                    .unwrap_or_default();
                if recent_invocations.is_empty() {
                    continue;
                }

                let live_account = DashboardActivityLiveAccount {
                    account_key: upstream_account_id
                        .map(|id| format!("upstream:{id}"))
                        .unwrap_or_else(|| "unassigned".to_string()),
                    upstream_account_id,
                    upstream_account_name: None,
                    in_progress_invocation_count: 0,
                    in_progress_phase_counts: InvocationPhaseCountsResponse::default(),
                    retry_invocation_count: 0,
                    in_progress_wait_sum_ms: 0.0,
                    in_progress_wait_sample_count: 0,
                    upload_bytes_per_second: 0.0,
                    download_bytes_per_second: 0.0,
                    network_live_bucket: None,
                };
                let meta = upstream_account_id.and_then(|id| account_meta.get(&id));
                let effective_routing_rule = upstream_account_id.map(|id| {
                    effective_routing_rules
                        .get(&id)
                        .cloned()
                        .unwrap_or_else(crate::upstream_accounts::default_effective_routing_rule)
                });
                let current_snapshot = current_snapshot_by_account
                    .get(&upstream_account_id)
                    .copied()
                    .unwrap_or_default();
                snapshot.accounts.push(dashboard_activity_account_from_live(
                    &live_account,
                    meta,
                    request_range,
                    current_snapshot,
                    snapshot.summary.model_performance.available,
                    effective_routing_rule,
                    recent_invocations,
                ));
            }
            sort_dashboard_activity_accounts(&mut snapshot.accounts);
        }
    }

    snapshot.summary = build_dashboard_activity_summary(
        &snapshot.accounts,
        true,
        current_snapshot_summary,
        snapshot.summary.current_first_response_byte_total_avg_ms,
        snapshot.summary.current_avg_total_ms,
        snapshot.summary.model_performance.clone(),
    );
    dashboard_activity_apply_materialized_archive_fallback_to_stats(
        &mut snapshot.summary.stats,
        snapshot.materialized_archive_fallback_totals,
    );
    if snapshot.materialized_archive_details_limited {
        dashboard_activity_clear_materialized_archive_detail_fields(&mut snapshot.summary.stats);
    }

    Ok(())
}

#[derive(Debug, FromRow)]
pub(crate) struct DashboardActivityRateUsageRow {
    invoke_id: String,
    occurred_at: String,
    upstream_account_id: Option<i64>,
    total_tokens: i64,
    total_cost: f64,
}

pub(crate) fn validate_dashboard_activity_params(
    endpoint: &str,
    range: &str,
    recent_limit: Option<i64>,
) -> Result<usize, ApiError> {
    if !matches!(range, "today" | "yesterday" | "1d" | "7d") {
        return Err(ApiError::bad_request(anyhow!(
            "unsupported {endpoint} range: {range}",
        )));
    }

    match recent_limit {
        Some(value) if !(1..=16).contains(&value) => Err(ApiError::bad_request(anyhow!(
            "recentLimit must be between 1 and 16"
        ))),
        Some(value) => Ok(value as usize),
        None => Ok(4),
    }
}

pub(crate) fn sum_optional_rates(
    accounts: &[DashboardActivityAccountResponse],
    value_of: impl Fn(&DashboardActivityAccountResponse) -> Option<f64>,
) -> Option<f64> {
    let mut saw_value = false;
    let mut total = 0.0;
    for account in accounts {
        if let Some(value) = value_of(account).filter(|value| value.is_finite()) {
            saw_value = true;
            total += value;
        }
    }
    saw_value.then_some(total)
}

async fn load_dashboard_activity_current_minute_rows(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<Vec<UpstreamAccountInvocationPreviewRow>, ApiError> {
    let current_window = dashboard_activity_last_complete_minute_window(range);
    let mut rows = query_live_upstream_account_activity_preview_rows_with_limit(
        &state.pool,
        source_scope,
        current_window,
        None,
        None,
        None,
        false,
        UpstreamAccountActivityPreviewReadTelemetry {
            route: "dashboard",
            builder: "current_minute",
            purpose: "current_minute_preview_rows",
        },
    )
    .await?;
    let mut rows_by_key = rows
        .drain(..)
        .map(|row| ((row.invoke_id.clone(), row.occurred_at.clone()), row))
        .collect::<HashMap<_, _>>();
    let mut unresolved_runtime_account_keys = HashSet::new();

    for record in state.proxy_runtime_invocations.snapshot() {
        let Some(mut row) =
            runtime_upstream_account_activity_preview_row_with_terminal(record, source_scope, true)
        else {
            continue;
        };
        let Some(occurred_at) = parse_to_utc_datetime(&row.occurred_at) else {
            continue;
        };
        if occurred_at < current_window.start || occurred_at >= current_window.end {
            continue;
        }
        let key = (row.invoke_id.clone(), row.occurred_at.clone());
        if let Some(existing) = rows_by_key.get(&key) {
            if row.upstream_account_id.is_none() {
                row.upstream_account_id = existing.upstream_account_id;
            }
            if row.upstream_account_name.is_none() {
                row.upstream_account_name = existing.upstream_account_name.clone();
            }
            if row.upstream_account_plan_type.is_none() {
                row.upstream_account_plan_type = existing.upstream_account_plan_type.clone();
            }
        }
        if row.upstream_account_id.is_none() {
            unresolved_runtime_account_keys.insert(key.clone());
        }
        rows_by_key.insert(key, row);
    }

    if !unresolved_runtime_account_keys.is_empty() {
        for fallback_row in query_runtime_recent_account_fallback_rows(
            &state.pool,
            source_scope,
            &unresolved_runtime_account_keys,
        )
        .await?
        {
            let key = (
                fallback_row.invoke_id.clone(),
                fallback_row.occurred_at.clone(),
            );
            if let Some(row) = rows_by_key.get_mut(&key) {
                if row.upstream_account_id.is_none() {
                    row.upstream_account_id = fallback_row.upstream_account_id;
                }
                if row.upstream_account_name.is_none() {
                    row.upstream_account_name = fallback_row.upstream_account_name;
                }
                if row.upstream_account_plan_type.is_none() {
                    row.upstream_account_plan_type = fallback_row.upstream_account_plan_type;
                }
            }
        }
    }

    Ok(rows_by_key.into_values().collect())
}

async fn load_dashboard_activity_current_minute_accumulators_by_account(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<HashMap<Option<i64>, DashboardActivityCurrentMinuteAccumulator>, ApiError> {
    let mut accumulators = HashMap::<Option<i64>, DashboardActivityCurrentMinuteAccumulator>::new();
    for row in load_dashboard_activity_current_minute_rows(state, source_scope, range).await? {
        accumulators
            .entry(row.upstream_account_id)
            .or_default()
            .add_row(&row);
    }
    Ok(accumulators)
}

fn sum_dashboard_activity_current_minute_accumulators(
    accumulators: impl IntoIterator<Item = DashboardActivityCurrentMinuteAccumulator>,
) -> DashboardActivityCurrentMinuteAccumulator {
    let mut total = DashboardActivityCurrentMinuteAccumulator::default();
    for accumulator in accumulators {
        total.merge(accumulator);
    }
    total
}

pub(crate) fn sum_dashboard_activity_current_snapshots(
    snapshots: impl IntoIterator<Item = DashboardActivityCurrentSnapshot>,
) -> DashboardActivityCurrentSnapshot {
    let mut total = DashboardActivityCurrentSnapshot::default();
    for snapshot in snapshots {
        total.add_assign(snapshot);
    }
    total
}

pub(crate) fn build_dashboard_activity_summary(
    accounts: &[DashboardActivityAccountResponse],
    include_live_counts: bool,
    current_snapshot: DashboardActivityCurrentSnapshot,
    latest_first_response_byte_total_in_range: Option<f64>,
    latest_avg_total_in_range: Option<f64>,
    model_performance: ModelPerformanceResponse,
) -> DashboardActivitySummaryResponse {
    let ttfb_sum = accounts
        .iter()
        .map(|account| account.in_progress_wait_sum_ms)
        .sum::<f64>();
    let ttfb_count = accounts
        .iter()
        .map(|account| account.in_progress_wait_sample_count)
        .sum::<i64>();

    let mut usage_breakdown = UsageBreakdownAccumulator::default();
    for account in accounts {
        usage_breakdown.merge_response(&account.usage_breakdown);
    }
    let stats = StatsResponse {
        total_count: accounts.iter().map(|account| account.request_count).sum(),
        success_count: accounts.iter().map(|account| account.success_count).sum(),
        failure_count: accounts.iter().map(|account| account.failure_count).sum(),
        total_cost: accounts.iter().map(|account| account.total_cost).sum(),
        total_tokens: accounts.iter().map(|account| account.total_tokens).sum(),
        usage_breakdown: Some(usage_breakdown.into_response()),
        in_progress_conversation_count: include_live_counts.then(|| {
            accounts
                .iter()
                .map(|account| account.in_progress_invocation_count.unwrap_or(0))
                .sum()
        }),
        in_progress_retry_conversation_count: include_live_counts.then(|| {
            accounts
                .iter()
                .map(|account| account.retry_invocation_count.unwrap_or(0))
                .sum()
        }),
        in_progress_avg_wait_ms: (ttfb_count > 0).then_some(ttfb_sum / ttfb_count as f64),
        in_progress_phase_counts: include_live_counts.then(|| {
            accounts.iter().fold(
                InvocationPhaseCountsResponse::default(),
                |mut total, account| {
                    if let Some(counts) = account.in_progress_phase_counts {
                        total.queued += counts.queued;
                        total.requesting += counts.requesting;
                        total.responding += counts.responding;
                    }
                    total
                },
            )
        }),
        non_success_cost: Some(
            accounts
                .iter()
                .map(|account| account.non_success_cost)
                .sum(),
        ),
        non_success_tokens: Some(
            accounts
                .iter()
                .map(|account| account.non_success_tokens)
                .sum(),
        ),
        maintenance: None,
    };

    DashboardActivitySummaryResponse {
        stats,
        tokens_per_minute: Some(
            sum_optional_rates(accounts, |account| account.tokens_per_minute)
                .unwrap_or(current_snapshot.qualified_tokens.max(0) as f64),
        ),
        spend_rate: Some(
            sum_optional_rates(accounts, |account| account.spend_rate)
                .unwrap_or(current_snapshot.total_cost.max(0.0)),
        ),
        current_first_response_byte_total_avg_ms: current_snapshot
            .first_response_byte_total_avg_ms()
            .or(latest_first_response_byte_total_in_range),
        current_first_token_avg_ms: current_snapshot.first_token_avg_ms(),
        current_avg_total_ms: current_snapshot
            .avg_total_ms()
            .or(latest_avg_total_in_range),
        current_avg_response_ms: current_snapshot.avg_response_duration_ms(),
        model_performance,
    }
}

fn build_dashboard_activity_latency_summary(
    current_snapshot: DashboardActivityCurrentSnapshot,
    latest_first_response_byte_total_in_range: Option<f64>,
    latest_avg_total_in_range: Option<f64>,
) -> (Option<f64>, Option<f64>) {
    (
        current_snapshot
            .first_response_byte_total_avg_ms()
            .or(latest_first_response_byte_total_in_range),
        current_snapshot
            .avg_total_ms()
            .or(latest_avg_total_in_range),
    )
}

async fn load_dashboard_activity_current_latency_fallback(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<(Option<f64>, Option<f64>), ApiError> {
    let metric_range = ExactUtcRange {
        start: range
            .start
            .max(range.end - ChronoDuration::minutes(DASHBOARD_ACTIVITY_RATE_WINDOW_MINUTES)),
        end: range.end,
    };
    let mut latest_first_response_byte_total = LatestTimedMetricValue::default();
    let mut latest_avg_total = LatestTimedMetricValue::default();
    for row in query_live_upstream_account_activity_aggregate_rows(
        &state.pool,
        source_scope,
        metric_range,
        true,
        DashboardActivityExcludedInvocationIdsFilter::None,
    )
    .await?
    {
        latest_first_response_byte_total.update(
            row.latest_first_response_byte_total_at,
            row.latest_first_response_byte_total_ms,
        );
        latest_avg_total.update(row.latest_avg_total_at, row.latest_avg_total_ms);
    }

    Ok((
        latest_first_response_byte_total.value,
        latest_avg_total.value,
    ))
}

pub(crate) async fn query_dashboard_activity_rate_usage_rows(
    pool: &Pool<Sqlite>,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<Vec<DashboardActivityRateUsageRow>, ApiError> {
    let rate_window_start = range
        .start
        .max(range.end - ChronoDuration::minutes(DASHBOARD_ACTIVITY_RATE_WINDOW_MINUTES));
    let upstream_account_id_sql =
        invocation_upstream_account_id_with_attempt_fallback_sql("codex_invocations");
    let mut query = QueryBuilder::<Sqlite>::new("SELECT invoke_id, occurred_at, ");
    query
        .push(upstream_account_id_sql.as_str())
        .push(
            " AS upstream_account_id, \
             COALESCE(total_tokens, 0) AS total_tokens, \
             COALESCE(cost, 0.0) AS total_cost \
             FROM codex_invocations \
             WHERE occurred_at >= ",
        )
        .push_bind(db_occurred_at_lower_bound(rate_window_start))
        .push(" AND occurred_at < ")
        .push_bind(db_occurred_at_upper_bound(range.end));
    if source_scope == InvocationSourceScope::ProxyOnly {
        query.push(" AND source = ").push_bind(SOURCE_PROXY);
    }

    Ok(query
        .build_query_as::<DashboardActivityRateUsageRow>()
        .fetch_all(pool)
        .await?)
}

pub(crate) async fn load_dashboard_activity_rate_events_by_account(
    state: &AppState,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<HashMap<Option<i64>, Vec<UpstreamAccountRateUsageEvent>>, ApiError> {
    let rows = query_dashboard_activity_rate_usage_rows(&state.pool, source_scope, range).await?;
    let db_account_by_key = rows
        .iter()
        .map(|row| {
            (
                (row.invoke_id.clone(), row.occurred_at.clone()),
                row.upstream_account_id,
            )
        })
        .collect::<HashMap<_, _>>();
    let runtime_snapshot = state.proxy_runtime_invocations.snapshot();
    let terminal_keys =
        query_terminal_db_keys_for_runtime_records(&state.pool, &runtime_snapshot, None).await?;
    let rate_window_start = range
        .start
        .max(range.end - ChronoDuration::minutes(DASHBOARD_ACTIVITY_RATE_WINDOW_MINUTES));
    let mut runtime_events_by_key =
        HashMap::<(String, String), (Option<i64>, UpstreamAccountRateUsageEvent)>::new();
    for record in runtime_snapshot {
        if source_scope == InvocationSourceScope::ProxyOnly && record.source != SOURCE_PROXY {
            continue;
        }
        if !matches!(
            normalized_runtime_text(record.status.as_deref()).as_str(),
            "running" | "pending"
        ) {
            continue;
        }
        let key = (record.invoke_id.clone(), record.occurred_at.clone());
        if terminal_keys.contains(&key) {
            continue;
        }
        let Some(occurred_at) = parse_to_utc_datetime(&record.occurred_at) else {
            continue;
        };
        if occurred_at < rate_window_start || occurred_at >= range.end {
            continue;
        }
        let upstream_account_id = record
            .upstream_account_id
            .or_else(|| db_account_by_key.get(&key).copied().flatten());
        runtime_events_by_key.insert(
            key,
            (
                upstream_account_id,
                UpstreamAccountRateUsageEvent {
                    occurred_at_epoch_ms: occurred_at.timestamp_millis(),
                    total_tokens: record.total_tokens.unwrap_or_default().max(0),
                    total_cost: record.cost.unwrap_or_default().max(0.0),
                },
            ),
        );
    }

    let mut events_by_account = HashMap::<Option<i64>, Vec<UpstreamAccountRateUsageEvent>>::new();
    for row in rows {
        let Some(occurred_at) = parse_to_utc_datetime(&row.occurred_at) else {
            continue;
        };
        if runtime_events_by_key.contains_key(&(row.invoke_id.clone(), row.occurred_at.clone())) {
            continue;
        }
        events_by_account
            .entry(row.upstream_account_id)
            .or_default()
            .push(UpstreamAccountRateUsageEvent {
                occurred_at_epoch_ms: occurred_at.timestamp_millis(),
                total_tokens: row.total_tokens.max(0),
                total_cost: row.total_cost.max(0.0),
            });
    }

    for (_key, (upstream_account_id, event)) in runtime_events_by_key {
        events_by_account
            .entry(upstream_account_id)
            .or_default()
            .push(event);
    }

    Ok(events_by_account)
}

pub(crate) fn sum_dashboard_activity_rate_events(
    events_by_account: &HashMap<Option<i64>, Vec<UpstreamAccountRateUsageEvent>>,
    range: ExactUtcRange,
) -> (Option<f64>, Option<f64>) {
    let mut saw_tokens_per_minute = false;
    let mut saw_spend_rate = false;
    let mut tokens_per_minute_total = 0.0;
    let mut spend_rate_total = 0.0;

    for events in events_by_account.values() {
        let (tokens_per_minute, spend_rate) =
            compute_upstream_account_activity_rates(events, range.start, range.end);
        if let Some(value) = tokens_per_minute.filter(|value| value.is_finite()) {
            saw_tokens_per_minute = true;
            tokens_per_minute_total += value;
        }
        if let Some(value) = spend_rate.filter(|value| value.is_finite()) {
            saw_spend_rate = true;
            spend_rate_total += value;
        }
    }

    (
        saw_tokens_per_minute.then_some(tokens_per_minute_total),
        saw_spend_rate.then_some(spend_rate_total),
    )
}

pub(crate) fn dashboard_activity_last_complete_minute_window(
    range: ExactUtcRange,
) -> ExactUtcRange {
    let closed_window_end = range
        .end
        .with_second(0)
        .and_then(|value| value.with_nanosecond(0))
        .expect("valid exact minute");
    let closed_window_start = (closed_window_end - ChronoDuration::minutes(1)).max(range.start);
    ExactUtcRange {
        start: closed_window_start,
        end: closed_window_end.max(closed_window_start),
    }
}

pub(crate) async fn load_dashboard_activity_summary_only_snapshot(
    state: &AppState,
    range_name: &str,
    source_scope: InvocationSourceScope,
    range: ExactUtcRange,
) -> Result<DashboardActivitySnapshot, ApiError> {
    let retention_cutoff = shanghai_retention_cutoff(state.config.invocation_max_days);
    let model_performance_available = range.start >= retention_cutoff;
    let mut totals =
        query_hourly_backed_summary_range(state, range.start, range.end, source_scope).await?;
    totals = totals.add(
        dashboard_activity_historical_live_gap_totals(state, source_scope, range, retention_cutoff)
            .await?,
    );
    let mut stats = totals.into_response();
    stats.non_success_cost = Some(totals.non_success_cost);
    let augmentation = load_summary_live_augmentation(
        state,
        source_scope,
        None,
        Some((range.start, range.end)),
        SummaryLiveAugmentationPolicy {
            include_in_progress: range_name != "yesterday",
            // Hourly summary rollups do not retain non-success token totals; a raw full-range
            // scan here would defeat the summary-only fast path.
            include_non_success_tokens: false,
        },
        None,
    )
    .await?;
    apply_summary_live_augmentation(&mut stats, augmentation);
    let current_snapshot = if range_name == "yesterday" {
        let current_minute_by_account =
            load_dashboard_activity_current_minute_accumulators_by_account(
                state,
                source_scope,
                range,
            )
            .await?;
        sum_dashboard_activity_current_minute_accumulators(current_minute_by_account.into_values())
            .into_current_snapshot()
    } else {
        sum_dashboard_activity_current_snapshots(
            state
                .dashboard_network_speed_cache
                .snapshot_dashboard_activity_accounts(range.end)
                .into_values(),
        )
    };
    let snapshot_first_response_byte_total_avg_ms =
        current_snapshot.first_response_byte_total_avg_ms();
    let snapshot_avg_total_ms = current_snapshot.avg_total_ms();
    let (latest_first_response_byte_total_avg_ms, latest_avg_total_ms) =
        if snapshot_first_response_byte_total_avg_ms.is_none() || snapshot_avg_total_ms.is_none() {
            load_dashboard_activity_current_latency_fallback(state, source_scope, range).await?
        } else {
            (None, None)
        };
    let (current_first_response_byte_total_avg_ms, current_avg_total_ms) =
        build_dashboard_activity_latency_summary(
            current_snapshot,
            latest_first_response_byte_total_avg_ms,
            latest_avg_total_ms,
        );

    Ok(DashboardActivitySnapshot {
        range: range_name.to_string(),
        range_start: range.start,
        range_end: range.end,
        terminal_sequence: 0,
        accounts: Vec::new(),
        summary: DashboardActivitySummaryResponse {
            stats,
            tokens_per_minute: Some(current_snapshot.qualified_tokens.max(0) as f64),
            spend_rate: Some(current_snapshot.total_cost.max(0.0)),
            current_first_token_avg_ms: current_snapshot.first_token_avg_ms(),
            current_first_response_byte_total_avg_ms,
            current_avg_total_ms,
            current_avg_response_ms: current_snapshot.avg_response_duration_ms(),
            model_performance: ModelPerformanceAccumulator::default()
                .into_response(range, model_performance_available),
        },
        summary_model_performance_accumulator: ModelPerformanceAccumulator::default(),
        account_model_performance_accumulators: HashMap::new(),
        account_latency_accumulators: HashMap::new(),
        model_performance_accumulator_ready: false,
        materialized_archive_fallback_totals: StatsTotals::default(),
        materialized_archive_details_limited: false,
        build_telemetry: DashboardActivityBuildTelemetry::default(),
    })
}

pub(crate) async fn load_dashboard_activity_snapshot(
    state: &AppState,
    range_name: &str,
    reporting_tz: Tz,
    recent_limit: usize,
    include_accounts: bool,
    include_recent: bool,
    in_progress_counts_override: Option<HashMap<Option<i64>, UpstreamAccountInProgressSummary>>,
) -> Result<DashboardActivitySnapshot, ApiError> {
    let range = resolve_dashboard_activity_exact_range(range_name, reporting_tz)?;
    load_dashboard_activity_snapshot_for_range(
        state,
        range_name,
        reporting_tz,
        range,
        recent_limit,
        include_accounts,
        include_recent,
        in_progress_counts_override,
    )
    .await
}

async fn load_dashboard_activity_snapshot_for_range(
    state: &AppState,
    range_name: &str,
    _reporting_tz: Tz,
    range: ExactUtcRange,
    recent_limit: usize,
    include_accounts: bool,
    include_recent: bool,
    in_progress_counts_override: Option<HashMap<Option<i64>, UpstreamAccountInProgressSummary>>,
) -> Result<DashboardActivitySnapshot, ApiError> {
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    if !include_accounts {
        return load_dashboard_activity_summary_only_snapshot(
            state,
            range_name,
            source_scope,
            range,
        )
        .await;
    }
    let build = load_dashboard_activity_account_build_result(
        state,
        range_name,
        range,
        recent_limit,
        include_recent,
        in_progress_counts_override,
        DashboardActivityAccountBuilderKind::DashboardFull,
    )
    .await?;
    let mut summary = build_dashboard_activity_summary(
        &build.accounts,
        range_name != "yesterday",
        build.current_snapshot_summary,
        build.latest_first_response_byte_total_in_range,
        build.latest_avg_total_in_range,
        build.summary_model_performance,
    );
    dashboard_activity_apply_materialized_archive_fallback_to_stats(
        &mut summary.stats,
        build.materialized_archive_fallback_totals,
    );
    if build.materialized_archive_details_limited {
        dashboard_activity_clear_materialized_archive_detail_fields(&mut summary.stats);
    }
    Ok(DashboardActivitySnapshot {
        range: range_name.to_string(),
        range_start: range.start,
        range_end: range.end,
        terminal_sequence: 0,
        accounts: build.accounts,
        summary,
        summary_model_performance_accumulator: build.summary_model_performance_accumulator,
        account_model_performance_accumulators: build.account_model_performance_accumulators,
        account_latency_accumulators: build.account_latency_accumulators,
        model_performance_accumulator_ready: true,
        materialized_archive_fallback_totals: build.materialized_archive_fallback_totals,
        materialized_archive_details_limited: build.materialized_archive_details_limited,
        build_telemetry: build.build_telemetry,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DashboardActivityAccountBuilderKind {
    DashboardFull,
    UpstreamAccount,
}

impl DashboardActivityAccountBuilderKind {
    fn preview_read_telemetry(self) -> UpstreamAccountActivityPreviewReadTelemetry {
        match self {
            Self::DashboardFull => UpstreamAccountActivityPreviewReadTelemetry {
                route: "dashboard",
                builder: "dashboard_full",
                purpose: "bounded_per_account_recent",
            },
            Self::UpstreamAccount => UpstreamAccountActivityPreviewReadTelemetry {
                route: "upstream_account",
                builder: "upstream_account",
                purpose: "bounded_per_account_recent",
            },
        }
    }
}

#[derive(Debug)]
struct DashboardActivityAccountBuildResult {
    accounts: Vec<DashboardActivityAccountResponse>,
    current_snapshot_summary: DashboardActivityCurrentSnapshot,
    latest_first_response_byte_total_in_range: Option<f64>,
    latest_avg_total_in_range: Option<f64>,
    summary_model_performance: ModelPerformanceResponse,
    summary_model_performance_accumulator: ModelPerformanceAccumulator,
    account_model_performance_accumulators: HashMap<Option<i64>, ModelPerformanceAccumulator>,
    account_latency_accumulators: HashMap<Option<i64>, DashboardActivityAccountLatencyAccumulator>,
    materialized_archive_fallback_totals: StatsTotals,
    materialized_archive_details_limited: bool,
    build_telemetry: DashboardActivityBuildTelemetry,
}

fn build_dashboard_activity_account_response(
    range_name: &str,
    range: ExactUtcRange,
    model_performance_available: bool,
    current_snapshot_by_account: &HashMap<Option<i64>, DashboardActivityCurrentSnapshot>,
    account_meta: &HashMap<i64, UpstreamAccountActivityMetaRow>,
    effective_routing_rules: &HashMap<i64, crate::upstream_accounts::EffectiveRoutingRule>,
    in_progress_counts: &HashMap<Option<i64>, UpstreamAccountInProgressSummary>,
    upstream_account_id: Option<i64>,
    aggregate: UpstreamAccountActivityAccumulator,
) -> DashboardActivityAccountResponse {
    let meta = upstream_account_id.and_then(|id| account_meta.get(&id));
    let status_fields =
        meta.map(|row| build_upstream_account_activity_status_fields(row, Utc::now()));
    let model_performance = aggregate
        .model_performance
        .into_response(range, model_performance_available);
    let current_snapshot = current_snapshot_by_account
        .get(&upstream_account_id)
        .copied()
        .unwrap_or_default();
    let (current_first_response_byte_total_avg_ms, current_avg_total_ms) =
        build_dashboard_activity_latency_summary(
            current_snapshot,
            aggregate.latest_first_response_byte_total_ms,
            aggregate.latest_avg_total_ms,
        );
    let tokens_per_minute = Some(current_snapshot.qualified_tokens.max(0) as f64);
    let spend_rate = Some(current_snapshot.total_cost.max(0.0));
    let (in_progress_invocation_count, in_progress_phase_counts, retry_invocation_count) =
        if range_name == "yesterday" {
            (None, None, None)
        } else {
            let summary = in_progress_counts
                .get(&upstream_account_id)
                .copied()
                .unwrap_or_default();
            (
                Some(summary.in_progress_count),
                Some(summary.phase_counts),
                Some(summary.retry_count),
            )
        };
    let account_key = upstream_account_id
        .map(|id| format!("upstream:{id}"))
        .unwrap_or_else(|| "unassigned".to_string());

    DashboardActivityAccountResponse {
        account_key,
        upstream_account_id,
        display_name: upstream_account_id
            .map(|id| {
                resolve_upstream_account_activity_display_name(
                    id,
                    meta,
                    aggregate.display_name_hint.as_deref(),
                )
            })
            .unwrap_or_else(|| "未分配上游账号".to_string()),
        is_unassigned: upstream_account_id.is_none(),
        latest_conversation_created_at: aggregate.latest_conversation_created_at,
        last_invocation_at: aggregate.last_invocation_at,
        group_name: normalize_trimmed_optional_string_local(
            meta.and_then(|row| row.group_name.clone()),
        ),
        plan_type: normalize_trimmed_optional_string_local(
            meta.and_then(|row| row.plan_type.clone())
                .or(aggregate.plan_type_hint),
        ),
        enabled: status_fields.as_ref().map(|fields| fields.enabled),
        display_status: status_fields
            .as_ref()
            .map(|fields| fields.display_status.clone()),
        enable_status: status_fields
            .as_ref()
            .map(|fields| fields.enable_status.clone()),
        work_status: status_fields
            .as_ref()
            .map(|fields| fields.work_status.clone()),
        health_status: status_fields
            .as_ref()
            .map(|fields| fields.health_status.clone()),
        sync_state: status_fields
            .as_ref()
            .map(|fields| fields.sync_state.clone()),
        last_error: status_fields
            .as_ref()
            .and_then(|fields| fields.last_error.clone()),
        last_action_reason_message: status_fields
            .as_ref()
            .and_then(|fields| fields.last_action_reason_message.clone()),
        request_count: aggregate.request_count,
        success_count: aggregate.success_count,
        failure_count: aggregate.failure_count,
        non_success_count: aggregate.non_success_count,
        total_tokens: aggregate.total_tokens,
        success_tokens: aggregate.success_tokens,
        non_success_tokens: aggregate.non_success_tokens,
        failure_tokens: aggregate.failure_tokens,
        failure_cost: aggregate.failure_cost,
        non_success_cost: aggregate.non_success_cost,
        total_cost: aggregate.total_cost,
        usage_breakdown: aggregate.usage_breakdown.clone().into_response(),
        model_performance,
        cache_hit_rate: (aggregate.total_tokens > 0)
            .then_some(aggregate.cache_input_tokens as f64 / aggregate.total_tokens as f64),
        tokens_per_minute,
        spend_rate,
        first_byte_avg_ms: (aggregate.first_response_byte_total_sample_count > 0).then_some(
            aggregate.first_response_byte_total_sum_ms
                / aggregate.first_response_byte_total_sample_count as f64,
        ),
        first_response_byte_total_avg_ms: (aggregate.first_response_byte_total_sample_count > 0)
            .then_some(
                aggregate.first_response_byte_total_sum_ms
                    / aggregate.first_response_byte_total_sample_count as f64,
            ),
        first_token_avg_ms: (aggregate.first_token_sample_count > 0)
            .then_some(aggregate.first_token_sum_ms / aggregate.first_token_sample_count as f64),
        avg_total_ms: (aggregate.total_latency_sample_count > 0).then_some(
            aggregate.total_latency_sum_ms / aggregate.total_latency_sample_count as f64,
        ),
        current_first_response_byte_total_avg_ms,
        current_first_token_avg_ms: current_snapshot.first_token_avg_ms(),
        current_avg_total_ms,
        current_avg_response_ms: current_snapshot.avg_response_duration_ms(),
        in_progress_invocation_count,
        in_progress_phase_counts,
        retry_invocation_count,
        upload_bytes_per_second: 0.0,
        download_bytes_per_second: 0.0,
        in_progress_wait_sum_ms: aggregate.in_progress_wait_sum_ms,
        in_progress_wait_sample_count: aggregate.in_progress_wait_sample_count,
        effective_routing_rule: upstream_account_id.map(|id| {
            effective_routing_rules
                .get(&id)
                .cloned()
                .unwrap_or_else(crate::upstream_accounts::default_effective_routing_rule)
        }),
        recent_invocations: aggregate.recent_invocations,
    }
}

async fn load_dashboard_activity_account_build_result(
    state: &AppState,
    range_name: &str,
    range: ExactUtcRange,
    recent_limit: usize,
    include_recent: bool,
    in_progress_counts_override: Option<HashMap<Option<i64>, UpstreamAccountInProgressSummary>>,
    builder_kind: DashboardActivityAccountBuilderKind,
) -> Result<DashboardActivityAccountBuildResult, ApiError> {
    let retention_cutoff = shanghai_retention_cutoff(state.config.invocation_max_days);
    let model_performance_available = range.start >= retention_cutoff;
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let mut account_activity = HashMap::<Option<i64>, UpstreamAccountActivityAccumulator>::new();
    let mut model_performance = ModelPerformanceAccumulator::default();
    let materialized_archive_fallback_totals = StatsTotals::default();
    let mut materialized_archive_details_limited = false;
    let current_snapshot_by_account = if range_name == "yesterday" {
        load_dashboard_activity_current_minute_accumulators_by_account(state, source_scope, range)
            .await?
            .into_iter()
            .map(|(upstream_account_id, accumulator)| {
                (upstream_account_id, accumulator.into_current_snapshot())
            })
            .collect::<HashMap<_, _>>()
    } else {
        state
            .dashboard_network_speed_cache
            .snapshot_dashboard_activity_accounts(range.end)
    };
    let current_snapshot_summary =
        sum_dashboard_activity_current_snapshots(current_snapshot_by_account.values().copied());
    let model_performance_duration_overrides = if builder_kind
        == DashboardActivityAccountBuilderKind::DashboardFull
        && model_performance_available
    {
        Some(
            query_live_model_performance_duration_overrides(&state.pool, source_scope, range, true)
                .await?,
        )
    } else {
        None
    };
    let account_range_build = if range_name == "yesterday" {
        AccountActivityRangeBuild {
            rows: query_live_upstream_account_activity_aggregate_rows(
                &state.pool,
                source_scope,
                range,
                true,
                DashboardActivityExcludedInvocationIdsFilter::None,
            )
            .await?,
            telemetry: AccountActivityRangeBuildTelemetry {
                raw_fallback_range_count: 1,
                ..AccountActivityRangeBuildTelemetry::default()
            },
        }
    } else {
        load_upstream_account_activity_range_rows(
            state,
            source_scope,
            range,
            if builder_kind == DashboardActivityAccountBuilderKind::UpstreamAccount {
                "upstream_account"
            } else {
                "dashboard"
            },
        )
        .await?
    };
    let account_aggregation_telemetry = account_range_build.telemetry;
    for row in account_range_build.rows {
        let entry = account_activity.entry(row.upstream_account_id).or_default();
        merge_upstream_account_activity_aggregate_row(entry, &row);
    }
    let usage_breakdown_build = load_usage_breakdown_rows_for_range(
        state,
        source_scope,
        None,
        range,
        UsageBreakdownBuildTelemetry::from_range_route(
            if builder_kind == DashboardActivityAccountBuilderKind::UpstreamAccount {
                "upstream_account"
            } else {
                "dashboard"
            },
            range_name,
        ),
    )
    .await?
    .rows;
    for row in &usage_breakdown_build {
        let entry = account_activity.entry(row.upstream_account_id).or_default();
        entry.usage_breakdown.add_aggregate_row(row);
        entry.model_performance.add_aggregate_row(row);
        model_performance.add_aggregate_row(row);
    }
    if range.start < retention_cutoff {
        let archive_rows = query_completed_invocation_archive_activity_aggregate_rows(
            &state.pool,
            source_scope,
            range,
        )
        .await?;
        let QueryCompletedInvocationArchiveActivityAggregateRows {
            aggregates: archived_aggregates,
            skipped_materialized_ranges,
        } = archive_rows;
        for row in archived_aggregates {
            let entry = account_activity.entry(row.upstream_account_id).or_default();
            merge_latest_optional_timestamp(
                &mut entry.latest_conversation_created_at,
                row.latest_conversation_created_at,
            );
            merge_latest_optional_timestamp(&mut entry.last_invocation_at, row.last_invocation_at);
            entry.request_count += row.request_count;
            entry.success_count += row.success_count;
            entry.failure_count += row.failure_count;
            entry.non_success_count += row.non_success_count;
            entry.total_tokens += row.total_tokens;
            entry.success_tokens += row.success_tokens;
            entry.non_success_tokens += row.non_success_tokens;
            entry.failure_tokens += row.failure_tokens;
            entry.failure_cost += row.failure_cost;
            entry.non_success_cost += row.non_success_cost;
            entry.cache_input_tokens += row.cache_input_tokens;
            entry.total_cost += row.total_cost;
            entry.first_response_byte_total_sample_count +=
                row.first_response_byte_total_sample_count;
            entry.first_response_byte_total_sum_ms += row.first_response_byte_total_sum_ms;
            entry.first_token_sample_count += row.first_token_sample_count;
            entry.first_token_sum_ms += row.first_token_sum_ms;
            entry.total_latency_sample_count += row.total_latency_sample_count;
            entry.total_latency_sum_ms += row.total_latency_sum_ms;
            merge_latest_timed_metric(
                &mut entry.latest_first_response_byte_total_at,
                &mut entry.latest_first_response_byte_total_ms,
                row.latest_first_response_byte_total_at,
                row.latest_first_response_byte_total_ms,
            );
            merge_latest_timed_metric(
                &mut entry.latest_avg_total_at,
                &mut entry.latest_avg_total_ms,
                row.latest_avg_total_at,
                row.latest_avg_total_ms,
            );
        }
        if !skipped_materialized_ranges.is_empty() {
            let global_fallback_totals = dashboard_activity_materialized_archive_fallback_totals(
                state,
                source_scope,
                skipped_materialized_ranges.clone(),
            )
            .await?;
            let (global_first_token_count, global_first_token_sum_ms) =
                dashboard_activity_materialized_archive_first_token_fallback_totals(
                    state,
                    source_scope,
                    &skipped_materialized_ranges,
                )
                .await?;
            if dashboard_activity_stats_totals_has_values(global_fallback_totals)
                || global_first_token_count > 0
            {
                if builder_kind == DashboardActivityAccountBuilderKind::DashboardFull {
                    materialized_archive_details_limited = true;
                }
                let mut account_fallback_totals =
                    dashboard_activity_materialized_archive_account_fallback_totals(
                        state,
                        source_scope,
                        &skipped_materialized_ranges,
                    )
                    .await?;
                let account_fallback_sum = account_fallback_totals
                    .values()
                    .fold(StatsTotals::default(), |total, account_totals| {
                        total.add(account_totals.stats_totals())
                    });
                let residual_fallback_totals = dashboard_activity_stats_totals_subtract(
                    global_fallback_totals,
                    account_fallback_sum,
                );
                let (residual_first_token_count, residual_first_token_sum_ms) =
                    dashboard_activity_residual_first_token_totals(
                        global_first_token_count,
                        global_first_token_sum_ms,
                        &account_fallback_totals,
                    );
                if dashboard_activity_stats_totals_has_values(residual_fallback_totals)
                    || residual_first_token_count > 0
                {
                    let mut residual = DashboardActivityAccountFallbackTotals::from_stats_totals(
                        residual_fallback_totals,
                    );
                    residual.first_token_sample_count = residual_first_token_count;
                    residual.first_token_sum_ms = residual_first_token_sum_ms;
                    account_fallback_totals
                        .entry(None)
                        .or_default()
                        .add_assign(residual);
                }
                for (upstream_account_id, totals) in account_fallback_totals {
                    dashboard_activity_merge_account_fallback_totals(
                        account_activity.entry(upstream_account_id).or_default(),
                        totals,
                    );
                }
            }
        }
    }
    if let Some(model_performance_duration_overrides) = model_performance_duration_overrides {
        model_performance.wall_clock_usage_duration_ms =
            model_performance_duration_overrides.total_wall_clock_ms;
        for (group, wall_clock_usage_duration_ms) in
            model_performance_duration_overrides.by_group_wall_clock_ms
        {
            if let Some(entry) = model_performance.models.get_mut(&group) {
                entry.wall_clock_usage_duration_ms = Some(wall_clock_usage_duration_ms);
            }
        }
        for (upstream_account_id, wall_clock_usage_duration_ms) in
            model_performance_duration_overrides.by_account_wall_clock_ms
        {
            if let Some(entry) = account_activity.get_mut(&upstream_account_id) {
                entry.model_performance.wall_clock_usage_duration_ms =
                    Some(wall_clock_usage_duration_ms);
            }
        }
        for (key, wall_clock_usage_duration_ms) in
            model_performance_duration_overrides.by_account_group_wall_clock_ms
        {
            if let Some(entry) = account_activity.get_mut(&key.upstream_account_id)
                && let Some(model_entry) = entry.model_performance.models.get_mut(&key.group)
            {
                model_entry.wall_clock_usage_duration_ms = Some(wall_clock_usage_duration_ms);
            }
        }
    }
    let mut build_telemetry = DashboardActivityBuildTelemetry {
        account_aggregation: account_aggregation_telemetry,
        ..DashboardActivityBuildTelemetry::default()
    };
    for row in
        query_live_upstream_account_activity_rate_rows(&state.pool, source_scope, range).await?
    {
        if let Some(occurred_at) = parse_to_utc_datetime(&row.occurred_at) {
            account_activity
                .entry(row.upstream_account_id)
                .or_default()
                .rate_usage_events
                .push(UpstreamAccountRateUsageEvent {
                    occurred_at_epoch_ms: occurred_at.timestamp_millis(),
                    total_tokens: row.total_tokens.max(0),
                    total_cost: row.total_cost.max(0.0),
                });
        }
    }

    if include_recent {
        let hydrated_rows =
            query_live_upstream_account_activity_preview_rows_per_account_limit_with_stats(
                &state.pool,
                source_scope,
                range,
                recent_limit,
                builder_kind.preview_read_telemetry(),
            )
            .await?;
        build_telemetry = DashboardActivityBuildTelemetry {
            preview_read_mode: "bounded_per_account",
            candidate_preview_id_count: hydrated_rows.candidate_preview_id_count,
            hydrated_preview_row_count: hydrated_rows.hydrated_preview_row_count,
            account_aggregation: account_aggregation_telemetry,
        };
        let mut recent_rows_by_account =
            HashMap::<Option<i64>, Vec<PromptCacheConversationInvocationPreviewResponse>>::new();
        let mut recent_rows = hydrated_rows.rows;
        overlay_runtime_upstream_account_activity_preview_rows(
            state,
            &mut recent_rows,
            source_scope,
            range,
        );
        overlay_runtime_terminal_upstream_account_activity_preview_rows(
            state,
            &mut recent_rows,
            source_scope,
            range,
        )
        .await?;
        let live_ids = recent_rows.iter().map(|row| row.id).collect::<HashSet<_>>();
        for row in recent_rows {
            merge_upstream_account_activity_recent_row_metadata(&mut account_activity, &row);
            recent_rows_by_account
                .entry(row.upstream_account_id)
                .or_default()
                .push(upstream_account_invocation_preview_from_row(row));
        }
        if range.start < retention_cutoff {
            let mut archived_rows = crate::stats::query_completed_invocation_archive_preview_rows(
                &state.pool,
                source_scope,
                range,
                Some(&live_ids),
            )
            .await?;
            let archived_row_ids = archived_rows.iter().map(|row| row.id).collect::<Vec<_>>();
            let persisted_live_ids = query_live_upstream_account_activity_existing_invocation_ids(
                &state.pool,
                source_scope,
                &archived_row_ids,
            )
            .await?;
            archived_rows.retain(|row| !persisted_live_ids.contains(&row.id));
            for row in archived_rows {
                merge_upstream_account_activity_recent_row_metadata(&mut account_activity, &row);
                recent_rows_by_account
                    .entry(row.upstream_account_id)
                    .or_default()
                    .push(upstream_account_invocation_preview_from_row(row));
            }
        }
        for (upstream_account_id, mut recent_rows) in recent_rows_by_account {
            let entry = account_activity.entry(upstream_account_id).or_default();
            recent_rows.append(&mut entry.recent_invocations);
            let mut seen_keys = HashSet::with_capacity(recent_rows.len());
            recent_rows.retain(|invocation| {
                seen_keys.insert((invocation.invoke_id.clone(), invocation.occurred_at.clone()))
            });
            recent_rows.sort_by(|left, right| {
                right
                    .occurred_at
                    .cmp(&left.occurred_at)
                    .then_with(|| right.id.cmp(&left.id))
            });
            recent_rows.truncate(recent_limit);
            entry.recent_invocations = recent_rows;
        }
    }

    let in_progress_counts = if range_name == "yesterday" {
        HashMap::new()
    } else {
        match in_progress_counts_override {
            Some(counts) => counts,
            None => query_upstream_account_in_progress_counts(state, source_scope).await?,
        }
    };
    for upstream_account_id in in_progress_counts.keys() {
        account_activity.entry(*upstream_account_id).or_default();
    }

    let mut latest_first_response_byte_total_in_range = LatestTimedMetricValue::default();
    let mut latest_avg_total_in_range = LatestTimedMetricValue::default();
    for aggregate in account_activity.values() {
        latest_first_response_byte_total_in_range.update(
            aggregate.latest_first_response_byte_total_at.clone(),
            aggregate.latest_first_response_byte_total_ms,
        );
        latest_avg_total_in_range.update(
            aggregate.latest_avg_total_at.clone(),
            aggregate.latest_avg_total_ms,
        );
    }

    let account_ids = account_activity
        .keys()
        .filter_map(|id| *id)
        .collect::<Vec<_>>();
    let account_meta = query_upstream_account_activity_meta(&state.pool, &account_ids).await?;
    let effective_routing_rules =
        crate::upstream_accounts::load_effective_routing_rules_for_accounts(
            &state.pool,
            &account_ids,
        )
        .await?;
    let account_model_performance_accumulators = account_activity
        .iter()
        .map(|(upstream_account_id, aggregate)| {
            (*upstream_account_id, aggregate.model_performance.clone())
        })
        .collect();
    let account_latency_accumulators = account_activity
        .iter()
        .map(|(upstream_account_id, aggregate)| {
            (
                *upstream_account_id,
                DashboardActivityAccountLatencyAccumulator::from_aggregate(aggregate),
            )
        })
        .collect();
    let summary_model_performance_accumulator = model_performance.clone();
    let mut accounts = account_activity
        .into_iter()
        .map(|(upstream_account_id, aggregate)| {
            build_dashboard_activity_account_response(
                range_name,
                range,
                model_performance_available,
                &current_snapshot_by_account,
                &account_meta,
                &effective_routing_rules,
                &in_progress_counts,
                upstream_account_id,
                aggregate,
            )
        })
        .collect::<Vec<_>>();
    sort_dashboard_activity_accounts(&mut accounts);
    Ok(DashboardActivityAccountBuildResult {
        accounts,
        current_snapshot_summary,
        latest_first_response_byte_total_in_range: latest_first_response_byte_total_in_range.value,
        latest_avg_total_in_range: latest_avg_total_in_range.value,
        summary_model_performance: model_performance
            .into_response(range, model_performance_available),
        summary_model_performance_accumulator,
        account_model_performance_accumulators,
        account_latency_accumulators,
        materialized_archive_fallback_totals,
        materialized_archive_details_limited,
        build_telemetry,
    })
}

async fn load_dashboard_activity_snapshot_cached(
    state: &AppState,
    range_name: &str,
    reporting_tz: Tz,
    recent_limit: usize,
    include_accounts: bool,
    include_recent: bool,
    in_progress_counts_override: Option<HashMap<Option<i64>, UpstreamAccountInProgressSummary>>,
) -> Result<
    (
        DashboardActivitySnapshot,
        DashboardActivitySnapshotCacheOutcome,
    ),
    ApiError,
> {
    if range_name == "yesterday" {
        let started_at = Instant::now();
        let range = resolve_dashboard_activity_exact_range(range_name, reporting_tz)?;
        let snapshot = load_dashboard_activity_snapshot_for_range(
            state,
            range_name,
            reporting_tz,
            range,
            recent_limit,
            include_accounts,
            include_recent,
            in_progress_counts_override.clone(),
        )
        .await?;
        return Ok((
            snapshot,
            DashboardActivitySnapshotCacheOutcome {
                cache_hit_or_miss: "uncached",
                cache_bypass_reason: "yesterday_exact",
                coalesced_waiter_count: 0,
                db_build_elapsed_ms: started_at.elapsed().as_millis() as u64,
                cache_ttl_ms: 0,
                cache_entry_age_ms: 0,
                cache_entry_count: 0,
                in_flight_count: 0,
                refresh_reason: "exact_uncached",
                selection_fingerprint: 0,
                terminal_delta_count: 0,
                duplicate_delta_count: 0,
                pending_delta_count: 0,
                pending_delta_estimated_bytes: 0,
                persisted_ack_pending_count: 0,
                delta_pruned_count: 0,
                expiry_delta_count: 0,
                hard_limit_reason: "none",
                baseline_cursor: 0,
                sequence_gap_count: 0,
                build_attempted: true,
                snapshot_origin: "exact_db",
            },
        ));
    }

    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let range = resolve_dashboard_activity_cached_range(range_name, reporting_tz)?;
    let selection = build_dashboard_activity_snapshot_selection(
        range_name,
        range,
        reporting_tz,
        source_scope,
        recent_limit,
        include_accounts,
        include_recent,
    );
    let baseline_build_gate = {
        let cache = state.dashboard_activity_snapshot_cache.lock().await;
        cache.baseline_build_gate.clone()
    };
    if !dashboard_activity_snapshot_cache_can_track_expiry(
        range_name,
        range,
        shanghai_retention_cutoff(state.config.invocation_max_days),
    ) {
        let started_at = Instant::now();
        let _baseline_build_guard = baseline_build_gate.lock().await;
        let reconcile_gate = state.sqlite_batch_writer.dashboard_reconcile_gate();
        let reconcile_guard = reconcile_gate.lock().await;
        let mut consistency_connection =
            Some(begin_dashboard_activity_consistency_barrier(&state.pool).await?);
        // Once BEGIN IMMEDIATE owns the SQLite write barrier, the batch writer can drain its
        // channel into its retained batch instead of backing up behind this process-local gate.
        drop(reconcile_guard);
        let build_result: Result<_, ApiError> = async {
            let baseline_cursor = if let Some(connection) = consistency_connection.as_mut() {
                query_live_dashboard_activity_snapshot_cursor_tx(connection.as_mut()).await?
            } else {
                query_live_dashboard_activity_snapshot_cursor(&state.pool).await?
            };
            let snapshot = load_dashboard_activity_snapshot_for_range(
                state,
                range_name,
                reporting_tz,
                range,
                recent_limit,
                include_accounts,
                include_recent,
                in_progress_counts_override,
            )
            .await?;
            let pending_terminal_keys_after_build = {
                let cache = state.dashboard_activity_snapshot_cache.lock().await;
                cache
                    .read_model
                    .pending_terminal_deltas
                    .iter()
                    .filter_map(|delta| {
                        let occurred_at = parse_to_utc_datetime(&delta.occurred_at)?;
                        dashboard_activity_selection_includes_compact_terminal(
                            &selection,
                            delta,
                            occurred_at,
                        )
                        .then_some(delta.key())
                    })
                    .collect::<Vec<_>>()
            };
            let persisted_terminal_ids = if let Some(connection) = consistency_connection.as_mut() {
                query_live_dashboard_activity_persisted_terminal_ids_tx(
                    connection.as_mut(),
                    dashboard_activity_selection_source_scope(&selection),
                    &pending_terminal_keys_after_build,
                )
                .await?
            } else {
                HashMap::new()
            };
            Ok((snapshot, baseline_cursor, persisted_terminal_ids))
        }
        .await;
        // Keep ACK pruning behind the exact snapshot replay. Once the consistency transaction
        // is released, the writer may persist and acknowledge a terminal that arrived during the
        // build; without this guard it could remove the pending delta before this older baseline
        // has incorporated it.
        let cache = state.dashboard_activity_snapshot_cache.lock().await;
        if let Some(connection) = consistency_connection.take() {
            finish_dashboard_activity_consistency_barrier(connection, build_result.is_ok()).await?;
        }
        let (mut snapshot, baseline_cursor, persisted_terminal_ids) = build_result?;
        if !dashboard_activity_hard_limit_is_settled(&cache.read_model) {
            return Err(ApiError::from(anyhow!(
                "dashboard activity hard-limit terminal writes are not persisted yet"
            )));
        }
        let replayed_pending_delta_count = replay_dashboard_activity_pending_deltas_without_expiry(
            &mut snapshot,
            &selection,
            &cache.read_model.pending_terminal_deltas,
            baseline_cursor,
            &persisted_terminal_ids,
        );
        tracing::debug!(
            selection_fingerprint = dashboard_activity_selection_fingerprint(&selection),
            replayed_pending_delta_count,
            "replayed pending dashboard deltas over archive-prefix exact snapshot"
        );
        let terminal_delta_count = cache.read_model.terminal_delta_count;
        let duplicate_delta_count = cache.read_model.duplicate_delta_count;
        let pending_delta_count = cache.read_model.pending_terminal_deltas.len();
        let pending_delta_estimated_bytes = cache.read_model.pending_delta_estimated_bytes;
        let persisted_ack_pending_count = cache.read_model.persisted_ack_pending_count;
        let delta_pruned_count = cache.read_model.delta_pruned_count;
        let hard_limit_reason = cache.read_model.hard_limit_reason.unwrap_or("none");
        let sequence_gap_count = cache.read_model.sequence_gap_count;
        return Ok((
            snapshot,
            DashboardActivitySnapshotCacheOutcome {
                cache_hit_or_miss: "uncached",
                cache_bypass_reason: "archive_expiry_unavailable",
                coalesced_waiter_count: 0,
                db_build_elapsed_ms: started_at.elapsed().as_millis() as u64,
                cache_ttl_ms: 0,
                cache_entry_age_ms: 0,
                cache_entry_count: 0,
                in_flight_count: 0,
                refresh_reason: "exact_uncached",
                selection_fingerprint: 0,
                terminal_delta_count,
                duplicate_delta_count,
                pending_delta_count,
                pending_delta_estimated_bytes,
                persisted_ack_pending_count,
                delta_pruned_count,
                expiry_delta_count: 0,
                hard_limit_reason,
                baseline_cursor,
                sequence_gap_count,
                build_attempted: true,
                snapshot_origin: "exact_db_with_pending_overlay",
            },
        ));
    }
    let mut waited_on_in_flight = false;
    let mut max_waiter_count = 0_usize;
    let mut saw_expired_entry = false;
    let cache_ttl = dashboard_activity_snapshot_cache_ttl(range_name);
    let cache_ttl_ms = cache_ttl.as_millis() as u64;
    let selection_fingerprint = dashboard_activity_selection_fingerprint(&selection);

    loop {
        let mut wait_on: Option<tokio::sync::watch::Receiver<bool>> = None;
        let mut flight_guard: Option<DashboardActivitySnapshotFlightGuard> = None;
        {
            let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
            saw_expired_entry |= cache
                .entries
                .get(&selection)
                .is_some_and(|entry| entry.cached_at.elapsed() > cache_ttl);
            cache.entries.retain(|_, entry| {
                entry.cached_at.elapsed() <= DASHBOARD_ACTIVITY_LAST_GOOD_MAX_AGE
            });
            let cache_entry_count = cache.entries.len();
            let in_flight_count = cache.in_flight.len();
            let terminal_delta_count = cache.read_model.terminal_delta_count;
            let duplicate_delta_count = cache.read_model.duplicate_delta_count;
            let pending_delta_count = cache.read_model.pending_terminal_deltas.len();
            let pending_delta_estimated_bytes = cache.read_model.pending_delta_estimated_bytes;
            let persisted_ack_pending_count = cache.read_model.persisted_ack_pending_count;
            let delta_pruned_count = cache.read_model.delta_pruned_count;
            let hard_limit_reason = cache.read_model.hard_limit_reason.unwrap_or("none");
            let sequence_gap_count = cache.read_model.sequence_gap_count;
            let settled_dirty_state =
                dashboard_activity_read_model_requires_reconcile(&cache.read_model);
            if !settled_dirty_state
                && let Some(entry) = cache.entries.get_mut(&selection)
                && let Some(reuse_mode) =
                    dashboard_activity_snapshot_reuse_mode(entry, range, cache_ttl)
            {
                let mut expired_count = 0usize;
                while entry.expiry_terminal_deltas.front().is_some_and(|delta| {
                    parse_to_utc_datetime(&delta.occurred_at)
                        .is_some_and(|occurred_at| occurred_at < range.start)
                }) {
                    if let Some(delta) = entry.expiry_terminal_deltas.pop_front() {
                        entry.expiry_delta_estimated_bytes = entry
                            .expiry_delta_estimated_bytes
                            .saturating_sub(delta.estimated_bytes);
                        subtract_dashboard_activity_compact_terminal_delta(
                            &mut entry.response,
                            &delta,
                        );
                        restore_dashboard_activity_last_invocation_after_expiry(
                            &mut entry.response,
                            &delta,
                            &entry.expiry_terminal_deltas,
                        );
                        expired_count += 1;
                    }
                }
                let cache_entry_age_ms = entry.cached_at.elapsed().as_millis() as u64;
                let is_last_good =
                    reuse_mode == DashboardActivitySnapshotReuseMode::LastGoodReconcileBackoff;
                return Ok((
                    entry.response.clone(),
                    DashboardActivitySnapshotCacheOutcome {
                        cache_hit_or_miss: if is_last_good {
                            "last_good_fallback"
                        } else if waited_on_in_flight {
                            "wait_on_in_flight"
                        } else {
                            "cache_hit"
                        },
                        cache_bypass_reason: if is_last_good {
                            "expiry_reconcile_backoff"
                        } else {
                            "none"
                        },
                        coalesced_waiter_count: max_waiter_count,
                        db_build_elapsed_ms: 0,
                        cache_ttl_ms,
                        cache_entry_age_ms,
                        cache_entry_count,
                        in_flight_count,
                        refresh_reason: if is_last_good {
                            "reconcile_backoff"
                        } else {
                            "within_ttl"
                        },
                        selection_fingerprint,
                        terminal_delta_count,
                        duplicate_delta_count,
                        pending_delta_count,
                        pending_delta_estimated_bytes,
                        persisted_ack_pending_count,
                        delta_pruned_count,
                        expiry_delta_count: expired_count,
                        hard_limit_reason,
                        baseline_cursor: entry.baseline_snapshot_cursor,
                        sequence_gap_count,
                        build_attempted: false,
                        snapshot_origin: if is_last_good { "last_good" } else { "memory" },
                    },
                ));
            }

            let writer_pressure = crate::db_pressure::global_db_pressure_gate()
                .snapshot()
                .pressure_cooldown_remaining_ms
                > 0;
            if !settled_dirty_state
                && writer_pressure
                && let Some(entry) = cache.entries.get_mut(&selection)
                && dashboard_activity_entry_expiry_covers(entry, range)
                && dashboard_activity_pressure_reconcile_deferred(entry)
            {
                let mut expired_count = 0usize;
                while entry.expiry_terminal_deltas.front().is_some_and(|delta| {
                    parse_to_utc_datetime(&delta.occurred_at)
                        .is_some_and(|occurred_at| occurred_at < range.start)
                }) {
                    if let Some(delta) = entry.expiry_terminal_deltas.pop_front() {
                        entry.expiry_delta_estimated_bytes = entry
                            .expiry_delta_estimated_bytes
                            .saturating_sub(delta.estimated_bytes);
                        subtract_dashboard_activity_compact_terminal_delta(
                            &mut entry.response,
                            &delta,
                        );
                        restore_dashboard_activity_last_invocation_after_expiry(
                            &mut entry.response,
                            &delta,
                            &entry.expiry_terminal_deltas,
                        );
                        expired_count += 1;
                    }
                }
                entry.last_reconcile_attempted_at = Instant::now();
                entry.last_reconcile_failed = true;
                let cache_entry_age_ms = entry.cached_at.elapsed().as_millis() as u64;
                return Ok((
                    entry.response.clone(),
                    DashboardActivitySnapshotCacheOutcome {
                        cache_hit_or_miss: "last_good_fallback",
                        cache_bypass_reason: "writer_pressure",
                        coalesced_waiter_count: max_waiter_count,
                        db_build_elapsed_ms: 0,
                        cache_ttl_ms,
                        cache_entry_age_ms,
                        cache_entry_count,
                        in_flight_count,
                        refresh_reason: "reconcile_deferred",
                        selection_fingerprint,
                        terminal_delta_count,
                        duplicate_delta_count,
                        pending_delta_count,
                        pending_delta_estimated_bytes,
                        persisted_ack_pending_count,
                        delta_pruned_count,
                        expiry_delta_count: expired_count,
                        hard_limit_reason,
                        baseline_cursor: entry.baseline_snapshot_cursor,
                        sequence_gap_count,
                        build_attempted: false,
                        snapshot_origin: "memory",
                    },
                ));
            }

            if let Some(in_flight) = cache.in_flight.get_mut(&selection) {
                in_flight.waiter_count += 1;
                max_waiter_count = max_waiter_count.max(in_flight.waiter_count);
                wait_on = Some(in_flight.signal.subscribe());
            } else {
                let (signal, _receiver) = tokio::sync::watch::channel(false);
                cache.in_flight.insert(
                    selection.clone(),
                    DashboardActivitySnapshotInFlight {
                        signal,
                        waiter_count: 0,
                        baseline_cursor: None,
                    },
                );
                flight_guard = Some(DashboardActivitySnapshotFlightGuard::new(
                    state.dashboard_activity_snapshot_cache.clone(),
                    selection.clone(),
                ));
            }
        }

        if let Some(mut receiver) = wait_on {
            waited_on_in_flight = true;
            if !*receiver.borrow() {
                let _ = receiver.changed().await;
            }
            continue;
        }

        let build_started_at = Instant::now();
        let _baseline_build_guard = baseline_build_gate.lock().await;
        let reconcile_gate = state.sqlite_batch_writer.dashboard_reconcile_gate();
        let reconcile_guard = reconcile_gate.lock().await;
        let has_last_good = {
            let cache = state.dashboard_activity_snapshot_cache.lock().await;
            cache.entries.contains_key(&selection)
        };
        let mut consistency_connection = if has_last_good {
            try_begin_dashboard_activity_consistency_barrier(&state.pool).await?
        } else {
            Some(begin_dashboard_activity_consistency_barrier(&state.pool).await?)
        };
        // SQLite now serializes commits against the consistency transaction. Releasing the
        // process-local gate lets the writer retain failed work without filling its input queue.
        drop(reconcile_guard);
        let consistency_barrier_unavailable = consistency_connection.is_none();
        if consistency_barrier_unavailable {
            let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
            if let Some(entry) = cache.entries.get_mut(&selection) {
                mark_dashboard_activity_reconcile_failed(entry);
                let response = entry.response.clone();
                let cache_entry_age_ms = entry.cached_at.elapsed().as_millis() as u64;
                let baseline_cursor = entry.baseline_snapshot_cursor;
                let in_flight = cache.in_flight.remove(&selection);
                if let Some(guard) = flight_guard.as_mut() {
                    guard.disarm();
                }
                let coalesced_waiter_count =
                    in_flight.as_ref().map_or(0, |flight| flight.waiter_count);
                if let Some(in_flight) = in_flight {
                    let _ = in_flight.signal.send(true);
                }
                return Ok((
                    response,
                    DashboardActivitySnapshotCacheOutcome {
                        cache_hit_or_miss: "last_good_fallback",
                        cache_bypass_reason: "consistency_barrier_unavailable",
                        coalesced_waiter_count,
                        db_build_elapsed_ms: build_started_at.elapsed().as_millis() as u64,
                        cache_ttl_ms,
                        cache_entry_age_ms,
                        cache_entry_count: cache.entries.len(),
                        in_flight_count: cache.in_flight.len(),
                        refresh_reason: "reconcile_lock_contended",
                        selection_fingerprint,
                        terminal_delta_count: cache.read_model.terminal_delta_count,
                        duplicate_delta_count: cache.read_model.duplicate_delta_count,
                        pending_delta_count: cache.read_model.pending_terminal_deltas.len(),
                        pending_delta_estimated_bytes: cache
                            .read_model
                            .pending_delta_estimated_bytes,
                        persisted_ack_pending_count: cache.read_model.persisted_ack_pending_count,
                        delta_pruned_count: cache.read_model.delta_pruned_count,
                        expiry_delta_count: 0,
                        hard_limit_reason: cache.read_model.hard_limit_reason.unwrap_or("none"),
                        baseline_cursor,
                        sequence_gap_count: cache.read_model.sequence_gap_count,
                        build_attempted: false,
                        snapshot_origin: "last_good",
                    },
                ));
            }
            let in_flight = cache.in_flight.remove(&selection);
            if let Some(guard) = flight_guard.as_mut() {
                guard.disarm();
            }
            if let Some(in_flight) = in_flight {
                let _ = in_flight.signal.send(true);
            }
            return Err(ApiError::from(anyhow!(
                "dashboard activity consistency barrier unavailable for initial snapshot"
            )));
        }
        let (snapshot_cursor_before_build, probe_error) =
            match if let Some(connection) = consistency_connection.as_mut() {
                query_live_dashboard_activity_snapshot_cursor_tx(connection.as_mut()).await
            } else {
                query_live_dashboard_activity_snapshot_cursor(&state.pool).await
            } {
                Ok(snapshot_cursor) => (snapshot_cursor, None),
                Err(err) => (0, Some(err)),
            };
        {
            let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
            if let Some(flight) = cache.in_flight.get_mut(&selection) {
                flight.baseline_cursor = Some(snapshot_cursor_before_build);
            }
        }
        let mut result = if let Some(err) = probe_error {
            Err(err)
        } else {
            load_dashboard_activity_snapshot_for_range(
                state,
                range_name,
                reporting_tz,
                range,
                recent_limit,
                include_accounts,
                include_recent,
                in_progress_counts_override.clone(),
            )
            .await
        };
        let (snapshot_cursor_after_build, persisted_terminal_ids_after_build) = if result.is_ok() {
            let pending_terminal_keys_after_build = {
                let cache = state.dashboard_activity_snapshot_cache.lock().await;
                cache
                    .read_model
                    .pending_terminal_deltas
                    .iter()
                    .filter_map(|delta| {
                        let occurred_at = parse_to_utc_datetime(&delta.occurred_at)?;
                        dashboard_activity_selection_includes_compact_terminal(
                            &selection,
                            delta,
                            occurred_at,
                        )
                        .then_some(delta.key())
                    })
                    .collect::<Vec<_>>()
            };
            let probe = if let Some(connection) = consistency_connection.as_mut() {
                query_live_dashboard_activity_persisted_terminal_ids_tx(
                    connection.as_mut(),
                    dashboard_activity_selection_source_scope(&selection),
                    &pending_terminal_keys_after_build,
                )
                .await
                .map(|ids| (snapshot_cursor_before_build, ids))
            } else {
                Ok((snapshot_cursor_before_build, HashMap::new()))
            };
            match probe {
                Ok(probe) => probe,
                Err(err) => {
                    result = Err(err);
                    (snapshot_cursor_before_build, HashMap::new())
                }
            }
        } else {
            (snapshot_cursor_before_build, HashMap::new())
        };
        let (
            mut expiry_terminal_deltas,
            mut expiry_covered_until,
            mut expiry_delta_estimated_bytes,
            mut expiry_tracking_failure_reason,
        ) = if result.is_ok() {
            match load_dashboard_activity_expiry_deltas(
                &state.pool,
                &selection,
                range,
                snapshot_cursor_after_build,
            )
            .await
            {
                Ok(expiry) => expiry,
                Err(err) => {
                    result = Err(err);
                    (VecDeque::new(), None, 0, None)
                }
            }
        } else {
            (VecDeque::new(), None, 0, None)
        };
        if consistency_barrier_unavailable {
            expiry_tracking_failure_reason = Some("consistency_barrier_unavailable");
            expiry_terminal_deltas.clear();
            expiry_delta_estimated_bytes = 0;
            expiry_covered_until = None;
        }
        if let Some(connection) = consistency_connection.take()
            && let Err(err) =
                finish_dashboard_activity_consistency_barrier(connection, result.is_ok()).await
        {
            result = Err(err);
        }
        let db_build_elapsed_ms = build_started_at.elapsed().as_millis() as u64;

        let mut cache = state.dashboard_activity_snapshot_cache.lock().await;
        let refresh_reason =
            cache
                .invalidation_reasons
                .remove(&selection)
                .unwrap_or(if saw_expired_entry {
                    "ttl_expired"
                } else {
                    "initial_build"
                });
        let in_flight = cache.in_flight.remove(&selection);
        if let Some(guard) = flight_guard.as_mut() {
            guard.disarm();
        }
        let coalesced_waiter_count = in_flight.as_ref().map_or(0, |flight| flight.waiter_count);
        if result.is_ok() && !dashboard_activity_hard_limit_is_settled(&cache.read_model) {
            result = Err(ApiError::from(anyhow!(
                "dashboard activity hard-limit terminal writes are not persisted yet"
            )));
        }
        if let Ok(snapshot) = result.as_mut() {
            // Pending records are shared by every in-flight selection. Do not consume them from
            // the first completed build: another selection may have started before the same
            // terminal reached SQLite and still needs to replay its delta.
            for delta in &cache.read_model.pending_terminal_deltas {
                let Some(occurred_at) = parse_to_utc_datetime(&delta.occurred_at) else {
                    continue;
                };
                if dashboard_activity_selection_includes_compact_terminal(
                    &selection,
                    delta,
                    occurred_at,
                ) {
                    if dashboard_activity_baseline_includes_pending_delta(
                        delta,
                        snapshot_cursor_after_build,
                        &persisted_terminal_ids_after_build,
                    ) {
                        snapshot.terminal_sequence =
                            snapshot.terminal_sequence.max(delta.terminal_sequence);
                        continue;
                    }
                    if expiry_tracking_failure_reason.is_none()
                        && let Err(reason) = insert_dashboard_activity_expiry_delta(
                            &mut expiry_terminal_deltas,
                            &mut expiry_delta_estimated_bytes,
                            expiry_covered_until,
                            delta,
                            occurred_at,
                        )
                    {
                        expiry_tracking_failure_reason = Some(reason);
                        expiry_terminal_deltas.clear();
                        expiry_delta_estimated_bytes = 0;
                        expiry_covered_until = None;
                    }
                    apply_dashboard_activity_compact_terminal_delta(snapshot, delta);
                }
            }
        }
        if let Some(in_flight) = in_flight {
            if let Ok(snapshot) = &result
                && expiry_tracking_failure_reason.is_none()
            {
                cache.entries.insert(
                    selection.clone(),
                    DashboardActivitySnapshotCacheEntry {
                        cached_at: Instant::now(),
                        last_reconcile_attempted_at: Instant::now(),
                        last_reconcile_failed: false,
                        baseline_snapshot_cursor: snapshot_cursor_after_build,
                        expiry_covered_until,
                        expiry_terminal_deltas,
                        expiry_delta_estimated_bytes,
                        response: snapshot.clone(),
                    },
                );
                let evicted_entry_count =
                    prune_dashboard_activity_snapshot_entries(&mut cache, Some(&selection));
                if evicted_entry_count > 0 {
                    tracing::debug!(
                        selection_fingerprint,
                        evicted_entry_count,
                        cache_entry_count = cache.entries.len(),
                        "evicted dashboard activity snapshots after baseline insertion"
                    );
                }
                prune_dashboard_activity_terminal_deltas(&mut cache);
                clear_dashboard_activity_hard_limit_after_baseline(&mut cache.read_model);
            } else if expiry_tracking_failure_reason.is_some() {
                cache.entries.remove(&selection);
            }
            let _ = in_flight.signal.send(true);
        }
        let cache_entry_count = cache.entries.len();
        let in_flight_count = cache.in_flight.len();
        let terminal_delta_count = cache.read_model.terminal_delta_count;
        let duplicate_delta_count = cache.read_model.duplicate_delta_count;
        let pending_delta_count = cache.read_model.pending_terminal_deltas.len();
        let pending_delta_estimated_bytes = cache.read_model.pending_delta_estimated_bytes;
        let persisted_ack_pending_count = cache.read_model.persisted_ack_pending_count;
        let delta_pruned_count = cache.read_model.delta_pruned_count;
        let hard_limit_reason = cache.read_model.hard_limit_reason.unwrap_or("none");
        let sequence_gap_count = cache.read_model.sequence_gap_count;

        return match result {
            Ok(snapshot) => Ok((
                snapshot,
                DashboardActivitySnapshotCacheOutcome {
                    cache_hit_or_miss: if expiry_tracking_failure_reason.is_some() {
                        "uncached"
                    } else {
                        "cache_miss_build"
                    },
                    cache_bypass_reason: expiry_tracking_failure_reason.unwrap_or("none"),
                    coalesced_waiter_count,
                    db_build_elapsed_ms,
                    cache_ttl_ms,
                    cache_entry_age_ms: 0,
                    cache_entry_count,
                    in_flight_count,
                    refresh_reason,
                    selection_fingerprint,
                    terminal_delta_count,
                    duplicate_delta_count,
                    pending_delta_count,
                    pending_delta_estimated_bytes,
                    persisted_ack_pending_count,
                    delta_pruned_count,
                    expiry_delta_count: 0,
                    hard_limit_reason,
                    baseline_cursor: snapshot_cursor_after_build,
                    sequence_gap_count,
                    build_attempted: true,
                    snapshot_origin: if expiry_tracking_failure_reason.is_some() {
                        "exact_db_expiry_untracked"
                    } else {
                        "db_reconciled"
                    },
                },
            )),
            Err(err) => {
                let Some(entry) = cache.entries.get_mut(&selection) else {
                    return Err(err);
                };
                mark_dashboard_activity_reconcile_failed(entry);
                let cache_entry_age_ms = entry.cached_at.elapsed().as_millis() as u64;
                tracing::warn!(
                    selection_fingerprint,
                    refresh_reason,
                    cache_entry_age_ms,
                    db_build_elapsed_ms,
                    error = ?err,
                    "dashboard activity reconciliation failed; retained last-good snapshot"
                );
                Ok((
                    entry.response.clone(),
                    DashboardActivitySnapshotCacheOutcome {
                        cache_hit_or_miss: "last_good_fallback",
                        cache_bypass_reason: "reconcile_failed",
                        coalesced_waiter_count,
                        db_build_elapsed_ms,
                        cache_ttl_ms,
                        cache_entry_age_ms,
                        cache_entry_count,
                        in_flight_count,
                        refresh_reason: "reconcile_failed",
                        selection_fingerprint,
                        terminal_delta_count,
                        duplicate_delta_count,
                        pending_delta_count,
                        pending_delta_estimated_bytes,
                        persisted_ack_pending_count,
                        delta_pruned_count,
                        expiry_delta_count: 0,
                        hard_limit_reason,
                        baseline_cursor: entry.baseline_snapshot_cursor,
                        sequence_gap_count,
                        build_attempted: true,
                        snapshot_origin: "last_good",
                    },
                ))
            }
        };
    }
}

